Tutor.registerIndex("soc-high", [
{"id":"soc-h-c1-01","kind":"unit","title":"통합적 관점으로 보기","text":"사회 현상을 바라보는 시간적·공간적·사회적·윤리적 관점의 의미와 특징을 알고, 이 관점들을 함께 쓰는 통합적 관점으로 사회 문제를 탐구하는 방법을 익힙니다. 시간적·공간적·사회적·윤리적 관점의 의미와 특징을 설명할 수 있다. 하나의 관점만으로 사회 현상을 볼 때 생기는 한계를 사례로 설명할 수 있다. 기후 변화·저출생 같은 사회 문제를 여러 관점을 함께 …","keywords":["관점","시간적 관점","공간적 관점","사회적 관점","윤리적 관점","통합적 관점","상호 작용","가치 판단"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-01","grade":"h1"},
{"id":"soc-h-c1-01#c0","kind":"concept","title":"시간적 관점: 시대의 흐름 속에서 보기","text":"시간적 관점은 사회 현상을 그것이 나타난 역사적 배경과 시대적 맥락 속에서 바라보는 관점입니다. 오늘의 모습은 갑자기 생긴 것이 아니라 과거로부터 이어지고 바뀌어 온 결과입니다. 그래서 \"이 현상은 언제, 어떤 시대 상황에서 생겼는가?\", \"시간이 흐르며 어떻게 달라졌는가?\"를 묻습니다","keywords":["관점","시간적 관점"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-01","grade":"h1"},
{"id":"soc-h-c1-01#c1","kind":"concept","title":"공간적 관점: 위치와 지역으로 보기","text":"공간적 관점은 사회 현상을 위치, 장소, 지역, 그리고 지역과 지역 사이의 상호 작용(사람·물자·정보의 이동)을 중심으로 바라보는 관점입니다. 같은 현상도 어디에서 일어나느냐에 따라 모습이 다르고, 한 지역의 변화는 다른 지역에 영향을 줍니다. 그래서 \"어디에서 일어나는가?\", \"왜 그","keywords":["관점","공간적 관점","상호 작용"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-01","grade":"h1"},
{"id":"soc-h-c1-01#c2","kind":"concept","title":"사회적 관점: 구조와 제도로 보기","text":"사회적 관점은 사회 현상을 사회 구조, 제도, 법과 정책이 사람들의 삶에 주는 영향을 중심으로 바라보는 관점입니다. 개인의 행동은 개인의 선택만으로 정해지지 않습니다. 어떤 제도가 있는지, 사회가 어떻게 짜여 있는지가 사람들의 선택을 넓히기도 하고 좁히기도 합니다. 그래서 \"어떤 제도와","keywords":["관점","사회적 관점"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-01","grade":"h1"},
{"id":"soc-h-c1-01#c3","kind":"concept","title":"윤리적 관점: 도덕적 가치로 판단하기","text":"윤리적 관점은 사회 현상을 도덕적 가치와 규범에 비추어 \"무엇이 옳은가, 무엇이 바람직한가\"를 판단하는 관점입니다. 앞의 세 관점이 주로 \"현상이 어떠한가, 왜 그런가\"를 밝힌다면, 윤리적 관점은 \"어떻게 하는 것이 옳은가\"를 묻습니다. 인간 존엄성, 정의, 생명 존중, 책임 같은 가치","keywords":["관점","윤리적 관점","가치 판단"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-01","grade":"h1"},
{"id":"soc-h-c1-01#c4","kind":"concept","title":"한 관점의 한계와 통합적 관점","text":"사회 현상은 여러 원인이 얽혀 나타나고, 그 영향도 여러 방면에 미칩니다. 그래서 하나의 관점만 쓰면 현상의 일부만 보게 되어 원인을 잘못 짚거나 엉뚱한 해결책을 내기 쉽습니다. 한 관점만 쓸 때 · 놓치기 쉬운 것 시간적 관점만 · 지역마다 다르게 나타나는 모습 공간적 관점만 · 그렇","keywords":["관점","시간적 관점","공간적 관점","사회적 관점","윤리적 관점","통합적 관점"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-01","grade":"h1"},
{"id":"soc-h-c1-01#c5","kind":"concept","title":"통합적 관점으로 사회 문제 탐구하기","text":"사회 문제를 통합적 관점으로 탐구할 때는 관점마다 질문을 세우고 답을 모아 봅니다. 기후 변화 시간적: 산업 혁명 이후 화석 연료 사용이 늘면서 온실가스 배출이 어떻게 늘어 왔는가? 공간적: 해발 고도가 낮은 섬나라·해안 지역, 가뭄이 잦은 지역 등 피해가 어느 곳에 크게 나타나는가? ","keywords":["관점","통합적 관점"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-01","grade":"h1"},
{"id":"soc-h-c1-01#t0","kind":"term","title":"관점","text":"어떤 대상이나 현상을 바라보는 방향이나 처지입니다. 같은 현상도 관점에 따라 다르게 보입니다.","keywords":["관점"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-01","grade":"h1"},
{"id":"soc-h-c1-01#t1","kind":"term","title":"시간적 관점","text":"사회 현상을 역사적 배경과 시대적 맥락 속에서, 시간에 따른 변화와 이어짐을 중심으로 보는 관점입니다.","keywords":["시간적 관점"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-01","grade":"h1"},
{"id":"soc-h-c1-01#t2","kind":"term","title":"공간적 관점","text":"사회 현상을 위치·장소·지역, 그리고 지역 사이의 상호 작용을 중심으로 보는 관점입니다.","keywords":["공간적 관점"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-01","grade":"h1"},
{"id":"soc-h-c1-01#t3","kind":"term","title":"사회적 관점","text":"사회 현상을 사회 구조, 제도, 법과 정책이 주는 영향을 중심으로 보는 관점입니다.","keywords":["사회적 관점"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-01","grade":"h1"},
{"id":"soc-h-c1-01#t4","kind":"term","title":"윤리적 관점","text":"사회 현상을 도덕적 가치와 규범에 비추어 옳고 바람직한지 판단하는 관점입니다.","keywords":["윤리적 관점"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-01","grade":"h1"},
{"id":"soc-h-c1-01#t5","kind":"term","title":"통합적 관점","text":"시간적·공간적·사회적·윤리적 관점을 함께 써서 사회 현상을 총체적으로 이해하는 관점입니다.","keywords":["통합적 관점"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-01","grade":"h1"},
{"id":"soc-h-c1-01#t6","kind":"term","title":"상호 작용","text":"서로 영향을 주고받는 것입니다. 공간적 관점에서는 지역 사이에 사람·물자·정보가 오가는 것을 말합니다.","keywords":["상호 작용"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-01","grade":"h1"},
{"id":"soc-h-c1-01#t7","kind":"term","title":"가치 판단","text":"\"~해야 한다\", \"~이 바람직하다\"처럼 옳고 그름, 좋고 나쁨을 판단하는 것입니다. 사실을 밝히는 사실 판단과 구분됩니다.","keywords":["가치 판단"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-01","grade":"h1"},
{"id":"soc-h-c1-01#f0","kind":"faq","title":"사회적 관점이랑 윤리적 관점은 둘 다 사회 이야기인데 뭐가 달라요?","text":"사회적 관점은 \"제도와 구조가 현상에 어떤 영향을 주는가\"를 밝히는 데 초점이 있습니다. 윤리적 관점은 \"무엇이 옳고 바람직한가\"를 판단합니다. 예를 들어 \"육아 휴직 제도가 생긴 뒤 출산이 늘었는가?\"는 사회적 관점, \"아이 돌봄을 사회가 함께 책임져야 하는가?\"는 윤리적 관점입니다.","keywords":["관점","사회적 관점","윤리적 관점"],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-01","grade":"h1"},
{"id":"soc-h-c1-01#f1","kind":"faq","title":"\"미래 세대\"라는 말이 나오면 시간적 관점 아닌가요?","text":"낱말보다 질문의 핵심을 보아야 합니다. \"미래 세대에게 피해를 넘기는 것이 정당한가?\"처럼 옳고 그름을 묻는다면 윤리적 관점입니다. \"100년 뒤 기온은 얼마나 오를까?\"처럼 시간에 따른 변화를 묻는다면 시간적 관점에 가깝습니다.","keywords":["관점","시간적 관점"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-01","grade":"h1"},
{"id":"soc-h-c1-01#f2","kind":"faq","title":"통합적 관점이면 네 관점을 꼭 똑같은 비중으로 써야 하나요?","text":"그렇지는 않습니다. 주제에 따라 어떤 관점이 더 중요할 수 있습니다. 다만 한 관점만 쓰고 나머지를 빠뜨리면 현상을 좁게 보게 되므로, 네 관점을 모두 점검한 뒤 필요한 만큼 깊이를 조절하는 것이 바람직합니다.","keywords":["관점","통합적 관점"],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-01","grade":"h1"},
{"id":"soc-h-c1-01#m0","kind":"mistake","title":"자주 하는 실수","text":"질문에 들어 있는 낱말(예: \"미래\", \"지역\")만 보고 관점을 고르는 실수 — 질문이 무엇을 밝히려는지(변화·위치·제도·옳고 그름)를 보아야 합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-01","grade":"h1"},
{"id":"soc-h-c1-01#m1","kind":"mistake","title":"자주 하는 실수","text":"통합적 관점을 \"네 관점 가운데 하나를 고르는 것\"으로 오해하는 실수 — 통합적 관점은 여러 관점을 함께 엮어 보는 것입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-01","grade":"h1"},
{"id":"soc-h-c1-01#m2","kind":"mistake","title":"자주 하는 실수","text":"사실을 밝힌 진술을 윤리적 관점으로 착각하는 실수 — \"~해야 한다\", \"~이 바람직하다\"처럼 가치를 판단할 때가 윤리적 관점입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-01","grade":"h1"},
{"id":"soc-h-c1-02","kind":"unit","title":"행복의 의미와 조건","text":"시대와 지역에 따라 달라지는 행복의 기준을 비교하고, 삶의 목적으로서 행복의 의미와 행복한 삶에 필요한 조건(정주 환경, 경제적 안정, 민주주의, 도덕적 실천과 성찰)을 알아봅니다. 시대적 상황과 지역적 여건에 따라 행복의 기준이 달라짐을 사례로 설명할 수 있다. 아리스토텔레스와 동양 사상을 통해 삶의 목적으로서 행복의 의미를 설명할 수 있다. 질 높은 …","keywords":["행복","최고선","덕","열반","무위자연","정주 환경","경제적 안정","이스털린의 역설","성찰"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-02","grade":"h1"},
{"id":"soc-h-c1-02#c0","kind":"concept","title":"시대에 따라 달라진 행복의 기준","text":"무엇을 행복으로 여기는지는 시대적 상황에 따라 달라졌습니다. 그 시대 사람들이 가장 절실하게 바란 것이 행복의 기준이 되었기 때문입니다. 시대 · 행복의 기준 (대표적인 모습) 선사 시대 · 먹을 것을 구하고 맹수·자연재해로부터 안전하게 살아남는 것 중세 서양 · 종교의 가르침에 따라 ","keywords":["행복"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-02","grade":"h1"},
{"id":"soc-h-c1-02#c1","kind":"concept","title":"지역에 따라 달라지는 행복의 기준","text":"행복의 기준은 지역적 여건에 따라서도 달라집니다. 자연환경: 비가 적은 건조 지역에서는 물을 넉넉히 얻는 것이, 자연재해가 잦은 지역에서는 재해로부터 안전한 것이 행복에 중요한 조건이 됩니다. 종교: 종교가 생활 깊숙이 자리 잡은 지역에서는 종교적 가르침을 따르는 삶을 행복으로 여기기도","keywords":["행복"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-02","grade":"h1"},
{"id":"soc-h-c1-02#c2","kind":"concept","title":"삶의 목적으로서의 행복","text":"많은 사상가는 행복을 삶의 궁극적인 목적으로 보았습니다. 아리스토텔레스(고대 그리스)는 다른 것을 위한 수단이 아니라 그 자체로 추구되는 최고의 좋음, 곧 최고선이 행복이라고 하였습니다. 돈이나 명예는 다른 무엇을 위해 바라지만, 행복은 오직 행복 그 자체를 위해 바란다는 것입니다. 그","keywords":["행복","최고선","덕"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-02","grade":"h1"},
{"id":"soc-h-c1-02#c3","kind":"concept","title":"조건 ① 질 높은 정주 환경","text":"정주 환경은 사람들이 일정한 곳에 자리 잡고 살아가는 주거지와 그 주변 환경을 말합니다. 하루 대부분을 보내는 곳이므로 정주 환경의 질은 행복에 큰 영향을 줍니다. 질 높은 정주 환경의 요소는 다음과 같습니다. 쾌적한 주거: 햇빛과 바람이 잘 들고, 소음·악취가 적으며, 적당한 넓이를 ","keywords":["행복","정주 환경"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-02","grade":"h1"},
{"id":"soc-h-c1-02#c4","kind":"concept","title":"조건 ② 경제적 안정","text":"경제적 안정은 행복의 중요한 바탕입니다. 일정한 소득이 있어야 의식주 같은 기본적 필요를 채우고, 교육·건강·여가에 쓸 여유를 가지며, 미래에 대한 불안을 줄일 수 있습니다. 그러나 소득이 늘어나는 만큼 행복이 끝없이 커지지는 않습니다. 소득이 낮을 때는 소득이 조금만 늘어도 생활이 크","keywords":["행복","경제적 안정","이스털린의 역설"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-02","grade":"h1"},
{"id":"soc-h-c1-02#c5","kind":"concept","title":"조건 ③ 민주주의의 실현과 ④ 도덕적 실천·성찰","text":"민주주의의 실현: 민주주의 사회에서는 시민이 자신의 의견을 자유롭게 표현하고, 선거·주민 참여 등으로 자신의 삶에 영향을 주는 결정에 참여할 수 있습니다. 자유와 권리가 보장되고, 스스로 삶을 결정한다는 느낌을 가질 수 있어 행복의 바탕이 됩니다. 반대로 의견을 말할 수 없고 권리가 침","keywords":["행복","덕","성찰"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-02","grade":"h1"},
{"id":"soc-h-c1-02#t0","kind":"term","title":"행복","text":"삶에서 느끼는 만족과 기쁨, 그리고 바람직한 삶을 살고 있다는 충만감입니다. 많은 사상가가 삶의 궁극적 목적으로 보았습니다.","keywords":["행복"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-02","grade":"h1"},
{"id":"soc-h-c1-02#t1","kind":"term","title":"최고선","text":"다른 것을 위한 수단이 아니라 그 자체로 추구되는 가장 높은 좋음입니다. 아리스토텔레스는 행복을 최고선이라고 하였습니다.","keywords":["최고선"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-02","grade":"h1"},
{"id":"soc-h-c1-02#t2","kind":"term","title":"덕","text":"인간이 지닌 능력이 훌륭하게 발휘된 상태, 곧 탁월함입니다. 아리스토텔레스는 덕을 실천하는 삶에서 행복을 얻는다고 보았습니다.","keywords":["덕"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-02","grade":"h1"},
{"id":"soc-h-c1-02#t3","kind":"term","title":"열반","text":"불교에서 집착과 번뇌가 사라져 괴로움에서 완전히 벗어난 상태입니다.","keywords":["열반"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-02","grade":"h1"},
{"id":"soc-h-c1-02#t4","kind":"term","title":"무위자연","text":"도가 사상에서, 억지로 꾸미지 않고 자연의 질서에 따라 사는 것입니다.","keywords":["무위자연"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-02","grade":"h1"},
{"id":"soc-h-c1-02#t5","kind":"term","title":"정주 환경","text":"사람들이 일정한 곳에 자리 잡고 살아가는 주거지와 그 주변 환경입니다. 주거, 편의 시설, 안전 등이 포함됩니다.","keywords":["정주 환경"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-02","grade":"h1"},
{"id":"soc-h-c1-02#t6","kind":"term","title":"경제적 안정","text":"안정된 소득과 일자리로 기본적 필요를 채우고 미래를 계획할 수 있는 상태입니다.","keywords":["경제적 안정"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-02","grade":"h1"},
{"id":"soc-h-c1-02#t7","kind":"term","title":"이스털린의 역설","text":"소득이 일정 수준을 넘으면 소득이 늘어도 행복감이 그만큼 늘지 않는 현상을 가리키는 말입니다.","keywords":["이스털린의 역설"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-02","grade":"h1"},
{"id":"soc-h-c1-02#t8","kind":"term","title":"성찰","text":"자신의 말과 행동, 삶을 돌아보며 잘잘못을 살피고 더 나은 방향을 찾는 것입니다.","keywords":["성찰"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-02","grade":"h1"},
{"id":"soc-h-c1-02#f0","kind":"faq","title":"돈이 많으면 무조건 행복한 거 아니에요?","text":"돈은 기본적인 필요를 채우고 미래의 불안을 줄여 주므로 행복에 분명히 중요합니다. 하지만 기본적 필요가 채워진 뒤에는 돈이 늘어도 행복이 늘어나는 폭이 점점 작아지는 경향이 있습니다. 소득 격차, 불안한 일자리, 나쁜 환경, 인간관계 같은 다른 조건도 행복에 큰 영향을 줍니다.","keywords":["행복"],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-02","grade":"h1"},
{"id":"soc-h-c1-02#f1","kind":"faq","title":"정주 환경이랑 주거 환경은 같은 말이에요?","text":"비슷하지만 정주 환경이 더 넓은 말입니다. 주거 환경이 주로 집 자체를 가리킨다면, 정주 환경은 집과 함께 주변의 편의 시설, 교통, 안전, 이웃 관계까지 포함한 \"자리 잡고 사는 곳의 환경 전체\"를 가리킵니다.","keywords":["정주 환경"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-02","grade":"h1"},
{"id":"soc-h-c1-02#f2","kind":"faq","title":"시대마다 행복의 기준이 다르면, 정답 같은 행복은 없는 건가요?","text":"행복의 구체적인 기준은 시대와 지역에 따라 다르지만, 많은 사상가와 사회는 공통된 조건도 찾아냈습니다. 안전하고 쾌적한 삶터, 경제적 안정, 자유와 참여가 보장되는 사회, 그리고 남을 배려하고 자신을 돌아보는 삶입니다. 다양성을 존중하면서도 이런 공통 조건을 함께 갖추어 가는 것이 중요합니다.","keywords":["행복"],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-02","grade":"h1"},
{"id":"soc-h-c1-02#m0","kind":"mistake","title":"자주 하는 실수","text":"\"소득이 늘면 행복도 같은 비율로 계속 늘어난다\"고 생각하는 실수 — 기본적 필요가 채워진 뒤에는 행복이 늘어나는 폭이 작아집니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-02","grade":"h1"},
{"id":"soc-h-c1-02#m1","kind":"mistake","title":"자주 하는 실수","text":"유교·불교·도가의 행복관을 섞는 실수 — 유교는 인(仁)의 실천, 불교는 집착에서 벗어난 열반, 도가는 무위자연으로 구분합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-02","grade":"h1"},
{"id":"soc-h-c1-02#m2","kind":"mistake","title":"자주 하는 실수","text":"정주 환경을 \"집\"만으로 좁게 이해하는 실수 — 주변의 편의 시설·교통·안전까지 포함합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-02","grade":"h1"},
{"id":"soc-h-c1-03","kind":"unit","title":"자연환경과 인간 생활","text":"기후와 지형 같은 자연환경이 의식주와 생업에 주는 영향을 살피고, 자연환경의 변화와 과학기술의 활용 사례를 통해 인간과 자연환경의 관계를 이해하며, 안전하고 쾌적한 환경에서 살 권리를 알아봅니다. 열대·건조·한대 기후 지역의 의식주와 생업을 기후의 특징과 관련지어 설명할 수 있다. 평야·산지·해안 지역의 생활 모습을 지형과 관련지어 설명할 수 있다. 자연…","keywords":["기후","고상 가옥","스콜","플랜테이션","오아시스","유목","고랭지 농업","환경권","안전권","환경 영향 평가"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-03","grade":"h1"},
{"id":"soc-h-c1-03#c0","kind":"concept","title":"기후와 생활 ① 열대 기후","text":"기온과 강수량 같은 기후는 옷, 음식, 집, 생업 등 사람들의 생활양식에 큰 영향을 줍니다. 열대 기후는 가장 추운 달의 평균 기온도 18 ℃ 이상일 만큼 일 년 내내 덥고, 비가 많이 옵니다. 오후에 짧고 강하게 쏟아지는 소나기(스콜)가 잦습니다. 생활 · 모습과 까닭 옷 · 얇고 바","keywords":["기후","고상 가옥","스콜","플랜테이션"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-03","grade":"h1"},
{"id":"soc-h-c1-03#c1","kind":"concept","title":"기후와 생활 ② 건조 기후와 한대 기후","text":"건조 기후는 비가 내리는 양보다 증발하는 양이 많은 기후로, 연 강수량이 대체로 500 mm 미만입니다. 사막에서는 낮과 밤의 기온 차가 큽니다. 옷: 강한 햇볕과 모래바람을 막는, 온몸을 감싸는 헐렁한 옷 집: 흙벽돌로 벽을 두껍게, 창문은 작게 (낮의 열기와 밤의 추위를 막음), 비","keywords":["기후","오아시스","유목"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-03","grade":"h1"},
{"id":"soc-h-c1-03#c2","kind":"concept","title":"지형과 생활: 평야·산지·해안","text":"땅의 생김새인 지형도 생활에 영향을 줍니다. 지형 · 생활 모습 평야 · 땅이 넓고 평탄하며 하천 주변은 기름져 벼농사 등 농업이 발달. 교통이 편리해 인구가 많이 모이고 도시가 발달 산지 · 경사가 급하고 기온이 낮아 밭농사·목축·임업, 비탈을 깎은 계단식 논밭, 여름에도 서늘한 기후","keywords":["기후","고랭지 농업"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-03","grade":"h1"},
{"id":"soc-h-c1-03#c3","kind":"concept","title":"자연환경의 변화가 바꾼 삶","text":"자연환경은 고정되어 있지 않고 변합니다. 그 변화는 사람들의 삶을 크게 바꾸어 왔습니다. 과거의 사례 마지막 빙하기가 끝나고 기후가 따뜻해지면서 사람들이 농경과 정착 생활을 시작하는 데 영향을 준 것으로 봅니다. 79년 베수비오 화산이 폭발하여 고대 로마의 도시 폼페이가 화산재에 묻혔습","keywords":["기후"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-03","grade":"h1"},
{"id":"soc-h-c1-03#c4","kind":"concept","title":"과학기술로 자연환경을 활용·극복하기와 그 한계","text":"사람들은 과학기술로 자연환경의 제약을 줄이고 자연을 활용해 왔습니다. 건조 지역: 관개 시설, 바닷물을 민물로 바꾸는 해수 담수화 시설로 농업용수·생활용수 확보 극한 기후: 냉난방 기술로 덥거나 추운 곳에서도 생활 지형의 장벽: 터널과 다리로 산과 바다를 넘어 교통망 연결, 간척으로 땅","keywords":["기후"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-03","grade":"h1"},
{"id":"soc-h-c1-03#c5","kind":"concept","title":"안전하고 쾌적한 환경에서 살 권리","text":"자연환경이 위협받고 재해가 잦아지면서, 안전하고 쾌적한 환경에서 사는 것은 누구나 누려야 할 권리로 여겨지게 되었습니다. 환경권: 건강하고 쾌적한 환경에서 생활할 권리입니다. 우리나라 헌법 제35조는 \"모든 국민은 건강하고 쾌적한 환경에서 생활할 권리를 가지며, 국가와 국민은 환경 보전","keywords":["환경권","안전권","환경 영향 평가"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-03","grade":"h1"},
{"id":"soc-h-c1-03#t0","kind":"term","title":"기후","text":"한 지역에서 오랜 기간에 걸쳐 나타나는 평균적인 대기 상태입니다. 날마다 바뀌는 날씨와 구분됩니다.","keywords":["기후"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-03","grade":"h1"},
{"id":"soc-h-c1-03#t1","kind":"term","title":"고상 가옥","text":"바닥을 땅에서 띄워 지은 집입니다. 열대 지역에서는 땅의 열기·습기·해충을 피하려고 짓습니다.","keywords":["고상 가옥"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-03","grade":"h1"},
{"id":"soc-h-c1-03#t2","kind":"term","title":"스콜","text":"열대 지역에서 주로 오후에 짧은 시간 동안 강하게 쏟아지는 소나기입니다.","keywords":["스콜"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-03","grade":"h1"},
{"id":"soc-h-c1-03#t3","kind":"term","title":"플랜테이션","text":"열대 지역에서 커피·카카오·천연고무 같은 작물을 대규모로 재배하는 농업 방식입니다.","keywords":["플랜테이션"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-03","grade":"h1"},
{"id":"soc-h-c1-03#t4","kind":"term","title":"오아시스","text":"사막에서 물을 얻을 수 있는 곳입니다. 주변에 마을이 생기고 대추야자·밀 등을 재배합니다.","keywords":["오아시스"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-03","grade":"h1"},
{"id":"soc-h-c1-03#t5","kind":"term","title":"유목","text":"물과 풀을 찾아 가축을 몰고 옮겨 다니며 사는 생활입니다. 건조 지역에서는 양·염소·낙타, 한대 지역에서는 순록을 기릅니다.","keywords":["유목"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-03","grade":"h1"},
{"id":"soc-h-c1-03#t6","kind":"term","title":"고랭지 농업","text":"해발 고도가 높아 여름에도 서늘한 산지의 기후를 이용해 배추·무 등을 재배하는 농업입니다.","keywords":["고랭지 농업"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-03","grade":"h1"},
{"id":"soc-h-c1-03#t7","kind":"term","title":"환경권","text":"건강하고 쾌적한 환경에서 생활할 권리입니다. 우리나라 헌법 제35조에 정해져 있습니다.","keywords":["환경권"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-03","grade":"h1"},
{"id":"soc-h-c1-03#t8","kind":"term","title":"안전권","text":"재난·사고 같은 위험으로부터 생명과 신체를 보호받으며 안전하게 살 권리입니다.","keywords":["안전권"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-03","grade":"h1"},
{"id":"soc-h-c1-03#t9","kind":"term","title":"환경 영향 평가","text":"개발 사업을 하기 전에 그 사업이 환경에 미칠 영향을 미리 조사·예측·평가해 피해를 줄이는 제도입니다.","keywords":["환경 영향 평가"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-03","grade":"h1"},
{"id":"soc-h-c1-03#f0","kind":"faq","title":"사막은 더운데 왜 긴 옷을 입어요?","text":"사막은 햇볕이 아주 강하고 모래바람이 붑니다. 피부를 드러내면 햇볕에 화상을 입거나 수분을 빼앗기기 쉽습니다. 온몸을 가리는 헐렁한 옷은 햇볕과 모래를 막고, 옷과 몸 사이로 공기가 통해 땀이 잘 마르게 해 줍니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-03","grade":"h1"},
{"id":"soc-h-c1-03#f1","kind":"faq","title":"고상 가옥은 열대 지역에만 있어요?","text":"아닙니다. 바닥을 띄워 짓는 방식은 목적에 따라 다른 기후 지역에서도 쓰입니다. 열대 지역에서는 열기·습기·해충을 피하려고, 땅속이 늘 얼어 있는 추운 지역에서는 집의 열이 언 땅을 녹여 집이 기울지 않도록 바닥을 띄웁니다. \"무엇을 피하려고 띄웠는가\"를 보면 구분할 수 있습니다.","keywords":["고상 가옥"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-03","grade":"h1"},
{"id":"soc-h-c1-03#f2","kind":"faq","title":"환경권은 권리인데 왜 국민도 노력해야 해요?","text":"깨끗한 환경은 모두가 함께 쓰는 것이어서 국가 혼자 지킬 수 없습니다. 그래서 헌법 제35조는 국민에게 환경권을 보장하면서 \"국가와 국민은 환경 보전을 위하여 노력하여야 한다\"고 함께 정하고 있습니다.","keywords":["환경권"],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-03","grade":"h1"},
{"id":"soc-h-c1-03#m0","kind":"mistake","title":"자주 하는 실수","text":"고상 가옥을 보면 무조건 열대 지역이라고 단정하는 실수 — 무엇을 피하려고 바닥을 띄웠는지(습기·해충인지, 언 땅이 녹는 것인지)를 확인해야 합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-03","grade":"h1"},
{"id":"soc-h-c1-03#m1","kind":"mistake","title":"자주 하는 실수","text":"기온이 오르면 작물 재배 지역이 남쪽으로 내려간다고 생각하는 실수 — 서늘한 곳을 찾아 북쪽(또는 더 높은 곳)으로 옮겨 갑니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-03","grade":"h1"},
{"id":"soc-h-c1-03#m2","kind":"mistake","title":"자주 하는 실수","text":"과학기술이 자연의 제약을 완전히 없애 준다고 생각하는 실수 — 환경 파괴, 비용, 예측의 한계가 있습니다(예: 아랄해 축소).","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-03","grade":"h1"},
{"id":"soc-h-c1-04","kind":"unit","title":"인간과 자연의 관계","text":"자연을 인간을 위한 도구로 보는 인간 중심주의와 생태계 전체의 가치를 중시하는 생태 중심주의를 비교하고, 생태계 위기를 부른 인간 사회의 모습을 성찰하며 인간과 자연이 공존하는 바람직한 관계를 생각합니다. 인간 중심주의 자연관과 생태 중심주의 자연관의 특징과 한계를 설명할 수 있다. 갯벌 개발, 댐 건설 같은 사례에 두 자연관을 적용해 비교할 수 있다. …","keywords":["자연관","인간 중심주의","생태 중심주의","도구적 가치","이분법적 세계관","전체론적 관점","대지 윤리","환경 파시즘","생태 통로"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-04","grade":"h1"},
{"id":"soc-h-c1-04#c0","kind":"concept","title":"인간 중심주의 자연관","text":"인간 중심주의는 인간만이 고유한 가치(본래적 가치)를 지니며, 자연은 인간의 필요를 채워 주는 도구적 가치를 지닌다고 보는 자연관입니다. 이성을 지닌 인간만이 도덕적으로 고려할 대상이라고 봅니다. 이분법적 세계관: 인간과 자연을 뚜렷이 나누고, 인간을 자연보다 우월한 존재로 봅니다. 대","keywords":["자연관","인간 중심주의","도구적 가치","이분법적 세계관"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-04","grade":"h1"},
{"id":"soc-h-c1-04#c1","kind":"concept","title":"생태 중심주의 자연관","text":"생태 중심주의는 도덕적 고려의 범위를 인간과 동식물을 넘어 흙·물·공기 같은 무생물까지 포함한 생태계 전체로 넓히는 자연관입니다. 전체론적 관점: 생태계를 구성 요소들이 서로 의존하며 이루는 하나의 전체로 봅니다. 개체 하나하나보다 생태계 전체의 균형과 안정을 중시합니다. 대표 사상: ","keywords":["자연관","생태 중심주의","전체론적 관점","대지 윤리","환경 파시즘"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-04","grade":"h1"},
{"id":"soc-h-c1-04#c2","kind":"concept","title":"두 관점을 사례에 적용하기: 갯벌 개발과 댐 건설","text":"같은 개발 계획도 어떤 자연관으로 보느냐에 따라 판단이 달라집니다. 사례 · 인간 중심주의의 시각 · 생태 중심주의의 시각 갯벌 개발(간척) · 갯벌을 메워 농경지·산업 용지를 얻으면 경제적 이익이 크다 · 갯벌은 수많은 생물의 서식지이자 철새가 쉬어 가는 곳이며, 오염 물질을 걸러 주","keywords":["자연관","인간 중심주의","생태 중심주의"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-04","grade":"h1"},
{"id":"soc-h-c1-04#c3","kind":"concept","title":"생태계 위기를 부른 인간 사회 돌아보기","text":"오늘날 기후 변화, 생물 다양성 감소, 환경 오염 같은 생태계 위기는 저절로 생긴 것이 아니라 인간 사회의 모습과 깊이 관련되어 있습니다. 대량 생산·대량 소비·대량 폐기: 산업화 이후 물건을 많이 만들고, 많이 쓰고, 많이 버리는 생활 방식이 자원 고갈과 쓰레기 문제를 낳았습니다. 화","keywords":["자연관"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-04","grade":"h1"},
{"id":"soc-h-c1-04#c4","kind":"concept","title":"인간과 자연의 공존을 위하여","text":"인간도 자연의 일부이며 자연에 기대어 살아갑니다. 그래서 인간과 자연이 함께 살아가는 공존의 관계를 만들어야 합니다. 자연을 바라보는 태도 자연을 쓸모로만 보지 않고 그 자체의 가치를 존중합니다. 인간과 자연이 서로 의존한다는 것을 인정합니다. 동양 전통 사상에도 이런 생각이 담겨 있습","keywords":[],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-04","grade":"h1"},
{"id":"soc-h-c1-04#t0","kind":"term","title":"자연관","text":"자연을 어떤 존재로 보고, 인간과 자연의 관계를 어떻게 이해하는지에 대한 관점입니다.","keywords":["자연관"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-04","grade":"h1"},
{"id":"soc-h-c1-04#t1","kind":"term","title":"인간 중심주의","text":"인간만이 고유한 가치를 지니고, 자연은 인간을 위한 도구적 가치를 지닌다고 보는 자연관입니다.","keywords":["인간 중심주의"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-04","grade":"h1"},
{"id":"soc-h-c1-04#t2","kind":"term","title":"생태 중심주의","text":"무생물까지 포함한 생태계 전체를 도덕적 고려 대상으로 보고, 생태계의 균형과 안정을 중시하는 자연관입니다.","keywords":["생태 중심주의"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-04","grade":"h1"},
{"id":"soc-h-c1-04#t3","kind":"term","title":"도구적 가치","text":"다른 목적을 이루는 수단으로서 지니는 가치입니다. 예: 목재를 얻는 수단으로서 숲의 가치","keywords":["도구적 가치"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-04","grade":"h1"},
{"id":"soc-h-c1-04#t4","kind":"term","title":"이분법적 세계관","text":"인간과 자연, 정신과 물질처럼 세계를 둘로 뚜렷이 나누어 보는 관점입니다.","keywords":["이분법적 세계관"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-04","grade":"h1"},
{"id":"soc-h-c1-04#t5","kind":"term","title":"전체론적 관점","text":"부분보다 부분들이 서로 의존하며 이루는 전체를 중시하는 관점입니다. 생태 중심주의의 특징입니다.","keywords":["전체론적 관점"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-04","grade":"h1"},
{"id":"soc-h-c1-04#t6","kind":"term","title":"대지 윤리","text":"레오폴드가 주장한 윤리입니다. 흙·물·동식물을 포함한 대지를 하나의 공동체로 보고, 인간은 그 평범한 구성원이라고 봅니다.","keywords":["대지 윤리"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-04","grade":"h1"},
{"id":"soc-h-c1-04#t7","kind":"term","title":"환경 파시즘","text":"생태계 전체를 위해 개체(개인)의 희생을 정당화할 수 있다는 점을 들어 생태 중심주의를 비판하는 말입니다.","keywords":["환경 파시즘"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-04","grade":"h1"},
{"id":"soc-h-c1-04#t8","kind":"term","title":"생태 통로","text":"도로나 철도 등으로 끊긴 서식지를 이어 야생 동물이 안전하게 오갈 수 있도록 만든 길입니다.","keywords":["생태 통로"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-04","grade":"h1"},
{"id":"soc-h-c1-04#f0","kind":"faq","title":"인간 중심주의는 무조건 나쁜 거예요?","text":"그렇지 않습니다. 인간 중심주의는 과학기술의 발전과 물질적 풍요에 이바지하였고, 인간의 이익을 위해서라도 자연을 아껴 써야 한다는 주장도 할 수 있습니다. 다만 자연을 도구로만 보면 무분별한 개발을 정당화할 수 있다는 한계가 있으므로, 그 한계를 알고 보완하는 것이 중요합니다.","keywords":["인간 중심주의"],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-04","grade":"h1"},
{"id":"soc-h-c1-04#f1","kind":"faq","title":"생태 중심주의대로라면 사람이 자연을 하나도 쓰면 안 되나요?","text":"생태 중심주의도 인간이 자연을 이용하는 것 자체를 모두 금지하지는 않습니다. 생태계 전체의 균형과 안정을 해치지 않는 범위에서 이용해야 한다는 것입니다. 다만 그 기준을 지나치게 적용하면 인간의 생존과 생계를 가볍게 여긴다는 비판을 받을 수 있습니다.","keywords":["생태 중심주의"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-04","grade":"h1"},
{"id":"soc-h-c1-04#f2","kind":"faq","title":"생태 중심주의랑 생명 중심주의는 뭐가 달라요?","text":"생명 중심주의는 모든 생명체 하나하나를 도덕적 고려의 대상으로 봅니다. 생태 중심주의는 여기에 흙·물·공기 같은 무생물까지 더해 생태계 전체를 대상으로 보고, 개체보다 전체의 균형을 중시합니다.","keywords":["생태 중심주의"],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-04","grade":"h1"},
{"id":"soc-h-c1-04#m0","kind":"mistake","title":"자주 하는 실수","text":"인간을 위한 이유로 자연을 보전하자는 주장을 무조건 생태 중심주의로 고르는 실수 — \"결국 사람에게 이익이 되니까\" 보전하자는 것은 인간 중심주의의 근거입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-04","grade":"h1"},
{"id":"soc-h-c1-04#m1","kind":"mistake","title":"자주 하는 실수","text":"생태 중심주의가 생물만 고려한다고 생각하는 실수 — 흙·물·공기 같은 무생물까지 포함한 생태계 전체를 고려합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-04","grade":"h1"},
{"id":"soc-h-c1-04#m2","kind":"mistake","title":"자주 하는 실수","text":"바람직한 관계를 \"자연을 전혀 이용하지 않는 것\"으로 이해하는 실수 — 생태계가 회복할 수 있는 범위에서 신중하게 이용하는 공존이 목표입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-04","grade":"h1"},
{"id":"soc-h-c1-05","kind":"unit","title":"환경 문제와 생태시민","text":"환경 문제가 왜 한 사람·한 나라의 힘만으로 풀기 어려운지 살피고, 정부·시민단체·기업의 노력과 생태시민으로서 일상에서 실천할 일을 알아봅니다. 환경 문제의 특징(넓은 피해 범위, 오래가는 영향, 국경을 넘는 피해)을 설명할 수 있다. 환경 문제를 해결하려는 정부·시민단체·기업의 노력을 구분하여 설명할 수 있다. 주요 국제 환경 협약의 목적을 말할 수 있…","keywords":["환경 문제","환경 영향 평가","배출권 거래제","국제 환경 협약","시민단체","ESG 경영","그린워싱","탄소 중립","생태시민","녹색 소비"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-05","grade":"h1"},
{"id":"soc-h-c1-05#c0","kind":"concept","title":"환경 문제의 특징","text":"환경 문제란 인간의 활동으로 자연환경이 오염되거나 훼손되어 인간과 다른 생물의 삶이 위협받는 문제입니다. 대기 오염, 수질 오염, 토양 오염, 쓰레기 문제, 기후 변화, 생물 다양성 감소 등이 있습니다. 환경 문제에는 다른 사회 문제와 구별되는 특징이 있습니다. 특징 · 뜻 · 예 넓은","keywords":["환경 문제"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-05","grade":"h1"},
{"id":"soc-h-c1-05#c1","kind":"concept","title":"정부의 노력 ① 환경 법과 제도","text":"정부는 법과 제도를 만들어 환경을 오염시키는 행동을 막고, 환경을 지키는 행동을 북돋웁니다. 환경 영향 평가 제도: 도로·댐·공장 같은 큰 개발 사업을 하기 전에 그 사업이 환경에 미칠 영향을 미리 조사·예측·평가하고, 나쁜 영향을 줄이는 방안을 마련하게 하는 제도입니다. 피해가 생긴 ","keywords":["환경 영향 평가","배출권 거래제"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-05","grade":"h1"},
{"id":"soc-h-c1-05#c2","kind":"concept","title":"정부의 노력 ② 국제 환경 협약 참여","text":"국경을 넘는 환경 문제는 한 나라의 법만으로는 해결할 수 없으므로, 여러 나라가 국제 환경 협약을 맺어 함께 지킬 약속을 정합니다. 정부는 협약에 가입하고 그 내용을 나라 안의 법과 정책에 반영합니다. 협약 · 채택 · 주요 내용 람사르 협약 · 1971년 · 물새 서식지로 중요한 습지","keywords":["환경 문제","국제 환경 협약"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-05","grade":"h1"},
{"id":"soc-h-c1-05#c3","kind":"concept","title":"시민단체의 노력","text":"시민단체는 시민들이 자발적으로 모여 공익(사회 전체의 이익)을 위해 활동하는 단체입니다. 이윤을 추구하지 않고, 정부에 속하지도 않습니다. 환경 분야에서 시민단체는 다음과 같은 일을 합니다. 환경 감시: 정부의 정책과 기업의 활동이 환경을 해치지 않는지 감시하고 문제를 알립니다. 예를 ","keywords":["환경 문제","환경 영향 평가","시민단체"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-05","grade":"h1"},
{"id":"soc-h-c1-05#c4","kind":"concept","title":"기업의 노력: 친환경 경영과 ESG 경영","text":"기업은 물건을 만들고 파는 과정에서 자원을 쓰고 오염 물질을 내보내므로 환경에 큰 영향을 줍니다. 그래서 기업의 노력이 중요합니다. 친환경 경영은 생산·유통·판매·폐기의 모든 과정에서 환경에 주는 피해를 줄이는 경영입니다. 오염 물질 배출을 줄이는 설비를 갖추고, 재생 에너지를 씁니다.","keywords":["ESG 경영"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-05","grade":"h1"},
{"id":"soc-h-c1-05#c5","kind":"concept","title":"생태전환적 사고와 생태시민","text":"정부·시민단체·기업의 노력만으로는 부족합니다. 결국 사회를 이루는 한 사람 한 사람의 생각과 생활이 바뀌어야 합니다. 생태전환적 사고란 인간을 자연을 마음대로 쓰는 주인이 아니라 생태계를 이루는 한 구성원으로 보고, 생산·소비·이동 같은 삶의 방식과 사회의 구조를 생태계가 지속될 수 있","keywords":["시민단체","생태시민","녹색 소비"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-05","grade":"h1"},
{"id":"soc-h-c1-05#t0","kind":"term","title":"환경 문제","text":"인간의 활동으로 자연환경이 오염되거나 훼손되어 인간과 다른 생물의 삶이 위협받는 문제입니다. 예: 대기 오염, 기후 변화","keywords":["환경 문제"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-05","grade":"h1"},
{"id":"soc-h-c1-05#t1","kind":"term","title":"환경 영향 평가","text":"큰 개발 사업을 하기 전에 그 사업이 환경에 미칠 영향을 미리 조사·예측·평가하여 피해를 줄이는 방안을 마련하게 하는 제도입니다.","keywords":["환경 영향 평가"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-05","grade":"h1"},
{"id":"soc-h-c1-05#t2","kind":"term","title":"배출권 거래제","text":"기업마다 온실가스를 배출할 수 있는 양을 나누어 주고, 남거나 모자란 양을 서로 사고팔게 하는 제도입니다.","keywords":["배출권 거래제"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-05","grade":"h1"},
{"id":"soc-h-c1-05#t3","kind":"term","title":"국제 환경 협약","text":"국경을 넘는 환경 문제를 함께 해결하기 위해 여러 나라가 맺은 약속입니다. 예: 람사르 협약, 몬트리올 의정서, 파리 협정","keywords":["국제 환경 협약"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-05","grade":"h1"},
{"id":"soc-h-c1-05#t4","kind":"term","title":"시민단체","text":"시민들이 자발적으로 모여 공익을 위해 활동하는 단체입니다. 이윤을 추구하지 않고 정부에 속하지 않습니다.","keywords":["시민단체"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-05","grade":"h1"},
{"id":"soc-h-c1-05#t5","kind":"term","title":"ESG 경영","text":"기업이 이윤뿐 아니라 환경(E), 사회(S), 지배 구조(G)를 함께 고려하는 경영입니다.","keywords":["ESG 경영"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-05","grade":"h1"},
{"id":"soc-h-c1-05#t6","kind":"term","title":"그린워싱","text":"실제로는 친환경적이지 않으면서 광고나 포장으로 친환경인 척하는 것입니다. 위장 환경주의라고도 합니다.","keywords":["그린워싱"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-05","grade":"h1"},
{"id":"soc-h-c1-05#t7","kind":"term","title":"탄소 중립","text":"온실가스 배출량과 흡수·제거량을 같게 하여 실제 배출량을 0으로 만드는 것입니다.","keywords":["탄소 중립"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-05","grade":"h1"},
{"id":"soc-h-c1-05#t8","kind":"term","title":"생태시민","text":"지구 생태계의 한 구성원으로서 지역·국가를 넘어 미래 세대와 다른 생명까지 생각하며 책임 있게 실천하는 시민입니다.","keywords":["생태시민"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-05","grade":"h1"},
{"id":"soc-h-c1-05#t9","kind":"term","title":"녹색 소비","text":"환경을 생각하며 물건을 고르고 쓰는 소비입니다. 필요한 만큼 사기, 오래 쓰기, 친환경 제품 고르기 등이 있습니다.","keywords":["녹색 소비"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-05","grade":"h1"},
{"id":"soc-h-c1-05#f0","kind":"faq","title":"나 하나 실천한다고 정말 달라지나요?","text":"한 사람의 실천이 만드는 변화는 작아 보입니다. 하지만 많은 사람이 같은 선택을 하면 기업은 친환경 제품을 더 만들고, 정부는 그런 요구를 정책에 반영합니다. 또 실천은 습관이 되어 다른 사람에게도 퍼집니다. 그래서 생태시민은 개인의 실천과 함께 제도를 바꾸는 참여도 중요하게 여깁니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-05","grade":"h1"},
{"id":"soc-h-c1-05#f1","kind":"faq","title":"시민단체랑 정부는 뭐가 달라요?","text":"정부는 법을 만들고 집행하는 권한을 가진 공적 기관입니다. 시민단체는 시민들이 스스로 모여 만든 단체로, 법을 만들 권한은 없지만 정부와 기업을 감시하고, 캠페인을 벌이고, 정책을 제안하여 영향을 줍니다. 둘 다 공익을 위해 일하지만 방법과 위치가 다릅니다.","keywords":["시민단체"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-05","grade":"h1"},
{"id":"soc-h-c1-05#f2","kind":"faq","title":"교토 의정서랑 파리 협정은 뭐가 달라요?","text":"두 협약 모두 온실가스를 줄이기 위한 약속입니다. 1997년 교토 의정서는 선진국에만 감축 의무를 지웠고, 2015년 파리 협정은 선진국과 개발 도상국이 모두 감축에 참여하도록 하였습니다. 참여 범위가 넓어졌다는 점이 가장 큰 차이입니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-05","grade":"h1"},
{"id":"soc-h-c1-05#m0","kind":"mistake","title":"자주 하는 실수","text":"환경 영향 평가를 \"피해가 난 뒤에 조사하는 제도\"로 아는 실수 — 개발 사업을 하기 전에 미리 평가하는 예방 제도입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-05","grade":"h1"},
{"id":"soc-h-c1-05#m1","kind":"mistake","title":"자주 하는 실수","text":"교토 의정서와 파리 협정을 헷갈리는 실수 — 선진국만 감축 의무(교토, 1997년), 모든 나라 참여(파리, 2015년)로 구분합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-05","grade":"h1"},
{"id":"soc-h-c1-05#m2","kind":"mistake","title":"자주 하는 실수","text":"ESG의 G를 \"정부(Government)\"로 아는 실수 — G는 기업의 지배 구조(Governance)입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-05","grade":"h1"},
{"id":"soc-h-c1-06","kind":"unit","title":"세계의 다양한 문화권","text":"문화권의 의미와 나누는 기준을 알고, 기후·지형 같은 자연환경과 종교·산업 같은 인문환경이 만들어 낸 세계 여러 문화권의 특징과 문화권의 경계(점이 지대)를 살펴봅니다. 문화권의 의미와 문화권을 나누는 기준을 설명할 수 있다. 기후·지형 같은 자연환경이 의식주 문화에 준 영향을 사례로 설명할 수 있다. 종교·산업 같은 인문환경이 생활 모습에 준 영향을 사…","keywords":["문화","문화권","자연환경","인문환경","고상 가옥","유목","할랄","모스크","점이 지대"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-06","grade":"h1"},
{"id":"soc-h-c1-06#c0","kind":"concept","title":"문화와 문화권","text":"문화는 한 사회의 구성원들이 함께 만들고 나누며 배워서 물려주는 생활 양식입니다. 의식주, 언어, 종교, 관습, 예술 등이 모두 문화에 들어갑니다. 문화권은 공통된 문화 특성이 나타나는 공간적 범위입니다. 같은 문화권에 사는 사람들은 비슷한 생활 방식과 가치관을 보이는 경우가 많습니다.","keywords":["문화","문화권","자연환경","인문환경"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-06","grade":"h1"},
{"id":"soc-h-c1-06#c1","kind":"concept","title":"자연환경과 의식주 문화","text":"사람들은 자기가 사는 곳의 기후와 지형에 맞추어 옷을 입고, 음식을 구하고, 집을 지었습니다. 그래서 자연환경이 다르면 의식주 문화도 달라집니다. 환경 · 옷 · 음식 · 집 열대 (덥고 비가 많음) · 얇고 바람이 잘 통하는 옷 · 쌀(벼농사), 음식이 쉽게 상하지 않게 향신료 사용 ","keywords":["문화","자연환경","고상 가옥","유목"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-06","grade":"h1"},
{"id":"soc-h-c1-06#c2","kind":"concept","title":"인문환경과 생활 모습: 종교와 산업","text":"자연환경만으로 문화가 정해지지는 않습니다. 비슷한 기후에서도 종교와 산업이 다르면 생활 모습이 달라집니다. 종교는 음식, 옷, 건축, 하루와 일 년의 생활 리듬에 큰 영향을 줍니다. 종교 · 생활에 나타나는 모습 크리스트교 · 교회와 십자가, 일요일 예배, 크리스마스·부활절 이슬람교 ·","keywords":["문화","자연환경","인문환경","할랄","모스크"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-06","grade":"h1"},
{"id":"soc-h-c1-06#c3","kind":"concept","title":"세계 문화권의 구분과 특징","text":"세계의 문화권은 기준에 따라 여러 가지로 나눌 수 있습니다. 자연환경과 종교·언어 등을 함께 고려하면 흔히 다음과 같이 나눕니다. 문화권 · 주요 특징 동아시아 · 한자, 유교·불교, 젓가락, 계절풍 기후의 벼농사 동남아시아 · 벼농사, 불교·이슬람교·크리스트교 등 다양한 종교, 중국·","keywords":["문화","문화권","자연환경","유목"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-06","grade":"h1"},
{"id":"soc-h-c1-06#c4","kind":"concept","title":"문화권의 경계와 점이 지대","text":"문화권의 경계는 선 하나로 딱 나뉘지 않습니다. 서로 다른 문화권이 만나는 곳에서는 두 문화의 특성이 함께 나타나거나 섞이는 지역이 생깁니다. 이런 지역을 점이 지대라고 합니다. 대표적인 예가 아프리카 사하라 사막 남쪽 가장자리(사헬 지대) 입니다. 북쪽의 건조 문화권과 남쪽의 아프리카","keywords":["문화","문화권","유목","점이 지대"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-06","grade":"h1"},
{"id":"soc-h-c1-06#t0","kind":"term","title":"문화","text":"한 사회의 구성원들이 함께 만들고 나누며 배워서 물려주는 생활 양식입니다. 의식주, 언어, 종교, 관습 등이 포함됩니다.","keywords":["문화"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-06","grade":"h1"},
{"id":"soc-h-c1-06#t1","kind":"term","title":"문화권","text":"공통된 문화 특성이 나타나는 공간적 범위입니다. 언어, 종교, 의식주, 산업 등을 기준으로 나눕니다.","keywords":["문화권"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-06","grade":"h1"},
{"id":"soc-h-c1-06#t2","kind":"term","title":"자연환경","text":"기후, 지형, 식생처럼 자연이 만든 환경입니다. 의식주 문화에 큰 영향을 줍니다.","keywords":["자연환경"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-06","grade":"h1"},
{"id":"soc-h-c1-06#t3","kind":"term","title":"인문환경","text":"종교, 언어, 산업, 역사처럼 사람이 만든 환경입니다.","keywords":["인문환경"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-06","grade":"h1"},
{"id":"soc-h-c1-06#t4","kind":"term","title":"고상 가옥","text":"땅의 습기와 해충을 피하고 바람이 잘 통하게 바닥을 땅에서 띄워 지은 집입니다. 덥고 습한 열대 지역에서 볼 수 있습니다.","keywords":["고상 가옥"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-06","grade":"h1"},
{"id":"soc-h-c1-06#t5","kind":"term","title":"유목","text":"가축을 데리고 물과 풀을 찾아 옮겨 다니며 사는 생활 방식입니다. 건조 지역에서 많이 볼 수 있습니다.","keywords":["유목"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-06","grade":"h1"},
{"id":"soc-h-c1-06#t6","kind":"term","title":"할랄","text":"이슬람교의 율법에 따라 먹거나 쓰는 것이 허용된 것을 말합니다. 할랄 음식에는 돼지고기와 술이 들어가지 않습니다.","keywords":["할랄"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-06","grade":"h1"},
{"id":"soc-h-c1-06#t7","kind":"term","title":"모스크","text":"이슬람교의 예배당입니다. 둥근 지붕과 뾰족한 탑(첨탑)이 특징입니다.","keywords":["모스크"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-06","grade":"h1"},
{"id":"soc-h-c1-06#t8","kind":"term","title":"점이 지대","text":"서로 다른 문화권이 만나는 곳에서 두 문화의 특성이 함께 나타나거나 섞이는 지역입니다. 예: 사하라 사막 남쪽의 사헬 지대","keywords":["점이 지대"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-06","grade":"h1"},
{"id":"soc-h-c1-06#f0","kind":"faq","title":"문화권은 왜 나누는 사람마다 조금씩 달라요?","text":"어떤 기준을 중요하게 보느냐에 따라 경계가 달라지기 때문입니다. 종교를 기준으로 하면 이슬람교 지역이 하나로 묶이지만, 언어를 기준으로 하면 아랍어 지역과 다른 언어 지역으로 나뉠 수 있습니다. 또 문화권의 경계에는 점이 지대가 있어 선을 딱 긋기 어렵습니다. 그래서 문화권 구분은 정답이 하나인 지도가 아니라, 세계를 이해하기 위한 도구라고 보는 것이 좋…","keywords":["문화","문화권"],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-06","grade":"h1"},
{"id":"soc-h-c1-06#f1","kind":"faq","title":"날씨가 같으면 문화도 같아지나요?","text":"그렇지 않습니다. 자연환경은 의식주에 큰 영향을 주지만, 종교·언어·산업·역사 같은 인문환경이 다르면 생활 모습도 달라집니다. 예를 들어 기후가 비슷한 초원이라도 유목을 하는 곳과 산업화된 도시는 생활 방식이 크게 다릅니다.","keywords":["문화"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-06","grade":"h1"},
{"id":"soc-h-c1-06#f2","kind":"faq","title":"이슬람교는 서남아시아 종교인데 왜 동남아시아에도 신자가 많아요?","text":"종교는 사람이 오가는 길을 따라 퍼집니다. 이슬람교는 서남아시아에서 시작되었지만, 바닷길을 오간 상인들의 교역 등을 통해 동남아시아의 여러 지역으로 전해졌습니다. 그래서 인도네시아·말레이시아처럼 기후는 서남아시아와 전혀 다르지만 이슬람교를 믿는 사람이 많은 나라가 있습니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-06","grade":"h1"},
{"id":"soc-h-c1-06#m0","kind":"mistake","title":"자주 하는 실수","text":"문화권을 기후만으로 나누는 실수 — 언어·종교·산업·역사 같은 인문환경도 중요한 기준입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-06","grade":"h1"},
{"id":"soc-h-c1-06#m1","kind":"mistake","title":"자주 하는 실수","text":"이슬람교와 힌두교의 음식 금기를 헷갈리는 실수 — 이슬람교는 돼지고기, 힌두교는 소고기를 먹지 않습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-06","grade":"h1"},
{"id":"soc-h-c1-06#m2","kind":"mistake","title":"자주 하는 실수","text":"고상 가옥과 흙벽돌집을 헷갈리는 실수 — 비가 많은 열대는 바닥을 띄운 고상 가옥, 비가 적은 건조 지역은 지붕이 평평한 흙벽돌집입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-06","grade":"h1"},
{"id":"soc-h-c1-07","kind":"unit","title":"문화 변동과 전통문화","text":"문화가 바뀌는 까닭(발명·발견·전파)과 서로 다른 문화가 만났을 때 나타나는 동화·병존·융합의 모습을 알고, 문화 변동 속에서 전통문화를 창조적으로 이어 가는 방법을 찾아봅니다. 문화 변동의 내재적 요인(발명·발견)과 외재적 요인(전파)을 구분하여 설명할 수 있다. 문화 접변의 양상인 문화 동화·병존·융합을 사례로 구분할 수 있다. 문화 변동 과정에서 나…","keywords":["문화 변동","발명","발견","전파","자극 전파","문화 접변","문화 동화","문화 병존","문화 융합","창조적 계승"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-07","grade":"h1"},
{"id":"soc-h-c1-07#c0","kind":"concept","title":"문화 변동과 내재적 요인: 발명과 발견","text":"문화는 고정되어 있지 않고 시간이 흐르며 끊임없이 바뀝니다. 이를 문화 변동이라고 합니다. 문화 변동의 요인은 그 사회 안에서 생기는 것(내재적 요인)과 밖에서 들어오는 것(외재적 요인)으로 나눌 수 있습니다. 내재적 요인에는 발명과 발견이 있습니다. 발명: 이전에 없던 새로운 문화 요","keywords":["문화 변동","발명","발견"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-07","grade":"h1"},
{"id":"soc-h-c1-07#c1","kind":"concept","title":"외재적 요인: 전파","text":"전파는 한 사회의 문화 요소가 다른 사회로 전해져 그 사회에 자리 잡는 것입니다. 다른 사회와의 접촉으로 생기므로 외재적 요인입니다. 오늘날 교통과 통신이 발달하면서 전파는 문화 변동의 가장 큰 요인이 되었습니다. 종류 · 뜻 · 예 직접 전파 · 사람들이 직접 만나 접촉하면서 전해짐 ","keywords":["문화 변동","전파","자극 전파"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-07","grade":"h1"},
{"id":"soc-h-c1-07#c2","kind":"concept","title":"문화 접변의 양상: 동화·병존·융합","text":"서로 다른 두 문화가 오랫동안 접촉하여 한쪽 또는 양쪽 문화가 바뀌는 현상을 문화 접변이라고 합니다. 문화 접변의 결과는 크게 세 가지로 나타납니다. 양상 · 뜻 · 예 문화 동화 · 한 문화가 다른 문화에 흡수되어 고유한 특성을 잃음 · 식민 지배를 받은 라틴 아메리카의 일부 원주민이","keywords":["문화 접변","문화 동화","문화 병존","문화 융합"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-07","grade":"h1"},
{"id":"soc-h-c1-07#c3","kind":"concept","title":"문화 변동 과정의 문제","text":"문화 변동은 생활을 풍요롭게 하지만, 변화가 빠르고 일방적일 때에는 문제가 생기기도 합니다. 전통문화의 약화: 외래문화가 빠르게 들어오면서 고유한 생활 방식, 놀이, 의례, 기술 등이 잊히거나 사라질 수 있습니다. 전통 기술을 이어받을 사람이 줄어드는 것이 한 예입니다. 문화 정체성 혼","keywords":["문화 변동"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-07","grade":"h1"},
{"id":"soc-h-c1-07#c4","kind":"concept","title":"전통문화의 의의와 창조적 계승","text":"전통문화는 한 사회에서 오랫동안 이어져 내려와 그 구성원들이 가치 있게 여기는 문화입니다. 현대 사회에서도 전통문화는 여러 의의가 있습니다. 정체성과 소속감: 우리가 누구인지 알려 주고, 구성원을 하나로 묶어 줍니다. 문화 다양성: 각 사회의 고유한 전통은 세계 문화를 풍부하게 합니다.","keywords":["창조적 계승"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-07","grade":"h1"},
{"id":"soc-h-c1-07#t0","kind":"term","title":"문화 변동","text":"한 사회의 문화가 시간이 흐르면서 새롭게 바뀌는 것입니다. 요인으로 발명·발견(내재적)과 전파(외재적)가 있습니다.","keywords":["문화 변동"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-07","grade":"h1"},
{"id":"soc-h-c1-07#t1","kind":"term","title":"발명","text":"이전에 없던 새로운 문화 요소를 만들어 내는 것입니다. 예: 바퀴, 바퀴의 원리를 응용한 수레","keywords":["발명"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-07","grade":"h1"},
{"id":"soc-h-c1-07#t2","kind":"term","title":"발견","text":"이미 있었지만 알려지지 않았던 사물이나 원리를 찾아내는 것입니다.","keywords":["발견"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-07","grade":"h1"},
{"id":"soc-h-c1-07#t3","kind":"term","title":"전파","text":"한 사회의 문화 요소가 다른 사회로 전해져 자리 잡는 것입니다. 직접 전파, 간접 전파, 자극 전파가 있습니다.","keywords":["전파"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-07","grade":"h1"},
{"id":"soc-h-c1-07#t4","kind":"term","title":"자극 전파","text":"다른 문화의 아이디어에 자극을 받아 새로운 문화 요소를 만들어 내는 것입니다. 예: 한자의 음과 뜻을 빌려 우리말을 적은 이두","keywords":["자극 전파"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-07","grade":"h1"},
{"id":"soc-h-c1-07#t5","kind":"term","title":"문화 접변","text":"서로 다른 두 문화가 오랫동안 접촉하여 한쪽 또는 양쪽 문화가 바뀌는 현상입니다.","keywords":["문화 접변"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-07","grade":"h1"},
{"id":"soc-h-c1-07#t6","kind":"term","title":"문화 동화","text":"한 문화가 다른 문화에 흡수되어 고유한 특성을 잃는 것입니다.","keywords":["문화 동화"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-07","grade":"h1"},
{"id":"soc-h-c1-07#t7","kind":"term","title":"문화 병존","text":"서로 다른 문화가 각각 고유한 특성을 유지하면서 함께 존재하는 것입니다.","keywords":["문화 병존"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-07","grade":"h1"},
{"id":"soc-h-c1-07#t8","kind":"term","title":"문화 융합","text":"서로 다른 문화가 결합하여 이전과 다른 새로운 문화가 생기는 것입니다. 예: 간다라 미술","keywords":["문화 융합"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-07","grade":"h1"},
{"id":"soc-h-c1-07#t9","kind":"term","title":"창조적 계승","text":"전통문화의 정신과 장점을 살리면서 현대 생활에 맞게 새롭게 해석하여 이어 가는 것입니다.","keywords":["창조적 계승"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-07","grade":"h1"},
{"id":"soc-h-c1-07#f0","kind":"faq","title":"문화 병존이랑 문화 융합은 어떻게 구별해요?","text":"\"섞여서 새것이 생겼는가\"를 보면 됩니다. 두 문화가 각자의 모습을 지키며 나란히 있으면 병존이고, 두 문화의 요소가 결합해 이전에 없던 새로운 것이 생겼으면 융합입니다. 한 도시에 전통 사찰과 성당이 각각 있으면 병존, 두 양식을 섞은 새로운 건축 양식이 생기면 융합입니다.","keywords":["문화 병존","문화 융합"],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-07","grade":"h1"},
{"id":"soc-h-c1-07#f1","kind":"faq","title":"자극 전파는 발명이에요, 전파예요?","text":"분류할 때는 전파(외재적 요인)에 넣습니다. 다른 문화와의 접촉에서 시작되었기 때문입니다. 다만 결과로 새로운 것을 만들어 냈다는 점에서 발명의 성격도 함께 지닌다고 설명합니다. 이두가 대표적인 예입니다.","keywords":["발명","전파","자극 전파"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-07","grade":"h1"},
{"id":"soc-h-c1-07#f2","kind":"faq","title":"전통문화를 바꾸면 전통이 망가지는 것 아닌가요?","text":"전통의 정신과 장점을 버리고 겉모습만 따라 하면 그럴 수 있습니다. 하지만 창조적 계승은 전통의 핵심을 살리면서 현대 생활에 맞게 새롭게 해석하는 것입니다. 원형을 보존하는 노력과 함께하면, 전통이 박물관에만 머물지 않고 사람들의 삶 속에서 계속 살아 있게 됩니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-07","grade":"h1"},
{"id":"soc-h-c1-07#m0","kind":"mistake","title":"자주 하는 실수","text":"발명과 발견을 헷갈리는 실수 — 없던 것을 새로 만들면 발명, 원래 있던 것을 찾아내면 발견입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-07","grade":"h1"},
{"id":"soc-h-c1-07#m1","kind":"mistake","title":"자주 하는 실수","text":"자극 전파를 내재적 요인으로 분류하는 실수 — 다른 문화와의 접촉에서 시작되었으므로 외재적 요인(전파)입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-07","grade":"h1"},
{"id":"soc-h-c1-07#m2","kind":"mistake","title":"자주 하는 실수","text":"두 문화가 함께 있기만 해도 융합이라고 하는 실수 — 각자 그대로 있으면 병존, 섞여 새것이 생겨야 융합입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-07","grade":"h1"},
{"id":"soc-h-c1-08","kind":"unit","title":"문화 상대주의와 보편 윤리","text":"지역마다 문화가 다른 까닭을 자연적·사회적 맥락에서 이해하는 문화 상대주의가 왜 필요한지 알고, 극단적 문화 상대주의의 문제를 넘어 보편 윤리에 비추어 자문화와 타문화를 성찰하는 법을 배웁니다. 지역마다 문화 차이가 나타나는 자연적·사회적 맥락을 사례로 설명할 수 있다. 자문화 중심주의·문화 사대주의와 비교하여 문화 상대주의의 필요성과 의의를 설명할 수 …","keywords":["자연적 맥락","사회적 맥락","자문화 중심주의","문화 사대주의","문화 상대주의","극단적 문화 상대주의","보편 윤리","인간 존엄성"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-08","grade":"h1"},
{"id":"soc-h-c1-08#c0","kind":"concept","title":"문화 차이가 나타나는 맥락","text":"지역마다 문화가 다른 데에는 그럴 만한 까닭(맥락) 이 있습니다. 문화는 사람들이 주어진 환경 속에서 살아가기 위해 만들어 온 생활 방식이기 때문입니다. 자연적 맥락 — 기후, 지형, 자원 같은 자연환경 물과 풀을 찾아 가축과 함께 옮겨 다니는 건조 초원의 유목민은 접어서 옮기기 쉬운 ","keywords":["자연적 맥락","사회적 맥락"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-08","grade":"h1"},
{"id":"soc-h-c1-08#c1","kind":"concept","title":"문화를 바라보는 태도와 문화 상대주의","text":"다른 문화를 바라보는 태도에는 크게 세 가지가 있습니다. 태도 · 뜻 · 문제점 또는 의의 자문화 중심주의 · 자기 문화만 우월하다고 여기고 다른 문화를 낮게 평가함 · 사회 통합에 도움을 주기도 하지만, 다른 문화를 무시하여 갈등을 낳고 자기 문화의 발전을 막을 수 있음. 예: 중국 ","keywords":["사회적 맥락","자문화 중심주의","문화 사대주의","문화 상대주의"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-08","grade":"h1"},
{"id":"soc-h-c1-08#c2","kind":"concept","title":"극단적 문화 상대주의의 문제","text":"문화 상대주의를 지나치게 밀고 나가면 \"모든 문화는 그 사회에서 나름의 의미가 있으므로, 어떤 문화도 옳고 그름을 따질 수 없다\"는 생각에 이릅니다. 이를 극단적 문화 상대주의라고 합니다. 극단적 문화 상대주의는 인간의 존엄성과 생명을 해치는 관습까지 \"그 사회의 문화\"라는 이유로 정당","keywords":["문화 상대주의","극단적 문화 상대주의"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-08","grade":"h1"},
{"id":"soc-h-c1-08#c3","kind":"concept","title":"보편 윤리의 의미","text":"보편 윤리는 시대와 지역, 문화의 차이를 넘어 모든 인간이 지켜야 할 도덕적 기준입니다. 문화가 서로 다르더라도 사람이라면 누구나 존중받아야 할 가치가 있다는 생각입니다. 보편 윤리의 핵심 가치는 다음과 같습니다. 인간 존엄성: 모든 사람은 인간이라는 이유만으로 귀하게 대우받아야 합니다","keywords":["문화 상대주의","보편 윤리","인간 존엄성"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-08","grade":"h1"},
{"id":"soc-h-c1-08#c4","kind":"concept","title":"보편 윤리에 비추어 자문화와 타문화 성찰하기","text":"문화를 바르게 평가하려면 문화 상대주의(맥락 속에서 이해하기)와 보편 윤리(존엄성의 기준으로 평가하기)를 함께 써야 합니다. 그 잣대는 다른 문화에만이 아니라 우리 문화에도 똑같이 적용됩니다. 문화를 성찰하고 평가하는 순서 이해하기: 이 문화는 어떤 자연적·사회적 맥락에서 생겼는가? 평","keywords":["사회적 맥락","문화 상대주의","보편 윤리","인간 존엄성"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-08","grade":"h1"},
{"id":"soc-h-c1-08#t0","kind":"term","title":"자연적 맥락","text":"문화 차이를 만든 기후, 지형, 자원 같은 자연환경의 배경입니다.","keywords":["자연적 맥락"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-08","grade":"h1"},
{"id":"soc-h-c1-08#t1","kind":"term","title":"사회적 맥락","text":"문화 차이를 만든 종교, 역사, 산업, 가치관 같은 인문환경의 배경입니다.","keywords":["사회적 맥락"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-08","grade":"h1"},
{"id":"soc-h-c1-08#t2","kind":"term","title":"자문화 중심주의","text":"자기 문화만 우월하다고 여기고 다른 문화를 낮게 평가하는 태도입니다. 예: 중화사상","keywords":["자문화 중심주의"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-08","grade":"h1"},
{"id":"soc-h-c1-08#t3","kind":"term","title":"문화 사대주의","text":"다른 문화를 높이 떠받들고 자기 문화를 낮게 평가하는 태도입니다. 자기 문화의 정체성을 잃을 수 있습니다.","keywords":["문화 사대주의"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-08","grade":"h1"},
{"id":"soc-h-c1-08#t4","kind":"term","title":"문화 상대주의","text":"각 문화를 그 사회의 자연환경과 역사적·사회적 맥락 속에서 이해하려는 태도입니다.","keywords":["문화 상대주의"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-08","grade":"h1"},
{"id":"soc-h-c1-08#t5","kind":"term","title":"극단적 문화 상대주의","text":"모든 문화는 그 사회에서 의미가 있으므로 어떤 문화도 비판할 수 없다고 보는 태도입니다. 인간 존엄성을 해치는 관습까지 정당화하는 오류가 있습니다.","keywords":["극단적 문화 상대주의"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-08","grade":"h1"},
{"id":"soc-h-c1-08#t6","kind":"term","title":"보편 윤리","text":"시대와 지역, 문화의 차이를 넘어 모든 인간이 지켜야 할 도덕적 기준입니다. 인간 존엄성, 생명 존중, 자유, 평등이 핵심입니다.","keywords":["보편 윤리"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-08","grade":"h1"},
{"id":"soc-h-c1-08#t7","kind":"term","title":"인간 존엄성","text":"모든 사람은 인간이라는 이유만으로 귀하게 대우받아야 한다는 가치입니다.","keywords":["인간 존엄성"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-08","grade":"h1"},
{"id":"soc-h-c1-08#f0","kind":"faq","title":"문화 상대주의면 다 이해해 줘야 하는 거 아니에요?","text":"문화 상대주의는 문화를 그 사회의 맥락에서 이해하자는 태도입니다. 하지만 \"무엇이든 옳다\"는 뜻은 아닙니다. 인간 존엄성이나 생명을 해치는 관습까지 인정하면 극단적 문화 상대주의의 오류에 빠집니다. 이해는 하되, 옳은지는 보편 윤리에 비추어 따로 평가해야 합니다.","keywords":["문화 상대주의"],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-08","grade":"h1"},
{"id":"soc-h-c1-08#f1","kind":"faq","title":"보편 윤리라는 것도 결국 어느 한 나라의 기준 아닌가요?","text":"좋은 질문입니다. 보편 윤리는 특정 나라의 생활 방식(음식, 옷, 예절 등)을 따르라는 것이 아닙니다. 인간 존엄성, 생명 존중, 자유, 평등처럼 거의 모든 사회의 사상과 종교에서 공통으로 소중히 여겨 온 아주 기본적인 가치를 말합니다. 그래서 생활 방식의 차이는 존중하고, 이 기본 가치를 해치는 경우만 문제로 삼는 것입니다.","keywords":["보편 윤리"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-08","grade":"h1"},
{"id":"soc-h-c1-08#f2","kind":"faq","title":"자문화 중심주의가 좋은 점도 있어요?","text":"자기 문화에 대한 자부심은 구성원을 하나로 묶어 사회 통합에 도움을 줄 수 있습니다. 하지만 그것이 다른 문화를 낮게 보는 데까지 나아가면 갈등과 차별을 낳고, 다른 문화의 좋은 점을 배우지 못해 자기 문화의 발전도 막습니다. 자부심과 존중은 함께 갈 수 있습니다.","keywords":["자문화 중심주의"],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-08","grade":"h1"},
{"id":"soc-h-c1-08#m0","kind":"mistake","title":"자주 하는 실수","text":"문화 상대주의를 \"모든 관습을 옳다고 인정하는 것\"으로 아는 실수 — 그것은 극단적 문화 상대주의이며, 보편 윤리를 넘어서는 관습은 비판할 수 있습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-08","grade":"h1"},
{"id":"soc-h-c1-08#m1","kind":"mistake","title":"자주 하는 실수","text":"보편 윤리를 다른 문화에만 적용하는 실수 — 자문화에도 똑같이 적용해야 하며, 그러지 않으면 다시 자문화 중심주의가 됩니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-08","grade":"h1"},
{"id":"soc-h-c1-08#m2","kind":"mistake","title":"자주 하는 실수","text":"자문화 중심주의와 문화 사대주의를 거꾸로 아는 실수 — 자기 문화를 높이면 자문화 중심주의, 다른 문화를 높이면 문화 사대주의입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-08","grade":"h1"},
{"id":"soc-h-c1-09","kind":"unit","title":"다문화 사회와 공존","text":"우리 사회가 다문화 사회로 바뀌어 온 배경과 현황을 통계로 읽고, 다문화 사회가 가져온 긍정적 영향과 갈등을 살펴 함께 살아가기 위한 태도와 제도를 찾아봅니다. 다문화 사회의 의미를 알고, 우리나라가 다문화 사회로 바뀐 배경을 설명할 수 있다. 체류 외국인·다문화 가구에 관한 통계 자료를 바르게 읽고 해석할 수 있다. 다문화 사회의 긍정적 영향과 갈등을 …","keywords":["다문화 사회","외국인 근로자","결혼 이민자","다문화 가족","문화 다양성","편견","차별","관용"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-09","grade":"h1"},
{"id":"soc-h-c1-09#c0","kind":"concept","title":"다문화 사회의 의미와 형성 배경","text":"다문화 사회는 인종, 민족, 종교, 언어 등 서로 다른 문화적 배경을 가진 사람들이 한 사회 안에서 함께 살아가는 사회입니다. 세계적 배경: 교통·통신이 발달하고 세계화가 진행되면서 일자리, 결혼, 공부, 여행 등을 위해 국경을 넘어 이동하는 사람이 크게 늘었습니다. 우리나라의 배경 외","keywords":["다문화 사회","외국인 근로자","결혼 이민자"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-09","grade":"h1"},
{"id":"soc-h-c1-09#c1","kind":"concept","title":"우리나라 다문화 사회의 현황과 통계 읽기","text":"우리나라에 머무는 외국인(국내 체류 외국인)은 1990년대 이후 대체로 꾸준히 늘어 2010년대 중반에 200만 명을 넘어섰습니다. 감염병이 크게 유행하던 2020년 무렵에는 국경 이동이 막혀 잠시 줄었다가 다시 늘었습니다. 결혼 이민자나 귀화자가 포함된 다문화 가구도 늘어, 학교에서 ","keywords":["다문화 사회","결혼 이민자"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-09","grade":"h1"},
{"id":"soc-h-c1-09#c2","kind":"concept","title":"다문화 사회의 긍정적 영향","text":"다문화 사회는 우리 사회에 여러 가지 긍정적인 영향을 줍니다. 노동력 보완: 저출산·고령화로 일할 사람이 부족한 제조업, 농어업, 건설업 등에서 외국인 근로자가 일손을 채워 경제 활동을 돕습니다. 문화 다양성 증대: 여러 나라의 음식, 음악, 축제, 생활 방식을 접할 수 있어 삶이 풍부","keywords":["다문화 사회","외국인 근로자","결혼 이민자","문화 다양성"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-09","grade":"h1"},
{"id":"soc-h-c1-09#c3","kind":"concept","title":"다문화 사회의 갈등","text":"다문화 사회에서는 서로 다른 문화를 가진 사람들이 함께 살면서 갈등이 생기기도 합니다. 편견과 차별: 피부색, 출신 국가, 한국어 실력 등을 이유로 사람을 낮추어 보거나(편견) 고용·임금·주거 등에서 불리하게 대우하는 것(차별)입니다. 외국인 근로자가 임금을 제대로 받지 못하거나 다문화","keywords":["다문화 사회","외국인 근로자","편견","차별"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-09","grade":"h1"},
{"id":"soc-h-c1-09#c4","kind":"concept","title":"갈등 해결 방안 — 존중하는 태도와 제도적 지원","text":"다문화 사회의 갈등을 풀고 함께 살아가려면 개인의 태도와 사회의 제도가 함께 바뀌어야 합니다. 개인적 차원 — 문화적 다양성을 존중하는 태도 다른 문화를 그 사회의 맥락에서 이해하는 문화 상대주의의 태도를 갖습니다. 편견을 버리고, 서로 다른 생각과 생활 방식을 너그럽게 받아들이는 관용","keywords":["다문화 사회","외국인 근로자","다문화 가족","편견","관용"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-09","grade":"h1"},
{"id":"soc-h-c1-09#t0","kind":"term","title":"다문화 사회","text":"인종, 민족, 종교, 언어 등 서로 다른 문화적 배경을 가진 사람들이 함께 살아가는 사회입니다.","keywords":["다문화 사회"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-09","grade":"h1"},
{"id":"soc-h-c1-09#t1","kind":"term","title":"외국인 근로자","text":"일자리를 얻어 다른 나라에서 일하는 외국 출신 사람입니다. 이주 노동자라고도 합니다.","keywords":["외국인 근로자"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-09","grade":"h1"},
{"id":"soc-h-c1-09#t2","kind":"term","title":"결혼 이민자","text":"그 나라 국민과 결혼하여 그 나라에 와서 사는 외국 출신 사람입니다.","keywords":["결혼 이민자"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-09","grade":"h1"},
{"id":"soc-h-c1-09#t3","kind":"term","title":"다문화 가족","text":"결혼 이민자나 귀화자 등이 가족 구성원으로 포함된 가족입니다.","keywords":["다문화 가족"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-09","grade":"h1"},
{"id":"soc-h-c1-09#t4","kind":"term","title":"문화 다양성","text":"한 사회 안에 여러 가지 문화가 함께 있는 상태입니다. 삶을 풍부하게 하고 새로운 문화를 만드는 바탕이 됩니다.","keywords":["문화 다양성"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-09","grade":"h1"},
{"id":"soc-h-c1-09#t5","kind":"term","title":"편견","text":"어떤 집단이나 사람에 대해 충분한 근거 없이 갖는 한쪽으로 치우친 생각입니다.","keywords":["편견"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-09","grade":"h1"},
{"id":"soc-h-c1-09#t6","kind":"term","title":"차별","text":"정당한 이유 없이 어떤 사람이나 집단을 불리하게 대우하는 것입니다.","keywords":["차별"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-09","grade":"h1"},
{"id":"soc-h-c1-09#t7","kind":"term","title":"관용","text":"나와 다른 생각이나 생활 방식을 너그럽게 받아들이고 존중하는 태도입니다.","keywords":["관용"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-09","grade":"h1"},
{"id":"soc-h-c1-09#f0","kind":"faq","title":"외국인 근로자가 많아지면 우리 일자리가 줄어드는 거 아니에요?","text":"그렇게 걱정하는 사람들도 있습니다. 하지만 외국인 근로자는 주로 일할 사람을 구하기 어려운 산업에서 부족한 일손을 채우는 경우가 많아, 일자리를 빼앗기보다 산업을 유지하는 데 도움이 된다는 견해가 많습니다. 다만 걱정이 커지면 갈등으로 이어질 수 있으므로, 정확한 정보를 바탕으로 판단하고 제도로 일자리 문제를 함께 살피는 것이 중요합니다.","keywords":["외국인 근로자"],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-09","grade":"h1"},
{"id":"soc-h-c1-09#f1","kind":"faq","title":"편견이랑 차별은 뭐가 달라요?","text":"편견은 충분한 근거 없이 갖는 치우친 생각이고, 차별은 정당한 이유 없이 불리하게 대우하는 행동입니다. \"그 나라 사람들은 게으르다\"는 생각이 편견이고, 그 생각 때문에 채용하지 않는 것이 차별입니다. 편견이 차별로 이어지기 쉬우므로 생각부터 돌아보는 것이 중요합니다.","keywords":["편견","차별"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-09","grade":"h1"},
{"id":"soc-h-c1-09#f2","kind":"faq","title":"통계에서 수가 늘었는데 비율이 줄 수도 있어요?","text":"네, 있습니다. 비율은 \"부분 ÷ 전체\"이므로, 부분이 늘어도 전체가 더 많이 늘면 비율은 줄어듭니다. 예를 들어 전체 100명 중 10명(10%)이던 것이 전체 200명 중 15명이 되면 수는 5명 늘었지만 비율은 7.5%로 줄어듭니다. 그래서 통계를 볼 때는 단위가 수인지 비율인지 먼저 확인해야 합니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-09","grade":"h1"},
{"id":"soc-h-c1-09#m0","kind":"mistake","title":"자주 하는 실수","text":"비율(%) 자료만 보고 사람 수가 늘었다거나 몇 배가 되었다고 단정하는 실수 — 비율은 전체 가운데 차지하는 몫이므로, 실제 수를 알려면 전체 수가 필요합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-09","grade":"h1"},
{"id":"soc-h-c1-09#m1","kind":"mistake","title":"자주 하는 실수","text":"편견과 차별을 같은 것으로 아는 실수 — 편견은 치우친 생각, 차별은 불리하게 대우하는 행동입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-09","grade":"h1"},
{"id":"soc-h-c1-09#m2","kind":"mistake","title":"자주 하는 실수","text":"갈등 해결을 이주민의 적응에만 맡기는 실수 — 기존 주민의 존중하는 태도와 사회의 제도적 지원이 함께 필요합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-09","grade":"h1"},
{"id":"soc-h-c1-10","kind":"unit","title":"산업화·도시화와 생활공간","text":"산업화와 도시화의 의미와 도시화 곡선의 단계를 알고, 이로 인해 생활공간과 생활양식이 어떻게 바뀌었는지, 어떤 문제가 생겼고 어떻게 해결할 수 있는지 살펴봅니다. 산업화와 도시화의 의미를 알고, 도시화 곡선의 단계별 특징을 설명할 수 있다. 산업화·도시화에 따른 거주 공간, 대도시권, 생태환경의 변화를 설명할 수 있다. 도시성의 확산, 직업의 분화, 개인…","keywords":["산업화","도시화","도시화율","이촌 향도","도시화 곡선","대도시권","인구 공동화 현상","열섬 현상","도시성","도시 재생"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-10","grade":"h1"},
{"id":"soc-h-c1-10#c0","kind":"concept","title":"산업화·도시화의 의미와 도시화 곡선","text":"산업화는 농업 중심의 사회가 기계를 이용한 공업과 서비스업 중심의 사회로 바뀌는 과정입니다. 1차 산업(농림어업)의 비중은 줄고 2차 산업(제조업)과 3차 산업(서비스업)의 비중이 커집니다. 도시화는 전체 인구 가운데 도시에 사는 인구의 비율이 높아지고, 도시적인 생활양식이 넓게 퍼지는","keywords":["산업화","도시화","도시화율","이촌 향도","도시화 곡선"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-10","grade":"h1"},
{"id":"soc-h-c1-10#c1","kind":"concept","title":"생활공간의 변화 — 거주 공간·대도시권·생태환경","text":"산업화·도시화는 사람들이 사는 공간의 모습을 크게 바꾸었습니다. 거주 공간의 변화 좁은 땅에 많은 사람이 살게 되면서 단독 주택보다 아파트 같은 고층·밀집 주거가 늘었습니다. 도시 안에서 지역마다 하는 일이 나뉩니다(지역 분화). 교통이 편리하고 땅값이 비싼 도심에는 업무·상업 시설이 ","keywords":["산업화","도시화","대도시권","인구 공동화 현상"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-10","grade":"h1"},
{"id":"soc-h-c1-10#c2","kind":"concept","title":"생활양식의 변화 — 도시성·직업 분화·개인주의","text":"도시화는 사람들이 살아가는 방식, 곧 생활양식도 바꾸었습니다. 도시성의 확산: 도시 특유의 생활 방식과 의식을 도시성이라고 합니다. 많은 사람이 모여 살기 때문에 서로 잘 모르는 익명성이 커지고, 이웃보다 직장·학교·취미처럼 목적에 따라 맺는 관계(2차적 관계)가 중요해집니다. 교통·통","keywords":["도시화","도시성"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-10","grade":"h1"},
{"id":"soc-h-c1-10#c3","kind":"concept","title":"산업화·도시화로 생긴 문제","text":"산업화·도시화는 생활을 편리하게 했지만 여러 문제도 낳았습니다. 환경 오염: 공장과 자동차에서 나오는 오염 물질로 대기·수질 오염이 심해지고, 많은 사람이 모여 살면서 쓰레기가 크게 늘었습니다. 주택 문제: 도시로 사람이 몰리면 집이 모자라 집값과 집세가 오르고, 낡고 열악한 주거 지역","keywords":["산업화","도시화"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-10","grade":"h1"},
{"id":"soc-h-c1-10#c4","kind":"concept","title":"문제 해결을 위한 지역적·국가적 방안","text":"산업화·도시화로 생긴 문제는 지역과 국가가 함께 풀어야 합니다. 지역적 차원 (지방 자치 단체·주민) 도시 계획: 땅을 어디에 어떻게 쓸지 미리 정해 주거·상업·공업·녹지 공간을 알맞게 배치하고, 대중교통을 늘려 교통 혼잡을 줄입니다. 도시 재생: 낡고 쇠퇴한 지역을 모두 허물고 새로 ","keywords":["산업화","도시화","도시 재생"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-10","grade":"h1"},
{"id":"soc-h-c1-10#t0","kind":"term","title":"산업화","text":"농업 중심의 사회가 공업과 서비스업 중심의 사회로 바뀌는 과정입니다.","keywords":["산업화"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-10","grade":"h1"},
{"id":"soc-h-c1-10#t1","kind":"term","title":"도시화","text":"전체 인구 가운데 도시 인구의 비율이 높아지고 도시적 생활양식이 퍼지는 과정입니다.","keywords":["도시화"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-10","grade":"h1"},
{"id":"soc-h-c1-10#t2","kind":"term","title":"도시화율","text":"전체 인구 가운데 도시에 사는 인구의 비율입니다. 도시 인구 ÷ 전체 인구 × 100 으로 구합니다.","keywords":["도시화율"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-10","grade":"h1"},
{"id":"soc-h-c1-10#t3","kind":"term","title":"이촌 향도","text":"촌락(농촌)을 떠나 도시로 옮겨 가는 인구 이동입니다. 산업화 시기에 활발합니다.","keywords":["이촌 향도"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-10","grade":"h1"},
{"id":"soc-h-c1-10#t4","kind":"term","title":"도시화 곡선","text":"도시화율의 변화를 나타낸 S자 모양의 곡선입니다. 초기·가속화·종착 단계로 나눕니다.","keywords":["도시화 곡선"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-10","grade":"h1"},
{"id":"soc-h-c1-10#t5","kind":"term","title":"대도시권","text":"대도시와, 그 영향을 받아 하나의 생활권으로 이어진 주변 지역을 합친 범위입니다.","keywords":["대도시권"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-10","grade":"h1"},
{"id":"soc-h-c1-10#t6","kind":"term","title":"인구 공동화 현상","text":"도심의 주거 기능이 빠져나가 낮에는 붐비고 밤에는 인구가 적어지는 현상입니다.","keywords":["인구 공동화 현상"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-10","grade":"h1"},
{"id":"soc-h-c1-10#t7","kind":"term","title":"열섬 현상","text":"도심의 기온이 주변 지역보다 높게 나타나는 현상입니다.","keywords":["열섬 현상"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-10","grade":"h1"},
{"id":"soc-h-c1-10#t8","kind":"term","title":"도시성","text":"익명성, 2차적 관계 중시처럼 도시에서 나타나는 특유의 생활 방식과 의식입니다.","keywords":["도시성"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-10","grade":"h1"},
{"id":"soc-h-c1-10#t9","kind":"term","title":"도시 재생","text":"쇠퇴한 도시 지역의 역사와 모습을 살리면서 새로운 기능을 넣고 환경을 고쳐 다시 활기를 찾게 하는 것입니다.","keywords":["도시 재생"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-10","grade":"h1"},
{"id":"soc-h-c1-10#f0","kind":"faq","title":"산업화랑 도시화는 같은 거예요?","text":"같지는 않지만 서로 깊이 관련됩니다. 산업화는 산업의 중심이 농업에서 공업·서비스업으로 바뀌는 것이고, 도시화는 도시에 사는 인구의 비율이 높아지는 것입니다. 산업화로 도시에 공장과 일자리가 생기면 사람들이 도시로 몰려 도시화가 빨라지므로, 두 현상은 대체로 함께 진행됩니다.","keywords":["산업화","도시화"],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-10","grade":"h1"},
{"id":"soc-h-c1-10#f1","kind":"faq","title":"개인주의는 나쁜 거 아니에요?","text":"개인주의는 개인의 자유와 권리, 개성을 존중하는 가치관으로, 그 자체가 나쁜 것은 아닙니다. 자기 이익만 앞세우고 남을 생각하지 않는 이기주의와는 다릅니다. 다만 개인주의가 커지면서 이웃과의 관계가 느슨해지는 면이 있으므로, 공동체와의 조화를 함께 생각하는 것이 중요합니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-10","grade":"h1"},
{"id":"soc-h-c1-10#f2","kind":"faq","title":"도시화율이 100%가 될 수도 있어요?","text":"도시 국가처럼 나라 전체가 하나의 도시인 경우가 아니라면 100%에 이르기는 어렵습니다. 농업이나 자연을 지키는 일을 하는 사람, 촌락의 생활을 원하는 사람이 있기 때문입니다. 그래서 종착 단계에서는 도시화율이 높은 수준에서 상승이 둔해지고, 역도시화가 나타나기도 합니다.","keywords":["도시화","도시화율"],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-10","grade":"h1"},
{"id":"soc-h-c1-10#m0","kind":"mistake","title":"자주 하는 실수","text":"도시화와 도시화율을 같은 말로 쓰는 실수 — 도시화는 과정, 도시화율은 전체 인구 중 도시 인구의 비율(수치)입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-10","grade":"h1"},
{"id":"soc-h-c1-10#m1","kind":"mistake","title":"자주 하는 실수","text":"도시화율이 가장 높은 시기를 가속화 단계로 아는 실수 — 가속화 단계는 도시화율이 가장 \"빠르게\" 오르는 단계이고, 가장 \"높은\" 것은 종착 단계입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-10","grade":"h1"},
{"id":"soc-h-c1-10#m2","kind":"mistake","title":"자주 하는 실수","text":"도시 재생을 모두 허물고 새로 짓는 것으로 아는 실수 — 도시 재생은 지역의 역사와 모습을 살리면서 고쳐 활기를 되찾게 하는 것입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-10","grade":"h1"},
{"id":"soc-h-c1-11","kind":"unit","title":"교통·통신·과학기술과 생활","text":"교통·통신과 과학기술의 발달로 생활공간과 생활양식이 어떻게 바뀌었는지 알아보고, 그 과정에서 새로 생긴 문제와 이를 해결하기 위한 개인적·사회적 노력을 살펴봅니다. 교통 발달에 따른 시공간 압축, 생활권 확대, 빨대 효과 등 공간 변화를 설명할 수 있다. 통신 발달과 정보화가 가져온 생활 모습의 변화를 사례로 설명할 수 있다. 제4차 산업 혁명과 과학기술…","keywords":["시간 거리","시공간 압축","생활권","빨대 효과","정보화","전자 상거래","제4차 산업 혁명","사물 인터넷","정보 격차","디지털 시민성"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-11","grade":"h1"},
{"id":"soc-h-c1-11#c0","kind":"concept","title":"교통 발달과 공간 변화","text":"고속 철도, 고속 국도, 항공 교통이 발달하면서 같은 거리를 훨씬 짧은 시간과 적은 비용으로 오갈 수 있게 되었습니다. 두 곳 사이를 이동하는 데 걸리는 시간(시간 거리)과 드는 비용(비용 거리)이 줄어든 것입니다. 시공간 압축: 시간 거리가 줄어 실제 거리는 그대로인데도 세계가 더 가","keywords":["시간 거리","시공간 압축","생활권","빨대 효과"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-11","grade":"h1"},
{"id":"soc-h-c1-11#c1","kind":"concept","title":"통신 발달과 정보화","text":"인터넷과 스마트폰 같은 통신 기술이 발달하면서 정보가 사회의 가장 중요한 자원이 되는 정보화가 진행되었습니다. 정보는 거의 실시간으로 세계 어디에나 전달되고, 사람들은 현실 공간뿐 아니라 가상 공간에서도 많은 일을 합니다. 변화 · 내용 원격 근무 · 회사에 가지 않고 집이나 다른 곳에","keywords":["정보화","전자 상거래"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-11","grade":"h1"},
{"id":"soc-h-c1-11#c2","kind":"concept","title":"제4차 산업 혁명과 생활양식의 변화","text":"제4차 산업 혁명은 인공지능, 사물 인터넷, 빅데이터 같은 기술이 서로 연결되어 사회와 산업 전반에 큰 변화를 가져오는 흐름입니다. 구분 · 시기 · 핵심 제1차 산업 혁명 · 18세기 후반 · 증기 기관을 이용한 기계화 제2차 산업 혁명 · 19세기 후반 · 전기를 이용한 대량 생산 ","keywords":["정보화","제4차 산업 혁명","사물 인터넷"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-11","grade":"h1"},
{"id":"soc-h-c1-11#c3","kind":"concept","title":"교통·통신·과학기술의 발달로 생긴 문제","text":"교통·통신·과학기술의 발달은 생활을 편리하게 했지만 새로운 문제도 만들었습니다. 지역 격차: 고속 교통망이 지나는 대도시는 더 성장하지만, 빨대 효과로 주변 지역이나 교통망에서 먼 지역은 쇠퇴할 수 있습니다. 정보 격차: 정보 기기를 갖추고 잘 다루는 사람과 그렇지 못한 사람(노인, 저","keywords":["빨대 효과","정보 격차"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-11","grade":"h1"},
{"id":"soc-h-c1-11#c4","kind":"concept","title":"문제 해결을 위한 개인적·사회적 노력","text":"새로운 문제를 해결하려면 개인의 노력과 사회의 제도가 함께 필요합니다. 개인적 노력 — 디지털 시민성 기르기 디지털 시민성은 디지털 공간에서 책임감 있게 참여하고 다른 사람을 존중하는 시민의 자질입니다. 다른 사람의 개인 정보와 저작권을 존중하고, 내 개인 정보도 함부로 공개하지 않습니","keywords":["정보화","정보 격차","디지털 시민성"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-11","grade":"h1"},
{"id":"soc-h-c1-11#t0","kind":"term","title":"시간 거리","text":"두 지점 사이를 이동하는 데 걸리는 시간으로 나타낸 거리입니다. 교통이 발달하면 줄어듭니다.","keywords":["시간 거리"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-11","grade":"h1"},
{"id":"soc-h-c1-11#t1","kind":"term","title":"시공간 압축","text":"교통·통신의 발달로 시간 거리가 줄어 세계가 더 가깝게 느껴지는 현상입니다.","keywords":["시공간 압축"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-11","grade":"h1"},
{"id":"soc-h-c1-11#t2","kind":"term","title":"생활권","text":"통근·통학·쇼핑 등 일상생활을 하는 공간의 범위입니다.","keywords":["생활권"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-11","grade":"h1"},
{"id":"soc-h-c1-11#t3","kind":"term","title":"빨대 효과","text":"고속 교통망 개통 뒤 대도시가 주변 지역의 인구와 경제력을 빨아들이는 현상입니다.","keywords":["빨대 효과"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-11","grade":"h1"},
{"id":"soc-h-c1-11#t4","kind":"term","title":"정보화","text":"정보가 사회의 중요한 자원이 되고, 정보 통신 기술이 생활 전반에 쓰이게 되는 과정입니다.","keywords":["정보화"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-11","grade":"h1"},
{"id":"soc-h-c1-11#t5","kind":"term","title":"전자 상거래","text":"인터넷 등 통신망을 이용하여 물건이나 서비스를 사고파는 것입니다.","keywords":["전자 상거래"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-11","grade":"h1"},
{"id":"soc-h-c1-11#t6","kind":"term","title":"제4차 산업 혁명","text":"인공지능, 사물 인터넷, 빅데이터 등이 서로 연결되어 사회 전반에 큰 변화를 가져오는 흐름입니다.","keywords":["제4차 산업 혁명"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-11","grade":"h1"},
{"id":"soc-h-c1-11#t7","kind":"term","title":"사물 인터넷","text":"여러 사물이 인터넷으로 연결되어 서로 정보를 주고받는 기술입니다.","keywords":["사물 인터넷"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-11","grade":"h1"},
{"id":"soc-h-c1-11#t8","kind":"term","title":"정보 격차","text":"정보 기기를 갖추고 다루는 능력의 차이로 정보를 얻고 활용하는 데 생기는 차이입니다.","keywords":["정보 격차"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-11","grade":"h1"},
{"id":"soc-h-c1-11#t9","kind":"term","title":"디지털 시민성","text":"디지털 공간에서 책임감 있게 참여하고 다른 사람을 존중하는 시민의 자질입니다.","keywords":["디지털 시민성"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-11","grade":"h1"},
{"id":"soc-h-c1-11#f0","kind":"faq","title":"시공간 압축이면 진짜로 거리가 줄어드는 거예요?","text":"아닙니다. 두 지점 사이의 실제 거리(km)는 그대로입니다. 교통·통신이 발달해 이동하거나 연락하는 데 걸리는 시간이 줄어들어 가깝게 느껴지는 것입니다. 그래서 시간 거리나 비용 거리가 줄어든다고 표현합니다.","keywords":["시공간 압축"],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-11","grade":"h1"},
{"id":"soc-h-c1-11#f1","kind":"faq","title":"교통이 좋아지면 작은 도시에도 좋은 거 아니에요?","text":"좋은 점도 있습니다. 작은 도시 주민들이 대도시의 서비스를 이용하기 쉬워지고, 대도시 사람들이 관광을 오기도 쉬워집니다. 하지만 주민의 소비와 인구가 대도시로 빠져나가는 빨대 효과가 나타나면 오히려 지역 상권이 위축될 수 있습니다. 그래서 교통망과 함께 지역의 매력을 키우는 정책이 필요합니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-11","grade":"h1"},
{"id":"soc-h-c1-11#f2","kind":"faq","title":"디지털 시민성은 컴퓨터를 잘 다루는 능력이에요?","text":"기기를 다루는 능력도 포함되지만, 그것만은 아닙니다. 디지털 공간에서 다른 사람의 권리와 개인 정보를 존중하고, 정보를 비판적으로 판단하며, 책임감 있게 참여하는 시민의 자질을 말합니다. 온라인에서 예의를 지키고 허위 정보를 퍼뜨리지 않는 것도 디지털 시민성입니다.","keywords":["디지털 시민성"],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-11","grade":"h1"},
{"id":"soc-h-c1-11#m0","kind":"mistake","title":"자주 하는 실수","text":"시공간 압축을 실제 거리가 줄어드는 것으로 아는 실수 — 줄어드는 것은 이동에 걸리는 시간(시간 거리)과 비용이고, 실제 거리는 그대로입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-11","grade":"h1"},
{"id":"soc-h-c1-11#m1","kind":"mistake","title":"자주 하는 실수","text":"교통 발달이 언제나 모든 지역에 이롭다고 보는 실수 — 빨대 효과처럼 주변 지역이 쇠퇴하여 지역 격차가 커지기도 합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-11","grade":"h1"},
{"id":"soc-h-c1-11#m2","kind":"mistake","title":"자주 하는 실수","text":"정보 격차를 개인의 노력 부족 문제로만 보는 실수 — 정보화 교육, 쉬운 서비스 설계 같은 사회적 노력이 함께 필요합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-11","grade":"h1"},
{"id":"soc-h-c1-12","kind":"unit","title":"우리 지역의 공간 변화","text":"지역 조사의 절차에 따라 우리 지역의 토지 이용·산업·인구·생태환경이 어떻게 바뀌었는지 조사하고, 공간 변화로 생긴 지역 문제를 지속가능성을 고려하여 해결하며, 주민으로서 참여하는 방법을 익힙니다. 지역 조사의 절차를 알고, 목적에 맞는 자료 수집 방법을 고를 수 있다. 토지 이용, 산업 구조, 인구, 생태환경을 기준으로 지역의 공간 변화를 분석할 수 있…","keywords":["지역 조사","답사","면담","원도심","젠트리피케이션","지속가능성","주민 참여 예산제","주민 조례 청구","공청회"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-12","grade":"h1"},
{"id":"soc-h-c1-12#c0","kind":"concept","title":"지역 조사의 절차","text":"우리 지역이 어떻게 바뀌었는지 알려면 체계적으로 지역 조사를 합니다. 조사 주제 정하기: 지역에서 궁금한 점이나 문제를 찾아 주제를 정합니다. 예: \"우리 동네 전통 시장 주변은 왜 빈 점포가 늘었을까?\" 조사 계획 세우기: 조사할 지역의 범위, 기간, 방법, 역할을 정합니다. 자료 수","keywords":["지역 조사","답사","면담"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-12","grade":"h1"},
{"id":"soc-h-c1-12#c1","kind":"concept","title":"지역의 공간 변화 양상","text":"지역의 공간 변화는 다음 네 가지 기준으로 나누어 살펴보면 분명하게 보입니다. 기준 · 살펴볼 것 · 변화의 예 토지 이용 · 땅을 어디에 쓰는가 · 논밭과 산림이 아파트 단지, 상가, 공업 단지, 도로로 바뀜 산업 구조 · 어떤 산업에 종사하는가 · 농업(1차 산업) 종사자가 줄고 제","keywords":[],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-12","grade":"h1"},
{"id":"soc-h-c1-12#c2","kind":"concept","title":"공간 변화로 생긴 지역 문제","text":"지역의 공간이 바뀌는 과정에서 여러 문제가 생깁니다. 원도심 쇠퇴 오래전부터 도시의 중심이었던 곳을 원도심(구도심)이라고 합니다. 도시 외곽에 새로운 시가지(신도시, 신시가지)가 개발되어 관공서·학교·상가와 인구가 옮겨 가면, 원도심은 빈 점포와 빈집이 늘고 건물이 낡아 활기를 잃습니다","keywords":["원도심","젠트리피케이션"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-12","grade":"h1"},
{"id":"soc-h-c1-12#c3","kind":"concept","title":"지속가능성을 고려한 해결 방안","text":"지역 문제를 해결할 때는 지금 당장의 이익만이 아니라 지속가능성을 생각해야 합니다. 지속가능성은 미래 세대가 누릴 몫을 해치지 않으면서 현재 세대의 필요를 채우는 것으로, 환경·경제·사회의 세 측면이 균형을 이루어야 합니다. 측면 · 따져 볼 질문 환경 · 녹지·하천 등 생태환경을 해치","keywords":["원도심","젠트리피케이션","지속가능성"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-12","grade":"h1"},
{"id":"soc-h-c1-12#c4","kind":"concept","title":"지역 문제 해결에 참여하는 방법","text":"지역의 주인은 주민입니다. 주민은 여러 방법으로 지역 문제 해결에 직접 참여할 수 있습니다. 방법 · 내용 주민 참여 예산제 · 지방 자치 단체가 예산을 짤 때 주민이 사업을 제안하거나 우선순위를 정하는 데 참여함 주민 조례 청구 · 일정한 수 이상의 주민이 서명하여 지역의 법인 조례를","keywords":["주민 참여 예산제","주민 조례 청구","공청회"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-12","grade":"h1"},
{"id":"soc-h-c1-12#t0","kind":"term","title":"지역 조사","text":"지역의 특성이나 문제를 알아보려고 주제 선정, 계획, 자료 수집, 분석, 보고서 작성의 절차로 조사하는 것입니다.","keywords":["지역 조사"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-12","grade":"h1"},
{"id":"soc-h-c1-12#t1","kind":"term","title":"답사","text":"조사할 현장에 직접 가서 보고 듣고 기록하는 야외 조사 방법입니다.","keywords":["답사"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-12","grade":"h1"},
{"id":"soc-h-c1-12#t2","kind":"term","title":"면담","text":"조사 대상자를 직접 만나 묻고 답을 듣는 조사 방법입니다.","keywords":["면담"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-12","grade":"h1"},
{"id":"soc-h-c1-12#t3","kind":"term","title":"원도심","text":"오래전부터 도시의 중심 역할을 해 온 지역입니다. 구도심이라고도 합니다.","keywords":["원도심"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-12","grade":"h1"},
{"id":"soc-h-c1-12#t4","kind":"term","title":"젠트리피케이션","text":"낙후된 지역이 활성화되면서 임대료가 올라 원래 살던 주민이나 상인이 밀려나는 현상입니다.","keywords":["젠트리피케이션"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-12","grade":"h1"},
{"id":"soc-h-c1-12#t5","kind":"term","title":"지속가능성","text":"미래 세대가 누릴 몫을 해치지 않으면서 현재 세대의 필요를 채우는 것입니다. 환경·경제·사회의 균형이 필요합니다.","keywords":["지속가능성"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-12","grade":"h1"},
{"id":"soc-h-c1-12#t6","kind":"term","title":"주민 참여 예산제","text":"지방 자치 단체가 예산을 짤 때 주민이 사업을 제안하고 우선순위를 정하는 데 참여하는 제도입니다.","keywords":["주민 참여 예산제"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-12","grade":"h1"},
{"id":"soc-h-c1-12#t7","kind":"term","title":"주민 조례 청구","text":"일정한 수 이상의 주민이 서명하여 조례를 만들거나 고치거나 없애 달라고 청구하는 제도입니다.","keywords":["주민 조례 청구"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-12","grade":"h1"},
{"id":"soc-h-c1-12#t8","kind":"term","title":"공청회","text":"정책을 정하기 전에 주민·전문가·이해 당사자의 의견을 공개적으로 듣는 모임입니다.","keywords":["공청회"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-12","grade":"h1"},
{"id":"soc-h-c1-12#f0","kind":"faq","title":"젠트리피케이션은 동네가 좋아지는 거니까 좋은 거 아니에요?","text":"동네가 깨끗해지고 사람이 많아지는 면은 긍정적일 수 있습니다. 문제는 그 혜택이 누구에게 돌아가느냐입니다. 임대료가 크게 올라 동네를 살린 작은 가게와 오래 산 주민이 떠나게 되면, 그 지역만의 개성도 사라지고 원래 주민은 삶의 터전을 잃습니다. 그래서 상생 협약처럼 활성화의 혜택을 나누는 방법이 필요합니다.","keywords":["젠트리피케이션"],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-12","grade":"h1"},
{"id":"soc-h-c1-12#f1","kind":"faq","title":"실내 조사랑 야외 조사 중에 뭐가 더 좋아요?","text":"어느 한쪽이 더 좋다기보다 서로 보완합니다. 실내 조사(통계·지도·문헌)는 오랜 기간의 변화와 전체 흐름을 보여 주고, 야외 조사(답사·면담·설문)는 현장의 모습과 사람들의 목소리를 생생하게 알려 줍니다. 조사 주제에 맞게 둘을 함께 쓰는 것이 좋습니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-12","grade":"h1"},
{"id":"soc-h-c1-12#f2","kind":"faq","title":"학생도 주민 참여 제도를 쓸 수 있어요?","text":"제도마다 참여할 수 있는 나이 조건이 다를 수 있으므로 우리 지역의 안내를 확인해야 합니다. 나이 조건이 있더라도 지방 자치 단체 누리집의 정책 제안, 청소년 참여 기구, 공청회 참석, 지역 공동체 활동처럼 학생이 참여할 수 있는 길은 많습니다. 지역 조사로 근거를 갖추어 제안하면 더 설득력이 있습니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-12","grade":"h1"},
{"id":"soc-h-c1-12#m0","kind":"mistake","title":"자주 하는 실수","text":"원도심 쇠퇴와 젠트리피케이션을 같은 것으로 아는 실수 — 원도심 쇠퇴는 지역이 활기를 잃는 것이고, 젠트리피케이션은 지역이 활성화되면서 임대료가 올라 원래 주민이 밀려나는 것입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-12","grade":"h1"},
{"id":"soc-h-c1-12#m1","kind":"mistake","title":"자주 하는 실수","text":"지속가능성을 환경 보호만으로 아는 실수 — 환경·경제·사회의 세 측면이 균형을 이루어야 합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-12","grade":"h1"},
{"id":"soc-h-c1-12#m2","kind":"mistake","title":"자주 하는 실수","text":"비율 자료만 보고 사람 수의 변화를 단정하는 실수 — 고령 인구 비율이 높아져도 고령 인구의 수가 늘었는지는 전체 인구를 함께 보아야 알 수 있습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c1","unit":"soc-h-c1-12","grade":"h1"},
{"id":"soc-h-c2-01","kind":"unit","title":"인권과 헌법","text":"근대 시민 혁명을 거쳐 인권이 확립되고 넓어져 온 과정을 알고, 헌법이 인권을 기본권으로 보장하는 방법과 시민이 권익을 지키기 위해 참여하는 방법을 배웁니다. 근대 시민 혁명과 권리 장전·미국 독립 선언·프랑스 인권 선언이 인권 확립에 끼친 영향을 설명할 수 있다. 참정권과 사회권의 확대, 세계 인권 선언, 새롭게 등장한 인권을 통해 인권이 넓어져 온 과…","keywords":["인권","권리 장전","세계 인권 선언","사회권","기본권","권력 분립","법치주의","헌법 소원 심판","시민 불복종"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-01","grade":"h1"},
{"id":"soc-h-c2-01#c0","kind":"concept","title":"근대 시민 혁명과 인권의 확립","text":"인권은 사람이 사람이기 때문에 마땅히 누려야 할 기본적인 권리입니다. 인권은 태어나면서부터 누리는 권리(천부성), 누구도 빼앗을 수 없는 권리(불가침성), 성별·인종·신분과 관계없이 모든 사람이 누리는 권리(보편성)라는 특징이 있습니다. 오늘날 당연하게 여기는 인권은 17~18세기 근대","keywords":["인권","권리 장전"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-01","grade":"h1"},
{"id":"soc-h-c2-01#c1","kind":"concept","title":"인권의 확장 — 참정권, 사회권, 세계 인권 선언","text":"시민 혁명 직후의 인권은 주로 재산을 가진 남성 시민의 자유권이었습니다. 그 뒤 인권을 누리는 사람과 인권의 내용이 함께 넓어졌습니다. 1. 참정권의 확대 — 처음에는 재산이 있는 남성만 선거권을 가졌습니다. 19세기 영국 노동자들은 차티스트 운동으로 노동자의 선거권을 요구했습니다. 여","keywords":["인권","세계 인권 선언","사회권"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-01","grade":"h1"},
{"id":"soc-h-c2-01#c2","kind":"concept","title":"현대 사회에서 새롭게 넓어지는 인권","text":"사회가 바뀌면 사람들이 인간답게 살기 위해 필요한 것도 바뀝니다. 그래서 오늘날에는 예전에는 크게 주목받지 못했던 권리들이 새로운 인권으로 강조되고 있습니다. 인권 · 뜻 · 관련된 사회 변화 주거권 · 안전하고 쾌적한 곳에서 인간다운 주거 생활을 누릴 권리 · 도시화로 집값과 주거 환","keywords":["인권"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-01","grade":"h1"},
{"id":"soc-h-c2-01#c3","kind":"concept","title":"인권과 헌법 — 기본권","text":"헌법은 국가를 어떻게 조직하고 운영할지, 국민의 권리를 어떻게 보장할지를 정한 나라의 최고법입니다. 인권은 소중하지만 선언만으로는 지켜지지 않습니다. 그래서 헌법에 인권을 적어 국가가 반드시 지키게 하는데, 헌법에 보장된 인권을 기본권이라고 합니다. 우리나라 헌법 제10조는 \"모든 국민","keywords":["인권","기본권"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-01","grade":"h1"},
{"id":"soc-h-c2-01#c4","kind":"concept","title":"헌법에 담긴 인권 보장 장치","text":"헌법은 기본권을 적어 두는 데 그치지 않고, 국가 권력이 인권을 함부로 해치지 못하게 하는 장치를 함께 두고 있습니다. 1. 권력 분립 — 국가 권력을 입법권(국회), 행정권(정부), 사법권(법원)으로 나누어 서로 견제하고 균형을 이루게 합니다. 권력이 한곳에 모이면 남용되기 쉬워 인권","keywords":["인권","기본권","권력 분립","법치주의"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-01","grade":"h1"},
{"id":"soc-h-c2-01#c5","kind":"concept","title":"시민의 권익을 지키는 참여와 시민 불복종","text":"헌법과 제도가 있어도 시민이 관심을 갖고 참여하지 않으면 인권은 온전히 지켜지기 어렵습니다. 시민 참여의 방법 선거: 대표를 뽑아 정책 방향에 영향을 줍니다. 가장 기본적인 참여입니다. 청원: 국가 기관에 문서로 희망 사항이나 불편 사항을 요구합니다(헌법이 보장하는 청원권). 시민 단체","keywords":["인권","시민 불복종"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-01","grade":"h1"},
{"id":"soc-h-c2-01#t0","kind":"term","title":"인권","text":"사람이 사람이기 때문에 마땅히 누려야 할 기본적인 권리입니다. 천부성·불가침성·보편성의 특징이 있습니다.","keywords":["인권"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-01","grade":"h1"},
{"id":"soc-h-c2-01#t1","kind":"term","title":"권리 장전","text":"1689년 영국 명예혁명 뒤 만들어진 문서입니다. 의회의 동의 없는 과세 등을 금지하여 왕권을 제한했습니다.","keywords":["권리 장전"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-01","grade":"h1"},
{"id":"soc-h-c2-01#t2","kind":"term","title":"세계 인권 선언","text":"1948년 국제 연합(UN) 총회에서 채택된 선언입니다. 인권을 모든 인류가 지켜야 할 보편적 가치로 밝혔습니다.","keywords":["세계 인권 선언"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-01","grade":"h1"},
{"id":"soc-h-c2-01#t3","kind":"term","title":"사회권","text":"인간다운 생활을 보장해 달라고 국가에 요구할 수 있는 권리입니다. 1919년 바이마르 헌법이 본격적으로 규정했습니다. 예: 교육받을 권리, 근로의 권리","keywords":["사회권"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-01","grade":"h1"},
{"id":"soc-h-c2-01#t4","kind":"term","title":"기본권","text":"헌법에 보장된 인권입니다. 자유권, 평등권, 참정권, 청구권, 사회권이 있습니다.","keywords":["기본권"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-01","grade":"h1"},
{"id":"soc-h-c2-01#t5","kind":"term","title":"권력 분립","text":"국가 권력을 입법·행정·사법으로 나누어 서로 견제하고 균형을 이루게 하는 원리입니다.","keywords":["권력 분립"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-01","grade":"h1"},
{"id":"soc-h-c2-01#t6","kind":"term","title":"법치주의","text":"국가 권력은 국회가 만든 법률에 근거하여 행사되어야 한다는 원리입니다. 오늘날에는 법의 내용까지 정의로워야 한다는 실질적 법치주의를 강조합니다.","keywords":["법치주의"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-01","grade":"h1"},
{"id":"soc-h-c2-01#t7","kind":"term","title":"헌법 소원 심판","text":"공권력 때문에 기본권을 침해당한 국민이 헌법재판소에 직접 구제를 청구하는 헌법 재판입니다.","keywords":["헌법 소원 심판"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-01","grade":"h1"},
{"id":"soc-h-c2-01#t8","kind":"term","title":"시민 불복종","text":"정의롭지 못한 법이나 정책을 바꾸기 위해 공개적·비폭력적으로 법을 위반하고 그 처벌을 감수하는 행위입니다.","keywords":["시민 불복종"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-01","grade":"h1"},
{"id":"soc-h-c2-01#f0","kind":"faq","title":"인권이랑 기본권은 같은 말 아닌가요?","text":"겹치지만 같지는 않습니다. 인권은 사람이라면 누구나 태어나면서부터 가지는 권리로, 법이 있든 없든 인정되는 보편적 권리입니다. 기본권은 그 인권을 한 나라의 헌법에 적어 보장한 것입니다. 헌법에 적으면 국가가 지켜야 할 의무가 분명해지고, 침해되었을 때 재판으로 구제받을 수 있습니다.","keywords":["인권","기본권"],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-01","grade":"h1"},
{"id":"soc-h-c2-01#f1","kind":"faq","title":"세계 인권 선언은 법적 구속력이 없다면서 왜 중요해요?","text":"세계 인권 선언은 그 자체로 나라들을 강제하지는 못하지만, 인류가 처음으로 \"모든 사람이 누려야 할 권리\"를 함께 정리한 문서입니다. 이후 법적 구속력이 있는 국제 인권 규약과 여러 인권 조약, 그리고 많은 나라 헌법의 기준이 되었습니다. 인권을 국제 사회의 공통 기준으로 만든 출발점이라는 점에서 중요합니다.","keywords":["인권","세계 인권 선언"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-01","grade":"h1"},
{"id":"soc-h-c2-01#f2","kind":"faq","title":"시민 불복종도 결국 법을 어기는 건데 왜 정당할 수 있어요?","text":"시민 불복종은 법체계 전체를 무시하는 것이 아니라, 정의롭지 못한 특정한 법이나 정책을 바로잡으려는 것입니다. 그래서 공개적으로, 폭력 없이, 합법적인 방법을 다 써 본 뒤에 하고, 처벌도 받아들입니다. 이런 조건을 갖출 때 사회의 양심에 호소하는 정당한 행위로 평가받을 수 있습니다. 조건을 갖추지 못하면 단순한 법 위반입니다.","keywords":["시민 불복종"],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-01","grade":"h1"},
{"id":"soc-h-c2-01#m0","kind":"mistake","title":"자주 하는 실수","text":"형식적 법치주의와 실질적 법치주의를 거꾸로 기억하는 실수 — \"형식\"은 법률이라는 모양만 갖추면 된다는 것이고, \"실질\"은 법의 목적과 내용까지 정의로워야 한다는 것입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-01","grade":"h1"},
{"id":"soc-h-c2-01#m1","kind":"mistake","title":"자주 하는 실수","text":"위헌 법률 심판과 헌법 소원 심판을 헷갈리는 실수 — 위헌 법률 심판은 법원이 제청하고, 헌법 소원 심판은 국민이 직접 청구합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-01","grade":"h1"},
{"id":"soc-h-c2-01#m2","kind":"mistake","title":"자주 하는 실수","text":"청구권을 \"국가에 무엇이든 요구하는 권리\"로 보아 사회권과 섞는 실수 — 청구권은 침해된 권리를 구제받기 위한 권리(청원권, 재판 청구권, 국가 배상 청구권 등)이고, 사회권은 인간다운 생활 보장을 요구하는 권리입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-01","grade":"h1"},
{"id":"soc-h-c2-02","kind":"unit","title":"인권 문제와 해결","text":"사회적 소수자에 대한 차별과 청소년 노동권 침해 같은 우리 사회의 인권 문제, 인권 지수로 본 세계 인권 문제의 지역별 양상을 살피고, 인권 문제를 해결하기 위한 제도와 실천을 알아봅니다. 사회적 소수자의 의미를 알고, 성별·연령·인종·국적·장애에 따른 차별 사례를 분석할 수 있다. 청소년 노동권의 내용(근로 계약서, 최저 임금, 근로 시간)을 알고, 침…","keywords":["사회적 소수자","근로 계약서","최저 임금","임금 체불","인간 개발 지수(HDI)","성 불평등 지수(GII)","국가인권위원회","비정부 기구(NGO)","인권 감수성"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-02","grade":"h1"},
{"id":"soc-h-c2-02#c0","kind":"concept","title":"사회적 소수자와 차별","text":"사회적 소수자는 신체적·문화적 특징 때문에 사회의 다른 구성원에게 차별을 받고, 스스로도 차별받는 집단에 속해 있다고 느끼는 사람들입니다. 사회적 소수자는 보통 다음 특징을 지닙니다. 식별 가능성: 신체적·문화적 특징으로 다른 사람과 구별됩니다. 권력의 열세: 정치·경제·사회적 힘이 상","keywords":["사회적 소수자"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-02","grade":"h1"},
{"id":"soc-h-c2-02#c1","kind":"concept","title":"청소년 노동권 — 알아야 할 기본 내용","text":"청소년도 일을 하면 근로자로서 법의 보호를 받습니다. 근로기준법이 정한 청소년 근로의 기본 내용은 다음과 같습니다. 1. 일할 수 있는 나이 — 15세 미만인 사람과 중학교에 다니는 18세 미만인 사람은 원칙적으로 근로자로 고용될 수 없습니다(고용노동부 장관이 발급한 취직 인허증이 있으","keywords":["근로 계약서","최저 임금"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-02","grade":"h1"},
{"id":"soc-h-c2-02#c2","kind":"concept","title":"청소년 노동권 침해와 도움받는 방법","text":"청소년은 법을 잘 모르거나 일자리를 잃을까 걱정해 부당한 대우를 참는 경우가 많습니다. 자주 일어나는 침해 사례는 다음과 같습니다. 근로 계약서를 쓰지 않거나, 써 놓고 한 부를 주지 않음 최저 임금보다 적게 주거나 임금을 제때 주지 않음(임금 체불) 약속한 시간보다 오래 일을 시키거나","keywords":["근로 계약서","최저 임금","임금 체불"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-02","grade":"h1"},
{"id":"soc-h-c2-02#c3","kind":"concept","title":"인권 지수로 보는 세계 인권 문제","text":"세계 곳곳의 인권 상황을 비교하기 위해 국제기구와 비정부 기구는 여러 인권 지수를 발표합니다. 지수 · 무엇을 보나 · 읽는 법 정치적 권리·시민적 자유 지수 · 선거, 표현·집회·언론의 자유, 법의 지배 · 점수가 높을수록 자유로움 인간 개발 지수(HDI) · 기대 수명, 교육 수준,","keywords":["인간 개발 지수(HDI)","성 불평등 지수(GII)"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-02","grade":"h1"},
{"id":"soc-h-c2-02#c4","kind":"concept","title":"인권 문제의 해결 방안","text":"인권 문제는 국가, 국제 사회, 시민 사회, 개인이 함께 나서야 해결할 수 있습니다. 1. 국가 차원 — 국가인권위원회는 2001년에 세워진 독립 기관으로, 인권 침해와 차별 행위에 대한 진정을 받아 조사하고 바로잡도록 권고합니다. 법령과 정책의 개선을 권고하고 인권 교육도 합니다. 그","keywords":["국가인권위원회","비정부 기구(NGO)"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-02","grade":"h1"},
{"id":"soc-h-c2-02#t0","kind":"term","title":"사회적 소수자","text":"신체적·문화적 특징 때문에 차별받고, 스스로 차별받는 집단에 속한다고 느끼는 사람들입니다. 수가 적다는 뜻이 아닙니다.","keywords":["사회적 소수자"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-02","grade":"h1"},
{"id":"soc-h-c2-02#t1","kind":"term","title":"근로 계약서","text":"임금, 근로 시간, 휴일·휴가, 일하는 장소와 업무를 적어 근로자와 사용자가 나누어 갖는 문서입니다. 일을 시작하기 전에 서면으로 써야 합니다.","keywords":["근로 계약서"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-02","grade":"h1"},
{"id":"soc-h-c2-02#t2","kind":"term","title":"최저 임금","text":"사용자가 근로자에게 적어도 이만큼은 주어야 한다고 법으로 정한 임금입니다. 청소년도 똑같이 적용됩니다.","keywords":["최저 임금"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-02","grade":"h1"},
{"id":"soc-h-c2-02#t3","kind":"term","title":"임금 체불","text":"일한 대가인 임금을 정해진 날에 주지 않거나 일부만 주는 것입니다.","keywords":["임금 체불"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-02","grade":"h1"},
{"id":"soc-h-c2-02#t4","kind":"term","title":"인간 개발 지수(HDI)","text":"기대 수명, 교육 수준, 1인당 국민 소득으로 삶의 질을 나타낸 지수입니다. 1에 가까울수록 높습니다.","keywords":["인간 개발 지수(HDI)"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-02","grade":"h1"},
{"id":"soc-h-c2-02#t5","kind":"term","title":"성 불평등 지수(GII)","text":"생식 건강, 여성의 정치·교육 참여, 노동 참여에서의 성별 차이를 나타낸 지수입니다. 0에 가까울수록 성 평등합니다.","keywords":["성 불평등 지수(GII)"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-02","grade":"h1"},
{"id":"soc-h-c2-02#t6","kind":"term","title":"국가인권위원회","text":"2001년에 세워진 독립 기관으로, 인권 침해와 차별 행위를 조사하고 시정을 권고합니다.","keywords":["국가인권위원회"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-02","grade":"h1"},
{"id":"soc-h-c2-02#t7","kind":"term","title":"비정부 기구(NGO)","text":"정부와 관계없이 시민이 자발적으로 만든 단체입니다. 인권, 환경, 구호 등 공공의 문제를 해결하려고 활동합니다.","keywords":["비정부 기구(NGO)"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-02","grade":"h1"},
{"id":"soc-h-c2-02#t8","kind":"term","title":"인권 감수성","text":"일상에서 인권 문제를 알아차리고, 피해자의 처지에 공감하며, 해결하려고 행동하는 능력과 태도입니다.","keywords":["인권 감수성"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-02","grade":"h1"},
{"id":"soc-h-c2-02#f0","kind":"faq","title":"아르바이트할 때 근로 계약서를 안 쓰자고 하면 어떻게 해요?","text":"근로 계약서를 서면으로 쓰고 근로자에게 주는 것은 사용자의 법적 의무입니다. 정중하게 작성을 요청하고, 그래도 쓰지 않으면 일한 날짜·시간·받은 돈을 스스로 기록해 두세요. 문제가 생기면 그 기록을 가지고 고용노동부에 도움을 청할 수 있습니다.","keywords":["근로 계약서"],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-02","grade":"h1"},
{"id":"soc-h-c2-02#f1","kind":"faq","title":"국가인권위원회 권고는 강제력이 없는데 왜 있는 거예요?","text":"국가인권위원회의 권고는 법원 판결처럼 강제로 집행할 수는 없습니다. 하지만 독립 기관이 조사해 공개적으로 권고하면 사회적 관심과 압력이 생겨, 많은 기관이 권고를 받아들여 제도를 고칩니다. 또 재판보다 빠르고 비용이 들지 않아 피해자가 쉽게 도움을 청할 수 있다는 장점이 있습니다.","keywords":["국가인권위원회"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-02","grade":"h1"},
{"id":"soc-h-c2-02#f2","kind":"faq","title":"인권 지수가 높은 나라는 인권 문제가 없는 거예요?","text":"그렇지 않습니다. 인권 지수는 나라 전체의 평균적인 상황을 보여 줄 뿐입니다. 지수가 높은 나라에도 이주민이나 장애인에 대한 차별 같은 문제가 있을 수 있고, 한 나라 안에서도 지역과 집단에 따라 상황이 다릅니다. 지수는 비교의 출발점으로 쓰고, 구체적인 사례를 함께 살펴야 합니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-02","grade":"h1"},
{"id":"soc-h-c2-02#m0","kind":"mistake","title":"자주 하는 실수","text":"사회적 소수자를 \"인구가 적은 집단\"으로만 생각하는 실수 — 기준은 수가 아니라 권력의 열세와 차별입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-02","grade":"h1"},
{"id":"soc-h-c2-02#m1","kind":"mistake","title":"자주 하는 실수","text":"청소년 근로 시간을 하루 8시간·1주 40시간으로 외우는 실수 — 기준은 하루 7시간·1주 35시간이고, 합의가 있을 때만 하루 1시간·1주 5시간까지 늘릴 수 있습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-02","grade":"h1"},
{"id":"soc-h-c2-02#m2","kind":"mistake","title":"자주 하는 실수","text":"성 불평등 지수도 높을수록 좋은 것으로 읽는 실수 — 성 불평등 지수는 0에 가까울수록 성 평등합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-02","grade":"h1"},
{"id":"soc-h-c2-03","kind":"unit","title":"정의의 의미와 정의관","text":"정의가 무엇이고 왜 필요한지 알고, 분배적 정의와 교정적 정의를 구분합니다. 분배의 기준인 업적·능력·필요의 장단점을 살피고, 자유주의적 정의관과 공동체주의적 정의관을 비교하여 사회 문제를 평가합니다. 정의의 의미와 정의가 필요한 이유를 개인과 사회 차원에서 설명할 수 있다. 분배적 정의와 교정적 정의를 구분하고, 업적·능력·필요에 따른 분배의 장점과 한…","keywords":["정의","분배적 정의","교정적 정의","무지의 베일","차등의 원칙","최소 국가","공동선","연대"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-03","grade":"h1"},
{"id":"soc-h-c2-03#c0","kind":"concept","title":"정의의 의미와 정의가 필요한 이유","text":"정의란 넓게는 사람으로서 마땅히 지켜야 할 바른 도리이고, 사회에서는 흔히 각자에게 정당한 몫을 주는 것을 뜻합니다. 고대 로마의 법학자 울피아누스는 정의를 \"각자에게 그의 몫을 주려는 변함없는 의지\"라고 표현했습니다. 여기서 핵심은 \"똑같이 나누는 것\"이 아니라 \"정당한 몫을 주는 것","keywords":["정의"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-03","grade":"h1"},
{"id":"soc-h-c2-03#c1","kind":"concept","title":"분배적 정의와 교정적 정의","text":"고대 그리스의 철학자 아리스토텔레스는 사회에서 문제 되는 정의를 몇 가지로 나누었습니다. 오늘날 특히 많이 쓰는 구분은 다음 두 가지입니다. 구분 · 뜻 · 예 분배적 정의 · 소득, 일자리, 권력, 명예 같은 사회적 재화와 부담을 각자의 자격에 맞게 공정하게 나누는 것 · 성과에 따른","keywords":["정의","분배적 정의","교정적 정의"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-03","grade":"h1"},
{"id":"soc-h-c2-03#c2","kind":"concept","title":"분배의 실질적 기준 — 업적, 능력, 필요","text":"\"정당한 몫\"을 정하려면 기준이 있어야 합니다. 대표적인 분배 기준은 세 가지이고, 각각 장점과 한계가 있습니다. 기준 · 뜻 · 장점 · 한계 업적 · 이룬 성과나 기여한 만큼 분배 · 열심히 일할 동기를 주어 생산성을 높임. 객관적으로 평가하기 비교적 쉬움 · 업적의 종류가 달라 비","keywords":[],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-03","grade":"h1"},
{"id":"soc-h-c2-03#c3","kind":"concept","title":"자유주의적 정의관","text":"자유주의적 정의관은 개인의 자유와 권리를 가장 중요하게 여깁니다. 개인은 공동체보다 먼저 존재하는 독립적인 존재이며, 스스로 삶의 목적을 정할 수 있다고 봅니다. 국가는 특정한 좋은 삶을 강요하지 말고 중립을 지키며, 모두가 따를 공정한 절차와 규칙을 마련해야 한다고 봅니다. 대표적인 ","keywords":["정의","무지의 베일","차등의 원칙"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-03","grade":"h1"},
{"id":"soc-h-c2-03#c4","kind":"concept","title":"공동체주의적 정의관","text":"공동체주의적 정의관은 개인이 공동체 속에서 태어나고 자라며 정체성을 형성한다는 점에 주목합니다. 사람은 가족, 지역, 국가의 역사와 전통 속에서 \"나는 누구인가\"를 알게 되므로, 공동체와 떨어진 개인은 상상하기 어렵다고 봅니다. 그래서 공동체주의는 다음을 강조합니다. 공동선: 공동체 구","keywords":["정의","공동선","연대"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-03","grade":"h1"},
{"id":"soc-h-c2-03#c5","kind":"concept","title":"두 정의관으로 현안·제도·정책 평가하기","text":"같은 정책도 어떤 정의관으로 보느냐에 따라 평가가 달라집니다. 가상의 지역 현안으로 생각해 봅시다. 어느 도시가 \"고등학생 지역 봉사 활동 20시간 의무화\" 조례를 만들려고 한다. 관점 · 주목하는 점 · 평가 방향 자유주의 · 봉사 여부는 개인이 스스로 정할 일인가? 시간을 강제로 쓰","keywords":["정의","공동선","연대"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-03","grade":"h1"},
{"id":"soc-h-c2-03#t0","kind":"term","title":"정의","text":"사람으로서 마땅히 지켜야 할 바른 도리이며, 사회적으로는 각자에게 정당한 몫을 주는 것입니다.","keywords":["정의"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-03","grade":"h1"},
{"id":"soc-h-c2-03#t1","kind":"term","title":"분배적 정의","text":"사회적 재화와 부담을 각자의 자격에 맞게 공정하게 나누는 것입니다.","keywords":["분배적 정의"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-03","grade":"h1"},
{"id":"soc-h-c2-03#t2","kind":"term","title":"교정적 정의","text":"잘못이나 피해에 대해 처벌과 배상을 공정하게 하여 깨진 균형을 되돌리는 것입니다.","keywords":["교정적 정의"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-03","grade":"h1"},
{"id":"soc-h-c2-03#t3","kind":"term","title":"무지의 베일","text":"롤스가 제시한 가정으로, 자신의 재능·계층·성별 등을 모르는 상태입니다. 이 상태에서 합의한 원칙은 누구에게도 치우치지 않아 공정하다고 보았습니다.","keywords":["무지의 베일"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-03","grade":"h1"},
{"id":"soc-h-c2-03#t4","kind":"term","title":"차등의 원칙","text":"사회적·경제적 불평등은 사회에서 가장 불리한 사람에게 가장 큰 이익이 되어야 한다는 롤스의 원칙입니다.","keywords":["차등의 원칙"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-03","grade":"h1"},
{"id":"soc-h-c2-03#t5","kind":"term","title":"최소 국가","text":"국가의 역할을 개인의 생명과 재산 보호, 계약 이행 보장 정도로 한정해야 한다는 노직의 주장입니다.","keywords":["최소 국가"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-03","grade":"h1"},
{"id":"soc-h-c2-03#t6","kind":"term","title":"공동선","text":"공동체 구성원 모두에게 좋은 것으로, 공동체주의가 함께 추구해야 한다고 강조하는 가치입니다.","keywords":["공동선"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-03","grade":"h1"},
{"id":"soc-h-c2-03#t7","kind":"term","title":"연대","text":"공동체 구성원들이 서로 돕고 책임을 함께 나누는 것입니다.","keywords":["연대"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-03","grade":"h1"},
{"id":"soc-h-c2-03#f0","kind":"faq","title":"롤스는 자유주의인데 왜 복지를 찬성해요?","text":"자유주의 안에도 여러 입장이 있습니다. 롤스는 개인의 기본적 자유를 가장 먼저 보장해야 한다는 점에서 자유주의자이지만, 타고난 재능이나 집안 환경 같은 우연 때문에 생긴 불리함은 사회가 바로잡아야 한다고 보았습니다. 그래서 가장 불리한 사람에게 이익이 되는 재분배(차등의 원칙)를 지지합니다. 반면 노직은 같은 자유주의이지만 소유권을 앞세워 재분배에 반대합…","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-03","grade":"h1"},
{"id":"soc-h-c2-03#f1","kind":"faq","title":"업적, 능력, 필요 중에 뭐가 제일 정의로운 기준이에요?","text":"어느 하나만 정답이라고 하기 어렵습니다. 업적은 의욕을 높이지만 약자를 놓치고, 필요는 약자를 지키지만 재화가 모자랄 수 있습니다. 그래서 실제 사회는 상황에 맞게 섞어 씁니다. 예를 들어 임금은 업적과 능력을 주로 보되, 최저 임금과 복지 제도로 필요를 채웁니다. 무엇을 나누는지, 누구에게 나누는지에 따라 알맞은 기준이 달라집니다.","keywords":["정의"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-03","grade":"h1"},
{"id":"soc-h-c2-03#f2","kind":"faq","title":"자유주의랑 공동체주의는 서로 반대니까 하나만 골라야 하나요?","text":"그렇지 않습니다. 두 정의관은 각자 놓치기 쉬운 것을 서로 일깨워 줍니다. 자유주의는 공동체가 개인을 억누르지 않도록 지켜 주고, 공동체주의는 개인이 이기적으로 흩어지지 않도록 붙잡아 줍니다. 실제 정책을 평가할 때는 두 관점을 모두 적용해 보고, 개인의 자유와 공동선이 조화를 이루는 방안을 찾는 것이 바람직합니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-03","grade":"h1"},
{"id":"soc-h-c2-03#m0","kind":"mistake","title":"자주 하는 실수","text":"정의를 \"모두에게 똑같이 나누기\"로만 이해하는 실수 — 정의는 각자에게 정당한 몫을 주는 것이고, 무엇이 정당한지는 기준에 따라 달라집니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-03","grade":"h1"},
{"id":"soc-h-c2-03#m1","kind":"mistake","title":"자주 하는 실수","text":"업적과 능력을 헷갈리는 실수 — 업적은 이미 이룬 성과, 능력은 지니고 있는 재능과 자격입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-03","grade":"h1"},
{"id":"soc-h-c2-03#m2","kind":"mistake","title":"자주 하는 실수","text":"롤스와 노직을 모두 \"복지에 반대하는 자유주의자\"로 묶는 실수 — 롤스는 차등의 원칙으로 재분배를 지지하고, 노직은 최소 국가를 주장하며 재분배에 반대합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-03","grade":"h1"},
{"id":"soc-h-c2-04","kind":"unit","title":"불평등과 정의로운 사회","text":"사회 계층의 양극화와 공간 불평등, 사회적 약자에 대한 차별과 기회의 불평등이 나타나는 모습과 원인을 살피고, 불평등을 줄이는 제도와 정의로운 사회를 위한 시민의 실천을 알아봅니다. 사회 계층의 양극화 현상을 지표로 해석하고, 그 원인과 영향을 설명할 수 있다. 수도권 집중, 도시와 농촌의 격차, 도시 안의 주거 격차 등 공간 불평등의 모습과 문제를 설명…","keywords":["사회 계층의 양극화","지니 계수","소득 5분위 배율","상대적 빈곤율","공간 불평등","사회 보험","공공 부조","적극적 평등 실현 조치","복지 사각지대"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-04","grade":"h1"},
{"id":"soc-h-c2-04#c0","kind":"concept","title":"사회 계층의 양극화","text":"사회 계층의 양극화란 중간층이 줄어들고 상층과 하층으로 나뉘어, 계층 사이의 소득과 자산 격차가 점점 커지는 현상입니다. 양극화를 재는 지표 지표 · 뜻 · 읽는 법 지니 계수 · 소득이 얼마나 고르게 나뉘어 있는지 나타낸 값 · 0~1, 1에 가까울수록 불평등 소득 5분위 배율 · 소","keywords":["사회 계층의 양극화","지니 계수","소득 5분위 배율","상대적 빈곤율"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-04","grade":"h1"},
{"id":"soc-h-c2-04#c1","kind":"concept","title":"공간 불평등","text":"공간 불평등은 사는 곳에 따라 소득, 일자리, 교육, 의료, 문화 같은 자원과 기회를 누리는 정도가 달라지는 현상입니다. 1. 수도권 집중 — 우리나라는 국토 면적의 약 12%인 수도권(서울·인천·경기)에 인구의 절반가량이 살고, 주요 기업 본사와 일자리, 대학, 대형 병원, 문화 시설","keywords":["공간 불평등"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-04","grade":"h1"},
{"id":"soc-h-c2-04#c2","kind":"concept","title":"사회적 약자에 대한 차별과 기회의 불평등","text":"사회적 약자는 신체적·경제적·사회적 이유로 사회에서 불리한 처지에 놓인 사람들입니다. 장애인, 노인, 저소득층, 한부모 가족, 이주민 등이 해당할 수 있습니다. 불평등은 결과에서만 나타나는 것이 아닙니다. 출발선부터 다르면 공정한 경쟁이 어렵습니다. 단계 · 불평등의 모습 출발선 · 가","keywords":[],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-04","grade":"h1"},
{"id":"soc-h-c2-04#c3","kind":"concept","title":"불평등을 줄이는 제도 ① — 사회 복지 제도","text":"사회 복지 제도는 사회 구성원이 인간다운 생활을 할 수 있도록 국가와 사회가 돕는 제도입니다. 소득을 다시 나누어 계층 간 격차를 줄이는 역할도 합니다. 구분 · 뜻과 특징 · 예 사회 보험 · 질병·노령·실업·산업 재해 같은 위험에 미리 대비하는 보험. 가입이 의무이고, 국가·기업·개","keywords":["사회 보험","공공 부조"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-04","grade":"h1"},
{"id":"soc-h-c2-04#c4","kind":"concept","title":"불평등을 줄이는 제도 ② — 지역 격차 완화와 적극적 평등 실현 조치","text":"1. 지역 격차 완화 정책 — 수도권에 몰린 인구와 기능을 나누고 지역이 고르게 발전하도록 하는 정책입니다. 공공 기관을 지방으로 옮기고 그 주변에 혁신 도시를 만들기 행정 기능을 나누어 맡는 행정 중심 복합 도시 건설 지역의 특성을 살린 특화 산업 육성, 지역 기업 지원 농어촌의 교통","keywords":["적극적 평등 실현 조치"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-04","grade":"h1"},
{"id":"soc-h-c2-04#c5","kind":"concept","title":"정의로운 사회를 위한 시민의 실천","text":"제도만으로는 불평등을 모두 해결할 수 없습니다. 제도를 만들고, 지키고, 고쳐 나가는 것은 결국 시민입니다. 시민이 실천할 수 있는 일 관심과 참여: 불평등 문제와 관련된 정책을 살피고, 선거·청원·공청회 등으로 의견을 냅니다. 편견과 차별 버리기: 사회적 약자를 낮추어 보는 말과 행동","keywords":[],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-04","grade":"h1"},
{"id":"soc-h-c2-04#t0","kind":"term","title":"사회 계층의 양극화","text":"중간층이 줄고 상층과 하층으로 나뉘어 계층 사이의 소득·자산 격차가 커지는 현상입니다.","keywords":["사회 계층의 양극화"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-04","grade":"h1"},
{"id":"soc-h-c2-04#t1","kind":"term","title":"지니 계수","text":"소득 분배가 얼마나 고른지 나타내는 0~1 사이의 값입니다. 0이면 완전 평등, 1에 가까울수록 불평등합니다.","keywords":["지니 계수"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-04","grade":"h1"},
{"id":"soc-h-c2-04#t2","kind":"term","title":"소득 5분위 배율","text":"소득 상위 20%의 평균 소득을 하위 20%의 평균 소득으로 나눈 값입니다. 클수록 불평등합니다.","keywords":["소득 5분위 배율"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-04","grade":"h1"},
{"id":"soc-h-c2-04#t3","kind":"term","title":"상대적 빈곤율","text":"중위 소득의 50%에 못 미치는 소득을 가진 사람의 비율입니다.","keywords":["상대적 빈곤율"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-04","grade":"h1"},
{"id":"soc-h-c2-04#t4","kind":"term","title":"공간 불평등","text":"사는 지역에 따라 소득, 일자리, 교육, 의료, 문화 같은 자원과 기회를 누리는 정도가 다른 현상입니다.","keywords":["공간 불평등"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-04","grade":"h1"},
{"id":"soc-h-c2-04#t5","kind":"term","title":"사회 보험","text":"질병·노령·실업·산업 재해 같은 위험에 미리 대비하는 의무 가입 보험입니다. 예: 국민연금, 국민건강보험","keywords":["사회 보험"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-04","grade":"h1"},
{"id":"soc-h-c2-04#t6","kind":"term","title":"공공 부조","text":"생활이 어려운 사람에게 국가가 세금으로 최저 생활을 보장하는 제도입니다. 예: 국민 기초 생활 보장 제도","keywords":["공공 부조"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-04","grade":"h1"},
{"id":"soc-h-c2-04#t7","kind":"term","title":"적극적 평등 실현 조치","text":"차별받아 온 사회적 약자에게 일시적으로 혜택을 주어 실질적 평등을 이루려는 조치입니다. 예: 장애인 의무 고용 제도","keywords":["적극적 평등 실현 조치"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-04","grade":"h1"},
{"id":"soc-h-c2-04#t8","kind":"term","title":"복지 사각지대","text":"도움이 필요한데도 제도의 기준에 맞지 않거나 정보가 없어 복지 혜택을 받지 못하는 상태나 계층입니다.","keywords":["복지 사각지대"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-04","grade":"h1"},
{"id":"soc-h-c2-04#f0","kind":"faq","title":"5분위 배율이랑 소득 차이는 뭐가 달라요?","text":"소득 차이는 \"얼마나 더 버는지\"를 빼기로 구하고, 5분위 배율은 \"몇 배를 버는지\"를 나누기로 구합니다. 예를 들어 상위 1,600만 원·하위 400만 원이면 차이는 1,200만 원이지만 배율은 4이고, 상위 1,000만 원·하위 200만 원이면 차이는 800만 원이지만 배율은 5입니다. 불평등 지표로는 배율을 씁니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-04","grade":"h1"},
{"id":"soc-h-c2-04#f1","kind":"faq","title":"적극적 평등 실현 조치는 결국 불공평한 거 아니에요?","text":"그런 비판(역차별 논란)이 실제로 있습니다. 다만 이 조치는 오랜 차별 때문에 출발선부터 불리해진 사람이 있을 때, 같은 조건만으로는 그 차이가 메워지지 않는다는 생각에서 나왔습니다. 그래서 대상과 정도를 신중하게 정하고, 목적을 이루면 그만두는 일시적 조치로 운영합니다. 어느 정도가 알맞은지는 사회적 토론으로 정해야 할 문제입니다.","keywords":["적극적 평등 실현 조치"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-04","grade":"h1"},
{"id":"soc-h-c2-04#f2","kind":"faq","title":"사회 보험이랑 공공 부조는 어떻게 구분해요?","text":"\"보험료를 내는가\"로 구분하면 쉽습니다. 사회 보험은 가입자가 보험료를 내고 위험에 미리 대비하며(국민연금, 고용 보험 등), 공공 부조는 보험료 없이 국가가 세금으로 생활이 어려운 사람을 돕습니다(국민 기초 생활 보장 제도 등). 돈 대신 돌봄이나 상담 같은 서비스를 주면 사회 서비스입니다.","keywords":["사회 보험","공공 부조"],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-04","grade":"h1"},
{"id":"soc-h-c2-04#m0","kind":"mistake","title":"자주 하는 실수","text":"소득 5분위 배율을 상위·하위 소득의 차이로 구하는 실수 — 배율은 상위 20% 평균 소득을 하위 20% 평균 소득으로 나눈 값입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-04","grade":"h1"},
{"id":"soc-h-c2-04#m1","kind":"mistake","title":"자주 하는 실수","text":"상대적 빈곤의 기준선을 중위 소득 그 자체로 잡는 실수 — 기준선은 중위 소득의 50%입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-04","grade":"h1"},
{"id":"soc-h-c2-04#m2","kind":"mistake","title":"자주 하는 실수","text":"지니 계수와 5분위 배율은 클수록 불평등하다는 것을 잊고, 인간 개발 지수처럼 클수록 좋다고 읽는 실수 — 지표마다 \"좋은 방향\"을 먼저 확인하세요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-04","grade":"h1"},
{"id":"soc-h-c2-05","kind":"unit","title":"자본주의와 시장경제","text":"자본주의의 특징을 알고, 상업 자본주의에서 신자유주의에 이르기까지 시장과 정부의 관계가 어떻게 바뀌어 왔는지 살핀 뒤, 시장경제 체제와 계획경제 체제를 비교합니다. 자본주의의 특징(사유 재산 제도, 시장 가격, 이윤 추구)을 설명할 수 있다. 상업 자본주의·산업 자본주의·수정 자본주의·신자유주의가 등장한 배경과 특징을 비교할 수 있다. 시대에 따라 시장과…","keywords":["자본주의","사유 재산 제도","중상주의","보이지 않는 손","자유방임주의","세계 대공황","유효 수요","수정 자본주의","스태그플레이션","신자유주의"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-05","grade":"h1"},
{"id":"soc-h-c2-05#c0","kind":"concept","title":"자본주의의 의미와 특징","text":"자본주의는 개인이 재산과 생산 수단(공장·기계·토지 등)을 가질 수 있고, 시장에서 자유롭게 경쟁하며 이윤을 얻으려고 경제 활동을 하는 경제 체제입니다. 자본주의는 다음 세 가지 특징을 가집니다. 사유 재산 제도: 개인이 재산을 소유하고, 그 재산을 자유롭게 쓰고 처분할 권리를 법으로 ","keywords":["자본주의","사유 재산 제도"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-05","grade":"h1"},
{"id":"soc-h-c2-05#c1","kind":"concept","title":"상업 자본주의와 중상주의","text":"15세기 말 신항로 개척 이후 유럽과 아시아·아메리카 사이의 무역이 크게 늘었습니다. 이때 상품을 싸게 사서 비싸게 팔아 이윤을 얻는 상인이 큰 부를 쌓았는데, 이렇게 상업 활동이 중심이 된 16~18세기의 자본주의를 상업 자본주의라고 합니다. 당시 유럽의 절대 왕정은 나라의 부를 금과","keywords":["자본주의","중상주의"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-05","grade":"h1"},
{"id":"soc-h-c2-05#c2","kind":"concept","title":"산업 자본주의와 보이지 않는 손","text":"18세기 후반 영국에서 시작된 산업 혁명으로 기계를 쓰는 공장에서 상품을 대량으로 생산하게 되었습니다. 이제 이윤의 중심은 상품의 유통이 아니라 생산으로 옮겨 갔고, 공장과 기계를 가진 산업 자본가가 경제를 이끌었습니다. 이를 산업 자본주의라고 합니다. 애덤 스미스는 『국부론』(1776","keywords":["자본주의","보이지 않는 손","자유방임주의"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-05","grade":"h1"},
{"id":"soc-h-c2-05#c3","kind":"concept","title":"수정 자본주의: 대공황과 정부의 개입","text":"1929년 미국에서 주가가 크게 떨어진 것을 계기로 세계 대공황이 일어났습니다. 기업이 줄줄이 문을 닫고 실업자가 크게 늘었지만, 시장은 스스로 회복하지 못했습니다. \"시장에 맡기면 저절로 균형을 찾는다\"는 자유방임주의에 대한 믿음이 흔들렸습니다. 경제학자 케인스는 공황의 원인을 유효 ","keywords":["자본주의","자유방임주의","세계 대공황","유효 수요","수정 자본주의"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-05","grade":"h1"},
{"id":"soc-h-c2-05#c4","kind":"concept","title":"신자유주의: 시장 자율과 작은 정부","text":"1970년대 두 차례의 석유 파동으로 원유 값이 크게 오르자, 경기가 침체하는데도 물가가 계속 오르는 스태그플레이션이 나타났습니다. 경기를 살리려고 정부가 돈을 더 쓰면 물가가 더 오르고, 물가를 잡으려 하면 경기가 더 나빠지는 어려움에 빠졌습니다. 이때 하이에크와 프리드먼 같은 경제학","keywords":["스태그플레이션","신자유주의"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-05","grade":"h1"},
{"id":"soc-h-c2-05#c5","kind":"concept","title":"시장경제 체제와 계획경제 체제","text":"모든 사회는 무엇을 얼마나, 어떻게, 누구에게 생산해 나눌지라는 경제의 기본 문제를 풀어야 합니다. 이 문제를 푸는 방식에 따라 경제 체제를 나눕니다. 구분 · 시장경제 체제 · 계획경제 체제 기본 문제 해결 · 시장 가격과 개인의 자유로운 선택 · 정부의 계획과 명령 생산 수단 · 개","keywords":[],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-05","grade":"h1"},
{"id":"soc-h-c2-05#t0","kind":"term","title":"자본주의","text":"사유 재산 제도를 바탕으로, 개인이 시장에서 자유롭게 경쟁하며 이윤을 얻으려고 경제 활동을 하는 경제 체제입니다.","keywords":["자본주의"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-05","grade":"h1"},
{"id":"soc-h-c2-05#t1","kind":"term","title":"사유 재산 제도","text":"개인이 재산을 소유하고 자유롭게 쓰고 처분할 권리를 법으로 보장하는 제도입니다.","keywords":["사유 재산 제도"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-05","grade":"h1"},
{"id":"soc-h-c2-05#t2","kind":"term","title":"중상주의","text":"16~18세기 유럽 절대 왕정이 금·은을 모으려고 수출을 장려하고 수입을 억제하며 식민지를 넓힌 정책입니다.","keywords":["중상주의"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-05","grade":"h1"},
{"id":"soc-h-c2-05#t3","kind":"term","title":"보이지 않는 손","text":"애덤 스미스가 쓴 비유로, 개인이 자기 이익을 좇아도 시장 가격이 자원을 효율적으로 배분해 사회 전체에 이익이 되게 하는 기능을 말합니다.","keywords":["보이지 않는 손"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-05","grade":"h1"},
{"id":"soc-h-c2-05#t4","kind":"term","title":"자유방임주의","text":"정부는 경제에 간섭하지 않고 국방·치안 같은 최소한의 일만 하며, 경제는 시장에 맡겨야 한다는 생각입니다.","keywords":["자유방임주의"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-05","grade":"h1"},
{"id":"soc-h-c2-05#t5","kind":"term","title":"세계 대공황","text":"1929년 미국에서 시작되어 전 세계로 퍼진 심각한 경기 침체입니다. 기업이 무너지고 실업자가 크게 늘었습니다.","keywords":["세계 대공황"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-05","grade":"h1"},
{"id":"soc-h-c2-05#t6","kind":"term","title":"유효 수요","text":"실제로 물건을 살 수 있는 돈(구매력)이 뒷받침된 수요입니다. 케인스는 이것이 부족해 대공황이 일어났다고 보았습니다.","keywords":["유효 수요"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-05","grade":"h1"},
{"id":"soc-h-c2-05#t7","kind":"term","title":"수정 자본주의","text":"정부가 시장에 적극 개입해 실업·불황·빈부 격차 같은 자본주의의 문제를 고치려는 자본주의입니다. 뉴딜 정책이 대표적입니다.","keywords":["수정 자본주의"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-05","grade":"h1"},
{"id":"soc-h-c2-05#t8","kind":"term","title":"스태그플레이션","text":"경기가 침체하는데도 물가가 계속 오르는 현상입니다. 1970년대 석유 파동 때 나타났습니다.","keywords":["스태그플레이션"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-05","grade":"h1"},
{"id":"soc-h-c2-05#t9","kind":"term","title":"신자유주의","text":"정부 실패를 비판하며 규제 완화·민영화·감세 등으로 시장의 자율과 경쟁을 강조하는 생각과 정책입니다.","keywords":["신자유주의"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-05","grade":"h1"},
{"id":"soc-h-c2-05#f0","kind":"faq","title":"애덤 스미스는 정부가 아무것도 하지 말라고 한 건가요?","text":"아닙니다. 애덤 스미스는 정부가 시장의 가격 결정이나 무역에 간섭하는 것을 비판했지만, 국방·치안·사법, 그리고 개인이 하기 어려운 공공시설을 갖추는 일은 정부가 맡아야 한다고 보았습니다. 그래서 \"최소한의 역할만 하는 작은 정부\"라고 표현합니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-05","grade":"h1"},
{"id":"soc-h-c2-05#f1","kind":"faq","title":"수정 자본주의와 신자유주의 가운데 어느 쪽이 옳은 거예요?","text":"어느 한쪽이 언제나 옳다고 말하기는 어렵습니다. 수정 자본주의는 대공황을 극복하고 복지를 넓혔지만 정부 실패의 문제를 낳았고, 신자유주의는 시장의 활력을 되살렸지만 빈부 격차와 금융 불안의 문제를 드러냈습니다. 각 시기의 경제 상황에 대응하려는 시도였다는 점에서, 장점과 한계를 함께 보는 것이 중요합니다.","keywords":["자본주의","수정 자본주의","신자유주의"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-05","grade":"h1"},
{"id":"soc-h-c2-05#f2","kind":"faq","title":"계획경제는 왜 잘 안 됐어요?","text":"정부가 수많은 상품의 수요를 정확히 알기 어려워 어떤 물건은 남고 어떤 물건은 모자랐습니다. 또 열심히 일해도 보상이 크게 달라지지 않아 근로 의욕과 생산성이 떨어졌습니다. 그래서 20세기 말 많은 계획경제 국가가 시장경제를 받아들였습니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-05","grade":"h1"},
{"id":"soc-h-c2-05#m0","kind":"mistake","title":"자주 하는 실수","text":"중상주의를 \"수입 장려\"로 거꾸로 기억하는 실수 — 금·은을 모으려고 수출은 장려하고 수입은 억제했습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-05","grade":"h1"},
{"id":"soc-h-c2-05#m1","kind":"mistake","title":"자주 하는 실수","text":"케인스와 하이에크·프리드먼을 헷갈리는 실수 — 케인스는 정부 개입(수정 자본주의), 하이에크·프리드먼은 시장 자율(신자유주의)입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-05","grade":"h1"},
{"id":"soc-h-c2-05#m2","kind":"mistake","title":"자주 하는 실수","text":"대공황과 스태그플레이션을 헷갈리는 실수 — 대공황(1929년)은 수정 자본주의, 스태그플레이션(1970년대)은 신자유주의가 등장한 배경입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-05","grade":"h1"},
{"id":"soc-h-c2-06","kind":"unit","title":"합리적 선택과 경제 주체","text":"편익과 기회비용을 비교하는 합리적 선택의 의미와 한계를 알고, 그 한계가 독과점·외부 효과·공공재 부족·공유지의 비극 같은 시장 실패로 이어지는 까닭과, 지속가능발전을 위한 정부·기업가·노동자·소비자의 역할을 배웁니다. 편익과 기회비용을 비교해 합리적 선택을 할 수 있다. 개인의 합리적 선택이 사회 전체에는 바람직하지 않을 수 있음을 사례로 설명할 수 있…","keywords":["기회비용","매몰 비용","합리적 선택","시장 실패","외부 효과","공공재","무임승차","공유지의 비극","기업가 정신","윤리적 소비"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-06","grade":"h1"},
{"id":"soc-h-c2-06#c0","kind":"concept","title":"합리적 선택과 기회비용","text":"자원은 한정되어 있는데 사람의 욕구는 끝이 없습니다(희소성). 그래서 우리는 늘 무엇인가를 고르고 무엇인가를 포기해야 합니다. 합리적 선택이란 선택에 따르는 편익(얻는 만족이나 이익)과 비용을 비교해, 편익이 비용보다 크거나 순편익(편익 − 비용)이 가장 큰 대안을 고르는 것입니다. 이","keywords":["기회비용","매몰 비용","합리적 선택"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-06","grade":"h1"},
{"id":"soc-h-c2-06#c1","kind":"concept","title":"합리적 선택의 한계","text":"합리적 선택이 언제나 좋은 결과를 낳는 것은 아닙니다. 첫째, 사람은 모든 정보를 알지 못하고, 감정이나 습관에 따라 선택하기도 합니다. 그래서 스스로는 합리적이라고 생각한 선택이 결과적으로 손해가 될 수 있습니다. 둘째, 더 중요한 한계는 개인에게 합리적인 선택이 사회 전체에는 손해가","keywords":["합리적 선택"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-06","grade":"h1"},
{"id":"soc-h-c2-06#c2","kind":"concept","title":"시장 실패: 독과점, 외부 효과, 공공재, 공유 자원","text":"시장이 자원을 효율적으로 배분하지 못하는 상태를 시장 실패라고 합니다. 대표적인 경우는 다음과 같습니다. 시장 실패 · 내용 · 결과 독과점 · 한 기업(독점)이나 소수의 기업(과점)이 시장을 차지해 경쟁이 약해짐 · 가격을 올리고 공급량을 줄여 소비자가 피해를 봄. 기업끼리 가격을 미","keywords":["시장 실패","외부 효과","공공재"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-06","grade":"h1"},
{"id":"soc-h-c2-06#c3","kind":"concept","title":"정부의 역할: 시장 실패 보완과 공정한 경쟁","text":"시장 실패가 나타나면 정부가 나서서 이를 보완합니다. 시장 실패 · 정부의 대응 독과점 · 「독점 규제 및 공정 거래에 관한 법률」로 독과점과 담합을 규제하고, 공정 거래 위원회가 감시해 공정한 경쟁 질서를 유지함 외부 불경제 · 오염 물질 배출 기준 같은 규제, 환경 오염에 세금이나 ","keywords":["시장 실패","공공재","공유지의 비극"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-06","grade":"h1"},
{"id":"soc-h-c2-06#c4","kind":"concept","title":"기업가 정신과 기업의 사회적 책임","text":"기업가 정신은 위험을 무릅쓰고 새로운 기회를 찾아 도전하며 혁신을 이루려는 자세입니다. 경제학자 슘페터는 새로운 상품의 개발, 새로운 생산 방법의 도입, 새로운 시장의 개척 같은 혁신이 경제를 발전시키는 힘이라고 보았습니다. 기업가 정신은 일자리를 만들고 생활을 편리하게 하며 경제 성장","keywords":["기업가 정신"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-06","grade":"h1"},
{"id":"soc-h-c2-06#c5","kind":"concept","title":"노동자와 소비자의 역할","text":"노동자는 노동을 제공하고 임금을 받는 경제 주체입니다. 노동자는 기업보다 협상력이 약하기 쉬우므로, 헌법과 법률이 노동자의 권익을 보호합니다. 헌법은 노동 3권을 보장합니다. 노동조합을 만들 수 있는 단결권, 노동조합이 근로 조건을 사용자와 협상하는 단체 교섭권, 협상이 이루어지지 않을","keywords":[],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-06","grade":"h1"},
{"id":"soc-h-c2-06#t0","kind":"term","title":"기회비용","text":"어떤 것을 선택해서 포기하게 된 대안 가운데 가장 가치가 큰 것입니다. 명시적 비용과 암묵적 비용을 모두 포함합니다.","keywords":["기회비용"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-06","grade":"h1"},
{"id":"soc-h-c2-06#t1","kind":"term","title":"매몰 비용","text":"이미 지출해서 어떤 선택을 해도 되찾을 수 없는 비용입니다. 합리적 선택에서는 고려하지 않습니다.","keywords":["매몰 비용"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-06","grade":"h1"},
{"id":"soc-h-c2-06#t2","kind":"term","title":"합리적 선택","text":"편익과 기회비용을 비교해 순편익이 가장 큰 대안을 고르는 것입니다.","keywords":["합리적 선택"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-06","grade":"h1"},
{"id":"soc-h-c2-06#t3","kind":"term","title":"시장 실패","text":"시장이 자원을 효율적으로 배분하지 못하는 상태입니다. 독과점, 외부 효과, 공공재 부족, 공유지의 비극 등이 있습니다.","keywords":["시장 실패"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-06","grade":"h1"},
{"id":"soc-h-c2-06#t4","kind":"term","title":"외부 효과","text":"어떤 경제 활동이 다른 사람에게 의도하지 않은 이익(외부 경제)이나 손해(외부 불경제)를 주는데, 그 대가를 주고받지 않는 현상입니다.","keywords":["외부 효과"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-06","grade":"h1"},
{"id":"soc-h-c2-06#t5","kind":"term","title":"공공재","text":"여러 사람이 함께 써도 줄지 않고, 돈을 내지 않은 사람도 막기 어려운 재화나 서비스입니다. 예: 국방, 치안, 가로등","keywords":["공공재"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-06","grade":"h1"},
{"id":"soc-h-c2-06#t6","kind":"term","title":"무임승차","text":"대가를 치르지 않고 다른 사람이 마련한 재화나 서비스의 혜택만 누리려는 행동입니다.","keywords":["무임승차"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-06","grade":"h1"},
{"id":"soc-h-c2-06#t7","kind":"term","title":"공유지의 비극","text":"누구나 쓸 수 있지만 쓸수록 줄어드는 공유 자원을 사람들이 저마다 많이 쓰려 해서 결국 자원이 고갈되는 현상입니다.","keywords":["공유지의 비극"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-06","grade":"h1"},
{"id":"soc-h-c2-06#t8","kind":"term","title":"기업가 정신","text":"위험을 무릅쓰고 새로운 기회에 도전해 혁신을 이루려는 기업가의 자세입니다.","keywords":["기업가 정신"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-06","grade":"h1"},
{"id":"soc-h-c2-06#t9","kind":"term","title":"윤리적 소비","text":"값과 품질뿐 아니라 환경·인권·노동 조건 등 소비가 사회에 미치는 영향까지 생각하는 소비입니다.","keywords":["윤리적 소비"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-06","grade":"h1"},
{"id":"soc-h-c2-06#f0","kind":"faq","title":"기회비용은 왜 포기한 것을 다 더하지 않아요?","text":"선택을 하지 않았더라도 포기한 대안들을 동시에 모두 할 수는 없었기 때문입니다. 영화를 보지 않았다면 아르바이트나 낮잠 가운데 하나를 했을 것입니다. 그래서 실제로 놓친 것은 그 가운데 가장 가치가 큰 하나입니다.","keywords":["기회비용"],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-06","grade":"h1"},
{"id":"soc-h-c2-06#f1","kind":"faq","title":"공공재와 공유 자원은 뭐가 달라요?","text":"둘 다 돈을 내지 않은 사람을 막기 어렵다는 점(비배제성)은 같습니다. 다른 점은, 공공재(국방·가로등)는 여러 사람이 함께 써도 줄지 않지만, 공유 자원(바다의 물고기·공동 목초지)은 한 사람이 쓰면 다른 사람이 쓸 양이 줄어든다는 것입니다. 그래서 공공재는 \"부족하게 공급되는\" 문제, 공유 자원은 \"지나치게 써서 고갈되는\" 문제가 생깁니다.","keywords":["공공재"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-06","grade":"h1"},
{"id":"soc-h-c2-06#f2","kind":"faq","title":"시장 실패가 있으면 정부가 다 해결하면 되지 않나요?","text":"정부가 개입하면 많은 문제를 줄일 수 있지만, 정부도 완벽하지 않습니다. 정보가 부족하거나 정책이 비효율적이면 오히려 자원 배분을 해치는 정부 실패가 생길 수 있습니다. 그래서 정부의 역할과 함께 기업·노동자·소비자 같은 경제 주체들의 책임 있는 행동이 함께 필요합니다.","keywords":["시장 실패"],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-06","grade":"h1"},
{"id":"soc-h-c2-06#m0","kind":"mistake","title":"자주 하는 실수","text":"기회비용을 구할 때 포기한 대안의 가치를 모두 더하는 실수 — 포기한 것 가운데 가장 가치가 큰 하나만 셉니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-06","grade":"h1"},
{"id":"soc-h-c2-06#m1","kind":"mistake","title":"자주 하는 실수","text":"이미 낸 돈(매몰 비용)을 아까워하며 선택에 넣는 실수 — 되찾을 수 없는 비용은 앞으로의 선택에서 고려하지 않습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-06","grade":"h1"},
{"id":"soc-h-c2-06#m2","kind":"mistake","title":"자주 하는 실수","text":"외부 경제와 외부 불경제의 결과를 거꾸로 기억하는 실수 — 이익을 주는 외부 경제는 적게, 손해를 주는 외부 불경제는 많이 생산됩니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-06","grade":"h1"},
{"id":"soc-h-c2-07","kind":"unit","title":"금융 생활과 자산 관리","text":"예금·채권·주식·펀드·보험·연금 같은 금융 자산의 특징과 수익성·안전성·유동성이라는 자산 관리의 원칙을 알고, 생애 주기와 금리·경기 같은 경제 상황을 고려해 금융 생활을 설계하는 방법을 배웁니다. 예금, 채권, 주식, 펀드, 보험, 연금의 특징을 비교할 수 있다. 수익성·안전성·유동성의 의미와 그 상충 관계를 설명할 수 있다. 위험과 수익의 관계를 이해…","keywords":["금융 자산","예금","채권","주식","펀드","수익성","안전성","유동성","분산 투자","생애 주기"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-07","grade":"h1"},
{"id":"soc-h-c2-07#c0","kind":"concept","title":"금융 자산 (1): 예금, 채권, 주식","text":"금융 자산은 현금, 예금, 채권, 주식처럼 돈이나 돈을 받을 권리를 나타내는 자산입니다. 자산 · 의미 · 수익 · 특징 예금 · 은행 등 금융 회사에 돈을 맡기는 것 · 이자 · 원금 손실 위험이 매우 낮음. 금융 회사가 망해도 예금자 보호 제도로 일정 금액까지 보호 채권 · 정부·지","keywords":["금융 자산","예금","채권","주식","수익성"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-07","grade":"h1"},
{"id":"soc-h-c2-07#c1","kind":"concept","title":"금융 자산 (2): 펀드, 보험, 연금","text":"펀드는 자산 운용 회사 같은 전문 기관이 여러 사람의 돈을 모아 주식·채권 등에 대신 투자하고, 그 결과로 생긴 수익을 투자한 금액에 따라 나눠 주는 상품입니다. 적은 돈으로도 여러 곳에 나누어 투자하는 효과를 낼 수 있지만, 원금이 보장되지 않고 운용 수수료를 내야 합니다. 보험은 질","keywords":["금융 자산","채권","주식","펀드"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-07","grade":"h1"},
{"id":"soc-h-c2-07#c2","kind":"concept","title":"자산 관리의 원칙: 수익성, 안전성, 유동성","text":"금융 자산을 고를 때는 세 가지 기준을 따집니다. 수익성: 그 자산으로 얼마나 많은 이익을 얻을 수 있는가 안전성: 원금이 줄어들지 않고 보전될 가능성이 얼마나 높은가 유동성(환금성): 필요할 때 얼마나 쉽게, 손해 없이 현금으로 바꿀 수 있는가 자산 · 수익성 · 안전성 · 유동성 요","keywords":["금융 자산","예금","채권","주식","수익성","안전성","유동성"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-07","grade":"h1"},
{"id":"soc-h-c2-07#c3","kind":"concept","title":"위험과 수익, 그리고 분산 투자","text":"금융에서 위험이란 앞으로 얻을 수익이 예상과 달라질 가능성, 곧 결과의 불확실성을 말합니다. 일반적으로 기대 수익이 높은 자산일수록 위험도 큽니다(고위험 고수익). 반대로 위험이 작은 자산은 기대 수익도 낮습니다. \"위험은 거의 없는데 수익은 아주 높다\"는 상품은 사기일 가능성을 의심해","keywords":["예금","채권","주식","분산 투자"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-07","grade":"h1"},
{"id":"soc-h-c2-07#c4","kind":"concept","title":"생애 주기와 금융 생활 설계","text":"사람의 일생을 몇 단계로 나눈 것을 생애 주기라고 합니다. 단계마다 소득과 소비의 모습, 이루어야 할 재무 목표가 다릅니다. 시기 · 소득과 소비 · 주요 재무 목표 유소년기 · 소득이 거의 없고 부모에게 기대어 소비 · 용돈 관리, 저축 습관 기르기 청년기 · 취업으로 소득이 생기기 ","keywords":["생애 주기"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-07","grade":"h1"},
{"id":"soc-h-c2-07#c5","kind":"concept","title":"경제 상황의 변화와 금융 의사 결정","text":"금융 자산의 가치는 나 혼자의 사정뿐 아니라 나라와 세계의 경제 상황(거시적 변화)에 따라서도 달라집니다. 아래는 일반적인 경향이며, 실제로는 여러 요인이 함께 작용합니다. 변화 · 금융 생활에 주는 영향 (일반적 경향) 금리 상승 · 예금 이자가 늘어 저축의 매력이 커짐. 대출 이자 ","keywords":["금융 자산","예금","주식"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-07","grade":"h1"},
{"id":"soc-h-c2-07#t0","kind":"term","title":"금융 자산","text":"현금, 예금, 채권, 주식처럼 돈이나 돈을 받을 권리를 나타내는 자산입니다.","keywords":["금융 자산"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-07","grade":"h1"},
{"id":"soc-h-c2-07#t1","kind":"term","title":"예금","text":"은행 등 금융 회사에 돈을 맡기고 이자를 받는 것입니다. 원금 손실 위험이 매우 낮습니다.","keywords":["예금"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-07","grade":"h1"},
{"id":"soc-h-c2-07#t2","kind":"term","title":"채권","text":"정부·지방 자치 단체·기업 등이 돈을 빌리면서 원금과 이자를 언제 갚겠다고 약속하고 발행하는 증서입니다.","keywords":["채권"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-07","grade":"h1"},
{"id":"soc-h-c2-07#t3","kind":"term","title":"주식","text":"주식회사가 자금을 마련하려고 발행하는 증서로, 가진 사람은 회사 소유권의 일부를 가집니다. 배당금과 시세 차익을 기대할 수 있습니다.","keywords":["주식"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-07","grade":"h1"},
{"id":"soc-h-c2-07#t4","kind":"term","title":"펀드","text":"전문 기관이 여러 사람의 돈을 모아 대신 투자하고, 그 수익을 투자한 금액에 따라 나눠 주는 금융 상품입니다. 원금이 보장되지 않습니다.","keywords":["펀드"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-07","grade":"h1"},
{"id":"soc-h-c2-07#t5","kind":"term","title":"수익성","text":"금융 자산으로 얼마나 많은 이익을 얻을 수 있는지를 나타내는 정도입니다.","keywords":["수익성"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-07","grade":"h1"},
{"id":"soc-h-c2-07#t6","kind":"term","title":"안전성","text":"금융 자산의 원금이 줄어들지 않고 보전될 수 있는 정도입니다.","keywords":["안전성"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-07","grade":"h1"},
{"id":"soc-h-c2-07#t7","kind":"term","title":"유동성","text":"금융 자산을 필요할 때 손해 없이 쉽게 현금으로 바꿀 수 있는 정도입니다. 환금성이라고도 합니다.","keywords":["유동성"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-07","grade":"h1"},
{"id":"soc-h-c2-07#t8","kind":"term","title":"분산 투자","text":"위험을 줄이려고 돈을 여러 자산이나 여러 회사에 나누어 투자하는 것입니다.","keywords":["분산 투자"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-07","grade":"h1"},
{"id":"soc-h-c2-07#t9","kind":"term","title":"생애 주기","text":"사람의 일생을 유소년기·청년기·중·장년기·노년기처럼 몇 단계로 나눈 것입니다. 단계마다 소득과 소비, 재무 목표가 다릅니다.","keywords":["생애 주기"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-07","grade":"h1"},
{"id":"soc-h-c2-07#f0","kind":"faq","title":"예금은 원금 손실이 전혀 없나요?","text":"예금은 금융 자산 가운데 안전성이 가장 높은 편입니다. 금융 회사가 문을 닫더라도 예금자 보호 제도에 따라 일정 금액까지는 보호받을 수 있습니다. 다만 보호 한도를 넘는 금액은 보호받지 못할 수 있고, 물가가 이자율보다 빨리 오르면 그 돈으로 살 수 있는 물건이 줄어드는 실질적인 손해는 생길 수 있습니다. 보호 한도와 대상 상품은 제도가 바뀔 수 있으니 …","keywords":["예금"],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-07","grade":"h1"},
{"id":"soc-h-c2-07#f1","kind":"faq","title":"주식이 수익이 높다면서요? 왜 다들 주식에만 투자하지 않아요?","text":"수익이 높은 만큼 위험도 크기 때문입니다. 주식은 가격이 크게 오를 수도 있지만 크게 떨어질 수도 있어 원금을 잃을 수 있습니다. 곧 써야 할 돈이나 잃으면 안 되는 돈은 예금처럼 안전한 곳에 두고, 감당할 수 있는 범위의 돈만 나누어 투자하는 것이 바람직합니다.","keywords":["주식"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-07","grade":"h1"},
{"id":"soc-h-c2-07#f2","kind":"faq","title":"학생인데 벌써 금융 설계를 해야 하나요?","text":"큰돈을 굴리는 것보다 용돈을 계획적으로 쓰고, 일부를 꾸준히 저축하는 습관을 기르는 것이 학생 시기의 금융 설계입니다. 복리의 효과는 일찍 시작할수록 크고, 좋은 금융 습관은 어른이 되어서도 이어집니다. 투자 상품에 가입하는 일은 반드시 보호자와 상의해야 합니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-07","grade":"h1"},
{"id":"soc-h-c2-07#m0","kind":"mistake","title":"자주 하는 실수","text":"채권과 주식을 헷갈리는 실수 — 채권은 돈을 빌려주고 받는 증서(이자), 주식은 회사 소유권의 일부(배당금·시세 차익)입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-07","grade":"h1"},
{"id":"soc-h-c2-07#m1","kind":"mistake","title":"자주 하는 실수","text":"\"수익성이 높으면 안전성도 높다\"고 생각하는 실수 — 수익성과 안전성은 대체로 반대로 움직이는 상충 관계입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-07","grade":"h1"},
{"id":"soc-h-c2-07#m2","kind":"mistake","title":"자주 하는 실수","text":"단리와 복리를 같게 계산하는 실수 — 복리는 이자에도 다시 이자가 붙어, 기간이 길수록 단리보다 이자가 많아집니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-07","grade":"h1"},
{"id":"soc-h-c2-08","kind":"unit","title":"국제 분업과 무역","text":"자원·노동·자본의 지역적 분포 차이가 생산비의 차이를 낳고, 각 나라가 상대적으로 유리한 상품에 특화해 교환하면 서로 이익을 얻는 원리를 배웁니다. 무역의 영향과 세계 무역 기구·자유 무역 협정, 지속가능발전에 기여하는 무역도 살펴봅니다. 자원·노동·자본의 분포 차이로 나라마다 생산비가 달라지는 까닭을 설명할 수 있다. 비교 우위에 따른 특화와 교환이 서…","keywords":["생산 요소","국제 분업","특화","절대 우위","비교 우위","무역 의존도","세계 무역 기구(WTO)","자유 무역 협정(FTA)","공정 무역","관세"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-08","grade":"h1"},
{"id":"soc-h-c2-08#c0","kind":"concept","title":"생산 요소의 분포와 생산비의 차이","text":"상품을 만드는 데 필요한 자원(토지·기후·지하자원), 노동, 자본(공장·기계·기술)을 생산 요소라고 합니다. 생산 요소는 세계 여러 지역에 고르게 퍼져 있지 않습니다. 자원: 기후가 덥고 비가 많은 지역은 커피·바나나·카카오 재배에 유리하고, 원유나 광물이 많이 묻힌 지역은 이를 싸게 ","keywords":["생산 요소"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-08","grade":"h1"},
{"id":"soc-h-c2-08#c1","kind":"concept","title":"국제 분업과 특화: 비교 우위","text":"각 나라가 자기 나라에서 상대적으로 적은 비용으로 만들 수 있는 상품을 집중적으로 생산하는 것을 특화, 이렇게 나라끼리 생산을 나누어 맡는 것을 국제 분업이라고 합니다. 절대 우위: 같은 상품을 다른 나라보다 더 적은 비용(예: 더 적은 노동 시간)으로 만들 수 있는 것 비교 우위: 다","keywords":["국제 분업","특화","절대 우위","비교 우위"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-08","grade":"h1"},
{"id":"soc-h-c2-08#c2","kind":"concept","title":"무역의 영향과 무역 의존도","text":"무역은 우리 생활에 여러 영향을 줍니다. 긍정적 영향 · 부정적 영향 나라 안에서 만들 수 없거나 비싼 상품을 싸게 살 수 있어 소비 선택의 폭이 넓어짐 · 값싼 수입품과의 경쟁에서 밀린 국내 산업이 피해를 입고 일자리가 줄어들 수 있음 수출 산업이 성장하고 더 넓은 시장에서 대량 생산","keywords":["무역 의존도"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-08","grade":"h1"},
{"id":"soc-h-c2-08#c3","kind":"concept","title":"세계 무역 기구(WTO)와 자유 무역 협정(FTA)","text":"제2차 세계 대전 뒤 나라들은 관세를 낮추고 무역을 늘리려고 관세 및 무역에 관한 일반 협정(GATT)을 맺었습니다. 이를 바탕으로 1995년 더 강한 권한을 가진 세계 무역 기구(WTO)가 출범했습니다. 여러 나라가 함께 참여하는 다자간 협상으로 관세와 무역 장벽을 낮춤 상품뿐 아니라","keywords":["세계 무역 기구(WTO)","자유 무역 협정(FTA)","관세"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-08","grade":"h1"},
{"id":"soc-h-c2-08#c4","kind":"concept","title":"지속가능발전에 기여하는 국제 무역","text":"무역은 세계 경제를 성장시켰지만, 그 이익이 고르게 나뉘지 않거나 환경과 노동을 해치는 문제도 낳았습니다. 예를 들어 커피·카카오를 기르는 개발 도상국의 농민이 낮은 가격 때문에 가난에서 벗어나지 못하거나, 값싼 생산을 위해 아동 노동과 숲 파괴가 이루어지기도 합니다. 공정 무역은 이런","keywords":["공정 무역"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-08","grade":"h1"},
{"id":"soc-h-c2-08#t0","kind":"term","title":"생산 요소","text":"상품을 만드는 데 필요한 자원(토지·자연), 노동, 자본을 말합니다. 그 분포가 나라마다 달라 생산비의 차이가 생깁니다.","keywords":["생산 요소"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-08","grade":"h1"},
{"id":"soc-h-c2-08#t1","kind":"term","title":"국제 분업","text":"각 나라가 상대적으로 유리한 상품의 생산을 나누어 맡는 것입니다.","keywords":["국제 분업"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-08","grade":"h1"},
{"id":"soc-h-c2-08#t2","kind":"term","title":"특화","text":"한 나라가 상대적으로 적은 비용으로 만들 수 있는 상품을 집중적으로 생산하는 것입니다.","keywords":["특화"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-08","grade":"h1"},
{"id":"soc-h-c2-08#t3","kind":"term","title":"절대 우위","text":"어떤 상품을 다른 나라보다 더 적은 비용(노동 시간 등)으로 생산할 수 있는 것입니다.","keywords":["절대 우위"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-08","grade":"h1"},
{"id":"soc-h-c2-08#t4","kind":"term","title":"비교 우위","text":"다른 나라에 비해 어떤 상품을 생산하는 기회비용이 더 작은 것입니다. 무역은 비교 우위에 따른 특화로 서로 이익이 됩니다.","keywords":["비교 우위"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-08","grade":"h1"},
{"id":"soc-h-c2-08#t5","kind":"term","title":"무역 의존도","text":"한 나라의 경제가 무역에 기대는 정도로, (수출액 + 수입액) ÷ 국내 총생산 × 100 으로 구합니다.","keywords":["무역 의존도"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-08","grade":"h1"},
{"id":"soc-h-c2-08#t6","kind":"term","title":"세계 무역 기구(WTO)","text":"1995년에 출범한 국제기구로, 다자간 협상으로 무역 장벽을 낮추고 회원국 사이의 무역 분쟁을 해결합니다.","keywords":["세계 무역 기구(WTO)"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-08","grade":"h1"},
{"id":"soc-h-c2-08#t7","kind":"term","title":"자유 무역 협정(FTA)","text":"협정을 맺은 나라끼리 관세와 무역 장벽을 낮추거나 없애기로 한 약속입니다.","keywords":["자유 무역 협정(FTA)"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-08","grade":"h1"},
{"id":"soc-h-c2-08#t8","kind":"term","title":"공정 무역","text":"개발 도상국 생산자에게 정당한 대가를 지급하고, 노동 환경과 자연환경을 지키며 거래하려는 무역입니다.","keywords":["공정 무역"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-08","grade":"h1"},
{"id":"soc-h-c2-08#t9","kind":"term","title":"관세","text":"다른 나라에서 들어오는 상품에 매기는 세금입니다. 관세를 높이면 수입품 가격이 올라 국내 산업이 보호됩니다.","keywords":["관세"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-08","grade":"h1"},
{"id":"soc-h-c2-08#f0","kind":"faq","title":"모든 걸 더 잘 만드는 나라는 왜 굳이 무역을 해요?","text":"모든 상품을 더 잘 만들어도, 시간과 자원은 한정되어 있어서 하나를 만들면 다른 것을 포기해야 합니다. 그 포기하는 것(기회비용)이 가장 작은 상품에 집중하고 나머지는 사 오면, 같은 노력으로 더 많은 상품을 누릴 수 있습니다. 이것이 비교 우위에 따른 무역입니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-08","grade":"h1"},
{"id":"soc-h-c2-08#f1","kind":"faq","title":"무역 의존도가 높은 건 좋은 거예요, 나쁜 거예요?","text":"한쪽으로 단정하기 어렵습니다. 무역 의존도가 높으면 넓은 세계 시장에서 성장할 기회가 많지만, 다른 나라의 경기 침체나 무역 갈등에 크게 흔들릴 수 있습니다. 그래서 무역 상대국과 수출 상품을 다양하게 하고, 국내 시장도 함께 키우는 노력이 필요합니다.","keywords":["무역 의존도"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-08","grade":"h1"},
{"id":"soc-h-c2-08#f2","kind":"faq","title":"공정 무역 상품은 왜 더 비싸요?","text":"생산자에게 생산비와 생활을 보장하는 가격을 주고, 아동 노동을 쓰지 않으며, 환경을 보호하는 방식으로 생산하기 때문에 비용이 더 들 수 있습니다. 그 차이는 생산자의 생활과 노동 환경, 자연환경을 지키는 데 쓰인다고 볼 수 있습니다.","keywords":["공정 무역"],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-08","grade":"h1"},
{"id":"soc-h-c2-08#m0","kind":"mistake","title":"자주 하는 실수","text":"절대 우위가 있는 상품에 비교 우위도 있다고 생각하는 실수 — 비교 우위는 노동 시간 자체가 아니라 기회비용을 비교해서 정합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-08","grade":"h1"},
{"id":"soc-h-c2-08#m1","kind":"mistake","title":"자주 하는 실수","text":"무역 의존도를 구할 때 수출액만 넣거나 수출액에서 수입액을 빼는 실수 — (수출액 + 수입액) ÷ 국내 총생산 × 100 입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-08","grade":"h1"},
{"id":"soc-h-c2-08#m2","kind":"mistake","title":"자주 하는 실수","text":"FTA의 관세 특혜가 모든 나라에 적용된다고 생각하는 실수 — FTA의 특혜는 협정을 맺은 나라끼리만 주어집니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-08","grade":"h1"},
{"id":"soc-h-c2-09","kind":"unit","title":"세계화의 양상과 과제","text":"교통·통신의 발달과 무역 자유화로 나타난 세계화의 모습을 세계 도시, 다국적 기업, 지역화를 통해 살펴보고, 세계화가 낳은 문제와 그 해결 방안을 탐구합니다. 세계화의 의미와 배경을 교통·통신 발달, 무역 자유화와 관련지어 설명할 수 있다. 세계화와 지역화의 관계를 지역 브랜드, 장소 마케팅 사례로 설명할 수 있다. 세계 도시의 특징과 다국적 기업의 공간…","keywords":["세계화","시공간 압축","세계 무역 기구(WTO)","지역화","장소 마케팅","지리적 표시제","세계 도시","다국적 기업","공간적 분업","특수 윤리"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-09","grade":"h1"},
{"id":"soc-h-c2-09#c0","kind":"concept","title":"세계화의 의미와 배경","text":"세계화란 국가 사이의 경계를 넘어 사람, 상품, 자본, 정보, 문화가 자유롭게 오가면서 세계가 하나의 생활권으로 묶여 가는 현상입니다. 세계화가 빨라진 배경은 크게 두 가지입니다. 교통·통신의 발달: 대형 선박과 항공기, 고속 철도가 등장하고 인터넷과 이동 통신이 퍼지면서 먼 곳까지 가","keywords":["세계화","시공간 압축","세계 무역 기구(WTO)"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-09","grade":"h1"},
{"id":"soc-h-c2-09#c1","kind":"concept","title":"세계화와 지역화","text":"세계화가 진행될수록 오히려 지역의 고유한 특성이 더 주목받기도 합니다. 지역의 자연환경, 전통문화, 특산물 같은 고유한 특성이 세계적으로 가치를 지니게 되는 현상을 지역화라고 합니다. 지역화를 위한 대표적인 전략은 다음과 같습니다. 전략 · 뜻 · 예 지역 브랜드 · 지역의 이름이나 특","keywords":["세계화","지역화","장소 마케팅","지리적 표시제"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-09","grade":"h1"},
{"id":"soc-h-c2-09#c2","kind":"concept","title":"세계 도시","text":"세계화가 진행되면서 세계 경제를 이끄는 중심 역할을 하는 도시가 나타났습니다. 이를 세계 도시라고 합니다. 세계 도시의 특징은 다음과 같습니다. 다국적 기업의 본사, 국제 금융 기관과 은행, 국제기구가 모여 있습니다. 생산자 서비스(금융, 법률, 광고, 회계 등 기업을 돕는 서비스)가 ","keywords":["세계화","세계 도시","다국적 기업"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-09","grade":"h1"},
{"id":"soc-h-c2-09#c3","kind":"concept","title":"다국적 기업과 공간적 분업","text":"다국적 기업은 둘 이상의 나라에 지사, 연구소, 생산 공장 등을 두고 세계를 무대로 활동하는 기업입니다. 무역 자유화와 교통·통신의 발달로 다국적 기업의 활동이 크게 늘었습니다. 다국적 기업은 각 기능을 그 기능에 가장 유리한 곳에 따로 둡니다. 이것을 공간적 분업이라고 합니다. 기능 ","keywords":["세계 도시","다국적 기업","공간적 분업"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-09","grade":"h1"},
{"id":"soc-h-c2-09#c4","kind":"concept","title":"세계화의 문제점","text":"세계화는 경제 성장과 문화 교류의 기회를 넓혔지만, 여러 문제도 낳았습니다. 1. 문화의 획일화와 소멸 세계적으로 영향력이 큰 문화가 빠르게 퍼지면서 세계 곳곳의 음식, 옷, 음악이 비슷해지고 있습니다. 그 과정에서 소수 민족의 언어나 전통문화가 사라질 위기에 놓이기도 합니다. 문화의 ","keywords":["세계화","특수 윤리"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-09","grade":"h1"},
{"id":"soc-h-c2-09#c5","kind":"concept","title":"세계화 문제의 해결 방안","text":"세계화가 낳은 문제는 한 나라의 힘만으로 풀기 어렵습니다. 다음과 같은 노력이 함께 필요합니다. 1. 국제 협력 국제기구와 각국 정부가 힘을 모읍니다. 선진국 정부가 개발 도상국의 발전을 돕는 공적 개발 원조(ODA), 국경을 넘는 문제에 함께 대응하는 국제 협약이 그 예입니다. 2. ","keywords":["세계화"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-09","grade":"h1"},
{"id":"soc-h-c2-09#t0","kind":"term","title":"세계화","text":"국가 사이의 경계를 넘어 사람, 상품, 자본, 정보, 문화가 자유롭게 오가면서 세계가 하나의 생활권으로 묶여 가는 현상입니다.","keywords":["세계화"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-09","grade":"h1"},
{"id":"soc-h-c2-09#t1","kind":"term","title":"시공간 압축","text":"교통·통신의 발달로 이동 시간과 비용이 줄어 지역 사이에 실제로 느끼는 거리가 가까워지는 현상입니다.","keywords":["시공간 압축"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-09","grade":"h1"},
{"id":"soc-h-c2-09#t2","kind":"term","title":"세계 무역 기구(WTO)","text":"1995년 출범한 국제기구로, 관세와 무역 장벽을 낮추어 자유 무역을 넓히고 무역 분쟁을 조정합니다.","keywords":["세계 무역 기구(WTO)"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-09","grade":"h1"},
{"id":"soc-h-c2-09#t3","kind":"term","title":"지역화","text":"지역의 자연환경, 전통문화, 특산물 같은 고유한 특성이 세계적으로 가치를 지니게 되는 현상입니다.","keywords":["지역화"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-09","grade":"h1"},
{"id":"soc-h-c2-09#t4","kind":"term","title":"장소 마케팅","text":"특정 장소를 하나의 상품으로 보고 매력적인 이미지와 시설을 만들어 알리는 전략입니다. 예: 지역 축제","keywords":["장소 마케팅"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-09","grade":"h1"},
{"id":"soc-h-c2-09#t5","kind":"term","title":"지리적 표시제","text":"품질과 명성이 그 지역의 지리적 특성에서 비롯된 상품에 지역 이름을 표시하고 법으로 보호하는 제도입니다. 예: 보성 녹차","keywords":["지리적 표시제"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-09","grade":"h1"},
{"id":"soc-h-c2-09#t6","kind":"term","title":"세계 도시","text":"다국적 기업 본사, 국제 금융 기관, 국제기구가 모여 세계 경제의 중심 역할을 하는 도시입니다. 예: 뉴욕, 런던, 도쿄","keywords":["세계 도시"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-09","grade":"h1"},
{"id":"soc-h-c2-09#t7","kind":"term","title":"다국적 기업","text":"둘 이상의 나라에 지사, 연구소, 생산 공장 등을 두고 세계를 무대로 활동하는 기업입니다.","keywords":["다국적 기업"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-09","grade":"h1"},
{"id":"soc-h-c2-09#t8","kind":"term","title":"공간적 분업","text":"기업이 본사, 연구소, 생산 공장 같은 기능을 각각 가장 유리한 곳에 나누어 배치하는 것입니다.","keywords":["공간적 분업"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-09","grade":"h1"},
{"id":"soc-h-c2-09#t9","kind":"term","title":"특수 윤리","text":"특정 국가·민족·종교·지역 등에서 고유하게 지켜 온 윤리입니다. 모든 인류가 지켜야 할 보편 윤리와 구별됩니다.","keywords":["특수 윤리"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-09","grade":"h1"},
{"id":"soc-h-c2-09#f0","kind":"faq","title":"세계화랑 지역화는 반대말 아닌가요?","text":"이름만 보면 반대처럼 보이지만, 실제로는 함께 진행됩니다. 세계가 하나의 시장으로 묶일수록 다른 곳과 구별되는 지역의 특색이 경쟁력이 되기 때문입니다. 그래서 지역들은 장소 마케팅, 지역 브랜드, 지리적 표시제로 자기 지역의 가치를 세계에 알립니다. 이렇게 둘이 함께 나타나는 것을 세계지역화라고 합니다.","keywords":["세계화","지역화"],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-09","grade":"h1"},
{"id":"soc-h-c2-09#f1","kind":"faq","title":"사람이 많이 사는 도시면 세계 도시인가요?","text":"세계 도시는 인구가 아니라 기능으로 판단합니다. 다국적 기업 본사, 국제 금융 기관, 국제기구가 얼마나 모여 있는지, 세계 여러 지역과 얼마나 촘촘히 연결되어 있는지가 기준입니다. 인구가 많아도 이런 기능이 약하면 세계 도시로 보기 어렵습니다.","keywords":["세계 도시"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-09","grade":"h1"},
{"id":"soc-h-c2-09#f2","kind":"faq","title":"공장이 개발 도상국으로 가면 그 나라에는 좋은 건가요?","text":"일자리가 생기고 기술과 자본이 들어온다는 좋은 점이 있습니다. 하지만 이익의 많은 부분이 본사가 있는 나라로 돌아가거나, 낮은 임금과 열악한 노동 환경, 환경 오염 문제가 생기기도 합니다. 그래서 공정한 국제 규범과 노동·환경 기준이 함께 필요합니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-09","grade":"h1"},
{"id":"soc-h-c2-09#m0","kind":"mistake","title":"자주 하는 실수","text":"세계 도시를 \"인구가 많은 도시\"로 아는 실수 — 다국적 기업 본사, 국제 금융 기관 같은 세계 경제를 이끄는 기능이 기준입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-09","grade":"h1"},
{"id":"soc-h-c2-09#m1","kind":"mistake","title":"자주 하는 실수","text":"다국적 기업의 생산 공장은 개발 도상국에만 들어선다고 아는 실수 — 무역 장벽을 피하고 시장을 넓히려고 선진국에 공장을 세우기도 합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-09","grade":"h1"},
{"id":"soc-h-c2-09#m2","kind":"mistake","title":"자주 하는 실수","text":"세계화와 지역화를 서로 막는 현상으로 아는 실수 — 둘은 함께 진행되며, 이를 세계지역화라고 합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-09","grade":"h1"},
{"id":"soc-h-c2-10","kind":"unit","title":"평화와 남북 통일","text":"소극적 평화와 적극적 평화의 뜻을 알고, 국제 사회의 갈등과 협력, 평화를 위한 여러 행위 주체의 역할을 살핍니다. 남북 분단과 동아시아 역사 갈등을 이해하고, 우리나라가 세계 평화에 기여하는 방안을 탐구합니다. 소극적 평화와 적극적 평화의 의미를 폭력의 종류와 관련지어 설명할 수 있다. 국제 사회의 갈등과 협력 사례를 분석하고, 평화를 위한 행위 주체의…","keywords":["소극적 평화","적극적 평화","구조적 폭력","문화적 폭력","국제 비정부 기구(NGO)","평화 유지 활동(PKO)","7·4 남북 공동 성명","남북 기본 합의서","동북공정","분단 비용"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-10","grade":"h1"},
{"id":"soc-h-c2-10#c0","kind":"concept","title":"평화의 의미 — 소극적 평화와 적극적 평화","text":"노르웨이의 평화학자 요한 갈퉁은 폭력을 세 가지로 나누고, 어떤 폭력이 없는 상태인지에 따라 평화를 두 가지로 구분하였습니다. 폭력 · 뜻 · 예 직접적 폭력 · 행위자가 분명히 드러나며 신체적·물리적으로 해를 입히는 폭력 · 전쟁, 테러, 폭행, 살인 구조적 폭력 · 사회 구조나 제도","keywords":["소극적 평화","적극적 평화","구조적 폭력","문화적 폭력"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-10","grade":"h1"},
{"id":"soc-h-c2-10#c1","kind":"concept","title":"국제 사회의 갈등과 협력","text":"국제 사회에서는 여러 까닭으로 갈등이 일어납니다. 영토와 자원: 땅과 바다, 그 아래 묻힌 자원을 서로 차지하려는 다툼. 예: 여러 나라가 섬의 영유권과 바다 자원을 두고 맞서는 남중국해 분쟁 민족과 종교: 민족이나 종교가 다른 집단 사이의 갈등. 예: 인도와 파키스탄이 영토와 종교 문","keywords":[],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-10","grade":"h1"},
{"id":"soc-h-c2-10#c2","kind":"concept","title":"평화를 위한 행위 주체의 역할","text":"국제 사회에서 평화를 만들어 가는 행위 주체는 여러 가지입니다. 행위 주체 · 특징과 역할 국가 · 가장 기본적인 행위 주체. 외교를 통해 자국의 이익을 지키면서 다른 나라와 갈등을 조정하고 협력함 정부 간 국제기구 · 여러 나라 정부가 회원으로 참여하는 기구. 예: 국제 연합(UN) ","keywords":["국제 비정부 기구(NGO)","평화 유지 활동(PKO)"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-10","grade":"h1"},
{"id":"soc-h-c2-10#c3","kind":"concept","title":"남북 분단의 배경과 평화 통일을 위한 노력","text":"분단의 배경 1945년 광복 뒤 북위 38도선을 경계로 남쪽에는 미군이, 북쪽에는 소련군이 주둔하였습니다. 미국과 소련이 맞서는 냉전이 깊어지면서 1948년 남과 북에 서로 다른 정부가 세워졌습니다. 1950년 6·25 전쟁이 일어나 큰 피해를 남겼고, 1953년 정전 협정을 맺으면서 ","keywords":["7·4 남북 공동 성명","남북 기본 합의서"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-10","grade":"h1"},
{"id":"soc-h-c2-10#c4","kind":"concept","title":"동아시아의 역사 갈등과 해결 노력","text":"동아시아에서는 과거 역사를 둘러싼 갈등이 오늘날까지 이어지고 있습니다. 일본의 역사 교과서 왜곡: 일본의 일부 역사 교과서는 식민 지배와 침략 전쟁을 정당화하거나 미화하고, 일본군 '위안부' 강제 동원 같은 가해 사실을 축소하거나 빼고 서술하여 주변국의 반발을 사고 있습니다. 일본의 독","keywords":["동북공정"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-10","grade":"h1"},
{"id":"soc-h-c2-10#c5","kind":"concept","title":"우리나라의 위상과 세계 평화를 위한 기여","text":"지정학적 위치 우리나라는 유라시아 대륙과 태평양 사이에 자리 잡은 반도국입니다. 대륙과 해양으로 모두 나아갈 수 있는 이점이 있지만, 주변 강대국의 이해관계가 맞부딪치는 곳이어서 역사적으로 여러 차례 침략과 갈등을 겪었습니다. 남북 분단 역시 이러한 국제 정세와 깊은 관련이 있습니다. ","keywords":[],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-10","grade":"h1"},
{"id":"soc-h-c2-10#t0","kind":"term","title":"소극적 평화","text":"전쟁, 테러, 폭행 같은 직접적 폭력이 없는 상태입니다.","keywords":["소극적 평화"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-10","grade":"h1"},
{"id":"soc-h-c2-10#t1","kind":"term","title":"적극적 평화","text":"직접적 폭력뿐 아니라 빈곤, 차별 같은 구조적 폭력과 문화적 폭력까지 없는 상태입니다. 갈퉁이 제시하였습니다.","keywords":["적극적 평화"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-10","grade":"h1"},
{"id":"soc-h-c2-10#t2","kind":"term","title":"구조적 폭력","text":"사회 구조나 제도 때문에 생기는 간접적인 폭력입니다. 가해자가 잘 드러나지 않습니다. 예: 빈곤, 기아, 차별","keywords":["구조적 폭력"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-10","grade":"h1"},
{"id":"soc-h-c2-10#t3","kind":"term","title":"문화적 폭력","text":"종교, 사상, 언어, 예술 같은 문화가 직접적·구조적 폭력을 옳은 것처럼 보이게 하는 것입니다.","keywords":["문화적 폭력"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-10","grade":"h1"},
{"id":"soc-h-c2-10#t4","kind":"term","title":"국제 비정부 기구(NGO)","text":"개인이나 민간단체가 국경을 넘어 만든 기구로, 인권 보호, 난민 구호, 환경 보호 등의 활동을 합니다.","keywords":["국제 비정부 기구(NGO)"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-10","grade":"h1"},
{"id":"soc-h-c2-10#t5","kind":"term","title":"평화 유지 활동(PKO)","text":"국제 연합이 분쟁 지역에 평화 유지군 등을 보내 휴전을 감시하고 평화를 지키도록 돕는 활동입니다.","keywords":["평화 유지 활동(PKO)"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-10","grade":"h1"},
{"id":"soc-h-c2-10#t6","kind":"term","title":"7·4 남북 공동 성명","text":"1972년 남북이 자주·평화·민족적 대단결의 통일 3대 원칙에 합의한 성명입니다.","keywords":["7·4 남북 공동 성명"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-10","grade":"h1"},
{"id":"soc-h-c2-10#t7","kind":"term","title":"남북 기본 합의서","text":"1991년 남북이 서로의 체제 인정, 상호 불가침, 교류·협력에 합의한 문서입니다.","keywords":["남북 기본 합의서"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-10","grade":"h1"},
{"id":"soc-h-c2-10#t8","kind":"term","title":"동북공정","text":"중국이 2002년부터 추진한 연구 사업으로, 고구려와 발해의 역사를 중국 지방 정권의 역사로 편입하려 하였습니다.","keywords":["동북공정"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-10","grade":"h1"},
{"id":"soc-h-c2-10#t9","kind":"term","title":"분단 비용","text":"분단 때문에 계속 들어가는 비용입니다. 군사비, 이산가족의 고통, 민족 동질성 약화 등이 있습니다.","keywords":["분단 비용"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-10","grade":"h1"},
{"id":"soc-h-c2-10#f0","kind":"faq","title":"전쟁만 없으면 평화로운 거 아닌가요?","text":"전쟁 같은 직접적 폭력이 없는 상태는 소극적 평화입니다. 갈퉁은 빈곤, 차별 같은 구조적 폭력과 그것을 당연하게 여기게 만드는 문화적 폭력까지 없어야 진정한 평화, 곧 적극적 평화라고 보았습니다. 오늘날 국제 사회가 빈곤 해결과 인권 보호에 힘쓰는 것도 적극적 평화를 이루기 위해서입니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-10","grade":"h1"},
{"id":"soc-h-c2-10#f1","kind":"faq","title":"정부 간 국제기구랑 비정부 기구는 뭐가 달라요?","text":"정부 간 국제기구는 여러 나라 정부가 회원으로 참여하는 기구로, 국제 연합(UN)이 대표적입니다. 국제 비정부 기구(NGO)는 개인이나 민간단체가 만든 기구로, 정부의 이익에 얽매이지 않고 인권·구호·환경 같은 활동을 펼칩니다. 누가 회원이고 누가 운영하는지가 가장 큰 차이입니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-10","grade":"h1"},
{"id":"soc-h-c2-10#f2","kind":"faq","title":"통일 비용이 많이 든다는데 그래도 통일해야 하나요?","text":"통일 비용은 한때 많이 들지만 미래를 위한 투자의 성격이 있습니다. 반면 분단이 계속되면 군사비 같은 분단 비용이 끝없이 들고, 이산가족의 아픔도 이어집니다. 그래서 통일 비용만이 아니라 분단 비용, 통일로 얻는 편익, 돈으로 계산하기 어려운 가치까지 함께 따져 보아야 합니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-10","grade":"h1"},
{"id":"soc-h-c2-10#m0","kind":"mistake","title":"자주 하는 실수","text":"소극적 평화와 적극적 평화를 거꾸로 아는 실수 — 직접적 폭력만 없으면 소극적 평화, 구조적·문화적 폭력까지 없으면 적극적 평화입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-10","grade":"h1"},
{"id":"soc-h-c2-10#m1","kind":"mistake","title":"자주 하는 실수","text":"국제 연합(UN)을 비정부 기구로 아는 실수 — 국제 연합은 각국 정부가 회원인 정부 간 국제기구입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-10","grade":"h1"},
{"id":"soc-h-c2-10#m2","kind":"mistake","title":"자주 하는 실수","text":"7·4 남북 공동 성명과 6·15 남북 공동 선언의 순서를 헷갈리는 실수 — 7·4 남북 공동 성명이 1972년으로 먼저이고, 6·15 남북 공동 선언은 2000년입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-10","grade":"h1"},
{"id":"soc-h-c2-11","kind":"unit","title":"세계의 인구 문제","text":"세계의 인구 분포와 그 요인, 인구 피라미드로 본 인구 구조, 국내·국제 인구 이동을 자료로 읽고, 개발 도상국과 선진국·우리나라의 인구 문제 및 해결 방안을 탐구합니다. 세계의 인구 밀집 지역과 희박 지역을 자연적·인문적 요인으로 설명할 수 있다. 인구 피라미드를 읽고 개발 도상국형과 선진국형 인구 구조를 구별할 수 있다. 국내·국제 인구 이동의 흐름과…","keywords":["인구 밀도","인구 구조","인구 피라미드","유소년층","청장년층","노년층","이촌 향도","합계 출산율","고령화","노년 부양비"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-11","grade":"h1"},
{"id":"soc-h-c2-11#c0","kind":"concept","title":"세계의 인구 분포와 요인","text":"세계 인구는 2022년에 80억 명을 넘었습니다. 하지만 사람들은 지구 위에 고르게 퍼져 살지 않습니다. 세계 인구의 대부분(약 90%)이 북반구에 살고, 아시아에만 절반 이상이 삽니다. 구분 · 주요 지역 · 까닭 인구 밀집 지역 · 동아시아·남아시아, 서부 유럽, 미국 북동부 · 기","keywords":[],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-11","grade":"h1"},
{"id":"soc-h-c2-11#c1","kind":"concept","title":"인구 구조와 인구 피라미드","text":"인구 구조는 한 지역의 인구를 성별, 연령별로 나누어 본 구성입니다. 연령은 보통 세 층으로 나눕니다. 유소년층: 0~14세 청장년층(생산 가능 인구): 15~64세 노년층: 65세 이상 인구 구조를 한눈에 보여 주는 그래프가 인구 피라미드입니다. 가운데 세로축을 기준으로 왼쪽에 남자,","keywords":["인구 구조","인구 피라미드","유소년층","청장년층","노년층"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-11","grade":"h1"},
{"id":"soc-h-c2-11#c2","kind":"concept","title":"인구 이동","text":"사람들은 더 나은 삶을 찾아 옮겨 갑니다. 살던 곳에서 떠나게 만드는 요인을 배출 요인(낮은 임금, 일자리 부족, 전쟁, 자연재해 등), 새로운 곳으로 끌어당기는 요인을 흡인 요인(높은 임금, 풍부한 일자리, 좋은 교육·문화 시설, 안전 등)이라고 합니다. 국제 인구 이동 경제적 이동:","keywords":[],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-11","grade":"h1"},
{"id":"soc-h-c2-11#c3","kind":"concept","title":"개발 도상국의 인구 문제","text":"많은 개발 도상국은 의학의 발달과 위생 개선으로 사망률은 빠르게 낮아졌지만 출생률은 여전히 높아 인구가 빠르게 늘었습니다. 인구 과잉의 문제 인구가 늘어나는 속도를 경제 성장이 따라가지 못해 식량·자원 부족, 일자리 부족, 빈곤이 나타납니다. 농촌 인구가 한꺼번에 도시로 몰려 주택·교통","keywords":["유소년층"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-11","grade":"h1"},
{"id":"soc-h-c2-11#c4","kind":"concept","title":"선진국과 우리나라의 저출생·고령화","text":"선진국과 우리나라는 개발 도상국과 반대로 저출생과 고령화가 문제입니다. 저출생 합계 출산율은 여성 한 명이 평생 낳을 것으로 예상되는 평균 자녀 수입니다. 인구가 줄지 않고 유지되려면 약 2.1명이 필요한데, 우리나라는 2018년에 1명 아래로 떨어져 세계에서 가장 낮은 수준입니다. 결","keywords":["노년층","합계 출산율","고령화"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-11","grade":"h1"},
{"id":"soc-h-c2-11#c5","kind":"concept","title":"미래 세대를 위한 인구 문제 해결 방안","text":"인구 문제는 오늘 해결하지 않으면 미래 세대가 더 큰 짐을 지게 됩니다. 선진국과 우리나라에서는 다음과 같은 노력이 필요합니다. 1. 출산·양육 지원 (저출생 대책) 출산 지원금, 아동 수당 등으로 양육비 부담을 줄입니다. 육아 휴직을 늘리고 보육 시설을 확충하여 일과 가정의 양립을 돕","keywords":["고령화"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-11","grade":"h1"},
{"id":"soc-h-c2-11#t0","kind":"term","title":"인구 밀도","text":"일정한 넓이(보통 1 km²)에 사는 사람의 수입니다. 인구 ÷ 면적으로 구합니다.","keywords":["인구 밀도"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-11","grade":"h1"},
{"id":"soc-h-c2-11#t1","kind":"term","title":"인구 구조","text":"한 지역의 인구를 성별·연령별로 나누어 본 구성입니다.","keywords":["인구 구조"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-11","grade":"h1"},
{"id":"soc-h-c2-11#t2","kind":"term","title":"인구 피라미드","text":"가운데 세로축의 왼쪽에 남자, 오른쪽에 여자의 연령층별 인구 비율을 막대로 나타낸 그래프입니다. 아래쪽일수록 어린 연령층입니다.","keywords":["인구 피라미드"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-11","grade":"h1"},
{"id":"soc-h-c2-11#t3","kind":"term","title":"유소년층","text":"0~14세 인구입니다.","keywords":["유소년층"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-11","grade":"h1"},
{"id":"soc-h-c2-11#t4","kind":"term","title":"청장년층","text":"15~64세 인구로, 생산 가능 인구라고도 합니다.","keywords":["청장년층"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-11","grade":"h1"},
{"id":"soc-h-c2-11#t5","kind":"term","title":"노년층","text":"65세 이상 인구입니다.","keywords":["노년층"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-11","grade":"h1"},
{"id":"soc-h-c2-11#t6","kind":"term","title":"이촌 향도","text":"농촌 인구가 일자리를 찾아 도시로 옮겨 가는 현상입니다. 산업화가 진행되는 시기에 활발합니다.","keywords":["이촌 향도"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-11","grade":"h1"},
{"id":"soc-h-c2-11#t7","kind":"term","title":"합계 출산율","text":"여성 한 명이 평생 낳을 것으로 예상되는 평균 자녀 수입니다. 인구가 유지되려면 약 2.1명이 필요합니다.","keywords":["합계 출산율"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-11","grade":"h1"},
{"id":"soc-h-c2-11#t8","kind":"term","title":"고령화","text":"전체 인구에서 노년층(65세 이상)이 차지하는 비율이 높아지는 현상입니다. 7% 이상 고령화 사회, 14% 이상 고령 사회, 20% 이상 초고령 사회라고 합니다.","keywords":["고령화"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-11","grade":"h1"},
{"id":"soc-h-c2-11#t9","kind":"term","title":"노년 부양비","text":"청장년층 인구 100명이 부양해야 하는 노년층 인구입니다. 노년층 ÷ 청장년층 × 100으로 구합니다.","keywords":["노년 부양비"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-11","grade":"h1"},
{"id":"soc-h-c2-11#f0","kind":"faq","title":"인구가 많으면 좋은 거 아니에요? 왜 줄어드는 게 문제예요?","text":"인구가 너무 빠르게 늘면 식량·일자리가 부족해지고, 반대로 너무 빠르게 줄거나 늙으면 일할 사람이 모자라고 부양 부담이 커집니다. 문제는 인구의 많고 적음보다 변화의 속도와 구조입니다. 사회가 적응할 시간 없이 급하게 변할 때 문제가 커집니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-11","grade":"h1"},
{"id":"soc-h-c2-11#f1","kind":"faq","title":"종형이랑 방추형은 어떻게 구별해요?","text":"맨 아래(유소년층) 막대를 보세요. 아래와 가운데의 폭이 비슷하면 종형, 아래가 가운데보다 눈에 띄게 좁아 가운데가 불룩하면 방추형입니다. 방추형은 출생률이 매우 낮아 앞으로 인구가 줄어들 수 있음을 뜻합니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-11","grade":"h1"},
{"id":"soc-h-c2-11#f2","kind":"faq","title":"노년 부양비랑 노년층 비율은 뭐가 달라요?","text":"노년층 비율은 노년층 ÷ 전체 인구 × 100으로, 고령화 단계를 판단할 때 씁니다. 노년 부양비는 노년층 ÷ 청장년층 × 100으로, 일하는 사람이 짊어지는 부양 부담을 볼 때 씁니다. 나누는 수가 다릅니다.","keywords":["노년층","노년 부양비"],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-11","grade":"h1"},
{"id":"soc-h-c2-11#m0","kind":"mistake","title":"자주 하는 실수","text":"노년 부양비를 구할 때 전체 인구로 나누는 실수 — 노년 부양비는 청장년층(15~64세)으로 나눕니다. 전체 인구로 나누면 노년층 비율입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-11","grade":"h1"},
{"id":"soc-h-c2-11#m1","kind":"mistake","title":"자주 하는 실수","text":"고령화 단계 기준을 헷갈리는 실수 — 65세 이상 비율이 7% 이상 고령화 사회, 14% 이상 고령 사회, 20% 이상 초고령 사회입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-11","grade":"h1"},
{"id":"soc-h-c2-11#m2","kind":"mistake","title":"자주 하는 실수","text":"개발 도상국과 선진국의 인구 정책을 거꾸로 짝짓는 실수 — 인구 과잉을 겪는 개발 도상국은 출산 조절, 저출생을 겪는 선진국은 출산·양육 지원이 중심입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-11","grade":"h1"},
{"id":"soc-h-c2-12","kind":"unit","title":"에너지와 지속가능한 미래","text":"석유·석탄·천연가스의 분포와 소비 실태, 화석 에너지 중심 소비의 문제를 살피고, 기후 변화에 대한 국제적 대응과 지속가능한 발전을 위한 노력을 탐구합니다. 미래 사회의 변화를 예측하여 세계시민으로서 나의 삶의 방향을 세워 봅니다. 석유·석탄·천연가스의 분포와 소비 특징을 설명하고, 화석 에너지 중심 소비의 문제를 분석할 수 있다. 기후 변화 협약, 파리…","keywords":["화석 에너지","편재성","자원 민족주의","신재생 에너지","기후 변화 협약","파리 협정","탄소 중립","지속가능한 발전","탄소 배출권 거래제","세계시민"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-12","grade":"h1"},
{"id":"soc-h-c2-12#c0","kind":"concept","title":"화석 에너지의 분포와 소비","text":"화석 에너지는 아주 오랜 옛날의 생물이 땅속에 묻혀 만들어진 석탄, 석유, 천연가스를 말합니다. 오늘날 세계에서 쓰는 에너지의 약 80%가 화석 에너지입니다. 자원 · 분포 · 주요 용도와 특징 석유 · 서남아시아의 페르시아만 연안에 특히 많이 묻혀 있어 분포가 매우 고르지 않음(편재성","keywords":["화석 에너지","편재성"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-12","grade":"h1"},
{"id":"soc-h-c2-12#c1","kind":"concept","title":"화석 에너지 중심 소비의 문제","text":"화석 에너지는 산업 발전을 이끌었지만, 지나치게 의존하면서 여러 문제가 나타났습니다. 1. 자원의 고갈 화석 에너지는 한번 쓰면 다시 만들어지는 데 아주 오랜 시간이 걸리는 재생 불가능한 자원입니다. 매장량에는 한계가 있어 언젠가 고갈될 수 있습니다. 2. 자원을 둘러싼 갈등 편재성이 ","keywords":["화석 에너지","편재성","자원 민족주의"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-12","grade":"h1"},
{"id":"soc-h-c2-12#c2","kind":"concept","title":"기후 변화에 대한 국제적 대응","text":"기후 변화는 한 나라의 노력만으로 막을 수 없어 국제 사회가 함께 대응해 왔습니다. 연도 · 협약 · 주요 내용 1992년 · 기후 변화 협약 · 리우데자네이루에서 열린 유엔 환경 개발 회의에서 여러 나라가 서명. 온실가스를 줄이기 위한 국제 협력의 틀을 마련함 1997년 · 교토 의정","keywords":["기후 변화 협약","파리 협정","탄소 중립"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-12","grade":"h1"},
{"id":"soc-h-c2-12#c3","kind":"concept","title":"지속가능한 발전을 위한 노력","text":"지속가능한 발전이란 미래 세대가 자신의 필요를 채울 수 있는 능력을 해치지 않으면서, 현재 세대의 필요를 채우는 발전입니다. 환경 보전, 경제 성장, 사회 통합이 조화를 이루어야 합니다. 국제 연합은 2015년 2030년까지 이루어야 할 17개의 지속가능발전목표(SDGs) 를 정하였습니","keywords":["신재생 에너지","지속가능한 발전","탄소 배출권 거래제"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-12","grade":"h1"},
{"id":"soc-h-c2-12#c4","kind":"concept","title":"미래 사회의 변화 예측","text":"미래를 정확히 알 수는 없지만, 지금의 흐름을 바탕으로 변화를 예측하고 대비할 수 있습니다. 1. 국가 간 협력과 갈등 갈등: 에너지, 물, 첨단 산업에 필요한 희소 금속 같은 자원을 확보하려는 경쟁이 심해지고, 기후 변화로 살던 곳을 떠나는 사람들이 늘어 새로운 갈등이 생길 수 있습니","keywords":[],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-12","grade":"h1"},
{"id":"soc-h-c2-12#c5","kind":"concept","title":"세계시민으로서 나의 미래 삶의 방향","text":"우리는 한 지역의 주민이면서, 한 국가의 국민이고, 동시에 지구촌의 구성원입니다. 오늘날 이 세 공간은 촘촘히 연결되어 있습니다. 내가 고른 물건 하나가 지구 반대편 생산자의 삶과 환경에 영향을 주고, 먼 나라의 가뭄이 우리 식탁의 물가를 바꿉니다. 세계시민으로서 미래 삶의 방향 세우기","keywords":["세계시민"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-12","grade":"h1"},
{"id":"soc-h-c2-12#t0","kind":"term","title":"화석 에너지","text":"아주 오랜 옛날의 생물이 땅속에 묻혀 만들어진 석탄, 석유, 천연가스입니다. 재생 불가능한 자원입니다.","keywords":["화석 에너지"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-12","grade":"h1"},
{"id":"soc-h-c2-12#t1","kind":"term","title":"편재성","text":"자원이 특정 지역에 몰려 있는 성질입니다. 석유는 편재성이 커서 국제 이동량이 많습니다.","keywords":["편재성"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-12","grade":"h1"},
{"id":"soc-h-c2-12#t2","kind":"term","title":"자원 민족주의","text":"자원을 가진 나라가 자원을 자기 나라의 이익을 위해 무기처럼 이용하려는 움직임입니다.","keywords":["자원 민족주의"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-12","grade":"h1"},
{"id":"soc-h-c2-12#t3","kind":"term","title":"신재생 에너지","text":"태양광, 풍력, 수력, 지열처럼 고갈되지 않고 온실가스 배출이 적은 에너지입니다.","keywords":["신재생 에너지"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-12","grade":"h1"},
{"id":"soc-h-c2-12#t4","kind":"term","title":"기후 변화 협약","text":"1992년에 채택되어 같은 해 유엔 환경 개발 회의에서 여러 나라가 서명한, 온실가스를 줄이기 위한 국제 협력의 틀입니다.","keywords":["기후 변화 협약"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-12","grade":"h1"},
{"id":"soc-h-c2-12#t5","kind":"term","title":"파리 협정","text":"2015년 채택된 기후 변화 대응 협정으로, 선진국과 개발 도상국이 모두 참여하고 각국이 스스로 감축 목표를 정해 제출합니다.","keywords":["파리 협정"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-12","grade":"h1"},
{"id":"soc-h-c2-12#t6","kind":"term","title":"탄소 중립","text":"온실가스를 배출하는 만큼 흡수하거나 없애서 실질적인 배출량을 0으로 만드는 것입니다. 넷 제로라고도 합니다.","keywords":["탄소 중립"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-12","grade":"h1"},
{"id":"soc-h-c2-12#t7","kind":"term","title":"지속가능한 발전","text":"미래 세대가 자신의 필요를 채울 수 있는 능력을 해치지 않으면서 현재 세대의 필요를 채우는 발전입니다.","keywords":["지속가능한 발전"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-12","grade":"h1"},
{"id":"soc-h-c2-12#t8","kind":"term","title":"탄소 배출권 거래제","text":"기업마다 온실가스 배출 허용량을 정해 주고, 남거나 모자라는 배출권을 사고팔게 하는 제도입니다.","keywords":["탄소 배출권 거래제"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-12","grade":"h1"},
{"id":"soc-h-c2-12#t9","kind":"term","title":"세계시민","text":"자신을 지역 주민이자 국민이면서 지구촌 공동체의 구성원으로 여기고, 인류 공동의 문제에 책임 있게 행동하는 사람입니다.","keywords":["세계시민"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-12","grade":"h1"},
{"id":"soc-h-c2-12#f0","kind":"faq","title":"탄소 중립이면 탄소를 하나도 안 내보내는 거예요?","text":"아닙니다. 탄소 중립은 배출을 0으로 만드는 것이 아니라, 배출하는 만큼 숲이나 기술로 흡수·제거해서 실질적인 배출량을 0으로 만드는 것입니다. 그래서 배출을 최대한 줄이는 노력과 흡수를 늘리는 노력이 함께 필요합니다.","keywords":["탄소 중립"],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-12","grade":"h1"},
{"id":"soc-h-c2-12#f1","kind":"faq","title":"교토 의정서랑 파리 협정은 뭐가 달라요?","text":"가장 큰 차이는 참여 범위입니다. 1997년의 교토 의정서는 선진국에만 온실가스 감축 의무를 지웠고, 2015년의 파리 협정은 선진국과 개발 도상국이 모두 참여하여 각국이 스스로 감축 목표를 정해 제출합니다.","keywords":["파리 협정"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-12","grade":"h1"},
{"id":"soc-h-c2-12#f2","kind":"faq","title":"저 혼자 전기를 아낀다고 기후 변화가 막아지나요?","text":"한 사람의 실천만으로는 부족한 것이 사실입니다. 그래서 정부의 제도, 기업의 친환경 경영, 국제 협약이 함께 필요합니다. 하지만 많은 사람의 실천이 모이면 큰 변화가 되고, 시민의 관심은 더 나은 제도를 만드는 힘이 됩니다. 개인의 노력과 제도적 노력은 서로를 이끌어 줍니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-12","grade":"h1"},
{"id":"soc-h-c2-12#m0","kind":"mistake","title":"자주 하는 실수","text":"교토 의정서와 파리 협정의 참여 범위를 거꾸로 아는 실수 — 교토 의정서는 선진국 중심, 파리 협정은 개발 도상국을 포함한 모든 당사국이 참여합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-12","grade":"h1"},
{"id":"soc-h-c2-12#m1","kind":"mistake","title":"자주 하는 실수","text":"탄소 중립을 \"배출량 0\"으로 아는 실수 — 배출량에서 흡수·제거량을 뺀 실질적인 배출량을 0으로 만드는 것입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-12","grade":"h1"},
{"id":"soc-h-c2-12#m2","kind":"mistake","title":"자주 하는 실수","text":"원자력이나 수력을 화석 에너지에 넣는 실수 — 화석 에너지는 석탄, 석유, 천연가스입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-c2","unit":"soc-h-c2-12","grade":"h1"},
{"id":"soc-h-econ-01","kind":"unit","title":"경제 문제와 경제 체제","text":"희소성 때문에 생기는 기본적인 경제 문제와 경제학의 분석 대상을 알고, 경제 문제를 해결하는 전통 경제·계획 경제·시장 경제를 비교합니다. 희소성의 뜻과 희소성이 상대적이라는 것을 사례로 설명할 수 있다. 기본적인 경제 문제 세 가지를 구분하고 각각의 판단 기준을 말할 수 있다. 경제학의 분석 대상을 미시 경제와 거시 경제로 나누어 설명할 수 있다. 전통…","keywords":["희소성","희귀성","자유재","경제재","효율성","형평성","미시 경제","거시 경제","혼합 경제","가격 기구"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-01","grade":"h2"},
{"id":"soc-h-econ-01#c0","kind":"concept","title":"희소성과 희소성의 상대성","text":"사람의 욕구는 끝이 없지만, 그 욕구를 채워 줄 자원(돈, 시간, 땅, 노동, 재료 등)은 한정되어 있습니다. 이처럼 인간의 욕구에 비해 자원이 상대적으로 부족한 상태를 희소성이라고 합니다. 희소성이 있으니 모든 것을 다 가질 수 없고, 무엇을 고를지 선택해야 합니다. 이것이 모든 경제","keywords":["희소성","희귀성"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-01","grade":"h2"},
{"id":"soc-h-econ-01#c1","kind":"concept","title":"기본적인 경제 문제","text":"희소성 때문에 어느 사회든 다음 세 가지 문제를 풀어야 합니다. 이를 기본적인 경제 문제라고 합니다. 경제 문제 · 내용 · 주된 판단 기준 무엇을 얼마나 생산할 것인가 · 생산물의 종류와 수량 결정 · 효율성 어떻게 생산할 것인가 · 생산 방법 결정 (노동과 기계, 기술을 어떻게 결합","keywords":["희소성","효율성","형평성"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-01","grade":"h2"},
{"id":"soc-h-econ-01#c2","kind":"concept","title":"경제학의 분석 대상","text":"경제학은 희소한 자원을 어떻게 선택해 쓰는지, 곧 경제적 선택 행위와 그 결과를 연구하는 학문입니다. 가계·기업·정부 같은 경제 주체가 무엇을 사고, 얼마나 만들고, 세금을 어떻게 쓸지 고르는 모든 선택이 분석 대상입니다. 가계: 소비의 주체. 생산 요소(노동·자본·토지)를 제공하고 소","keywords":["미시 경제","거시 경제"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-01","grade":"h2"},
{"id":"soc-h-econ-01#c3","kind":"concept","title":"경제 문제를 해결하는 방식 — 경제 체제","text":"기본적인 경제 문제를 해결하는 방식과 제도를 경제 체제라고 합니다. 무엇이 문제를 해결하느냐에 따라 세 가지로 나눕니다. 경제 체제 · 해결 방식 · 장점 · 한계 전통 경제 · 관습과 전통 · 사회가 안정적 · 변화가 느리고 생산성이 낮음 계획 경제 · 정부의 계획과 명령 · 목표 산","keywords":["형평성","가격 기구"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-01","grade":"h2"},
{"id":"soc-h-econ-01#c4","kind":"concept","title":"시장 경제의 기본 원리와 제도","text":"시장 경제가 제대로 돌아가려면 다음 원리와 제도가 필요합니다. 사유 재산권 보장: 개인이 재산을 소유하고 자유롭게 쓰고 처분할 권리를 보장합니다. 노력한 만큼 자기 몫이 되므로 열심히 일하고 투자할 동기가 생깁니다. 경제 활동의 자유: 직업 선택, 기업 활동, 계약, 소비를 개인이 스스","keywords":["효율성","가격 기구"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-01","grade":"h2"},
{"id":"soc-h-econ-01#t0","kind":"term","title":"희소성","text":"인간의 욕구에 비해 그것을 채워 줄 자원이 상대적으로 부족한 상태입니다. 시대와 장소에 따라 달라집니다.","keywords":["희소성"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-01","grade":"h2"},
{"id":"soc-h-econ-01#t1","kind":"term","title":"희귀성","text":"존재하는 양 자체가 적은 것입니다. 원하는 사람이 없으면 희귀해도 희소하지 않습니다.","keywords":["희귀성"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-01","grade":"h2"},
{"id":"soc-h-econ-01#t2","kind":"term","title":"자유재","text":"양이 무한에 가까워 대가를 치르지 않고 얻을 수 있는 재화입니다. 예: 일상의 공기","keywords":["자유재"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-01","grade":"h2"},
{"id":"soc-h-econ-01#t3","kind":"term","title":"경제재","text":"희소성이 있어 대가를 치러야 얻을 수 있는 재화입니다. 예: 생수, 쌀","keywords":["경제재"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-01","grade":"h2"},
{"id":"soc-h-econ-01#t4","kind":"term","title":"효율성","text":"같은 자원으로 더 큰 만족을 얻는 것, 곧 적은 비용으로 큰 성과를 내는 것입니다.","keywords":["효율성"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-01","grade":"h2"},
{"id":"soc-h-econ-01#t5","kind":"term","title":"형평성","text":"분배가 공평한지를 따지는 기준입니다. 누구를 위하여 생산할 것인가를 판단할 때 함께 고려합니다.","keywords":["형평성"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-01","grade":"h2"},
{"id":"soc-h-econ-01#t6","kind":"term","title":"미시 경제","text":"개별 가계·기업의 선택과 개별 시장의 가격 결정을 분석하는 분야입니다.","keywords":["미시 경제"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-01","grade":"h2"},
{"id":"soc-h-econ-01#t7","kind":"term","title":"거시 경제","text":"물가, 실업, 경제 성장처럼 나라 경제 전체의 흐름을 분석하는 분야입니다.","keywords":["거시 경제"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-01","grade":"h2"},
{"id":"soc-h-econ-01#t8","kind":"term","title":"혼합 경제","text":"시장 경제를 바탕으로 하면서 정부가 개입해 시장의 한계를 보완하는 경제 체제입니다.","keywords":["혼합 경제"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-01","grade":"h2"},
{"id":"soc-h-econ-01#t9","kind":"term","title":"가격 기구","text":"시장 가격이 신호가 되어 무엇을 얼마나 생산·소비할지 조정하는 장치입니다. \"보이지 않는 손\"이라고도 합니다.","keywords":["가격 기구"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-01","grade":"h2"},
{"id":"soc-h-econ-01#f0","kind":"faq","title":"희소성이랑 희귀성이 너무 헷갈려요.","text":"희귀성은 양만 봅니다. 양이 적으면 희귀합니다. 희소성은 양과 욕구를 함께 봅니다. 원하는 만큼에 비해 부족하면 희소합니다. 그래서 아무도 원하지 않는 물건은 희귀해도 희소하지 않고, 양이 많은 물건도 원하는 사람이 더 많으면 희소합니다. 경제학에서 중요한 것은 희소성입니다.","keywords":["희소성","희귀성"],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-01","grade":"h2"},
{"id":"soc-h-econ-01#f1","kind":"faq","title":"공기는 자유재라는데, 공기청정기나 산소통은 돈을 내고 사잖아요?","text":"일상에서 숨 쉬는 공기는 대가 없이 얻으므로 자유재입니다. 하지만 미세 먼지가 심한 곳의 깨끗한 공기, 높은 산이나 물속에서 쓰는 산소처럼 원하는 양에 비해 부족해지면 대가를 치러야 하는 경제재가 됩니다. 같은 재화도 상황에 따라 자유재가 되기도, 경제재가 되기도 합니다. 희소성이 상대적이기 때문입니다.","keywords":["자유재"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-01","grade":"h2"},
{"id":"soc-h-econ-01#f2","kind":"faq","title":"우리나라는 시장 경제예요, 혼합 경제예요?","text":"둘 다 맞는 말입니다. 우리나라는 시장 경제를 바탕으로 하면서 정부가 필요한 곳에 개입하는 혼합 경제 체제입니다. 오늘날 대부분의 나라가 이와 같습니다. 나라마다 정부가 개입하는 정도가 다를 뿐입니다.","keywords":["혼합 경제"],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-01","grade":"h2"},
{"id":"soc-h-econ-01#m0","kind":"mistake","title":"자주 하는 실수","text":"\"양이 적으면 희소하다\"고 생각하는 실수 — 희소성은 욕구에 비해 부족한 정도입니다. 양만 보는 것은 희귀성입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-01","grade":"h2"},
{"id":"soc-h-econ-01#m1","kind":"mistake","title":"자주 하는 실수","text":"\"누구를 위하여 생산할 것인가\"를 효율성만으로 판단하는 실수 — 분배의 문제는 형평성도 함께 고려합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-01","grade":"h2"},
{"id":"soc-h-econ-01#m2","kind":"mistake","title":"자주 하는 실수","text":"계획 경제의 장점을 효율성으로 착각하는 실수 — 계획 경제는 목표 산업에 자원을 모으기 쉽지만, 경제적 유인이 부족해 비효율적이기 쉽습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-01","grade":"h2"},
{"id":"soc-h-econ-02","kind":"unit","title":"합리적 선택과 한계 분석","text":"사람들이 경제적 유인에 반응한다는 것을 알고, 편익과 기회비용, 한계 편익과 한계 비용을 비교해 합리적으로 결정하는 방법을 익힙니다. 긍정적 유인과 부정적 유인의 사례를 들어 사람들이 유인에 반응한다는 것을 설명할 수 있다. 기회비용을 명시적 비용과 암묵적 비용으로 나누어 계산할 수 있다. 매몰 비용을 선택에서 제외하고, 순편익이 가장 큰 대안을 고를 수…","keywords":["경제적 유인","긍정적 유인","부정적 유인","기회비용","명시적 비용","암묵적 비용","매몰 비용","순편익","한계 편익","한계 비용"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-02","grade":"h2"},
{"id":"soc-h-econ-02#c0","kind":"concept","title":"경제적 유인 — 사람들은 유인에 반응한다","text":"경제적 유인은 사람들이 어떤 행동을 하거나 하지 않도록 이끄는 동기, 곧 보상이나 불이익입니다. 사람들은 편익이 커지면 그 행동을 더 하고, 비용이 커지면 덜 합니다. 그래서 유인이 바뀌면 행동이 바뀝니다. 구분 · 뜻 · 사례 긍정적 유인 · 보상을 주어 어떤 행동을 더 하게 함 · ","keywords":["경제적 유인","긍정적 유인","부정적 유인"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-02","grade":"h2"},
{"id":"soc-h-econ-02#c1","kind":"concept","title":"기회비용 — 명시적 비용과 암묵적 비용","text":"무엇인가를 선택하면 다른 것은 포기해야 합니다. 기회비용은 어떤 선택을 할 때 포기한 대안 가운데 가장 가치가 큰 것의 가치입니다. 기회비용은 두 부분으로 나누어 볼 수 있습니다. 명시적 비용: 그 선택을 위해 실제로 지출한 돈 (관람료, 등록금, 재료비) 암묵적 비용: 돈을 내지는 않","keywords":["기회비용","명시적 비용","암묵적 비용"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-02","grade":"h2"},
{"id":"soc-h-econ-02#c2","kind":"concept","title":"매몰 비용은 고려하지 않는다","text":"매몰 비용은 이미 지출해서 어떤 선택을 하더라도 돌려받을 수 없는 비용입니다. 환불이 안 되는 표 값, 이미 들인 개발비 같은 것입니다. 매몰 비용은 지금부터 무엇을 고르든 똑같이 사라진 돈이므로, 앞으로의 선택에 영향을 주어서는 안 됩니다. 합리적인 사람은 앞으로 얻을 편익과 앞으로 ","keywords":["매몰 비용"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-02","grade":"h2"},
{"id":"soc-h-econ-02#c3","kind":"concept","title":"합리적 선택 — 순편익이 가장 큰 대안","text":"편익은 어떤 선택으로 얻는 만족이나 이익이고, 순편익은 편익에서 비용을 뺀 것입니다. 순편익 = 편익−비용 합리적 선택은 여러 대안의 편익과 비용을 비교해 순편익이 가장 큰 대안을 고르는 것입니다. 이렇게 고른 대안은 편익이 기회비용보다 크거나 같습니다. 예 일요일에 셋 중 하나만 할 ","keywords":["기회비용","순편익"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-02","grade":"h2"},
{"id":"soc-h-econ-02#c4","kind":"concept","title":"한계 분석 — 한계 편익과 한계 비용","text":"\"할까 말까\"뿐 아니라 \"얼마나 할까\"도 선택입니다. 이때는 한 단위를 더할 때 생기는 변화를 봅니다. 한계 편익: 한 단위를 더 할 때 추가로 얻는 편익 한계 비용: 한 단위를 더 할 때 추가로 드는 비용 한계 편익이 한계 비용보다 크면 한 단위를 더 하는 것이 이득이므로 늘리고, 작","keywords":["순편익","한계 편익","한계 비용"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-02","grade":"h2"},
{"id":"soc-h-econ-02#t0","kind":"term","title":"경제적 유인","text":"사람들이 어떤 행동을 하거나 하지 않도록 이끄는 보상이나 불이익입니다.","keywords":["경제적 유인"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-02","grade":"h2"},
{"id":"soc-h-econ-02#t1","kind":"term","title":"긍정적 유인","text":"보상을 주어 어떤 행동을 더 하게 하는 유인입니다. 예: 장학금, 보조금","keywords":["긍정적 유인"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-02","grade":"h2"},
{"id":"soc-h-econ-02#t2","kind":"term","title":"부정적 유인","text":"불이익을 주어 어떤 행동을 덜 하게 하는 유인입니다. 예: 벌금, 과태료, 연체료","keywords":["부정적 유인"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-02","grade":"h2"},
{"id":"soc-h-econ-02#t3","kind":"term","title":"기회비용","text":"어떤 선택으로 포기한 대안 가운데 가장 가치가 큰 것의 가치입니다. 명시적 비용과 암묵적 비용을 더한 것입니다.","keywords":["기회비용"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-02","grade":"h2"},
{"id":"soc-h-econ-02#t4","kind":"term","title":"명시적 비용","text":"어떤 선택을 위해 실제로 지출한 화폐 비용입니다. 예: 관람료, 등록금","keywords":["명시적 비용"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-02","grade":"h2"},
{"id":"soc-h-econ-02#t5","kind":"term","title":"암묵적 비용","text":"돈을 내지는 않았지만 그 선택으로 포기한 다른 대안의 가치입니다. 예: 그 시간에 벌 수 있었던 소득","keywords":["암묵적 비용"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-02","grade":"h2"},
{"id":"soc-h-econ-02#t6","kind":"term","title":"매몰 비용","text":"이미 지출해서 어떤 선택을 해도 돌려받을 수 없는 비용입니다. 합리적 선택에서는 고려하지 않습니다.","keywords":["매몰 비용"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-02","grade":"h2"},
{"id":"soc-h-econ-02#t7","kind":"term","title":"순편익","text":"편익에서 비용을 뺀 값입니다. 합리적 선택은 순편익이 가장 큰 대안을 고르는 것입니다.","keywords":["순편익"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-02","grade":"h2"},
{"id":"soc-h-econ-02#t8","kind":"term","title":"한계 편익","text":"어떤 활동을 한 단위 더 할 때 추가로 얻는 편익입니다.","keywords":["한계 편익"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-02","grade":"h2"},
{"id":"soc-h-econ-02#t9","kind":"term","title":"한계 비용","text":"어떤 활동을 한 단위 더 할 때 추가로 드는 비용입니다.","keywords":["한계 비용"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-02","grade":"h2"},
{"id":"soc-h-econ-02#f0","kind":"faq","title":"기회비용을 구할 때 포기한 것을 다 더하면 안 되나요?","text":"안 됩니다. 어차피 여러 대안 가운데 하나만 할 수 있었으므로, 포기한 것 가운데 가장 가치가 큰 것 하나만 셉니다. 아르바이트(8만 원)와 낮잠(3만 원)을 포기했다면, 두 일을 동시에 할 수는 없었으니 8만 원만 암묵적 비용이 됩니다. 여기에 그 선택에 실제로 낸 돈(명시적 비용)을 더하면 기회비용입니다.","keywords":["기회비용"],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-02","grade":"h2"},
{"id":"soc-h-econ-02#f1","kind":"faq","title":"이미 쓴 돈을 생각하지 말라는 건 돈을 아끼지 말라는 뜻인가요?","text":"아닙니다. 쓰기 전에는 그 돈이 비용이므로 신중하게 따져야 합니다. 다만 이미 써서 돌려받을 수 없게 된 뒤에는, 그 돈 때문에 앞으로의 선택을 바꾸지 말라는 뜻입니다. 앞으로 얻을 것과 앞으로 들 것만 비교해야 손해를 더 키우지 않습니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-02","grade":"h2"},
{"id":"soc-h-econ-02#f2","kind":"faq","title":"한계 편익과 한계 비용이 딱 같아지면 그 단위는 해요, 말아요?","text":"그 단위를 하든 안 하든 순편익 합계는 똑같습니다. 더해지는 편익과 비용이 같아 순편익이 변하지 않기 때문입니다. 그래서 \"한계 편익 = 한계 비용인 수준에서 순편익이 가장 크다\"고 말합니다. 표로 된 문제에서는 한계 편익이 한계 비용보다 크거나 같은 마지막 단위까지 한다고 생각하면 됩니다.","keywords":["한계 편익","한계 비용"],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-02","grade":"h2"},
{"id":"soc-h-econ-02#m0","kind":"mistake","title":"자주 하는 실수","text":"기회비용에 실제로 낸 돈만 넣는 실수 — 그 시간에 벌 수 있었던 소득 같은 암묵적 비용도 더해야 합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-02","grade":"h2"},
{"id":"soc-h-econ-02#m1","kind":"mistake","title":"자주 하는 실수","text":"포기한 대안을 모두 더해 기회비용을 구하는 실수 — 포기한 것 가운데 가장 가치가 큰 것 하나만 셉니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-02","grade":"h2"},
{"id":"soc-h-econ-02#m2","kind":"mistake","title":"자주 하는 실수","text":"\"본전 생각\"으로 매몰 비용을 판단에 넣는 실수 — 돌려받을 수 없는 돈은 앞으로의 선택에서 빼고 생각합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-02","grade":"h2"},
{"id":"soc-h-econ-03","kind":"unit","title":"수요·공급과 시장 균형","text":"수요와 공급이 바뀌는 요인을 알고, 균형 가격과 균형 거래량이 정해지고 변하는 원리를 그래프로 분석합니다. 수요량의 변화와 수요의 변화, 공급량의 변화와 공급의 변화를 구분할 수 있다. 수요와 공급을 변동시키는 요인을 사례에 적용할 수 있다. 초과 수요와 초과 공급이 해소되며 균형 가격과 균형 거래량이 정해지는 과정을 설명할 수 있다. 수요와 공급이 변할…","keywords":["수요 법칙","수요량의 변화","수요의 변화","정상재","열등재","대체재","보완재","균형 가격","초과 수요","초과 공급"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-03","grade":"h2"},
{"id":"soc-h-econ-03#c0","kind":"concept","title":"수요 — 수요량의 변화와 수요의 변화","text":"수요는 일정 기간에 소비자가 재화나 서비스를 사려고 하는 욕구이고, 수요량은 어떤 가격에서 사려고 하는 구체적인 양입니다. 다른 조건이 같을 때 가격이 오르면 수요량이 줄고, 가격이 내리면 수요량이 늘어납니다. 이를 수요 법칙이라 하고, 그래서 수요 곡선은 오른쪽 아래로 내려가는 모양입","keywords":["수요 법칙","수요량의 변화","수요의 변화"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-03","grade":"h2"},
{"id":"soc-h-econ-03#c1","kind":"concept","title":"수요를 변동시키는 요인","text":"수요 곡선을 이동시키는 가격 이외의 요인은 다음과 같습니다. 요인 · 수요 증가(오른쪽 이동) · 수요 감소(왼쪽 이동) 소득 · 정상재: 소득 증가 / 열등재: 소득 감소 · 정상재: 소득 감소 / 열등재: 소득 증가 대체재의 가격 · 대체재 가격 상승 · 대체재 가격 하락 보완재의 ","keywords":["정상재","열등재","대체재","보완재"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-03","grade":"h2"},
{"id":"soc-h-econ-03#c2","kind":"concept","title":"공급 — 공급량의 변화와 공급을 변동시키는 요인","text":"공급은 일정 기간에 생산자가 재화나 서비스를 팔려고 하는 욕구이고, 공급량은 어떤 가격에서 팔려고 하는 구체적인 양입니다. 다른 조건이 같을 때 가격이 오르면 공급량이 늘어납니다(공급 법칙). 그래서 공급 곡선은 오른쪽 위로 올라가는 모양입니다. 수요와 마찬가지로 그 재화 자체의 가격이","keywords":[],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-03","grade":"h2"},
{"id":"soc-h-econ-03#c3","kind":"concept","title":"시장 균형 — 초과 수요와 초과 공급","text":"수요 곡선과 공급 곡선이 만나는 점에서 수요량과 공급량이 같아집니다. 이 상태를 시장 균형이라 하고, 이때의 가격을 균형 가격, 거래량을 균형 거래량이라고 합니다. 가격이 균형 가격이 아니면 시장은 스스로 균형을 찾아갑니다. 상황 · 상태 · 가격의 움직임 가격 > 균형 가격 · 공급량","keywords":["균형 가격","초과 수요","초과 공급"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-03","grade":"h2"},
{"id":"soc-h-econ-03#c4","kind":"concept","title":"수요나 공급이 변할 때 균형의 변화","text":"수요나 공급 가운데 하나가 변하면 곡선이 이동해 새 균형점이 생깁니다. 변화 · 균형 가격 · 균형 거래량 수요 증가 (D 오른쪽) · 상승 · 증가 수요 감소 (D 왼쪽) · 하락 · 감소 공급 증가 (S 오른쪽) · 하락 · 증가 공급 감소 (S 왼쪽) · 상승 · 감소 분석 순서는","keywords":["균형 가격"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-03","grade":"h2"},
{"id":"soc-h-econ-03#c5","kind":"concept","title":"수요와 공급이 함께 변할 때","text":"수요와 공급이 동시에 변하면 두 변화의 효과를 더해 봅니다. 하나는 확실히 정해지지만, 다른 하나는 어느 쪽이 더 크게 변했는지에 따라 달라집니다. 변화 · 균형 가격 · 균형 거래량 수요 증가 + 공급 증가 · 알 수 없음 · 증가 수요 감소 + 공급 감소 · 알 수 없음 · 감소 수","keywords":["균형 가격"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-03","grade":"h2"},
{"id":"soc-h-econ-03#t0","kind":"term","title":"수요 법칙","text":"다른 조건이 같을 때 가격이 오르면 수요량이 줄고, 가격이 내리면 수요량이 늘어나는 관계입니다. 공급에서는 가격이 오르면 공급량이 늘어나는데, 이를 공급 법칙이라고 합니다.","keywords":["수요 법칙"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-03","grade":"h2"},
{"id":"soc-h-econ-03#t1","kind":"term","title":"수요량의 변화","text":"그 재화 자체의 가격이 변해 수요 곡선 위에서 점이 이동하는 것입니다.","keywords":["수요량의 변화"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-03","grade":"h2"},
{"id":"soc-h-econ-03#t2","kind":"term","title":"수요의 변화","text":"소득·관련 재화의 가격·선호처럼 가격 이외의 요인이 변해 수요 곡선 자체가 이동하는 것입니다.","keywords":["수요의 변화"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-03","grade":"h2"},
{"id":"soc-h-econ-03#t3","kind":"term","title":"정상재","text":"소득이 늘면 수요가 증가하는 재화입니다. 대부분의 재화가 정상재입니다.","keywords":["정상재"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-03","grade":"h2"},
{"id":"soc-h-econ-03#t4","kind":"term","title":"열등재","text":"소득이 늘면 오히려 수요가 감소하는 재화입니다.","keywords":["열등재"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-03","grade":"h2"},
{"id":"soc-h-econ-03#t5","kind":"term","title":"대체재","text":"서로 대신 쓸 수 있는 재화입니다. 한 재화의 가격이 오르면 다른 재화의 수요가 증가합니다. 예: 버터와 마가린","keywords":["대체재"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-03","grade":"h2"},
{"id":"soc-h-econ-03#t6","kind":"term","title":"보완재","text":"함께 쓸 때 만족이 커지는 재화입니다. 한 재화의 가격이 오르면 다른 재화의 수요가 감소합니다. 예: 커피와 설탕","keywords":["보완재"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-03","grade":"h2"},
{"id":"soc-h-econ-03#t7","kind":"term","title":"균형 가격","text":"수요량과 공급량이 같아지는 가격입니다. 이때의 거래량을 균형 거래량이라고 합니다.","keywords":["균형 가격"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-03","grade":"h2"},
{"id":"soc-h-econ-03#t8","kind":"term","title":"초과 수요","text":"어떤 가격에서 수요량이 공급량보다 많은 상태입니다. 가격이 오르는 압력이 생깁니다.","keywords":["초과 수요"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-03","grade":"h2"},
{"id":"soc-h-econ-03#t9","kind":"term","title":"초과 공급","text":"어떤 가격에서 공급량이 수요량보다 많은 상태입니다. 가격이 내리는 압력이 생깁니다.","keywords":["초과 공급"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-03","grade":"h2"},
{"id":"soc-h-econ-03#f0","kind":"faq","title":"\"가격이 올라서 수요가 줄었다\"는 말이 왜 틀린 건가요?","text":"가격이 올라 줄어든 것은 수요량입니다. 수요 곡선은 그대로이고, 곡선 위에서 점이 위쪽으로 움직였을 뿐입니다. \"수요가 줄었다\"는 소득이나 선호 같은 다른 요인이 변해 곡선 자체가 왼쪽으로 옮겨 갔을 때 쓰는 말입니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-03","grade":"h2"},
{"id":"soc-h-econ-03#f1","kind":"faq","title":"수요와 공급이 함께 변하면 왜 하나는 \"알 수 없음\"이 되나요?","text":"두 변화가 가격(또는 거래량)을 서로 반대 방향으로 밀기 때문입니다. 예를 들어 수요 증가는 가격을 올리고 공급 증가는 가격을 내립니다. 어느 쪽 힘이 더 큰지 문제에서 알려 주지 않으면 결과를 정할 수 없습니다. 변화의 크기가 주어지면 정할 수 있습니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-03","grade":"h2"},
{"id":"soc-h-econ-03#f2","kind":"faq","title":"대체재와 보완재는 어떻게 쉽게 구별해요?","text":"\"둘 중 하나만 있으면 되나?\"를 물어보세요. 버스와 지하철처럼 하나만 있어도 되면 대체재, 자동차와 휘발유처럼 함께 있어야 쓸모가 커지면 보완재입니다. 대체재는 상대 가격이 오를 때 내 수요가 늘고, 보완재는 상대 가격이 오를 때 내 수요가 줄어듭니다.","keywords":["대체재","보완재"],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-03","grade":"h2"},
{"id":"soc-h-econ-03#m0","kind":"mistake","title":"자주 하는 실수","text":"그 재화 자체의 가격 변화를 \"수요(공급)의 변화\"라고 하는 실수 — 자기 가격이 변하면 곡선 위의 이동, 곧 수요량(공급량)의 변화입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-03","grade":"h2"},
{"id":"soc-h-econ-03#m1","kind":"mistake","title":"자주 하는 실수","text":"원료 가격 상승을 수요 쪽 요인으로 보는 실수 — 생산 요소 가격은 생산자의 비용이므로 공급을 움직입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-03","grade":"h2"},
{"id":"soc-h-econ-03#m2","kind":"mistake","title":"자주 하는 실수","text":"수요와 공급이 함께 변할 때 가격과 거래량을 모두 단정하는 실수 — 두 효과가 반대인 쪽은 변화의 크기를 알아야 정할 수 있습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-03","grade":"h2"},
{"id":"soc-h-econ-04","kind":"unit","title":"여러 시장에 적용하기","text":"수요와 공급의 원리를 생산 요소 시장인 노동 시장과 금융 시장에 적용해 임금과 이자율이 정해지고 변하는 까닭을 알아보고, 신문 기사 속 가격 변화를 수요·공급으로 설명합니다. 생산물 시장과 생산 요소 시장에서 가계와 기업의 역할을 경제 순환으로 설명할 수 있다. 노동의 수요와 공급으로 임금이 결정되고 변동하는 원리를 분석할 수 있다. 자금의 수요와 공급으…","keywords":["생산물 시장","생산 요소 시장","경제 순환","임금","파생 수요","이자율","금융 시장","간접 금융","직접 금융"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-04","grade":"h2"},
{"id":"soc-h-econ-04#c0","kind":"concept","title":"생산물 시장과 생산 요소 시장 — 경제 순환","text":"시장은 거래하는 대상에 따라 둘로 나눌 수 있습니다. 시장 · 거래하는 것 · 수요자 · 공급자 생산물 시장 · 재화와 서비스 · 가계 · 기업 생산 요소 시장 · 노동·자본·토지 같은 생산 요소 · 기업 · 가계 가계는 생산 요소 시장에 노동·자본·토지를 제공하고 그 대가로 임금·이자","keywords":["생산물 시장","생산 요소 시장","경제 순환","임금"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-04","grade":"h2"},
{"id":"soc-h-econ-04#c1","kind":"concept","title":"노동 시장 — 임금의 결정","text":"노동 시장에서는 노동이 거래되고, 노동의 가격이 임금입니다. 노동 수요: 기업이 노동자를 고용하려는 것입니다. 임금이 오르면 고용 비용이 늘어 기업은 노동 수요량을 줄입니다. → 노동 수요 곡선은 오른쪽 아래로 내려갑니다. 노동 공급: 가계가 일하려는 것입니다. 임금이 오르면 일할 때 ","keywords":["임금","파생 수요"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-04","grade":"h2"},
{"id":"soc-h-econ-04#c2","kind":"concept","title":"임금의 변동","text":"노동 수요나 노동 공급이 변하면 균형 임금과 균형 고용량이 변합니다. 변화 · 대표적인 요인 · 균형 임금 · 균형 고용량 노동 수요 증가 · 그 노동으로 만드는 생산물의 수요 증가, 노동 생산성 향상 · 상승 · 증가 노동 수요 감소 · 생산물의 수요 감소, 그 노동을 대신하는 기계·","keywords":["임금","파생 수요"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-04","grade":"h2"},
{"id":"soc-h-econ-04#c3","kind":"concept","title":"금융 시장 — 이자율의 결정","text":"금융 시장은 돈(자금)을 빌려주고 빌리는 시장입니다. 자금을 빌려 쓰는 대가가 이자이고, 원금에 대한 이자의 비율이 이자율입니다. 이자율은 곧 자금의 가격입니다. 자금 공급: 주로 저축하는 가계입니다. 이자율이 오르면 저축으로 얻는 대가가 커져 자금 공급량이 늘어납니다. 자금 수요: 주","keywords":["이자율","금융 시장","간접 금융","직접 금융"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-04","grade":"h2"},
{"id":"soc-h-econ-04#c4","kind":"concept","title":"이자율의 변동","text":"자금의 수요나 공급이 변하면 균형 이자율과 자금 거래량이 변합니다. 변화 · 대표적인 요인 · 균형 이자율 · 자금 거래량 자금 수요 증가 · 경기가 좋아질 것으로 보고 기업의 투자 계획 증가, 돈을 빌리려는 가계 증가 · 상승 · 증가 자금 수요 감소 · 기업의 투자 계획 감소 · 하","keywords":["생산물 시장","이자율","금융 시장"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-04","grade":"h2"},
{"id":"soc-h-econ-04#c5","kind":"concept","title":"신문 기사 속 가격 변화 읽기","text":"기사에 나오는 가격 변화는 다음 순서로 분석하면 됩니다. 어떤 시장인가? 생산물 시장인지, 노동 시장(임금)인지, 금융 시장(이자율)인지 찾습니다. 수요 쪽인가, 공급 쪽인가? 사려는(빌리려는·고용하려는) 쪽의 사정이 바뀌었으면 수요, 팔려는(빌려주려는·일하려는) 쪽의 사정이 바뀌었으면","keywords":["생산물 시장","임금","이자율","금융 시장"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-04","grade":"h2"},
{"id":"soc-h-econ-04#t0","kind":"term","title":"생산물 시장","text":"재화와 서비스가 거래되는 시장입니다. 가계가 수요자, 기업이 공급자입니다.","keywords":["생산물 시장"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-04","grade":"h2"},
{"id":"soc-h-econ-04#t1","kind":"term","title":"생산 요소 시장","text":"노동·자본·토지 같은 생산 요소가 거래되는 시장입니다. 기업이 수요자, 가계가 공급자입니다.","keywords":["생산 요소 시장"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-04","grade":"h2"},
{"id":"soc-h-econ-04#t2","kind":"term","title":"경제 순환","text":"가계와 기업이 생산물 시장과 생산 요소 시장을 거쳐 실물과 화폐를 주고받으며 이어지는 흐름입니다. 실물과 화폐는 반대 방향으로 흐릅니다.","keywords":["경제 순환"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-04","grade":"h2"},
{"id":"soc-h-econ-04#t3","kind":"term","title":"임금","text":"노동을 제공한 대가이자 노동 시장에서 노동의 가격입니다.","keywords":["임금"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-04","grade":"h2"},
{"id":"soc-h-econ-04#t4","kind":"term","title":"파생 수요","text":"다른 것에 대한 수요에서 생겨나는 수요입니다. 노동 수요는 그 노동으로 만드는 생산물의 수요에서 생겨납니다.","keywords":["파생 수요"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-04","grade":"h2"},
{"id":"soc-h-econ-04#t5","kind":"term","title":"이자율","text":"빌린 돈(원금)에 대한 이자의 비율입니다. 금융 시장에서 자금의 가격 역할을 합니다.","keywords":["이자율"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-04","grade":"h2"},
{"id":"soc-h-econ-04#t6","kind":"term","title":"금융 시장","text":"자금을 빌려주려는 쪽과 빌리려는 쪽이 만나 자금이 거래되는 시장입니다.","keywords":["금융 시장"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-04","grade":"h2"},
{"id":"soc-h-econ-04#t7","kind":"term","title":"간접 금융","text":"은행 같은 금융 기관이 예금을 받아 대출해 주는 방식으로 자금이 오가는 것입니다.","keywords":["간접 금융"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-04","grade":"h2"},
{"id":"soc-h-econ-04#t8","kind":"term","title":"직접 금융","text":"기업이 주식이나 채권을 팔아 자금을 공급하는 사람에게서 직접 자금을 모으는 것입니다.","keywords":["직접 금융"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-04","grade":"h2"},
{"id":"soc-h-econ-04#f0","kind":"faq","title":"노동 시장에서는 왜 가계가 공급자예요? 가계는 늘 사는 쪽 아닌가요?","text":"생산물 시장에서는 가계가 물건을 사는 수요자입니다. 하지만 노동 시장에서 가계가 파는 것은 자신의 노동입니다. 노동을 제공하고 그 대가로 임금을 받으므로 공급자입니다. 같은 가계라도 어느 시장이냐에 따라 역할이 바뀝니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-04","grade":"h2"},
{"id":"soc-h-econ-04#f1","kind":"faq","title":"저축이 늘면 왜 이자율이 내려가요? 은행에 돈이 많으면 좋은 것 아닌가요?","text":"저축이 늘면 빌려줄 수 있는 돈(자금 공급)이 많아집니다. 빌리려는 사람은 그대로인데 빌려줄 돈이 넘치면, 은행은 낮은 이자로라도 빌려주려 합니다. 그래서 자금의 가격인 이자율이 내려가고, 빌리고 빌려주는 돈(거래량)은 늘어납니다.","keywords":["이자율"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-04","grade":"h2"},
{"id":"soc-h-econ-04#f2","kind":"faq","title":"로봇이 들어오면 일자리가 무조건 줄어드나요?","text":"로봇이 대신하는 일을 하던 노동자의 노동 수요는 줄어듭니다. 하지만 로봇을 만들고 관리하는 일처럼 새로 생기는 일의 노동 수요는 늘 수 있습니다. 경제 전체의 일자리가 어떻게 변할지는 여러 요인에 따라 달라지므로 한 시장만 보고 단정하지 않습니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-04","grade":"h2"},
{"id":"soc-h-econ-04#m0","kind":"mistake","title":"자주 하는 실수","text":"노동 시장에서 가계를 수요자로 보는 실수 — 노동 시장에서 가계는 노동을 파는 공급자, 기업은 노동을 사는 수요자입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-04","grade":"h2"},
{"id":"soc-h-econ-04#m1","kind":"mistake","title":"자주 하는 실수","text":"저축 증가를 자금 수요 증가로 보는 실수 — 저축은 돈을 빌려주는 쪽이므로 자금 공급 증가입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-04","grade":"h2"},
{"id":"soc-h-econ-04#m2","kind":"mistake","title":"자주 하는 실수","text":"기사에서 \"값이 올랐다\"만 보고 수요 증가라고 단정하는 실수 — 공급 감소로도 값이 오릅니다. 기사 속 원인을 찾아 수요 쪽인지 공급 쪽인지 가려야 합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-04","grade":"h2"},
{"id":"soc-h-econ-05","kind":"unit","title":"정부의 역할과 시장 실패","text":"독과점·외부 효과·공공재·정보의 비대칭성처럼 시장이 자원을 효율적으로 배분하지 못하는 경우를 알고, 공정 거래 정책·가격 규제·조세 같은 정부의 역할을 탐구합니다. 시장 실패의 뜻과 그 요인(독과점, 외부 효과, 공공재, 정보의 비대칭성)을 설명할 수 있다. 외부 경제와 외부 불경제에서 시장 거래량과 사회적으로 바람직한 양이 어떻게 다른지 분석할 수 있다…","keywords":["시장 실패","독과점","담합","외부 효과","공공재","무임승차","정보의 비대칭성","최고 가격제","최저 가격제","조세 전가"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-05","grade":"h2"},
{"id":"soc-h-econ-05#c0","kind":"concept","title":"시장 실패와 독과점","text":"시장에서 수요와 공급에 따라 가격이 정해지면 자원이 효율적으로 배분된다고 배웠습니다. 그런데 현실의 시장은 언제나 그렇게 움직이지는 않습니다. 시장이 스스로 자원을 효율적으로 배분하지 못하는 상태를 시장 실패라고 합니다. 대표적인 요인은 독과점, 외부 효과, 공공재, 정보의 비대칭성입니","keywords":["시장 실패","독과점","담합","외부 효과","공공재","정보의 비대칭성"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-05","grade":"h2"},
{"id":"soc-h-econ-05#c1","kind":"concept","title":"외부 효과: 외부 경제와 외부 불경제","text":"어떤 사람의 경제 활동이 다른 사람에게 의도하지 않은 이익이나 손해를 주면서도 그에 대한 대가를 주고받지 않는 것을 외부 효과라고 합니다. 구분 · 뜻 · 예 · 시장 거래량 외부 경제(긍정적 외부 효과) · 남에게 대가 없이 이익을 줌 · 과수원 옆 양봉장, 예방 접종, 아름다운 정원","keywords":["외부 효과"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-05","grade":"h2"},
{"id":"soc-h-econ-05#c2","kind":"concept","title":"공공재와 무임승차","text":"공공재는 국방, 치안, 등대, 일반 도로, 가로등처럼 여러 사람이 함께 쓰는 재화와 서비스입니다. 공공재는 두 가지 특징을 가집니다. 비경합성: 한 사람이 쓴다고 해서 다른 사람이 쓸 수 있는 양이 줄지 않습니다. 내가 국방 서비스를 누려도 이웃이 누리는 국방이 줄지 않습니다. 비배제성","keywords":["공공재","무임승차"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-05","grade":"h2"},
{"id":"soc-h-econ-05#c3","kind":"concept","title":"정보의 비대칭성","text":"거래하는 두 사람 가운데 한쪽만 중요한 정보를 더 많이 알고 있는 상태를 정보의 비대칭성이라고 합니다. 정보가 고르게 나뉘어 있지 않으면 시장이 효율적인 결과를 내지 못할 수 있습니다. 역선택: 거래 전에 정보를 덜 가진 쪽이 불리한 상대와 거래하게 되는 현상입니다. 중고차를 사는 사람","keywords":["정보의 비대칭성"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-05","grade":"h2"},
{"id":"soc-h-econ-05#c4","kind":"concept","title":"가격 규제: 최고 가격제와 최저 가격제","text":"정부가 시장 가격이 너무 높거나 낮다고 판단할 때, 가격의 상한이나 하한을 정하는 것을 가격 규제라고 합니다. 최고 가격제는 정부가 가격의 상한을 정하고 그보다 높은 가격으로 거래하지 못하게 하는 제도입니다. 물가를 안정시키고 소비자를 보호하려는 목적으로, 임대료 상한이나 이자율 상한이","keywords":["최고 가격제","최저 가격제"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-05","grade":"h2"},
{"id":"soc-h-econ-05#c5","kind":"concept","title":"조세의 종류","text":"정부는 공공재를 공급하고 시장 실패를 바로잡는 데 필요한 돈을 주로 조세(세금)로 마련합니다. 조세는 기준에 따라 다음과 같이 나눕니다. 1) 걷는 주체에 따라: 국세와 지방세 국세: 중앙 정부(국가)가 걷습니다. 소득세, 법인세, 부가 가치세, 개별 소비세, 상속세, 주세 등 지방세:","keywords":["시장 실패","공공재","조세 전가"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-05","grade":"h2"},
{"id":"soc-h-econ-05#t0","kind":"term","title":"시장 실패","text":"시장이 스스로 자원을 효율적으로 배분하지 못하는 상태입니다. 독과점, 외부 효과, 공공재, 정보의 비대칭성이 요인입니다.","keywords":["시장 실패"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-05","grade":"h2"},
{"id":"soc-h-econ-05#t1","kind":"term","title":"독과점","text":"공급자가 하나뿐인 독점과 소수인 과점을 함께 이르는 말입니다. 경쟁이 약해 가격이 높고 생산량이 적어지기 쉽습니다.","keywords":["독과점"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-05","grade":"h2"},
{"id":"soc-h-econ-05#t2","kind":"term","title":"담합","text":"기업들이 경쟁하지 않고 서로 짜서 가격·생산량 등을 정하는 행위입니다. 공정 거래법으로 금지됩니다.","keywords":["담합"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-05","grade":"h2"},
{"id":"soc-h-econ-05#t3","kind":"term","title":"외부 효과","text":"어떤 경제 활동이 다른 사람에게 의도하지 않은 이익(외부 경제)이나 손해(외부 불경제)를 주면서도 대가를 주고받지 않는 것입니다.","keywords":["외부 효과"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-05","grade":"h2"},
{"id":"soc-h-econ-05#t4","kind":"term","title":"공공재","text":"비경합성과 비배제성을 가진 재화·서비스입니다. 예: 국방, 치안, 등대, 가로등","keywords":["공공재"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-05","grade":"h2"},
{"id":"soc-h-econ-05#t5","kind":"term","title":"무임승차","text":"대가를 치르지 않고 다른 사람이 비용을 낸 혜택만 누리려는 행동입니다. 공공재의 비배제성 때문에 생깁니다.","keywords":["무임승차"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-05","grade":"h2"},
{"id":"soc-h-econ-05#t6","kind":"term","title":"정보의 비대칭성","text":"거래하는 두 사람 가운데 한쪽만 중요한 정보를 더 많이 가진 상태입니다. 역선택과 도덕적 해이를 낳습니다.","keywords":["정보의 비대칭성"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-05","grade":"h2"},
{"id":"soc-h-econ-05#t7","kind":"term","title":"최고 가격제","text":"정부가 가격의 상한을 정하는 제도입니다. 균형 가격보다 낮게 정하면 초과 수요와 암시장이 생길 수 있습니다.","keywords":["최고 가격제"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-05","grade":"h2"},
{"id":"soc-h-econ-05#t8","kind":"term","title":"최저 가격제","text":"정부가 가격의 하한을 정하는 제도입니다. 균형 가격보다 높게 정하면 초과 공급이 생깁니다. 예: 최저 임금제","keywords":["최저 가격제"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-05","grade":"h2"},
{"id":"soc-h-econ-05#t9","kind":"term","title":"조세 전가","text":"세금을 내는 사람(납세자)의 부담이 가격 등을 통해 다른 사람(담세자)에게 넘어가는 것입니다. 간접세에서 나타납니다.","keywords":["조세 전가"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-05","grade":"h2"},
{"id":"soc-h-econ-05#f0","kind":"faq","title":"공공재는 다 정부가 만들어야 하나요?","text":"꼭 그런 것은 아닙니다. 공공재의 핵심은 무임승차 때문에 시장에 맡기면 충분히 공급되지 않는다는 점입니다. 그래서 보통 정부가 세금으로 비용을 대지만, 실제 건설이나 운영은 민간 기업에 맡기기도 합니다. 중요한 것은 누가 만드느냐보다 비용을 세금처럼 함께 부담하는 방식이 필요하다는 점입니다.","keywords":["공공재"],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-05","grade":"h2"},
{"id":"soc-h-econ-05#f1","kind":"faq","title":"외부 경제는 좋은 거니까 시장 실패가 아닌 것 아닌가요?","text":"외부 경제도 시장 실패입니다. 남에게 이익을 주는 활동이라도 그 이익이 거래하는 사람의 계산에 들어가지 않으므로, 사회적으로 바람직한 양보다 적게 생산·소비됩니다. \"좋은 일이 충분히 일어나지 않는\" 비효율이 생기는 것이지요.","keywords":["시장 실패"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-05","grade":"h2"},
{"id":"soc-h-econ-05#f2","kind":"faq","title":"최고 가격제를 하면 물건이 싸지니까 소비자에게 무조건 좋은 거 아니에요?","text":"물건을 산 소비자는 싸게 사서 이익이지만, 공급량이 줄어 물건을 아예 못 구하는 소비자가 생깁니다. 줄을 서는 데 시간을 쓰거나 암시장에서 더 비싸게 사는 일도 생깁니다. 그래서 가격 규제는 목적과 함께 이런 부작용을 따져 보아야 합니다.","keywords":["최고 가격제"],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-05","grade":"h2"},
{"id":"soc-h-econ-05#m0","kind":"mistake","title":"자주 하는 실수","text":"외부 경제와 외부 불경제의 거래량을 거꾸로 기억하는 실수 — 남에게 이익을 주는 외부 경제는 과소, 손해를 주는 외부 불경제는 과다 생산·소비됩니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-05","grade":"h2"},
{"id":"soc-h-econ-05#m1","kind":"mistake","title":"자주 하는 실수","text":"가격 규제 아래 실제 거래량을 수요량으로 답하는 실수 — 거래량은 수요량과 공급량 가운데 작은 쪽입니다. 최고 가격제면 공급량, 최저 가격제면 수요량입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-05","grade":"h2"},
{"id":"soc-h-econ-05#m2","kind":"mistake","title":"자주 하는 실수","text":"납세자와 담세자를 헷갈리는 실수 — 부가 가치세는 사업자가 내지만(납세자) 소비자가 부담합니다(담세자).","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-05","grade":"h2"},
{"id":"soc-h-econ-06","kind":"unit","title":"효율성과 형평성","text":"소비자 잉여와 생산자 잉여로 시장 거래의 효율성을 평가하고, 정부 실패의 원인, 로렌츠 곡선·지니 계수로 본 소득 분배, 누진세와 사회 보장 제도 같은 재분배 정책을 살펴 효율성과 형평성의 관계를 생각합니다. 소비자 잉여·생산자 잉여·총잉여를 구하고 시장 균형의 효율성을 설명할 수 있다. 정부 실패의 뜻과 원인(정보 부족, 관료주의, 이익 집단의 영향)을…","keywords":["소비자 잉여","생산자 잉여","총잉여","정부 실패","로렌츠 곡선","지니 계수","누진세","사회 보험","공공 부조","형평성"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-06","grade":"h2"},
{"id":"soc-h-econ-06#c0","kind":"concept","title":"소비자 잉여와 생산자 잉여","text":"시장에서 거래가 이루어지면 사는 사람과 파는 사람 모두 이익을 얻습니다. 이 이익을 잉여로 나타냅니다. 소비자 잉여 = 소비자가 지불할 용의가 있는 최고 금액 − 실제로 지불한 금액 생산자 잉여 = 생산자가 실제로 받은 금액 − 생산자가 최소한 받아야겠다고 생각하는 금액(생산 비용) 총","keywords":["소비자 잉여","생산자 잉여","총잉여"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-06","grade":"h2"},
{"id":"soc-h-econ-06#c1","kind":"concept","title":"시장 균형과 효율성","text":"경제학에서 자원 배분이 효율적이라는 것은 주어진 자원으로 사회 전체가 얻는 이익(총잉여)이 가장 큰 상태를 말합니다. 경쟁 시장에서는 시장 균형에서 총잉여가 가장 큽니다. 균형 거래량보다 적게 거래하면: 소비자가 낼 용의가 있는 금액이 생산 비용보다 큰, 곧 서로에게 이익이 되는 거래가","keywords":["총잉여"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-06","grade":"h2"},
{"id":"soc-h-econ-06#c2","kind":"concept","title":"정부 실패","text":"앞 단원에서 시장 실패를 바로잡기 위해 정부가 개입한다고 배웠습니다. 그러나 정부의 개입이 오히려 자원 배분을 비효율적으로 만들기도 하는데, 이를 정부 실패라고 합니다. 정부 실패의 주요 원인은 다음과 같습니다. 정보 부족: 정부도 시장에서 일어나는 일을 모두 알 수 없습니다. 수요·공","keywords":["정부 실패"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-06","grade":"h2"},
{"id":"soc-h-econ-06#c3","kind":"concept","title":"소득 분배: 로렌츠 곡선과 지니 계수","text":"시장은 효율적으로 자원을 배분하더라도, 소득은 사람마다 가진 능력·재산·기회에 따라 크게 다르게 나뉠 수 있습니다. 소득이 얼마나 고르게 나뉘어 있는지 나타내는 대표적인 지표가 로렌츠 곡선과 지니 계수입니다. 로렌츠 곡선은 소득이 낮은 사람부터 차례로 늘어세웠을 때, 가로축에 인구의 누","keywords":["로렌츠 곡선","지니 계수"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-06","grade":"h2"},
{"id":"soc-h-econ-06#c4","kind":"concept","title":"소득 재분배 정책: 누진세와 사회 보장 제도","text":"정부는 시장에서 나뉜 소득(시장 소득)의 격차를 줄이려고 소득 재분배 정책을 펼칩니다. 대표적인 수단은 누진세와 사회 보장 제도입니다. 누진세는 과세 대상 금액이 클수록 높은 세율을 매기는 세금입니다. 우리나라 소득세는 소득을 여러 구간으로 나누고, 각 구간을 넘는 부분에만 더 높은 세","keywords":["누진세","사회 보험","공공 부조"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-06","grade":"h2"},
{"id":"soc-h-econ-06#c5","kind":"concept","title":"효율성과 형평성의 상충","text":"효율성은 한정된 자원으로 가장 큰 이익을 얻는 것, 형평성은 소득과 기회가 공평하게 나뉘는 것입니다. 둘 다 중요한 가치이지만, 한쪽을 높이려 하면 다른 쪽이 낮아지는 상충 관계가 나타나기도 합니다. 예를 들어 누진세율을 크게 높이면 소득 격차가 줄어 형평성은 높아질 수 있습니다. 하지","keywords":["정부 실패","누진세","형평성"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-06","grade":"h2"},
{"id":"soc-h-econ-06#t0","kind":"term","title":"소비자 잉여","text":"소비자가 지불할 용의가 있는 최고 금액에서 실제로 지불한 금액을 뺀 것입니다. 그래프에서 수요 곡선 아래, 시장 가격 위의 넓이입니다.","keywords":["소비자 잉여"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-06","grade":"h2"},
{"id":"soc-h-econ-06#t1","kind":"term","title":"생산자 잉여","text":"생산자가 실제로 받은 금액에서 최소한 받아야 하는 금액(생산 비용)을 뺀 것입니다. 그래프에서 시장 가격 아래, 공급 곡선 위의 넓이입니다.","keywords":["생산자 잉여"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-06","grade":"h2"},
{"id":"soc-h-econ-06#t2","kind":"term","title":"총잉여","text":"소비자 잉여와 생산자 잉여의 합으로, 사회적 잉여라고도 합니다. 시장 실패가 없는 경쟁 시장에서는 시장 균형에서 가장 큽니다.","keywords":["총잉여"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-06","grade":"h2"},
{"id":"soc-h-econ-06#t3","kind":"term","title":"정부 실패","text":"정부의 시장 개입이 오히려 자원 배분을 비효율적으로 만드는 것입니다. 원인: 정보 부족, 관료주의, 이익 집단의 영향 등","keywords":["정부 실패"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-06","grade":"h2"},
{"id":"soc-h-econ-06#t4","kind":"term","title":"로렌츠 곡선","text":"소득이 낮은 사람부터 늘어세워 인구의 누적 비율과 소득의 누적 비율을 나타낸 곡선입니다. 대각선에서 멀리 휠수록 불평등합니다.","keywords":["로렌츠 곡선"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-06","grade":"h2"},
{"id":"soc-h-econ-06#t5","kind":"term","title":"지니 계수","text":"완전 평등선과 로렌츠 곡선 사이 넓이(A)를 완전 평등선 아래 삼각형 전체 넓이(A+B)로 나눈 값입니다. 0에 가까울수록 평등합니다.","keywords":["지니 계수"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-06","grade":"h2"},
{"id":"soc-h-econ-06#t6","kind":"term","title":"누진세","text":"과세 대상 금액이 클수록 높은 세율을 적용하는 세금입니다. 소득 재분배 효과가 큽니다.","keywords":["누진세"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-06","grade":"h2"},
{"id":"soc-h-econ-06#t7","kind":"term","title":"사회 보험","text":"가입자가 보험료를 내고 질병·노령·실업·산업 재해 같은 위험에 대비하는 사회 보장 제도입니다. 예: 국민연금, 국민 건강 보험","keywords":["사회 보험"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-06","grade":"h2"},
{"id":"soc-h-econ-06#t8","kind":"term","title":"공공 부조","text":"생활이 어려운 사람에게 국가·지방 자치 단체가 조세로 최저 생활을 보장하는 제도입니다. 예: 국민 기초 생활 보장 제도","keywords":["공공 부조"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-06","grade":"h2"},
{"id":"soc-h-econ-06#t9","kind":"term","title":"형평성","text":"소득과 기회가 공평하게 나뉘는 정도입니다. 능력이 같으면 같게(수평적 형평성), 다르면 다르게(수직적 형평성) 대우하는 것을 포함합니다.","keywords":["형평성"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-06","grade":"h2"},
{"id":"soc-h-econ-06#f0","kind":"faq","title":"누진세면 소득이 조금 늘었을 때 높은 구간으로 넘어가서 세금을 낸 뒤 소득이 오히려 줄 수도 있나요?","text":"초과 누진 세율에서는 그렇지 않습니다. 높은 세율은 구간을 넘는 부분에만 붙기 때문입니다. 예를 들어 4,000만 원 초과분에 30%가 붙는다면, 소득이 4,000만 원에서 4,100만 원으로 늘 때 추가로 붙는 세금은 늘어난 100만 원의 30%인 30만 원뿐입니다. 그래서 소득이 늘면 세금을 낸 뒤의 소득도 늘어납니다.","keywords":["누진세"],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-06","grade":"h2"},
{"id":"soc-h-econ-06#f1","kind":"faq","title":"지니 계수가 같으면 두 나라의 소득 분배 모양도 같은 건가요?","text":"꼭 같지는 않습니다. 지니 계수는 넓이의 비율 하나로 나타낸 값이라, 로렌츠 곡선의 모양이 달라도 A의 넓이가 같으면 지니 계수가 같아질 수 있습니다. 예를 들어 한 나라는 최하위층이 특히 가난하고, 다른 나라는 최상위층이 특히 부유할 수 있습니다. 그래서 로렌츠 곡선이나 다른 지표를 함께 보는 것이 좋습니다.","keywords":["지니 계수"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-06","grade":"h2"},
{"id":"soc-h-econ-06#f2","kind":"faq","title":"정부 실패가 있다면 정부는 아무것도 하지 않는 게 낫지 않나요?","text":"그렇게 단정하기는 어렵습니다. 시장 실패도 있고 정부 실패도 있으므로, 중요한 것은 \"어느 쪽이 더 나은 결과를 내는가\"를 사안마다 따져 보는 것입니다. 국방·치안처럼 시장이 해결하기 어려운 일도 있고, 민간에 맡기는 편이 나은 일도 있습니다. 그래서 정부의 역할을 두고 여러 의견이 함께 존재합니다.","keywords":["정부 실패"],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-06","grade":"h2"},
{"id":"soc-h-econ-06#m0","kind":"mistake","title":"자주 하는 실수","text":"소비자 잉여와 생산자 잉여의 자리를 바꾸는 실수 — 소비자 잉여는 수요 곡선과 가격 사이(가격 위), 생산자 잉여는 가격과 공급 곡선 사이(가격 아래)입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-06","grade":"h2"},
{"id":"soc-h-econ-06#m1","kind":"mistake","title":"자주 하는 실수","text":"지니 계수가 클수록 평등하다고 기억하는 실수 — 지니 계수는 클수록 불평등합니다. 반대로 10분위 분배율은 클수록 평등하니 지표마다 확인해야 합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-06","grade":"h2"},
{"id":"soc-h-econ-06#m2","kind":"mistake","title":"자주 하는 실수","text":"초과 누진 세율에서 소득 전체에 가장 높은 세율을 곱하는 실수 — 높은 세율은 구간을 넘는 부분에만 적용합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-06","grade":"h2"},
{"id":"soc-h-econ-07","kind":"unit","title":"국민 경제의 지표","text":"국내 총생산(GDP), 물가 지수와 물가 상승률, 실업률·고용률·경제 활동 참가율을 직접 계산해 보고, 이 지표들로 나라 경제의 활동 수준을 읽는 방법을 익힙니다. GDP의 뜻을 알고 최종 생산물의 시장 가치와 부가 가치의 합으로 GDP를 계산할 수 있다. 명목 GDP와 실질 GDP, 1인당 GDP를 구분하고 계산할 수 있다. 물가 지수를 읽고 물가 상승…","keywords":["국내 총생산(GDP)","중간재","부가 가치","명목 GDP","실질 GDP","1인당 GDP","물가 지수","물가 상승률","실업률","고용률"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-07","grade":"h2"},
{"id":"soc-h-econ-07#c0","kind":"concept","title":"국내 총생산(GDP)의 뜻과 측정 범위","text":"나라 경제 전체의 생산 활동 수준을 나타내는 대표 지표가 국내 총생산(GDP)입니다. GDP: 일정 기간 동안 한 나라 안에서 새로 생산된 최종 생산물의 시장 가치를 모두 더한 것 정의의 낱말 하나하나가 기준이 됩니다. 일정 기간: 보통 1년(또는 분기) 동안 생산된 것만 셉니다. 작년","keywords":["국내 총생산(GDP)","중간재"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-07","grade":"h2"},
{"id":"soc-h-econ-07#c1","kind":"concept","title":"부가 가치의 합으로 구하는 GDP","text":"생산은 여러 단계를 거칩니다. 각 단계에서 생산자가 새로 덧붙인 가치를 부가 가치라고 합니다. 부가 가치 = 생산물의 가치 − 생산에 쓴 중간재의 가치 예를 들어 가상의 나라에서 올해 다음 생산만 이루어졌다고 해 봅시다(단위: 만 원). 생산 단계 · 판매액 · 사들인 중간재 · 부가 ","keywords":["중간재","부가 가치"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-07","grade":"h2"},
{"id":"soc-h-econ-07#c2","kind":"concept","title":"명목 GDP와 실질 GDP, 1인당 GDP","text":"GDP는 \"생산량 × 가격\"을 더한 값이라서, 생산량이 늘지 않아도 가격만 오르면 커집니다. 그래서 두 가지 GDP를 구분합니다. 명목 GDP = 그해의 생산량 × 그해의 가격 실질 GDP = 그해의 생산량 × 기준 연도의 가격 실질 GDP는 가격을 기준 연도에 묶어 두고 계산하므로, ","keywords":["명목 GDP","실질 GDP","1인당 GDP"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-07","grade":"h2"},
{"id":"soc-h-econ-07#c3","kind":"concept","title":"물가 지수와 물가 상승률","text":"물가는 여러 상품의 가격을 종합한 평균적인 가격 수준입니다. 물가의 움직임은 물가 지수로 나타냅니다. 물가 지수는 기준 연도의 물가를 100으로 놓고 비교 연도의 물가가 얼마인지를 나타낸 수입니다. 물가 지수 = (비교 연도의 물가)/(기준 연도의 물가)×100 예를 들어 기준 연도에 ","keywords":["물가 지수","물가 상승률"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-07","grade":"h2"},
{"id":"soc-h-econ-07#c4","kind":"concept","title":"실업률·고용률·경제 활동 참가율","text":"고용 통계는 15세 이상 인구를 다음과 같이 나눕니다. 15세 이상 인구 · · 경제 활동 인구 (일할 의사와 능력이 있는 사람) · 취업자 · 조사 기간에 수입을 목적으로 1시간 이상 일한 사람, 일시 휴직자 등 · 실업자 · 일하지 않았지만 적극적으로 일자리를 찾았고, 일이 주어지면","keywords":["실업률","고용률"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-07","grade":"h2"},
{"id":"soc-h-econ-07#c5","kind":"concept","title":"경제 지표로 나라 경제 읽기","text":"나라 경제의 상태를 알려면 한 가지 지표만 보지 말고 여러 지표를 함께, 정확한 뜻에 맞게 읽어야 합니다. 우리나라에서는 한국은행이 GDP를, 국가 통계 기관이 물가·고용 통계를 정기적으로 발표합니다. 통계 자료를 읽을 때 다음을 확인합니다. 명목인가, 실질인가? 물가가 오르면 명목 G","keywords":["명목 GDP","실질 GDP","1인당 GDP","물가 상승률","실업률","고용률"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-07","grade":"h2"},
{"id":"soc-h-econ-07#t0","kind":"term","title":"국내 총생산(GDP)","text":"일정 기간 동안 한 나라 안에서 새로 생산된 최종 생산물의 시장 가치를 모두 더한 것입니다.","keywords":["국내 총생산(GDP)"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-07","grade":"h2"},
{"id":"soc-h-econ-07#t1","kind":"term","title":"중간재","text":"다른 상품을 생산하는 데 쓰이는 생산물입니다. 예: 빵을 만들려고 산 밀가루. GDP를 구할 때는 중복 계산을 피하려고 빼고 셉니다.","keywords":["중간재"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-07","grade":"h2"},
{"id":"soc-h-econ-07#t2","kind":"term","title":"부가 가치","text":"생산 과정에서 새로 덧붙여진 가치입니다. 생산물의 가치에서 중간재의 가치를 뺀 값이며, 모든 단계의 부가 가치를 더하면 GDP와 같습니다.","keywords":["부가 가치"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-07","grade":"h2"},
{"id":"soc-h-econ-07#t3","kind":"term","title":"명목 GDP","text":"그해의 생산량에 그해의 가격을 곱해 구한 GDP입니다. 가격이 오르기만 해도 커집니다.","keywords":["명목 GDP"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-07","grade":"h2"},
{"id":"soc-h-econ-07#t4","kind":"term","title":"실질 GDP","text":"그해의 생산량에 기준 연도의 가격을 곱해 구한 GDP입니다. 생산량의 실제 변화를 보여 줍니다.","keywords":["실질 GDP"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-07","grade":"h2"},
{"id":"soc-h-econ-07#t5","kind":"term","title":"1인당 GDP","text":"GDP를 인구로 나눈 값입니다. 나라 사이의 평균적인 생활 수준을 비교할 때 씁니다.","keywords":["1인당 GDP"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-07","grade":"h2"},
{"id":"soc-h-econ-07#t6","kind":"term","title":"물가 지수","text":"기준 연도의 물가를 100으로 하여 비교 연도의 물가 수준을 나타낸 수입니다. 예: 소비자 물가 지수","keywords":["물가 지수"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-07","grade":"h2"},
{"id":"soc-h-econ-07#t7","kind":"term","title":"물가 상승률","text":"물가 지수가 앞 해에 비해 몇 % 올랐는지 나타낸 값입니다. (올해 지수 − 작년 지수) ÷ 작년 지수 × 100","keywords":["물가 상승률"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-07","grade":"h2"},
{"id":"soc-h-econ-07#t8","kind":"term","title":"실업률","text":"경제 활동 인구 가운데 실업자가 차지하는 비율(%)입니다.","keywords":["실업률"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-07","grade":"h2"},
{"id":"soc-h-econ-07#t9","kind":"term","title":"고용률","text":"15세 이상 인구 가운데 취업자가 차지하는 비율(%)입니다. 구직 단념자의 변화에 영향을 받지 않아 실업률을 보완합니다.","keywords":["고용률"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-07","grade":"h2"},
{"id":"soc-h-econ-07#f0","kind":"faq","title":"학생인데 주말에 아르바이트를 하면 취업자인가요?","text":"네. 고용 통계에서는 조사 기간에 수입을 목적으로 1시간 이상 일했다면 학생이라도 취업자로 셉니다. 반대로 아르바이트를 하지 않고 공부만 하는 학생은 일할 의사가 없으므로 비경제 활동 인구입니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-07","grade":"h2"},
{"id":"soc-h-econ-07#f1","kind":"faq","title":"GDP가 크면 그 나라 사람들이 다 잘사는 건가요?","text":"꼭 그렇지는 않습니다. 인구가 많으면 GDP가 커도 한 사람의 몫(1인당 GDP)은 작을 수 있고, 1인당 GDP가 같아도 소득이 고르게 나뉘었는지는 GDP로 알 수 없습니다. 또 가사 노동이나 여가, 환경의 질처럼 삶에 중요한데 GDP에 들어가지 않는 것도 많습니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-07","grade":"h2"},
{"id":"soc-h-econ-07#f2","kind":"faq","title":"물가 지수가 100보다 작으면 무슨 뜻이에요?","text":"비교 연도의 물가가 기준 연도보다 낮다는 뜻입니다. 예를 들어 물가 지수가 95라면 기준 연도보다 물가가 5% 낮습니다. 물가 지수는 기준 연도를 100으로 놓은 상대적인 값이라서, 같은 물가라도 기준 연도를 바꾸면 지수의 숫자가 달라집니다.","keywords":["물가 지수"],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-07","grade":"h2"},
{"id":"soc-h-econ-07#m0","kind":"mistake","title":"자주 하는 실수","text":"모든 단계의 판매액을 더해 GDP를 구하는 실수 — 중간재를 여러 번 세게 됩니다. 최종 생산물의 가치만 더하거나 부가 가치를 더합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-07","grade":"h2"},
{"id":"soc-h-econ-07#m1","kind":"mistake","title":"자주 하는 실수","text":"물가 상승률을 지수의 차이로 쓰는 실수 — 작년 120에서 올해 126이면 6%가 아니라 6/120×100 = 5(%)입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-07","grade":"h2"},
{"id":"soc-h-econ-07#m2","kind":"mistake","title":"자주 하는 실수","text":"실업률의 분모를 15세 이상 인구로 쓰는 실수 — 실업률의 분모는 경제 활동 인구, 고용률·경제 활동 참가율의 분모가 15세 이상 인구입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-07","grade":"h2"},
{"id":"soc-h-econ-08","kind":"unit","title":"경제 성장과 한국 경제","text":"경제 성장의 뜻과 경제 성장률 계산, 성장을 이끄는 요인을 알고, 산업화 시기부터 정보화·세계화 시기까지 한국 경제가 걸어온 길과 그 성과·과제를 균형 있게 평가합니다. 경제 성장의 의미를 알고 실질 GDP로 경제 성장률을 계산할 수 있다. 노동·자본, 기술 혁신, 제도와 기업가 정신이 경제 성장에 미치는 영향을 설명할 수 있다. 경제 성장의 성과와 한계…","keywords":["경제 성장","경제 성장률","인적 자본","기술 혁신","기업가 정신","지속 가능한 성장","수출 주도형 성장","중화학 공업","외환 위기","자유 무역 협정(FTA)"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-08","grade":"h2"},
{"id":"soc-h-econ-08#c0","kind":"concept","title":"경제 성장의 의미와 경제 성장률","text":"경제 성장은 한 나라의 생산 능력이 커져 생산되는 재화와 서비스의 양이 늘어나는 것입니다. 가격이 오르기만 해도 커지는 명목 GDP가 아니라, 생산량의 변화를 보여 주는 실질 GDP가 늘어나는 것으로 측정합니다. 경제 성장률은 실질 GDP가 앞 해보다 몇 % 늘었는지 나타냅니다. 경제 ","keywords":["경제 성장","경제 성장률"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-08","grade":"h2"},
{"id":"soc-h-econ-08#c1","kind":"concept","title":"경제 성장의 요인","text":"경제가 성장하려면 더 많이 생산할 수 있는 능력이 커져야 합니다. 그 능력을 키우는 요인은 다음과 같습니다. 노동: 일하는 사람의 수와 일하는 시간이 늘면 생산이 늘어납니다. 그러나 인구가 줄거나 고령화가 진행되면 노동 투입을 늘리기 어렵습니다. 자본: 공장·기계·도로·항만 같은 물적 ","keywords":["경제 성장","인적 자본","기술 혁신","기업가 정신"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-08","grade":"h2"},
{"id":"soc-h-econ-08#c2","kind":"concept","title":"경제 성장의 성과와 한계","text":"경제 성장은 사람들의 삶에 큰 변화를 가져옵니다. 성과 소득이 늘어 더 많은 재화와 서비스를 누리고, 일자리가 늘어납니다. 세금이 늘어 정부가 교육·의료·사회 보장에 더 많이 투자할 수 있습니다. 영양·위생·의료가 나아져 평균 수명이 늘고 교육 수준이 높아집니다. 한계 삶의 질: GDP","keywords":["경제 성장"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-08","grade":"h2"},
{"id":"soc-h-econ-08#c3","kind":"concept","title":"한국 경제의 변화 ①: 산업화 시기","text":"6·25 전쟁 뒤 우리나라는 자원과 자본이 부족하고 원조에 크게 기대는 가난한 나라였습니다. 1960년대부터 정부가 주도하는 경제 개발이 본격적으로 시작되었습니다. 시기 · 주요 내용 1960년대 · 1962년 경제 개발 5개년 계획 시작. 풍부한 노동력을 바탕으로 섬유·의류·신발 같은","keywords":["수출 주도형 성장","중화학 공업"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-08","grade":"h2"},
{"id":"soc-h-econ-08#c4","kind":"concept","title":"한국 경제의 변화 ②: 정보화·세계화 시기","text":"1990년대 이후 우리 경제는 세계 경제와 더욱 긴밀하게 연결되고, 정보 통신 기술을 중심으로 산업 구조가 다시 바뀌었습니다. 시기 · 주요 내용 1990년대 · 1995년 세계 무역 기구(WTO) 출범으로 시장 개방 확대, 1996년 경제 협력 개발 기구(OECD) 가입, 1997년 ","keywords":["외환 위기","자유 무역 협정(FTA)"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-08","grade":"h2"},
{"id":"soc-h-econ-08#c5","kind":"concept","title":"한국 경제의 성과와 과제","text":"한국 경제는 짧은 기간에 가난한 농업 국가에서 세계적인 무역 국가로 성장했습니다. 이를 평가할 때는 성과와 과제를 함께, 여러 관점에서 보아야 합니다. 성과 매우 빠른 경제 성장으로 국민 소득과 생활 수준이 크게 높아졌습니다. 반도체·자동차·조선 같은 산업에서 세계적인 경쟁력을 갖추었습","keywords":["경제 성장","기술 혁신"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-08","grade":"h2"},
{"id":"soc-h-econ-08#t0","kind":"term","title":"경제 성장","text":"한 나라의 생산 능력이 커져 실질 GDP가 늘어나는 것입니다.","keywords":["경제 성장"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-08","grade":"h2"},
{"id":"soc-h-econ-08#t1","kind":"term","title":"경제 성장률","text":"실질 GDP가 앞 해보다 몇 % 늘었는지 나타낸 값입니다. (올해 실질 GDP − 작년 실질 GDP) ÷ 작년 실질 GDP × 100","keywords":["경제 성장률"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-08","grade":"h2"},
{"id":"soc-h-econ-08#t2","kind":"term","title":"인적 자본","text":"교육과 훈련, 경험으로 사람에게 쌓인 지식과 기술입니다. 노동의 생산성을 높입니다.","keywords":["인적 자본"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-08","grade":"h2"},
{"id":"soc-h-econ-08#t3","kind":"term","title":"기술 혁신","text":"새로운 기술·생산 방법·상품을 개발해 같은 자원으로 더 많이, 더 좋게 생산할 수 있게 되는 것입니다.","keywords":["기술 혁신"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-08","grade":"h2"},
{"id":"soc-h-econ-08#t4","kind":"term","title":"기업가 정신","text":"위험을 무릅쓰고 새로운 상품·시장·생산 방법에 도전해 혁신을 이루려는 태도입니다.","keywords":["기업가 정신"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-08","grade":"h2"},
{"id":"soc-h-econ-08#t5","kind":"term","title":"지속 가능한 성장","text":"환경을 보전하고 미래 세대의 필요를 해치지 않으면서 이루는 경제 성장입니다.","keywords":["지속 가능한 성장"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-08","grade":"h2"},
{"id":"soc-h-econ-08#t6","kind":"term","title":"수출 주도형 성장","text":"수출을 늘리는 것을 중심으로 경제를 성장시키는 전략입니다. 1960년대 이후 우리나라의 성장 방식입니다.","keywords":["수출 주도형 성장"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-08","grade":"h2"},
{"id":"soc-h-econ-08#t7","kind":"term","title":"중화학 공업","text":"철강·조선·석유 화학·기계처럼 큰 설비와 많은 자본이 필요한 공업입니다. 우리나라는 1970년대에 집중 육성했습니다.","keywords":["중화학 공업"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-08","grade":"h2"},
{"id":"soc-h-econ-08#t8","kind":"term","title":"외환 위기","text":"나라에 외국 돈(외환)이 모자라 외국에 진 빚을 갚기 어려워진 위기입니다. 우리나라는 1997년에 겪었습니다.","keywords":["외환 위기"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-08","grade":"h2"},
{"id":"soc-h-econ-08#t9","kind":"term","title":"자유 무역 협정(FTA)","text":"나라 사이에 관세 같은 무역 장벽을 낮추거나 없애기로 맺은 협정입니다. 우리나라의 첫 FTA는 2004년에 발효된 한·칠레 FTA입니다.","keywords":["자유 무역 협정(FTA)"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-08","grade":"h2"},
{"id":"soc-h-econ-08#f0","kind":"faq","title":"경제 성장률이 떨어졌다는 뉴스는 경제가 작아졌다는 뜻인가요?","text":"아닙니다. 성장률이 4%에서 2%로 떨어졌다면 경제가 커지는 속도가 느려진 것이고, 경제 규모(실질 GDP)는 여전히 2% 커졌습니다. 경제가 실제로 작아진 것은 성장률이 0보다 작은 마이너스 성장일 때입니다.","keywords":["경제 성장","경제 성장률"],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-08","grade":"h2"},
{"id":"soc-h-econ-08#f1","kind":"faq","title":"잘사는 나라일수록 경제 성장률이 낮은 경우가 많은 것은 왜인가요?","text":"이미 자본과 기술이 많이 쌓인 나라는 같은 투자를 더 해도 늘어나는 생산이 점점 작아지는 경향이 있습니다. 또 인구 고령화로 일할 사람이 늘기 어렵기도 합니다. 반면 자본이 적은 나라는 공장과 기계를 늘리고 앞선 기술을 받아들이는 것만으로도 빠르게 성장할 수 있습니다. 그래서 잘사는 나라는 성장을 이어 가려면 새로운 기술 혁신이 더욱 중요합니다.","keywords":["경제 성장","경제 성장률"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-08","grade":"h2"},
{"id":"soc-h-econ-08#f2","kind":"faq","title":"한국 경제가 짧은 기간에 빨리 성장할 수 있었던 까닭은 무엇인가요?","text":"한 가지 이유로 설명하기는 어렵습니다. 교육으로 길러진 인적 자본, 수출 주도형 성장 전략과 정부의 산업 정책, 기업과 노동자의 노력, 높은 저축과 투자, 그리고 무역이 확대되던 세계 경제 환경 등이 함께 작용했다고 봅니다. 한편 그 과정에서 생긴 불균형과 문제점도 함께 살펴야 균형 잡힌 이해가 됩니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-08","grade":"h2"},
{"id":"soc-h-econ-08#m0","kind":"mistake","title":"자주 하는 실수","text":"경제 성장률이 낮아진 것을 실질 GDP가 줄어든 것으로 읽는 실수 — 성장률이 양수이면 GDP는 늘었습니다. 음수일 때만 줄어듭니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-08","grade":"h2"},
{"id":"soc-h-econ-08#m1","kind":"mistake","title":"자주 하는 실수","text":"명목 GDP로 경제 성장률을 구하는 실수 — 명목 GDP에는 물가 상승의 효과가 섞여 있으므로 실질 GDP를 씁니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-08","grade":"h2"},
{"id":"soc-h-econ-08#m2","kind":"mistake","title":"자주 하는 실수","text":"여러 해의 성장률을 단순히 더하는 실수 — 해마다 앞 해를 기준으로 늘어나므로 10% 뒤 5% 성장은 15%가 아니라 15.5%입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-08","grade":"h2"},
{"id":"soc-h-econ-09","kind":"unit","title":"경기 변동과 총수요·총공급","text":"경기가 좋아지고 나빠지는 까닭을 총수요와 총공급으로 설명하고, 인플레이션과 실업이 경제와 생활에 미치는 영향을 분석합니다. 경기 변동의 의미와 확장기·수축기의 특징을 설명할 수 있다. 총수요의 구성 요소(소비, 투자, 정부 지출, 순수출)를 알고 총수요와 총공급의 변동 요인을 사례에 적용할 수 있다. 총수요·총공급이 변할 때 물가 수준과 실질 GDP가 어…","keywords":["경기 변동","확장기","수축기","총수요","총공급","인플레이션","수요 견인 인플레이션","비용 인상 인플레이션","스태그플레이션"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-09","grade":"h2"},
{"id":"soc-h-econ-09#c0","kind":"concept","title":"경기 변동의 의미와 국면","text":"경기는 생산·소비·투자·고용 같은 국민 경제 전체의 활동 수준을 말합니다. 경제는 장기적으로 성장하더라도 그 길을 곧게 가지 않고, 활발해졌다가 가라앉기를 되풀이합니다. 이처럼 경제 활동이 장기 추세를 중심으로 오르내리는 현상을 경기 변동이라고 합니다. 경기 변동은 크게 두 국면으로 나","keywords":["경기 변동","확장기","수축기"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-09","grade":"h2"},
{"id":"soc-h-econ-09#c1","kind":"concept","title":"총수요와 그 구성","text":"총수요는 한 나라 안의 모든 경제 주체가 일정 기간 사려고 하는 재화와 서비스의 총량입니다. 누가 사느냐에 따라 네 부분으로 나눕니다. 총수요 = 소비+투자+정부 지출+순수출 소비: 가계가 재화와 서비스를 사는 지출 투자: 기업이 공장·기계 같은 자본재를 사는 지출 정부 지출: 정부가 ","keywords":["총수요"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-09","grade":"h2"},
{"id":"soc-h-econ-09#c2","kind":"concept","title":"총공급과 거시 경제의 균형","text":"총공급은 한 나라의 모든 기업이 일정 기간 생산하여 팔려고 하는 재화와 서비스의 총량입니다. 물가 수준이 오르면 기업은 제품을 더 비싸게 팔 수 있어 생산을 늘리려 하므로, 총공급 곡선은 (단기적으로) 오른쪽 위로 올라갑니다. 물가 이외의 요인이 바뀌면 총공급 곡선 자체가 이동합니다. ","keywords":["총수요","총공급"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-09","grade":"h2"},
{"id":"soc-h-econ-09#c3","kind":"concept","title":"총수요·총공급의 변동과 물가·실질 GDP","text":"총수요나 총공급이 변하면 균형점이 옮겨 가면서 물가 수준과 실질 GDP가 함께 달라집니다. 변화 · 물가 수준 · 실질 GDP 총수요 증가 · 상승 · 증가 총수요 감소 · 하락 · 감소 총공급 증가 · 하락 · 증가 총공급 감소 · 상승 · 감소 총수요가 변할 때는 물가와 실질 GDP","keywords":["경기 변동","총수요","총공급"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-09","grade":"h2"},
{"id":"soc-h-econ-09#c4","kind":"concept","title":"인플레이션의 유형과 스태그플레이션","text":"물가 수준이 지속적으로 오르는 현상을 인플레이션이라고 합니다. 원인에 따라 두 가지로 나눕니다. 수요 견인 인플레이션: 총수요가 증가해 생기는 인플레이션입니다. 소비·투자·정부 지출·순수출이 늘어 물가가 오르며, 이때 실질 GDP도 늘어납니다. 경기 과열기에 자주 나타납니다. 비용 인상","keywords":["총수요","총공급","인플레이션","수요 견인 인플레이션","비용 인상 인플레이션","스태그플레이션"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-09","grade":"h2"},
{"id":"soc-h-econ-09#c5","kind":"concept","title":"인플레이션과 실업이 미치는 영향","text":"인플레이션이 일어나면 화폐의 가치(같은 돈으로 살 수 있는 양)가 떨어집니다. 그 결과 다음과 같은 문제가 생깁니다. 부와 소득의 재분배: 예상하지 못한 인플레이션은 사람마다 손익을 다르게 만듭니다. 상대적으로 유리 · 상대적으로 불리 채무자(돈을 빌린 사람) · 채권자(돈을 빌려준 사","keywords":["인플레이션"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-09","grade":"h2"},
{"id":"soc-h-econ-09#t0","kind":"term","title":"경기 변동","text":"생산·소비·고용 같은 국민 경제 전체의 활동 수준이 장기 추세를 중심으로 오르내리기를 되풀이하는 현상입니다.","keywords":["경기 변동"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-09","grade":"h2"},
{"id":"soc-h-econ-09#t1","kind":"term","title":"확장기","text":"경기의 저점에서 정점까지의 국면입니다. 생산·소득·고용이 늘고 물가 상승 압력이 커집니다. 회복기와 호황기로 나누기도 합니다.","keywords":["확장기"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-09","grade":"h2"},
{"id":"soc-h-econ-09#t2","kind":"term","title":"수축기","text":"경기의 정점에서 저점까지의 국면입니다. 생산·소득이 줄고 실업과 재고가 늘어납니다. 후퇴기와 불황기로 나누기도 합니다.","keywords":["수축기"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-09","grade":"h2"},
{"id":"soc-h-econ-09#t3","kind":"term","title":"총수요","text":"한 나라의 모든 경제 주체가 일정 기간 사려고 하는 재화와 서비스의 총량입니다. 소비 + 투자 + 정부 지출 + 순수출(수출 − 수입)로 이루어집니다.","keywords":["총수요"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-09","grade":"h2"},
{"id":"soc-h-econ-09#t4","kind":"term","title":"총공급","text":"한 나라의 모든 기업이 일정 기간 생산하여 팔려고 하는 재화와 서비스의 총량입니다.","keywords":["총공급"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-09","grade":"h2"},
{"id":"soc-h-econ-09#t5","kind":"term","title":"인플레이션","text":"물가 수준이 지속적으로 오르는 현상입니다. 화폐의 가치가 떨어집니다.","keywords":["인플레이션"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-09","grade":"h2"},
{"id":"soc-h-econ-09#t6","kind":"term","title":"수요 견인 인플레이션","text":"총수요가 증가해 생기는 인플레이션입니다. 물가와 함께 실질 GDP도 늘어납니다.","keywords":["수요 견인 인플레이션"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-09","grade":"h2"},
{"id":"soc-h-econ-09#t7","kind":"term","title":"비용 인상 인플레이션","text":"원자재 가격·임금 같은 생산 비용이 올라 총공급이 감소해 생기는 인플레이션입니다. 물가는 오르고 실질 GDP는 줄어듭니다.","keywords":["비용 인상 인플레이션"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-09","grade":"h2"},
{"id":"soc-h-econ-09#t8","kind":"term","title":"스태그플레이션","text":"경기 침체(스태그네이션)와 인플레이션이 합쳐진 말로, 경기가 침체해 실업이 늘어나는데도 물가가 계속 오르는 현상입니다.","keywords":["스태그플레이션"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-09","grade":"h2"},
{"id":"soc-h-econ-09#f0","kind":"faq","title":"물가가 오르면 왜 돈을 빌린 사람이 유리해요?","text":"빌린 금액은 숫자로 정해져 있는데, 물가가 오르면 그 돈의 가치(살 수 있는 양)가 줄어들기 때문입니다. 1년 전에 운동화 열 켤레 값을 빌렸는데 물가가 올라 같은 돈이 이제 여덟 켤레 값밖에 안 된다면, 빌린 사람은 실제로는 덜 갚는 셈입니다. 반대로 빌려준 사람은 그만큼 손해를 봅니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-09","grade":"h2"},
{"id":"soc-h-econ-09#f1","kind":"faq","title":"총수요 곡선은 왜 오른쪽 아래로 내려가요?","text":"물가 수준이 내리면 ① 같은 돈과 자산으로 더 많이 살 수 있어 소비가 늘고, ② 거래에 필요한 돈이 줄어 이자율이 내려가 투자가 늘고, ③ 우리 상품이 외국 상품보다 상대적으로 싸져 순수출이 늘어납니다. 그래서 물가가 낮을수록 총수요량이 많아집니다.","keywords":["총수요"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-09","grade":"h2"},
{"id":"soc-h-econ-09#f2","kind":"faq","title":"수요 견인 인플레이션과 비용 인상 인플레이션은 어떻게 구별해요?","text":"물가가 오를 때 생산(실질 GDP)이 어떻게 되는지를 보면 됩니다. 물가와 함께 생산·고용이 늘면 총수요가 늘어난 수요 견인 인플레이션, 물가는 오르는데 생산이 줄고 실업이 늘면 총공급이 줄어든 비용 인상 인플레이션입니다.","keywords":["인플레이션","수요 견인 인플레이션","비용 인상 인플레이션"],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-09","grade":"h2"},
{"id":"soc-h-econ-09#f3","kind":"faq","title":"경기 변동은 늘 같은 간격으로 반복돼요?","text":"아닙니다. 확장기와 수축기의 길이, 오르내리는 폭은 매번 다릅니다. 원인도 소비 심리 변화, 기업 투자의 변동, 원자재 가격 충격, 해외 경기 변화 등으로 다양합니다. 그래서 경기의 정점과 저점은 지나고 나서 여러 지표를 종합해 판단합니다.","keywords":["경기 변동"],"ref":{"tab":"faq","idx":3},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-09","grade":"h2"},
{"id":"soc-h-econ-09#m0","kind":"mistake","title":"자주 하는 실수","text":"총수요를 계산할 때 수입을 더하는 실수 — 총수요에는 순수출(수출 − 수입)이 들어가므로 수입은 뺍니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-09","grade":"h2"},
{"id":"soc-h-econ-09#m1","kind":"mistake","title":"자주 하는 실수","text":"물가가 오르면 실질 GDP도 늘었다고 단정하는 실수 — 총수요 증가면 늘지만, 총공급 감소(비용 인상 인플레이션)면 오히려 줄어듭니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-09","grade":"h2"},
{"id":"soc-h-econ-09#m2","kind":"mistake","title":"자주 하는 실수","text":"인플레이션의 손익을 거꾸로 기억하는 실수 — 화폐 가치가 떨어지므로 채무자·실물 자산 보유자가 유리하고, 채권자·현금과 예금 보유자·고정 소득자가 불리합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-09","grade":"h2"},
{"id":"soc-h-econ-10","kind":"unit","title":"재정 정책과 통화 정책","text":"정부의 재정 정책과 중앙은행의 통화 정책이 총수요를 조절해 경기를 안정시키는 원리와 효과를 알고, 정책의 한계와 찬반 논쟁을 살펴봅니다. 확장적·긴축적 재정 정책의 수단과 효과를 설명할 수 있다. 기준 금리, 공개 시장 운영, 지급 준비율 정책이 통화량과 이자율에 미치는 영향을 설명할 수 있다. 경기 과열과 경기 침체에 알맞은 정책을 고르고 그 결과를 총…","keywords":["경제 안정화 정책","재정 정책","통화 정책","기준 금리","공개 시장 운영","지급 준비율","정책 시차","재정 적자","국가 채무","구축 효과"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-10","grade":"h2"},
{"id":"soc-h-econ-10#c0","kind":"concept","title":"경제 안정화 정책과 재정 정책","text":"경기가 지나치게 달아오르면 물가가 빠르게 오르고, 지나치게 가라앉으면 실업이 늘어납니다. 그래서 정부와 중앙은행은 총수요를 조절해 경기의 오르내림을 줄이려 합니다. 이를 경제 안정화 정책이라고 하며, 대표적인 것이 재정 정책과 통화 정책입니다. 재정 정책은 정부가 재정 지출(정부 지출)","keywords":["경제 안정화 정책","재정 정책","통화 정책"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-10","grade":"h2"},
{"id":"soc-h-econ-10#c1","kind":"concept","title":"통화 정책 — 기준 금리, 공개 시장 운영, 지급 준비율","text":"통화 정책은 중앙은행이 시중의 통화량과 이자율을 조절해 총수요를 관리하는 정책입니다. 우리나라의 중앙은행은 한국은행이며, 한국은행의 금융 통화 위원회가 통화 정책을 결정합니다. 기준 금리: 중앙은행이 정하는 정책 금리로, 시중의 여러 금리에 영향을 줍니다. 기준 금리를 내리면 예금·대출","keywords":["통화 정책","기준 금리","공개 시장 운영","지급 준비율"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-10","grade":"h2"},
{"id":"soc-h-econ-10#c2","kind":"concept","title":"경기 과열과 경기 침체에 맞는 정책 선택","text":"경제 안정화 정책은 경기의 방향과 반대로 총수요를 움직입니다. 상황 · 문제 · 정책 방향 · 재정 정책 · 통화 정책 경기 침체 · 실업 증가, 생산 감소 · 총수요 늘리기 · 정부 지출 확대, 세율 인하 · 기준 금리 인하, 국공채 매입, 지급 준비율 인하 경기 과열 · 물가 급등 ","keywords":["경제 안정화 정책","재정 정책","통화 정책","기준 금리","지급 준비율"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-10","grade":"h2"},
{"id":"soc-h-econ-10#c3","kind":"concept","title":"정책의 한계 ① — 정책 시차","text":"경제 안정화 정책은 결정하자마자 효과가 나타나지 않습니다. 경제 문제가 생긴 때부터 정책의 효과가 나타날 때까지 걸리는 시간을 정책 시차라고 합니다. 내부 시차: 경제 문제를 알아차리고, 정책을 결정해 실행하기까지 걸리는 시간 외부 시차: 정책을 실행한 뒤 실제로 경제에 효과가 나타나기","keywords":["경제 안정화 정책","재정 정책","통화 정책","정책 시차"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-10","grade":"h2"},
{"id":"soc-h-econ-10#c4","kind":"concept","title":"정책의 한계 ② — 재정 적자와 국가 채무","text":"정부의 한 해 수입(세입)에서 지출(세출)을 뺀 것을 재정 수지라고 합니다. 세입이 세출보다 많으면 재정 흑자, 세출이 세입보다 많으면 재정 적자입니다. 확장적 재정 정책으로 지출을 늘리고 세금을 줄이면 재정 적자가 생기기 쉽습니다. 정부는 모자라는 돈을 주로 국채를 발행해 빌려 오므로","keywords":["재정 정책","재정 적자","국가 채무","구축 효과"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-10","grade":"h2"},
{"id":"soc-h-econ-10#c5","kind":"concept","title":"안정화 정책을 둘러싼 논쟁과 사례","text":"정부와 중앙은행이 경기에 얼마나 적극적으로 개입해야 하는지에 대해서는 서로 다른 주장이 있습니다. 적극적 개입을 주장하는 쪽 · 신중한 개입을 주장하는 쪽 시장이 스스로 회복하기까지 오래 걸리고, 그동안 실업과 소득 감소의 고통이 크다 · 정책 시차와 정보 부족 때문에 정책이 엉뚱한 때","keywords":["재정 정책","정책 시차","재정 적자","국가 채무"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-10","grade":"h2"},
{"id":"soc-h-econ-10#t0","kind":"term","title":"경제 안정화 정책","text":"총수요를 조절해 경기의 지나친 과열과 침체를 막고 물가와 고용을 안정시키려는 정책입니다. 재정 정책과 통화 정책이 대표적입니다.","keywords":["경제 안정화 정책"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-10","grade":"h2"},
{"id":"soc-h-econ-10#t1","kind":"term","title":"재정 정책","text":"정부가 재정 지출과 조세를 조절해 총수요를 관리하는 정책입니다. 지출 확대·세율 인하는 확장적, 지출 축소·세율 인상은 긴축적 재정 정책입니다.","keywords":["재정 정책"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-10","grade":"h2"},
{"id":"soc-h-econ-10#t2","kind":"term","title":"통화 정책","text":"중앙은행이 통화량과 이자율을 조절해 총수요를 관리하는 정책입니다. 기준 금리, 공개 시장 운영, 지급 준비율 정책 등을 씁니다.","keywords":["통화 정책"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-10","grade":"h2"},
{"id":"soc-h-econ-10#t3","kind":"term","title":"기준 금리","text":"중앙은행이 정하는 정책 금리로, 시중의 예금·대출 금리에 영향을 줍니다. 우리나라는 한국은행 금융 통화 위원회가 정합니다.","keywords":["기준 금리"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-10","grade":"h2"},
{"id":"soc-h-econ-10#t4","kind":"term","title":"공개 시장 운영","text":"중앙은행이 금융 시장에서 국공채 같은 증권을 사고팔아 통화량을 조절하는 정책입니다. 사들이면 통화량이 늘고, 팔면 줄어듭니다.","keywords":["공개 시장 운영"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-10","grade":"h2"},
{"id":"soc-h-econ-10#t5","kind":"term","title":"지급 준비율","text":"은행이 고객의 예금 가운데 대출하지 않고 지급 준비금으로 남겨 두어야 하는 비율입니다. 내리면 대출이 늘어 통화량이 늘어납니다.","keywords":["지급 준비율"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-10","grade":"h2"},
{"id":"soc-h-econ-10#t6","kind":"term","title":"정책 시차","text":"경제 문제가 생긴 때부터 정책의 효과가 나타날 때까지 걸리는 시간입니다. 정책을 결정·실행하기까지의 내부 시차와, 실행 뒤 효과가 나타나기까지의 외부 시차로 나뉩니다.","keywords":["정책 시차"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-10","grade":"h2"},
{"id":"soc-h-econ-10#t7","kind":"term","title":"재정 적자","text":"정부의 한 해 세출이 세입보다 많은 상태입니다. 모자라는 돈은 주로 국채를 발행해 메웁니다.","keywords":["재정 적자"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-10","grade":"h2"},
{"id":"soc-h-econ-10#t8","kind":"term","title":"국가 채무","text":"정부가 갚아야 할 빚입니다. 재정 적자가 이어지면 늘어나며, 흔히 GDP 대비 비율로 그 크기를 봅니다.","keywords":["국가 채무"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-10","grade":"h2"},
{"id":"soc-h-econ-10#t9","kind":"term","title":"구축 효과","text":"정부가 국채를 발행해 지출을 늘리면 이자율이 올라 민간 투자가 줄어드는 현상입니다. 확장적 재정 정책의 효과를 일부 줄입니다.","keywords":["구축 효과"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-10","grade":"h2"},
{"id":"soc-h-econ-10#f0","kind":"faq","title":"기준 금리를 내리면 왜 경기가 좋아져요?","text":"기준 금리를 내리면 은행의 예금·대출 금리가 따라 내립니다. 대출 이자 부담이 줄어 기업은 공장과 기계에 더 투자하고, 가계는 저축보다 소비를 늘립니다. 소비와 투자는 총수요의 구성 요소이므로 총수요가 늘어 생산과 고용이 늘어납니다. 다만 효과가 나타나기까지 시간이 걸리고, 물가가 오를 수도 있습니다.","keywords":["기준 금리"],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-10","grade":"h2"},
{"id":"soc-h-econ-10#f1","kind":"faq","title":"재정 적자는 무조건 나쁜 거예요?","text":"그렇지는 않습니다. 경기 침체 때 정부가 지출을 늘려 실업을 줄이면 적자가 생겨도 경제에 도움이 될 수 있습니다. 문제는 적자가 오래 이어져 국가 채무가 지나치게 쌓이는 경우입니다. 이자 부담이 커지고 미래 세대의 부담이 늘 수 있으므로, 적자의 크기와 기간, 쓰임새를 함께 살펴야 합니다.","keywords":["재정 적자"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-10","grade":"h2"},
{"id":"soc-h-econ-10#f2","kind":"faq","title":"국공채를 사면 왜 통화량이 늘어요?","text":"중앙은행이 국공채를 살 때는 그 값을 은행이나 투자자에게 치릅니다. 그 돈은 원래 시중에 없던 돈이 새로 풀려나온 것이어서 시중의 통화량이 늘어납니다. 반대로 중앙은행이 국공채를 팔면 산 사람들이 중앙은행에 돈을 내므로 그만큼 시중의 돈이 줄어듭니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-10","grade":"h2"},
{"id":"soc-h-econ-10#f3","kind":"faq","title":"재정 정책과 통화 정책은 누가 결정해요?","text":"재정 정책은 정부가 예산안을 만들고 국회가 심의·의결해 결정합니다. 통화 정책은 중앙은행이 결정하며, 우리나라에서는 한국은행의 금융 통화 위원회가 기준 금리 등을 정합니다.","keywords":["재정 정책","통화 정책"],"ref":{"tab":"faq","idx":3},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-10","grade":"h2"},
{"id":"soc-h-econ-10#m0","kind":"mistake","title":"자주 하는 실수","text":"국공채 매입과 매각의 방향을 거꾸로 기억하는 실수 — 중앙은행이 국공채를 사면 돈을 내주므로 통화량이 늘고, 팔면 돈을 거두므로 통화량이 줄어듭니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-10","grade":"h2"},
{"id":"soc-h-econ-10#m1","kind":"mistake","title":"자주 하는 실수","text":"기준 금리 인하를 재정 정책으로 분류하는 실수 — 금리·통화량을 조절하는 것은 중앙은행의 통화 정책, 지출·세금을 조절하는 것은 정부의 재정 정책입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-10","grade":"h2"},
{"id":"soc-h-econ-10#m2","kind":"mistake","title":"자주 하는 실수","text":"재정 정책과 통화 정책의 시차를 거꾸로 기억하는 실수 — 재정 정책은 내부 시차가 길고 외부 시차가 짧은 편, 통화 정책은 내부 시차가 짧고 외부 시차가 긴 편입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-10","grade":"h2"},
{"id":"soc-h-econ-11","kind":"unit","title":"국제 거래와 무역 정책","text":"국가 간 거래가 늘어 상호 의존이 깊어지는 모습을 알고, 비교 우위에 따른 무역의 원리와 자유 무역·보호 무역, 관세의 경제적 효과를 분석합니다. 국제 거래의 대상(재화, 서비스, 생산 요소)과 국가 간 상호 의존성을 설명할 수 있다. 절대 우위와 비교 우위를 구분하고, 기회비용으로 비교 우위를 찾을 수 있다. 비교 우위에 따른 특화와 교역으로 두 나라가…","keywords":["국제 거래","절대 우위","비교 우위","특화","교역 조건","자유 무역","보호 무역","유치산업 보호론","관세","비관세 장벽"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-11","grade":"h2"},
{"id":"soc-h-econ-11#c0","kind":"concept","title":"국제 거래의 대상과 상호 의존","text":"나라와 나라 사이에 이루어지는 거래를 국제 거래라고 합니다. 거래 대상은 세 가지로 나눌 수 있습니다. 대상 · 뜻 · 예 재화 · 눈에 보이는 물건 · 반도체·자동차 수출, 원유·농산물 수입 서비스 · 눈에 보이지 않는 활동 · 운송, 관광, 숙박, 유학, 금융 생산 요소 · 노동·자","keywords":["국제 거래","자유 무역"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-11","grade":"h2"},
{"id":"soc-h-econ-11#c1","kind":"concept","title":"절대 우위","text":"절대 우위는 어떤 재화를 다른 나라보다 더 적은 생산 요소(비용)로 생산할 수 있는 능력입니다. 애덤 스미스는 각 나라가 절대 우위를 가진 재화를 전문적으로 생산(특화)해 교환하면 서로 이익이 된다고 설명했습니다. 1개를 생산하는 데 필요한 노동 시간 · X재 · Y재 갑국 · 2시간 ","keywords":["절대 우위","비교 우위","특화"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-11","grade":"h2"},
{"id":"soc-h-econ-11#c2","kind":"concept","title":"비교 우위 — 기회비용으로 찾기","text":"비교 우위는 어떤 재화를 다른 나라보다 더 작은 기회비용으로 생산할 수 있는 능력입니다. 리카도는 한 나라가 두 재화 모두에 절대 우위가 있어도, 각 나라가 비교 우위를 가진 재화에 특화해 교역하면 서로 이익을 얻을 수 있다고 설명했습니다. 1개를 생산하는 데 필요한 노동 시간 · X재","keywords":["절대 우위","비교 우위","특화"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-11","grade":"h2"},
{"id":"soc-h-econ-11#c3","kind":"concept","title":"특화와 교역으로 얻는 이익","text":"각 나라가 비교 우위를 가진 재화만 집중해서 생산하는 것을 특화라고 합니다. 앞의 예에서 갑국은 9시간, 을국은 18시간의 노동을 가지고 있다고 해 봅시다. 구분 · 특화 전 (두 재화를 1개씩 생산) · 특화 후 갑국 (X재 4시간, Y재 5시간) · X재 1개, Y재 1개 · X재만","keywords":["비교 우위","특화"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-11","grade":"h2"},
{"id":"soc-h-econ-11#c4","kind":"concept","title":"자유 무역과 보호 무역","text":"자유 무역은 정부가 무역에 간섭하지 않고 자유롭게 거래하게 하는 것이고, 보호 무역은 관세나 수입 제한 등으로 국내 산업을 보호하는 것입니다. 자유 무역의 논리 · 보호 무역의 논리 비교 우위에 따른 특화로 세계 전체의 생산이 늘고 자원이 효율적으로 쓰인다 · 유치산업 보호론: 아직 경","keywords":["비교 우위","특화","자유 무역","보호 무역","유치산업 보호론","관세"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-11","grade":"h2"},
{"id":"soc-h-econ-11#c5","kind":"concept","title":"관세의 경제적 효과","text":"국제 가격(P_w)이 국내 균형 가격보다 낮은 상품을 생각해 봅시다. 무역을 하면 국내 가격은 국제 가격과 같아지고, 국내 수요량(Q₄)이 국내 공급량(Q₁)보다 많아 그 차이만큼 수입합니다. 이 상품 1개마다 관세 T를 매기면 국내 가격이 P_w+T로 오릅니다. 그 결과는 다음과 같습","keywords":["관세"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-11","grade":"h2"},
{"id":"soc-h-econ-11#t0","kind":"term","title":"국제 거래","text":"나라와 나라 사이에 재화, 서비스, 생산 요소(노동·자본·기술)를 사고파는 거래입니다.","keywords":["국제 거래"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-11","grade":"h2"},
{"id":"soc-h-econ-11#t1","kind":"term","title":"절대 우위","text":"어떤 재화를 다른 나라보다 더 적은 생산 요소(비용)로 생산할 수 있는 능력입니다. 애덤 스미스가 설명했습니다.","keywords":["절대 우위"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-11","grade":"h2"},
{"id":"soc-h-econ-11#t2","kind":"term","title":"비교 우위","text":"어떤 재화를 다른 나라보다 더 작은 기회비용으로 생산할 수 있는 능력입니다. 리카도가 설명했습니다.","keywords":["비교 우위"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-11","grade":"h2"},
{"id":"soc-h-econ-11#t3","kind":"term","title":"특화","text":"비교 우위가 있는 재화의 생산에 생산 요소를 집중하는 것입니다.","keywords":["특화"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-11","grade":"h2"},
{"id":"soc-h-econ-11#t4","kind":"term","title":"교역 조건","text":"수출품과 수입품이 교환되는 비율입니다. 두 나라가 모두 이익을 얻으려면 두 나라의 기회비용 사이에서 정해져야 합니다.","keywords":["교역 조건"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-11","grade":"h2"},
{"id":"soc-h-econ-11#t5","kind":"term","title":"자유 무역","text":"정부가 관세나 수입 제한 같은 간섭을 하지 않고 자유롭게 하는 무역입니다.","keywords":["자유 무역"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-11","grade":"h2"},
{"id":"soc-h-econ-11#t6","kind":"term","title":"보호 무역","text":"관세, 수입 할당제, 비관세 장벽 등으로 외국과의 경쟁에서 국내 산업을 보호하는 무역 정책입니다.","keywords":["보호 무역"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-11","grade":"h2"},
{"id":"soc-h-econ-11#t7","kind":"term","title":"유치산업 보호론","text":"아직 경쟁력이 약한 신생 산업이 자랄 때까지 일정 기간 보호해야 한다는 주장입니다. 19세기 독일의 리스트가 주장했습니다.","keywords":["유치산업 보호론"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-11","grade":"h2"},
{"id":"soc-h-econ-11#t8","kind":"term","title":"관세","text":"수입품(또는 수출품)에 매기는 세금입니다. 수입품의 국내 가격을 올려 국내 생산자를 보호하는 효과가 있습니다.","keywords":["관세"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-11","grade":"h2"},
{"id":"soc-h-econ-11#t9","kind":"term","title":"비관세 장벽","text":"관세 말고 수입을 어렵게 하는 수단입니다. 까다로운 검역·인증·기술 기준, 복잡한 통관 절차 등이 있습니다.","keywords":["비관세 장벽"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-11","grade":"h2"},
{"id":"soc-h-econ-11#f0","kind":"faq","title":"모든 것을 더 잘 만드는 나라도 왜 무역을 해요?","text":"절대 우위가 모든 재화에 있어도 기회비용은 재화마다 다릅니다. 그 나라가 상대적으로 덜 포기하는(기회비용이 작은) 재화에 집중하고, 나머지는 사 오면 같은 자원으로 더 많은 것을 누릴 수 있습니다. 다른 나라도 마찬가지로 자기 비교 우위 재화에 집중하므로 두 나라 모두 이익을 얻습니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-11","grade":"h2"},
{"id":"soc-h-econ-11#f1","kind":"faq","title":"관세를 매기면 누가 이익이고 누가 손해예요?","text":"수입품과 경쟁하는 국내 생산자는 가격이 올라 이익(생산자 잉여 증가)을 보고, 정부는 관세 수입을 얻습니다. 소비자는 더 비싸게 덜 사게 되어 손해(소비자 잉여 감소)를 봅니다. 소비자의 손해가 생산자 이익과 관세 수입의 합보다 커서 사회 전체로는 손실이 생깁니다.","keywords":["관세"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-11","grade":"h2"},
{"id":"soc-h-econ-11#f2","kind":"faq","title":"보호 무역은 무조건 나쁜 거예요?","text":"그렇게 단정할 수는 없습니다. 신생 산업 보호, 국가 안보, 급격한 실업 방지처럼 보호 무역에도 근거가 있습니다. 다만 보호가 길어지면 소비자 부담이 커지고 보호받는 산업의 경쟁력이 오히려 약해질 수 있으며, 상대국의 보복을 부를 수 있습니다. 그래서 보호의 목적·기간·비용을 함께 따져 보아야 합니다.","keywords":["보호 무역"],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-11","grade":"h2"},
{"id":"soc-h-econ-11#f3","kind":"faq","title":"기회비용을 구할 때 무엇을 무엇으로 나눠요?","text":"노동 시간이 주어졌다면, X재 1개의 기회비용(Y재 몇 개) = X재 1개에 드는 시간 ÷ Y재 1개에 드는 시간입니다. \"X재를 만드는 그 시간에 Y재를 몇 개 만들 수 있었나\"를 묻는 것이라고 생각하면 헷갈리지 않습니다. 생산량이 주어졌다면 반대로, X재 1개의 기회비용 = Y재 생산량 ÷ X재 생산량입니다.","keywords":[],"ref":{"tab":"faq","idx":3},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-11","grade":"h2"},
{"id":"soc-h-econ-11#m0","kind":"mistake","title":"자주 하는 실수","text":"절대 우위와 비교 우위를 섞는 실수 — 노동 시간(비용)을 그대로 비교하면 절대 우위, 기회비용을 비교하면 비교 우위입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-11","grade":"h2"},
{"id":"soc-h-econ-11#m1","kind":"mistake","title":"자주 하는 실수","text":"기회비용을 거꾸로 나누는 실수 — X재 1개의 기회비용(Y재 몇 개)은 X재 1개의 시간 ÷ Y재 1개의 시간입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-11","grade":"h2"},
{"id":"soc-h-econ-11#m2","kind":"mistake","title":"자주 하는 실수","text":"관세가 국내 생산자에게도 손해라고 생각하는 실수 — 관세로 국내 가격이 오르면 국내 생산자는 생산을 늘리고 생산자 잉여가 커집니다. 손해를 보는 쪽은 소비자입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-11","grade":"h2"},
{"id":"soc-h-econ-12","kind":"unit","title":"외환 시장과 환율","text":"외환 시장에서 외화의 수요와 공급에 따라 환율이 정해지는 원리를 알고, 환율이 오르내릴 때 나라 경제와 우리 생활이 받는 영향을 분석합니다. 환율의 뜻과 표시 방법을 알고, 환율 변동과 원화 가치의 관계를 설명할 수 있다. 외화의 수요·공급 요인을 알고 그 변화에 따른 환율의 결정과 변동을 분석할 수 있다. 환율 상승과 하락이 수출·수입, 물가, 외채 부…","keywords":["외환","외환 시장","환율","외화의 수요","외화의 공급","원화 가치","경상 수지","외채"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-12","grade":"h2"},
{"id":"soc-h-econ-12#c0","kind":"concept","title":"외환 시장과 환율의 의미","text":"다른 나라와 거래하려면 그 나라의 화폐가 필요합니다. 외국 화폐나 외국 화폐로 표시된 지급 수단을 외환(외화)이라 하고, 외환을 사고파는 시장을 외환 시장이라고 합니다. 환율은 두 나라 화폐의 교환 비율입니다. 우리나라에서는 보통 외화 1단위와 바꾸는 원화의 양으로 나타냅니다. 예를 들","keywords":["외환","외환 시장","환율"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-12","grade":"h2"},
{"id":"soc-h-econ-12#c1","kind":"concept","title":"외화의 수요와 공급, 환율의 결정","text":"환율도 다른 가격처럼 외환 시장에서 외화의 수요와 공급에 따라 정해집니다. 외화의 수요 (외화가 필요한 경우) · 외화의 공급 (외화가 들어오는 경우) 상품·서비스의 수입 · 상품·서비스의 수출 우리 국민의 해외여행·유학 · 외국인 관광객의 국내 여행 우리 국민·기업의 해외 투자 · 외","keywords":["외환","외환 시장","환율","외화의 수요","외화의 공급","외채"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-12","grade":"h2"},
{"id":"soc-h-econ-12#c2","kind":"concept","title":"환율의 변동 요인","text":"외화의 수요나 공급이 바뀌면 균형 환율이 바뀝니다. 외화 수요 증가 → 수요 곡선 오른쪽 이동 → 환율 상승 외화 공급 증가 → 공급 곡선 오른쪽 이동 → 환율 하락 요인 · 외환 시장의 변화 · 환율 수출 증가 · 외화 공급 증가 · 하락 수입 증가 · 외화 수요 증가 · 상승 우리 ","keywords":["외환","외환 시장","환율","외화의 수요"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-12","grade":"h2"},
{"id":"soc-h-econ-12#c3","kind":"concept","title":"환율 변동이 나라 경제에 미치는 영향","text":"환율이 바뀌면 수출품과 수입품의 가격이 달라져 나라 경제 전체가 영향을 받습니다. 구분 · 환율 상승 (원화 가치 하락) · 환율 하락 (원화 가치 상승) 수출 · 수출품의 외화 표시 가격 하락 → 수출 증가 · 수출품의 외화 표시 가격 상승 → 수출 감소 수입 · 수입품의 원화 표시 ","keywords":["환율","원화 가치","경상 수지","외채"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-12","grade":"h2"},
{"id":"soc-h-econ-12#c4","kind":"concept","title":"환율 변동과 개인의 경제생활","text":"환율은 수출 기업만의 일이 아닙니다. 해외여행, 유학, 수입품 구매처럼 우리 생활에도 바로 영향을 줍니다. 구분 · 환율 상승 때 · 환율 하락 때 해외여행을 가려는 사람 · 같은 달러를 바꾸는 데 원화가 더 들어 불리 · 원화가 덜 들어 유리 해외 유학생에게 학비를 보내는 가정 · 송","keywords":["환율"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-12","grade":"h2"},
{"id":"soc-h-econ-12#t0","kind":"term","title":"외환","text":"외국 화폐나 외국 화폐로 표시된 지급 수단입니다. 외화라고도 합니다.","keywords":["외환"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-12","grade":"h2"},
{"id":"soc-h-econ-12#t1","kind":"term","title":"외환 시장","text":"외환(외화)을 사고파는 시장입니다. 이곳에서 외화의 수요와 공급에 따라 환율이 정해집니다.","keywords":["외환 시장"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-12","grade":"h2"},
{"id":"soc-h-econ-12#t2","kind":"term","title":"환율","text":"두 나라 화폐의 교환 비율입니다. 우리나라에서는 보통 외화 1단위와 바꾸는 원화의 양(예: 1달러 = 1,200원)으로 나타냅니다.","keywords":["환율"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-12","grade":"h2"},
{"id":"soc-h-econ-12#t3","kind":"term","title":"외화의 수요","text":"외화가 필요해 사려는 것입니다. 수입, 해외여행·유학, 해외 투자, 외채 상환 등으로 생깁니다.","keywords":["외화의 수요"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-12","grade":"h2"},
{"id":"soc-h-econ-12#t4","kind":"term","title":"외화의 공급","text":"외화가 들어와 팔리는 것입니다. 수출, 외국인 관광객의 국내 여행, 외국인의 국내 투자 등으로 생깁니다.","keywords":["외화의 공급"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-12","grade":"h2"},
{"id":"soc-h-econ-12#t5","kind":"term","title":"원화 가치","text":"원화로 외화를 얼마나 살 수 있는지를 나타냅니다. 환율이 오르면 원화 가치는 떨어지고, 환율이 내리면 원화 가치는 오릅니다.","keywords":["원화 가치"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-12","grade":"h2"},
{"id":"soc-h-econ-12#t6","kind":"term","title":"경상 수지","text":"국제 수지 가운데 상품·서비스를 사고판 결과, 임금·이자·배당 같은 소득, 대가 없이 주고받은 돈을 기록한 부분입니다.","keywords":["경상 수지"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-12","grade":"h2"},
{"id":"soc-h-econ-12#t7","kind":"term","title":"외채","text":"나라 안의 정부·기업·금융 기관이 외국에서 빌려 갚아야 할 빚입니다. 환율이 오르면 원화로 갚는 부담이 커집니다.","keywords":["외채"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-12","grade":"h2"},
{"id":"soc-h-econ-12#f0","kind":"faq","title":"환율이 오르면 원화 가치는 왜 떨어진다고 해요?","text":"환율은 1달러의 원화 가격입니다. 1달러 = 1,200원이 1,300원으로 오르면 같은 1달러를 얻는 데 원화를 100원 더 내야 합니다. 원화 1,300원이 예전 1,200원만큼의 달러밖에 못 사니, 원화의 힘(가치)이 약해진 것입니다. 그래서 환율 상승 = 원화 가치 하락(원화 약세)입니다.","keywords":["환율","원화 가치"],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-12","grade":"h2"},
{"id":"soc-h-econ-12#f1","kind":"faq","title":"어떤 일이 외화 수요인지 공급인지 헷갈려요.","text":"\"그 일을 하려면 외화가 필요한가, 아니면 외화가 들어오는가\"를 물어보세요. 수입·해외여행·유학·해외 투자·외채 상환은 외화가 필요하므로 수요입니다. 수출·외국인 관광객·외국인의 국내 투자·해외에서 돈 빌려 오기는 외화가 들어오므로 공급입니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-12","grade":"h2"},
{"id":"soc-h-econ-12#f2","kind":"faq","title":"환율이 오르면 왜 수출이 늘어요?","text":"수출 기업이 국내에서 120만 원 받는 상품을 판다고 합시다. 1달러 = 1,000원이면 미국에서 1,200달러를 받아야 하지만, 1달러 = 1,200원이 되면 1,000달러만 받아도 같은 120만 원이 됩니다. 기업은 달러 가격을 낮출 수 있고, 미국 소비자에게는 더 싸 보이므로 수출이 늘어나는 경향이 있습니다.","keywords":["환율"],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-12","grade":"h2"},
{"id":"soc-h-econ-12#f3","kind":"faq","title":"해외여행을 가려면 환율이 오를 때와 내릴 때 중 언제가 좋아요?","text":"다른 조건이 같다면 환율이 내렸을 때가 유리합니다. 같은 달러를 더 적은 원화로 바꿀 수 있기 때문입니다. 다만 환율이 앞으로 어떻게 움직일지는 누구도 정확히 알 수 없으므로, 환율만 보고 무리하게 결정하기보다 필요한 시기와 예산을 함께 생각하는 것이 좋습니다.","keywords":["환율"],"ref":{"tab":"faq","idx":3},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-12","grade":"h2"},
{"id":"soc-h-econ-12#m0","kind":"mistake","title":"자주 하는 실수","text":"환율 숫자가 커지면 원화 가치도 커진다고 생각하는 실수 — 환율 상승(1,200원 → 1,300원)은 1달러를 사는 데 원화가 더 든다는 뜻이므로 원화 가치 하락입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-12","grade":"h2"},
{"id":"soc-h-econ-12#m1","kind":"mistake","title":"자주 하는 실수","text":"외화의 수요와 공급을 거꾸로 정하는 실수 — 수입·해외여행·해외 투자처럼 외화가 필요한 일은 수요, 수출·외국인 관광객·외국인 투자처럼 외화가 들어오는 일은 공급입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-12","grade":"h2"},
{"id":"soc-h-econ-12#m2","kind":"mistake","title":"자주 하는 실수","text":"달러 가격과 원화 가격을 바꾸어 계산하는 실수 — 원화 금액 = 달러 금액 × 환율, 달러 금액 = 원화 금액 ÷ 환율입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-econ","unit":"soc-h-econ-12","grade":"h2"},
{"id":"soc-h-ethics-01","kind":"unit","title":"윤리학과 윤리적 탐구","text":"윤리학이 무엇을 연구하는지 알고, 동서양 윤리 사상과 사회사상으로 현대 사회의 윤리 문제에 다가가는 방법과 도덕 추론으로 판단을 이끌어 내는 방법을 익힙니다. 윤리학을 이론 윤리학, 실천 윤리학, 메타 윤리학, 기술 윤리학으로 구분하여 설명할 수 있다. 도덕과학적 접근(진화 윤리학, 뇌과학)의 의의와 한계를 말할 수 있다. 동양 윤리, 서양 윤리, 사회사…","keywords":["이론 윤리학","실천 윤리학","메타 윤리학","기술 윤리학","진화 윤리학","연기","무위자연","정언 명령","공동체주의","도덕 추론"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-01","grade":"h2"},
{"id":"soc-h-ethics-01#c0","kind":"concept","title":"윤리학의 성격과 분류","text":"윤리학은 \"인간은 어떻게 살아야 하는가\", \"무엇이 옳고 그른가\"를 탐구하는 학문입니다. 사실이 어떠한지를 밝히는 자연 과학과 달리, 윤리학은 마땅히 어떠해야 하는지(당위)를 다루는 규범 학문의 성격을 지닙니다. 현대 윤리학은 탐구하는 대상과 방식에 따라 다음과 같이 나눕니다. 갈래 ·","keywords":["이론 윤리학","실천 윤리학","메타 윤리학","기술 윤리학"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-01","grade":"h2"},
{"id":"soc-h-ethics-01#c1","kind":"concept","title":"윤리적 존재로서의 인간과 도덕과학적 접근","text":"인간은 본능에 따라서만 사는 것이 아니라 옳고 그름을 따지고, 스스로 선택한 행동에 책임을 지는 윤리적 존재입니다. 인간은 이성으로 도덕 원리를 생각하고, 다른 사람과 어울려 살며 규범을 만들고, 자신의 삶을 반성하며 더 나은 사람이 되려고 합니다. 인간 본성을 두고 동양에서는 맹자가 ","keywords":["진화 윤리학"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-01","grade":"h2"},
{"id":"soc-h-ethics-01#c2","kind":"concept","title":"동양 윤리의 접근 — 유교·불교·도가","text":"동양 윤리는 이론을 따지는 것보다 수양을 통한 인격 완성과 조화로운 공동체를 중시합니다. 사상 · 핵심 · 내용 유교 · 인(仁)과 예(禮) · 인은 사람을 사랑하는 마음이고, 예는 그 마음을 바르게 드러내는 사회 규범이다. 공자는 사사로운 욕심을 이기고 예로 돌아가는 것(극기복례)이 ","keywords":["연기","무위자연"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-01","grade":"h2"},
{"id":"soc-h-ethics-01#c3","kind":"concept","title":"서양 윤리의 접근 — 의무론·공리주의·덕 윤리·배려 윤리","text":"서양의 규범 윤리 이론은 무엇을 기준으로 옳고 그름을 판단하는지에 따라 나뉩니다. 이론 · 대표 사상가 · 판단 기준 의무론 · 칸트 · 행위의 결과가 아니라 동기와 원칙. 의무에서 나온 행위만 도덕적 가치가 있다 공리주의 · 벤담, 밀 · 행위의 결과. 최대 다수의 최대 행복을 낳는 ","keywords":["정언 명령"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-01","grade":"h2"},
{"id":"soc-h-ethics-01#c4","kind":"concept","title":"사회사상의 접근 — 자유주의와 공동체주의","text":"윤리 문제 가운데에는 개인의 양심만으로 풀기 어려운 것이 많습니다. 빈곤, 차별, 불공정한 분배처럼 사회 제도와 구조에서 생기는 문제가 그렇습니다. 사회사상은 바람직한 사회의 모습을 그리고, 제도와 구조가 정당한지 묻습니다. 신학자 니부어는 개인이 아무리 도덕적이어도 집단은 이기적으로 ","keywords":["공동체주의"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-01","grade":"h2"},
{"id":"soc-h-ethics-01#c5","kind":"concept","title":"윤리적 탐구와 도덕 추론","text":"도덕 판단은 어떤 행위가 옳은지 그른지에 대한 판단입니다. 도덕 판단은 다음과 같은 도덕 추론으로 이끌어 냅니다. 단계 · 역할 · 예 도덕 원리 (대전제) · 일반적인 도덕 규범 · 남의 글을 허락 없이 베껴 자기 것처럼 내는 것은 옳지 않다 사실 판단 (소전제) · 구체적 상황에 대","keywords":["도덕 추론"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-01","grade":"h2"},
{"id":"soc-h-ethics-01#t0","kind":"term","title":"이론 윤리학","text":"옳고 그름을 판단하는 보편적인 도덕 원리를 세우고 정당화하는 윤리학입니다. 예: 의무론, 공리주의, 덕 윤리","keywords":["이론 윤리학"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-01","grade":"h2"},
{"id":"soc-h-ethics-01#t1","kind":"term","title":"실천 윤리학","text":"윤리 이론을 생명, 정보, 환경 같은 구체적인 현대의 문제에 적용해 해결책을 찾는 윤리학입니다. 여러 학문의 지식을 함께 쓰는 학제적 성격을 띱니다.","keywords":["실천 윤리학"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-01","grade":"h2"},
{"id":"soc-h-ethics-01#t2","kind":"term","title":"메타 윤리학","text":"도덕 언어의 의미와 도덕적 추론의 타당성을 분석하는 윤리학입니다. 예: \"선하다\"는 무엇을 뜻하는가?","keywords":["메타 윤리학"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-01","grade":"h2"},
{"id":"soc-h-ethics-01#t3","kind":"term","title":"기술 윤리학","text":"도덕 현상이나 풍습을 가치 판단 없이 있는 그대로 조사·기술하고 설명하는 윤리학입니다.","keywords":["기술 윤리학"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-01","grade":"h2"},
{"id":"soc-h-ethics-01#t4","kind":"term","title":"진화 윤리학","text":"이타심 같은 도덕성이 집단생활에 유리했기 때문에 진화 과정에서 자리 잡았다고 설명하는 도덕과학적 접근입니다.","keywords":["진화 윤리학"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-01","grade":"h2"},
{"id":"soc-h-ethics-01#t5","kind":"term","title":"연기","text":"모든 것은 서로 의존하여 생겨나고 사라진다는 불교의 가르침입니다. 이를 깨달으면 모든 생명에 자비를 베풀게 됩니다.","keywords":["연기"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-01","grade":"h2"},
{"id":"soc-h-ethics-01#t6","kind":"term","title":"무위자연","text":"억지로 꾸미는 인위를 버리고 자연의 흐름을 따르라는 도가의 가르침입니다.","keywords":["무위자연"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-01","grade":"h2"},
{"id":"soc-h-ethics-01#t7","kind":"term","title":"정언 명령","text":"칸트가 말한, 어떤 조건이나 결과와 상관없이 무조건 따라야 하는 도덕 명령입니다.","keywords":["정언 명령"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-01","grade":"h2"},
{"id":"soc-h-ethics-01#t8","kind":"term","title":"공동체주의","text":"개인은 공동체 속에서 정체성을 형성한다고 보고, 공동선과 공동체에 대한 책임을 중시하는 사회사상입니다.","keywords":["공동체주의"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-01","grade":"h2"},
{"id":"soc-h-ethics-01#t9","kind":"term","title":"도덕 추론","text":"도덕 원리(대전제)와 사실 판단(소전제)으로 도덕 판단(결론)을 이끌어 내는 과정입니다.","keywords":["도덕 추론"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-01","grade":"h2"},
{"id":"soc-h-ethics-01#f0","kind":"faq","title":"윤리와 도덕은 같은 말인가요?","text":"일상에서는 거의 같은 뜻으로 섞어 씁니다. 굳이 구별하면, 도덕은 개인이 지키려는 양심과 품성 쪽을, 윤리는 사람 사이의 관계에서 마땅히 따라야 할 이치와 규범 쪽을 더 강조하는 말로 쓰입니다. 윤리학은 이 둘을 모두 학문적으로 탐구합니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-01","grade":"h2"},
{"id":"soc-h-ethics-01#f1","kind":"faq","title":"공리주의는 다수의 행복을 위해 소수를 희생해도 된다는 건가요?","text":"공리주의는 그런 비판을 자주 받습니다. 행복의 총량만 따지면 소수의 권리가 무시될 수 있기 때문입니다. 밀은 이 문제를 의식해, 다른 사람에게 해를 끼치지 않는 한 개인의 자유를 간섭해서는 안 된다는 원칙을 함께 강조했습니다. 그래서 공리주의를 적용할 때도 개인의 권리와 정의를 함께 따져야 합니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-01","grade":"h2"},
{"id":"soc-h-ethics-01#f2","kind":"faq","title":"과학이 더 발달하면 윤리학은 필요 없어지지 않나요?","text":"과학은 \"무엇이 어떠한가\"를 밝히지만, \"무엇을 해야 하는가\"는 정해 주지 못합니다. 오히려 생명 복제나 인공지능처럼 과학이 발달할수록 새로운 윤리 문제가 생기므로 윤리학의 역할은 더 커집니다. 과학이 주는 사실은 도덕 추론의 사실 판단으로 쓰입니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-01","grade":"h2"},
{"id":"soc-h-ethics-01#m0","kind":"mistake","title":"자주 하는 실수","text":"메타 윤리학을 \"가장 높은 수준의 규범 윤리학\"으로 착각하는 실수 — 메타 윤리학은 옳고 그름을 직접 판단하지 않고 도덕 언어의 뜻과 추론의 타당성을 분석합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-01","grade":"h2"},
{"id":"soc-h-ethics-01#m1","kind":"mistake","title":"자주 하는 실수","text":"벤담과 밀을 바꾸어 기억하는 실수 — 쾌락의 양을 계산한 사람은 벤담, 쾌락의 질을 구별한 사람은 밀입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-01","grade":"h2"},
{"id":"soc-h-ethics-01#m2","kind":"mistake","title":"자주 하는 실수","text":"도덕 추론에서 결론(도덕 판단)을 전제 자리에 그대로 넣는 실수 — 도덕 원리는 결론보다 더 일반적인 규범이어야 합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-01","grade":"h2"},
{"id":"soc-h-ethics-02","kind":"unit","title":"삶과 죽음의 윤리","text":"삶과 죽음을 동서양 윤리의 입장에서 생각해 보고, 인공 임신 중절·생식 보조술·안락사·뇌사·생명 복제·동물 실험 같은 생명 윤리 문제를 여러 관점으로 따져 봅니다. 삶과 죽음에 대한 동서양 사상가의 관점을 비교하여 설명할 수 있다. 출생과 죽음에 관련된 생명 윤리 쟁점에서 찬반 입장의 근거를 정리할 수 있다. 생명 존중의 근거를 말하고, 어려울 때 도움을…","keywords":["윤회","해탈","인공 임신 중절","체외 수정","안락사","소극적 안락사","뇌사","연명 의료","생식세포 유전자 치료","3R 원칙"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-02","grade":"h2"},
{"id":"soc-h-ethics-02#c0","kind":"concept","title":"삶과 죽음에 대한 동양의 관점","text":"동양 사상은 죽음 자체보다 죽음을 어떻게 받아들이고 지금의 삶을 어떻게 살 것인가에 관심을 둡니다. 사상 · 죽음을 보는 관점 · 삶의 태도 유교 (공자) · 죽음보다 현재의 삶을 먼저 알아야 한다 · 인(仁)을 실천하며 도덕적으로 살고, 죽은 이에게는 예를 다한다 불교 · 죽음은 끝이","keywords":["윤회","해탈"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-02","grade":"h2"},
{"id":"soc-h-ethics-02#c1","kind":"concept","title":"삶과 죽음에 대한 서양의 관점","text":"서양 사상가들도 죽음을 어떻게 이해하느냐에 따라 삶의 태도를 다르게 제시했습니다. 사상가 · 죽음을 보는 관점 · 삶의 태도 플라톤 · 죽음은 불멸하는 영혼이 육체에서 벗어나 참된 세계(이데아)로 가는 것이다 · 영혼을 맑게 가꾸는 철학적 삶을 산다 에피쿠로스 · 죽음은 몸을 이루던 원","keywords":[],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-02","grade":"h2"},
{"id":"soc-h-ethics-02#c2","kind":"concept","title":"출생과 관련된 생명 윤리 — 인공 임신 중절과 생식 보조술","text":"인공 임신 중절은 태아가 엄마의 몸 밖에서는 살 수 없는 시기에 인위적으로 임신을 끝내는 것입니다. 이 쟁점의 핵심은 태아의 도덕적 지위와 여성의 자기 결정권이 부딪친다는 데 있습니다. 입장 · 주요 근거 허용해야 한다 · 여성은 자기 몸과 삶에 대해 스스로 결정할 권리가 있다. 태아는","keywords":["인공 임신 중절","체외 수정"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-02","grade":"h2"},
{"id":"soc-h-ethics-02#c3","kind":"concept","title":"죽음과 관련된 생명 윤리 — 안락사, 뇌사와 장기 이식","text":"안락사는 회복할 가능성이 없는 환자의 고통을 덜어 주기 위해 인위적으로 죽음에 이르게 하는 것입니다. 두 가지 기준으로 나눕니다. 기준 · 갈래 방법 · 적극적 안락사: 약물 투여 등으로 죽음을 직접 앞당긴다 / 소극적 안락사: 생명 유지에 필요한 치료를 하지 않거나 중단한다 환자의 의","keywords":["안락사","소극적 안락사","뇌사"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-02","grade":"h2"},
{"id":"soc-h-ethics-02#c4","kind":"concept","title":"자살 문제와 생명 존중","text":"동서양 윤리는 대부분 생명을 소중히 여기며 스스로 생명을 해치는 일을 그르다고 봅니다. 사상 · 생명 존중의 근거 유교 · 우리 몸은 부모에게서 받은 것이므로 함부로 상하게 하지 않는 것이 효의 시작이다 불교 · 자신을 포함한 모든 생명을 해치지 말라(불살생) 그리스도교 (아퀴나스) ·","keywords":[],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-02","grade":"h2"},
{"id":"soc-h-ethics-02#c5","kind":"concept","title":"생명 과학과 윤리 — 생명 복제, 유전자 치료, 동물 실험","text":"생명 과학의 발달은 질병 치료의 희망을 주지만 새로운 윤리 문제도 낳습니다. 생명 복제 동물 복제: 우수한 품종 보존, 멸종 위기종 복원에 쓸 수 있지만, 유전적 다양성이 줄고 복제 과정에서 동물이 고통받는다는 문제가 있습니다. 배아 복제: 복제 배아에서 줄기세포를 얻어 난치병 치료를 ","keywords":["생식세포 유전자 치료"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-02","grade":"h2"},
{"id":"soc-h-ethics-02#t0","kind":"term","title":"윤회","text":"생명이 죽은 뒤 자신이 지은 업(행위)에 따라 다른 삶으로 거듭 태어난다는 불교의 생각입니다.","keywords":["윤회"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-02","grade":"h2"},
{"id":"soc-h-ethics-02#t1","kind":"term","title":"해탈","text":"집착을 끊고 깨달음을 얻어 윤회의 괴로움에서 벗어나는 것입니다.","keywords":["해탈"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-02","grade":"h2"},
{"id":"soc-h-ethics-02#t2","kind":"term","title":"인공 임신 중절","text":"태아가 엄마의 몸 밖에서는 살 수 없는 시기에 인위적으로 임신을 끝내는 것입니다.","keywords":["인공 임신 중절"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-02","grade":"h2"},
{"id":"soc-h-ethics-02#t3","kind":"term","title":"체외 수정","text":"정자와 난자를 몸 밖에서 수정시켜 만든 배아를 자궁에 옮겨 임신하게 하는 생식 보조술입니다.","keywords":["체외 수정"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-02","grade":"h2"},
{"id":"soc-h-ethics-02#t4","kind":"term","title":"안락사","text":"회복 가능성이 없는 환자의 고통을 덜기 위해 인위적으로 죽음에 이르게 하는 것입니다. 방법에 따라 적극적·소극적으로 나눕니다.","keywords":["안락사"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-02","grade":"h2"},
{"id":"soc-h-ethics-02#t5","kind":"term","title":"소극적 안락사","text":"생명 유지에 필요한 치료를 하지 않거나 중단하여 죽음에 이르게 하는 것입니다.","keywords":["소극적 안락사"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-02","grade":"h2"},
{"id":"soc-h-ethics-02#t6","kind":"term","title":"뇌사","text":"뇌 전체의 기능이 회복할 수 없게 멈춘 상태입니다. 스스로 숨 쉬지 못한다는 점에서 식물인간 상태와 다릅니다.","keywords":["뇌사"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-02","grade":"h2"},
{"id":"soc-h-ethics-02#t7","kind":"term","title":"연명 의료","text":"임종 과정에 있는 환자에게 치료 효과 없이 생명만 이어 가게 하는 의료(심폐 소생술, 인공호흡기 착용 등)입니다.","keywords":["연명 의료"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-02","grade":"h2"},
{"id":"soc-h-ethics-02#t8","kind":"term","title":"생식세포 유전자 치료","text":"정자·난자 같은 생식세포의 유전자를 바꾸는 치료입니다. 바뀐 유전자가 후손에게 전해집니다.","keywords":["생식세포 유전자 치료"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-02","grade":"h2"},
{"id":"soc-h-ethics-02#t9","kind":"term","title":"3R 원칙","text":"동물 실험을 할 때 지켜야 할 대체(다른 방법으로 바꾸기), 감소(수 줄이기), 개선(고통 줄이기)의 원칙입니다.","keywords":["3R 원칙"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-02","grade":"h2"},
{"id":"soc-h-ethics-02#f0","kind":"faq","title":"안락사와 연명 의료 중단은 같은 건가요?","text":"비슷해 보이지만 구별해서 씁니다. 우리나라의 연명 의료 중단은 회생 가능성이 없고 임종 과정에 있는 환자가 법에 정한 절차를 거쳐 효과 없는 연명 의료만 받지 않는 것입니다. 통증 완화 같은 기본 돌봄은 계속합니다. 약물로 죽음을 직접 앞당기는 적극적 안락사와는 다릅니다.","keywords":["안락사","연명 의료"],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-02","grade":"h2"},
{"id":"soc-h-ethics-02#f1","kind":"faq","title":"뇌사와 식물인간은 어떻게 달라요?","text":"뇌사는 뇌간을 포함한 뇌 전체의 기능이 회복할 수 없게 멈춘 상태로, 인공호흡기 없이는 숨을 쉬지 못합니다. 식물인간 상태는 대뇌의 기능이 크게 손상되었지만 뇌간이 살아 있어 스스로 숨 쉴 수 있고, 드물게 회복하기도 합니다. 식물인간 상태인 사람은 살아 있는 환자이므로 뇌사자처럼 장기 기증의 대상이 되지 않습니다.","keywords":["뇌사"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-02","grade":"h2"},
{"id":"soc-h-ethics-02#f2","kind":"faq","title":"마음이 너무 힘들 때는 어떻게 해야 하나요?","text":"혼자 견디지 않아도 됩니다. 가족, 선생님, 믿을 수 있는 어른에게 지금의 마음을 이야기해 보세요. 말하기 어렵다면 자살예방상담전화 109(24시간)나 청소년상담전화 1388에 전화하면 전문 상담을 받을 수 있습니다. 친구가 힘들어 보일 때도 이야기를 들어 주고, 어른이나 전문가에게 꼭 알려 주세요.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-02","grade":"h2"},
{"id":"soc-h-ethics-02#m0","kind":"mistake","title":"자주 하는 실수","text":"뇌사와 식물인간 상태를 같은 것으로 아는 실수 — 뇌사는 스스로 숨 쉬지 못하고 회복할 수 없으며, 식물인간 상태는 뇌간이 살아 있어 스스로 숨 쉴 수 있습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-02","grade":"h2"},
{"id":"soc-h-ethics-02#m1","kind":"mistake","title":"자주 하는 실수","text":"안락사를 나누는 두 기준을 섞는 실수 — 적극적·소극적은 \"방법\"의 기준이고, 자발적·반자발적·비자발적은 \"환자의 의사\"의 기준입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-02","grade":"h2"},
{"id":"soc-h-ethics-02#m2","kind":"mistake","title":"자주 하는 실수","text":"체세포와 생식세포 유전자 치료를 거꾸로 기억하는 실수 — 후손에게 전해지는 것은 생식세포 유전자 치료입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-02","grade":"h2"},
{"id":"soc-h-ethics-03","kind":"unit","title":"사랑과 성, 가족의 윤리","text":"사랑과 성에 관한 여러 입장과 성차별·성 상품화 문제를 이해하고, 결혼과 가족 안에서 지켜야 할 윤리와 현대 가족의 변화를 생각해 봅니다. 프롬이 말한 사랑의 요소를 설명하고 성숙한 사랑의 모습을 말할 수 있다. 성의 가치와 성에 대한 보수주의·중도주의·자유주의의 입장을 비교할 수 있다. 성차별과 성 상품화의 문제를 알고 양성평등의 의미를 설명할 수 있다…","keywords":["사랑의 네 요소","성의 인격적 가치","보수주의 (성 윤리)","중도주의 (성 윤리)","자유주의 (성 윤리)","성 상품화","양성평등","부부유별","부자자효","형우제공"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-03","grade":"h2"},
{"id":"soc-h-ethics-03#c0","kind":"concept","title":"사랑의 의미와 요소 — 프롬","text":"사랑은 다른 존재를 아끼고 그와 함께하며 그의 행복을 바라는 마음과 행동입니다. 유교의 인(仁), 불교의 자비처럼 동양 사상도 남을 아끼는 마음을 도덕의 중심에 두었습니다. 사회 심리학자 프롬은 사랑을 우연히 \"빠지는\" 감정이 아니라, 배우고 노력해서 익혀야 하는 기술이자 능동적인 활동","keywords":[],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-03","grade":"h2"},
{"id":"soc-h-ethics-03#c1","kind":"concept","title":"성의 가치와 성에 대한 입장","text":"성(性)은 생물학적 특징만이 아니라 인간의 정체성과 관계에 관련된 중요한 영역입니다. 성에는 다음과 같은 가치가 있습니다. 생식적 가치: 새로운 생명을 낳아 인류를 이어 가게 한다. 쾌락적 가치: 감각적인 즐거움과 만족을 준다. 인격적 가치: 사랑하는 사람과 인격적으로 교감하고 사랑을 ","keywords":[],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-03","grade":"h2"},
{"id":"soc-h-ethics-03#c2","kind":"concept","title":"성차별과 성 상품화, 양성평등","text":"성차별은 성별을 이유로 사람을 부당하게 대우하는 것입니다. \"남자는 ~해야 한다\", \"여자는 ~해야 한다\" 같은 성 역할 고정관념은 개인이 자기 능력과 개성을 펼칠 기회를 빼앗고 차별을 낳습니다. 성 상품화는 성 자체를 사고팔거나, 상품을 팔기 위한 수단으로 성적 매력을 이용하는 것입니","keywords":["성 상품화","양성평등"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-03","grade":"h2"},
{"id":"soc-h-ethics-03#c3","kind":"concept","title":"결혼의 윤리적 의미와 부부 윤리","text":"결혼은 사랑하는 두 사람이 부부가 되어 법적·사회적으로 인정받는 공동의 삶을 시작하는 것입니다. 결혼은 다음과 같은 윤리적 의미를 지닙니다. 사랑을 바탕으로 한 인격적 결합이다. 서로에게, 그리고 태어날 자녀에게 책임을 지겠다는 약속이다. 사회의 기초 단위인 가족을 이루는 출발점이다. ","keywords":["부부유별"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-03","grade":"h2"},
{"id":"soc-h-ethics-03#c4","kind":"concept","title":"현대 가족의 변화와 가족 윤리","text":"가족은 결혼, 혈연, 입양 등으로 맺어져 함께 생활하며 서로 돌보는 공동체입니다. 부모와 자녀의 윤리 — 부자자효(父慈子孝): 부모는 자녀를 자애로 대하고, 자녀는 부모에게 효를 다한다. 자애: 자녀를 사랑으로 기르고, 한 인격체로 존중하며 바르게 이끈다. 효: 부모를 공경하고 받들며,","keywords":["부자자효","형우제공"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-03","grade":"h2"},
{"id":"soc-h-ethics-03#t0","kind":"term","title":"사랑의 네 요소","text":"프롬이 말한 성숙한 사랑의 요소로, 보호·책임·존경·이해입니다.","keywords":["사랑의 네 요소"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-03","grade":"h2"},
{"id":"soc-h-ethics-03#t1","kind":"term","title":"성의 인격적 가치","text":"성이 사랑하는 사람과 인격적으로 교감하고 사랑을 표현하는 수단이 된다는 가치입니다.","keywords":["성의 인격적 가치"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-03","grade":"h2"},
{"id":"soc-h-ethics-03#t2","kind":"term","title":"보수주의 (성 윤리)","text":"성적 관계는 결혼한 부부 사이에서만 정당하다고 보는 입장입니다.","keywords":["보수주의 (성 윤리)"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-03","grade":"h2"},
{"id":"soc-h-ethics-03#t3","kind":"term","title":"중도주의 (성 윤리)","text":"결혼 여부보다 사랑이 함께할 때 성적 관계가 정당하다고 보는 입장입니다.","keywords":["중도주의 (성 윤리)"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-03","grade":"h2"},
{"id":"soc-h-ethics-03#t4","kind":"term","title":"자유주의 (성 윤리)","text":"성인이 자발적으로 동의하고 남에게 해를 끼치지 않는다면 성적 관계를 허용할 수 있다고 보는 입장입니다.","keywords":["자유주의 (성 윤리)"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-03","grade":"h2"},
{"id":"soc-h-ethics-03#t5","kind":"term","title":"성 상품화","text":"성 자체를 사고팔거나, 상품을 팔기 위한 수단으로 성적 매력을 이용하는 것입니다.","keywords":["성 상품화"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-03","grade":"h2"},
{"id":"soc-h-ethics-03#t6","kind":"term","title":"양성평등","text":"남녀가 성별 때문에 차별받지 않고 동등한 권리와 기회, 책임을 누리는 것입니다. 차이를 인정하되 차별하지 않는 것입니다.","keywords":["양성평등"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-03","grade":"h2"},
{"id":"soc-h-ethics-03#t7","kind":"term","title":"부부유별","text":"남편과 아내 사이에 구별이 있다는 전통 윤리입니다. 오늘날에는 서로의 고유한 역할과 인격을 존중하라는 뜻으로 해석합니다.","keywords":["부부유별"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-03","grade":"h2"},
{"id":"soc-h-ethics-03#t8","kind":"term","title":"부자자효","text":"부모는 자녀를 자애로 대하고, 자녀는 부모에게 효를 다해야 한다는 가족 윤리입니다.","keywords":["부자자효"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-03","grade":"h2"},
{"id":"soc-h-ethics-03#t9","kind":"term","title":"형우제공","text":"형은 아우를 사랑하고 아우는 형을 공경해야 한다는 형제자매의 윤리입니다.","keywords":["형우제공"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-03","grade":"h2"},
{"id":"soc-h-ethics-03#f0","kind":"faq","title":"좋아하는 마음과 사랑은 어떻게 다른가요?","text":"좋아하는 마음은 상대에게 끌리는 감정에서 시작합니다. 프롬에 따르면 사랑은 그 감정에 머무르지 않고, 상대를 돌보고(보호), 요구에 응답하고(책임), 있는 그대로 인정하고(존경), 깊이 알려는(이해) 능동적인 활동으로 이어집니다. 그래서 사랑은 배우고 노력해야 하는 것입니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-03","grade":"h2"},
{"id":"soc-h-ethics-03#f1","kind":"faq","title":"양성평등이면 남녀를 모든 면에서 똑같이 대해야 하나요?","text":"양성평등은 생물학적 차이를 없애자는 것이 아니라, 그 차이를 이유로 차별하지 말자는 것입니다. 예를 들어 임신과 출산을 고려한 배려는 차이를 인정한 것이고, 같은 일을 하는데 성별 때문에 임금을 다르게 주는 것은 차별입니다.","keywords":["양성평등"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-03","grade":"h2"},
{"id":"soc-h-ethics-03#f2","kind":"faq","title":"효도는 부모님 말씀을 무조건 따르는 건가요?","text":"그렇지 않습니다. 유교에서도 부모에게 잘못이 있으면 공손하게 말씀드려 바로잡도록 하는 것을 효의 하나로 보았습니다. 효는 부모를 공경하고, 자기 몸을 아끼며 바르게 살아 부모를 기쁘게 하는 것까지 포함합니다. 부모 역시 자녀를 한 인격체로 존중하는 자애를 실천해야 합니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-03","grade":"h2"},
{"id":"soc-h-ethics-03#m0","kind":"mistake","title":"자주 하는 실수","text":"프롬의 사랑의 요소 가운데 \"존경\"과 \"이해\"를 헷갈리는 실수 — 상대를 있는 그대로 인정하고 이용하지 않는 것은 존경, 상대를 깊이 아는 것은 이해입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-03","grade":"h2"},
{"id":"soc-h-ethics-03#m1","kind":"mistake","title":"자주 하는 실수","text":"성에 대한 입장을 조건으로 구별하지 못하는 실수 — 결혼이면 보수주의, 사랑이면 중도주의, 자발적 동의와 해악 없음이면 자유주의입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-03","grade":"h2"},
{"id":"soc-h-ethics-03#m2","kind":"mistake","title":"자주 하는 실수","text":"부부유별을 성 역할 고정이나 차별의 뜻으로만 읽는 실수 — 오늘날에는 서로의 고유한 역할과 인격을 존중하라는 뜻으로 해석합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-03","grade":"h2"},
{"id":"soc-h-ethics-04","kind":"unit","title":"자연과 생태 윤리","text":"자연을 바라보는 서양의 인간 중심주의·동물 중심주의·생명 중심주의·생태 중심주의와 동양의 자연관을 비교하고, 기후 정의·미래 세대에 대한 책임·개발과 보전 같은 환경 쟁점을 윤리적으로 따져 봅니다. 인간 중심주의, 동물 중심주의, 생명 중심주의, 생태 중심주의의 주장과 한계를 비교할 수 있다. 유교·불교·도가의 자연관을 설명하고 서양의 자연관과 견줄 수 …","keywords":["인간 중심주의","쾌고 감수 능력","종 차별주의","삶의 주체","생명 외경","대지 윤리","심층 생태주의","천인합일","기후 정의","지속 가능한 발전"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-04","grade":"h2"},
{"id":"soc-h-ethics-04#c0","kind":"concept","title":"인간 중심주의 자연관","text":"인간 중심주의는 인간만이 도덕적으로 고려할 대상이고, 자연은 인간의 필요를 채워 주는 도구적 가치를 지닐 뿐이라고 보는 자연관입니다. 인간과 자연을 나누어 보는 이분법적 세계관이 그 바탕에 있습니다. 사상가 · 주장 아리스토텔레스 · 식물은 동물을 위해, 동물은 인간을 위해 존재한다 베","keywords":["인간 중심주의"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-04","grade":"h2"},
{"id":"soc-h-ethics-04#c1","kind":"concept","title":"동물 중심주의 — 싱어와 레건","text":"동물 중심주의는 도덕적 고려의 범위를 인간에서 동물까지 넓힌 입장입니다. 싱어는 공리주의에 바탕을 둡니다. 쾌락과 고통을 느낄 수 있는 능력, 곧 쾌고 감수 능력이 있는 존재라면 그 이익을 똑같이 고려해야 한다는 이익 평등 고려의 원칙을 내세웠습니다. 인간이라는 종에 속한다는 이유만으로","keywords":["쾌고 감수 능력","종 차별주의","삶의 주체"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-04","grade":"h2"},
{"id":"soc-h-ethics-04#c2","kind":"concept","title":"생명 중심주의 — 슈바이처와 테일러","text":"생명 중심주의는 도덕적 고려의 범위를 모든 생명체로 넓힙니다. 고통을 느끼는지가 아니라 살아 있다는 것 자체를 근거로 삼으므로 식물과 미생물도 포함됩니다. 슈바이처는 생명 외경 사상을 펼쳤습니다. 모든 생명은 살려는 의지를 지닌 신성한 것이므로 경외해야 한다고 보았습니다. 생명을 보존하","keywords":["생명 외경"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-04","grade":"h2"},
{"id":"soc-h-ethics-04#c3","kind":"concept","title":"생태 중심주의 — 대지 윤리와 심층 생태주의","text":"생태 중심주의는 개별 생명체를 넘어 생태계 전체를 도덕적 고려의 대상으로 봅니다. 개체보다 개체들이 맺는 관계와 전체를 중시하므로 전체론(전일론)적 관점이라고 합니다. 레오폴드는 대지 윤리를 주장했습니다. 도덕 공동체의 범위를 흙, 물, 식물, 동물을 모두 포함하는 대지로 넓혀야 한다.","keywords":["대지 윤리","심층 생태주의"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-04","grade":"h2"},
{"id":"soc-h-ethics-04#c4","kind":"concept","title":"동양의 자연관 — 유교·불교·도가","text":"동양 사상은 대체로 인간을 자연의 일부로 보고, 자연과의 조화와 공존을 추구합니다. 인간과 자연을 하나의 유기적 전체로 본다는 점에서 서양의 인간 중심주의와 다릅니다. 사상 · 핵심 · 자연을 대하는 태도 유교 · 천인합일(天人合一) · 하늘(자연의 이치)과 인간이 본래 하나라고 보고,","keywords":["인간 중심주의","천인합일"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-04","grade":"h2"},
{"id":"soc-h-ethics-04#c5","kind":"concept","title":"환경 문제의 윤리적 쟁점","text":"오늘날 환경 문제는 한 지역을 넘어 지구 전체, 그리고 미래 세대에까지 영향을 미칩니다. 그래서 누가 책임을 지고, 부담과 혜택을 어떻게 나눌 것인가라는 정의의 문제가 됩니다. 기후 정의 온실가스는 산업화를 일찍 이룬 선진국이 오랫동안 많이 배출했지만, 해수면 상승·가뭄·폭염 같은 피해","keywords":["기후 정의"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-04","grade":"h2"},
{"id":"soc-h-ethics-04#t0","kind":"term","title":"인간 중심주의","text":"인간만이 도덕적 고려의 대상이고, 자연은 인간을 위한 도구적 가치를 지닌다고 보는 자연관입니다. 예: 베이컨, 데카르트, 칸트","keywords":["인간 중심주의"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-04","grade":"h2"},
{"id":"soc-h-ethics-04#t1","kind":"term","title":"쾌고 감수 능력","text":"쾌락과 고통을 느낄 수 있는 능력입니다. 싱어는 이 능력이 있는 존재라면 그 이익을 평등하게 고려해야 한다고 보았습니다.","keywords":["쾌고 감수 능력"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-04","grade":"h2"},
{"id":"soc-h-ethics-04#t2","kind":"term","title":"종 차별주의","text":"인간이라는 종에 속한다는 이유만으로 다른 종의 이익을 무시하는 태도입니다. 싱어가 비판했습니다.","keywords":["종 차별주의"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-04","grade":"h2"},
{"id":"soc-h-ethics-04#t3","kind":"term","title":"삶의 주체","text":"믿음, 욕구, 기억, 미래에 대한 감각을 지닌 존재입니다. 레건은 삶의 주체인 동물이 내재적 가치와 권리를 지닌다고 보았습니다.","keywords":["삶의 주체"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-04","grade":"h2"},
{"id":"soc-h-ethics-04#t4","kind":"term","title":"생명 외경","text":"모든 생명은 살려는 의지를 지닌 신성한 것이므로 경외해야 한다는 슈바이처의 사상입니다.","keywords":["생명 외경"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-04","grade":"h2"},
{"id":"soc-h-ethics-04#t5","kind":"term","title":"대지 윤리","text":"도덕 공동체의 범위를 흙, 물, 식물, 동물을 포함한 대지로 넓혀야 한다는 레오폴드의 윤리입니다.","keywords":["대지 윤리"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-04","grade":"h2"},
{"id":"soc-h-ethics-04#t6","kind":"term","title":"심층 생태주의","text":"인간 중심적 세계관을 근본부터 바꾸어 큰 자아실현과 생명 중심적 평등에 이르러야 한다는 네스의 생태 사상입니다.","keywords":["심층 생태주의"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-04","grade":"h2"},
{"id":"soc-h-ethics-04#t7","kind":"term","title":"천인합일","text":"하늘(자연의 이치)과 인간이 본래 하나라고 보는 유교의 이상입니다.","keywords":["천인합일"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-04","grade":"h2"},
{"id":"soc-h-ethics-04#t8","kind":"term","title":"기후 정의","text":"기후 변화의 책임과 피해가 어긋나 있으므로, 이를 공정하게 바로잡자는 요구입니다.","keywords":["기후 정의"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-04","grade":"h2"},
{"id":"soc-h-ethics-04#t9","kind":"term","title":"지속 가능한 발전","text":"미래 세대가 자신의 필요를 충족할 능력을 해치지 않으면서 현재 세대의 필요를 충족하는 발전입니다.","keywords":["지속 가능한 발전"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-04","grade":"h2"},
{"id":"soc-h-ethics-04#f0","kind":"faq","title":"식물은 고통을 못 느낀다는데 왜 존중해야 하나요?","text":"입장마다 답이 다릅니다. 싱어는 쾌고 감수 능력을 기준으로 삼으므로 식물을 직접적인 도덕적 고려 대상으로 보지 않습니다. 반면 슈바이처와 테일러는 고통을 느끼는지가 아니라, 생명체가 스스로 자라고 번식하며 살아가려 한다는 점 자체를 존중의 근거로 삼습니다. 생태 중심주의는 식물이 생태계 전체의 균형을 이루는 중요한 구성원이라는 점을 강조합니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-04","grade":"h2"},
{"id":"soc-h-ethics-04#f1","kind":"faq","title":"동물 중심주의대로라면 고기를 먹으면 안 되나요?","text":"이것도 입장에 따라 다릅니다. 싱어는 동물에게 큰 고통을 주는 공장식 사육을 비판하고 채식을 권했고, 레건은 상업적 목축 자체를 없애야 한다고 보았습니다. 한편 고기를 먹는 것은 인정하되 사육 환경을 개선해 동물의 고통을 줄이자는 동물 복지의 관점도 있습니다. 각 입장의 근거를 따져 보고 스스로 판단해 보는 것이 이 단원의 목표입니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-04","grade":"h2"},
{"id":"soc-h-ethics-04#f2","kind":"faq","title":"나 혼자 환경을 지킨다고 정말 달라지나요?","text":"한 사람의 실천은 작아 보여도, 많은 사람이 함께하면 소비가 바뀌고 기업과 정책도 달라집니다. 또 생활 속 실천은 환경 문제에 대한 관심을 키워 제도 개선에 참여하는 바탕이 됩니다. 다만 개인의 노력만으로는 부족하므로, 기후 정의처럼 나라와 사회 차원의 책임 있는 제도도 함께 요구해야 합니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-04","grade":"h2"},
{"id":"soc-h-ethics-04#m0","kind":"mistake","title":"자주 하는 실수","text":"싱어와 레건을 바꾸어 기억하는 실수 — 공리주의·쾌고 감수 능력·이익의 평등한 고려는 싱어, 의무론·삶의 주체·동물의 권리는 레건입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-04","grade":"h2"},
{"id":"soc-h-ethics-04#m1","kind":"mistake","title":"자주 하는 실수","text":"칸트가 동물을 아무렇게나 대해도 된다고 보았다고 아는 실수 — 칸트는 동물에 대한 직접적 의무는 없지만, 동물을 잔인하게 대하지 말아야 할 간접적 의무가 있다고 보았습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-04","grade":"h2"},
{"id":"soc-h-ethics-04#m2","kind":"mistake","title":"자주 하는 실수","text":"생명 중심주의와 생태 중심주의를 헷갈리는 실수 — 생명 중심주의는 개별 생명체 하나하나를, 생태 중심주의는 흙과 물까지 포함한 생태계 전체를 도덕적 고려의 대상으로 봅니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-04","grade":"h2"},
{"id":"soc-h-ethics-05","kind":"unit","title":"과학 기술과 윤리","text":"과학 기술이 가치 중립적인가를 둘러싼 논쟁과 과학 기술 지상주의·혐오주의의 문제를 살펴보고, 과학 기술자의 내적·외적 책임, 요나스의 책임 윤리, 기술 영향 평가와 시민 참여 같은 사회적 통제 방안을 사례에 적용해 봅니다. 과학 기술의 가치 중립성을 주장하는 입장과 반대하는 입장을 근거와 함께 비교할 수 있다. 과학 기술 지상주의와 과학 기술 혐오주의의 …","keywords":["가치 중립성","과학 기술 지상주의","과학 기술 혐오주의","연구 윤리","위조","변조","표절","책임 윤리","기술 영향 평가","합의 회의"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-05","grade":"h2"},
{"id":"soc-h-ethics-05#c0","kind":"concept","title":"과학 기술의 가치 중립성 논쟁","text":"가치 중립성이란 어떤 활동이 옳고 그름이나 좋고 나쁨 같은 가치 판단에서 벗어나 있다는 뜻입니다. 과학 기술이 가치 중립적인지를 두고 두 입장이 맞섭니다. 구분 · 가치 중립성을 인정하는 입장 · 가치 중립성을 부정하는 입장 핵심 주장 · 과학 기술은 사실을 발견하고 설명할 뿐이다 · ","keywords":["가치 중립성"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-05","grade":"h2"},
{"id":"soc-h-ethics-05#c1","kind":"concept","title":"과학 기술 지상주의와 과학 기술 혐오주의","text":"과학 기술을 대하는 극단적인 두 태도가 있습니다. 과학 기술 지상주의(과학 기술 만능주의): 과학 기술이 인간과 사회의 모든 문제를 해결할 수 있다고 믿고, 과학적으로 검증된 지식만을 참된 지식으로 여깁니다. 문제점: 과학 기술이 낳는 부작용(환경 오염, 생명 경시, 인간 소외)을 가볍","keywords":["과학 기술 지상주의","과학 기술 혐오주의"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-05","grade":"h2"},
{"id":"soc-h-ethics-05#c2","kind":"concept","title":"과학 기술자의 책임: 내적 책임과 외적 책임","text":"과학 기술자는 전문 지식을 가진 사람으로서 두 가지 책임을 집니다. 1. 내적 책임(연구 윤리): 연구 과정 자체를 정직하고 공정하게 수행할 책임입니다. 대표적인 연구 부정행위는 다음과 같습니다. 부정행위 · 뜻 위조 · 존재하지 않는 자료나 결과를 만들어 내는 것 변조 · 연구 자료나","keywords":["연구 윤리","위조","변조","표절"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-05","grade":"h2"},
{"id":"soc-h-ethics-05#c3","kind":"concept","title":"요나스의 책임 윤리","text":"독일 출신의 철학자 요나스는 현대 과학 기술의 힘이 너무 커졌기 때문에 새로운 윤리가 필요하다고 보았습니다. 전통 윤리의 한계: 지금까지의 윤리는 주로 같은 시대를 사는 가까운 사람 사이의 관계, 그리고 행위의 가까운 결과만 다루었습니다. 서로 의무를 주고받는 상호적 관계가 중심이었습니","keywords":["책임 윤리"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-05","grade":"h2"},
{"id":"soc-h-ethics-05#c4","kind":"concept","title":"과학 기술의 사회적 통제와 시민 참여","text":"과학 기술은 전문가만의 일이 아니라 모든 시민의 삶에 영향을 줍니다. 그래서 과학 기술이 바람직한 방향으로 발전하도록 사회가 통제할 장치가 필요합니다. 기술 영향 평가: 새로운 기술이 널리 쓰이기 전에 그 기술이 경제·사회·문화·윤리·환경에 미칠 영향을 미리 분석하고 평가하여, 부정적인","keywords":["연구 윤리","기술 영향 평가","합의 회의"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-05","grade":"h2"},
{"id":"soc-h-ethics-05#t0","kind":"term","title":"가치 중립성","text":"어떤 활동이 옳고 그름 같은 가치 판단에서 벗어나 있다는 성질입니다. 과학 기술이 가치 중립적인가를 두고 논쟁이 있습니다.","keywords":["가치 중립성"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-05","grade":"h2"},
{"id":"soc-h-ethics-05#t1","kind":"term","title":"과학 기술 지상주의","text":"과학 기술이 모든 문제를 해결할 수 있다고 믿는 태도입니다. 부작용을 가볍게 보고 인간의 가치를 무시하기 쉽다는 비판을 받습니다.","keywords":["과학 기술 지상주의"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-05","grade":"h2"},
{"id":"soc-h-ethics-05#t2","kind":"term","title":"과학 기술 혐오주의","text":"과학 기술이 인간 소외와 자연 파괴를 낳는다고 보아 과학 기술 자체를 거부하는 태도입니다. 과학 기술의 혜택을 외면한다는 비판을 받습니다.","keywords":["과학 기술 혐오주의"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-05","grade":"h2"},
{"id":"soc-h-ethics-05#t3","kind":"term","title":"연구 윤리","text":"연구를 정직하고 공정하게 수행하기 위해 연구자가 지켜야 할 원칙입니다. 위조·변조·표절·부당한 저자 표시를 금지합니다.","keywords":["연구 윤리"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-05","grade":"h2"},
{"id":"soc-h-ethics-05#t4","kind":"term","title":"위조","text":"존재하지 않는 연구 자료나 결과를 만들어 내는 연구 부정행위입니다.","keywords":["위조"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-05","grade":"h2"},
{"id":"soc-h-ethics-05#t5","kind":"term","title":"변조","text":"연구 자료나 과정을 임의로 바꾸거나 삭제하여 결과를 왜곡하는 연구 부정행위입니다.","keywords":["변조"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-05","grade":"h2"},
{"id":"soc-h-ethics-05#t6","kind":"term","title":"표절","text":"다른 사람의 아이디어·문장·자료를 출처를 밝히지 않고 자기 것처럼 쓰는 행위입니다.","keywords":["표절"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-05","grade":"h2"},
{"id":"soc-h-ethics-05#t7","kind":"term","title":"책임 윤리","text":"요나스가 제시한 윤리로, 과학 기술 시대에 책임의 범위를 미래 세대와 자연까지 넓혀야 한다고 봅니다.","keywords":["책임 윤리"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-05","grade":"h2"},
{"id":"soc-h-ethics-05#t8","kind":"term","title":"기술 영향 평가","text":"새로운 기술이 사회·경제·환경 등에 미칠 영향을 미리 평가하여 부정적 영향을 줄이는 방안을 찾는 제도입니다.","keywords":["기술 영향 평가"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-05","grade":"h2"},
{"id":"soc-h-ethics-05#t9","kind":"term","title":"합의 회의","text":"일반 시민 패널이 전문가의 설명을 듣고 토론하여 과학 기술 쟁점에 대한 의견을 모으는 시민 참여 방식입니다.","keywords":["합의 회의"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-05","grade":"h2"},
{"id":"soc-h-ethics-05#f0","kind":"faq","title":"과학 기술이 가치 중립적이라면 과학자는 아무 책임도 없나요?","text":"그렇지 않습니다. 가치 중립성을 인정하는 입장도 대개 연구 과정의 객관성을 강조하는 것이지, 연구자가 정직하게 연구할 책임(연구 윤리)까지 없다고 보지는 않습니다. 또 오늘날에는 연구 결과의 활용과 사회적 영향에 대해서도 과학자가 책임을 나누어 져야 한다는 생각이 널리 받아들여집니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-05","grade":"h2"},
{"id":"soc-h-ethics-05#f1","kind":"faq","title":"요나스는 왜 \"두려움\"을 강조했나요? 겁을 내면 발전을 못 하지 않나요?","text":"요나스가 말한 두려움은 무작정 겁내는 것이 아니라, 되돌릴 수 없는 피해를 막기 위해 나쁜 가능성을 먼저 따져 보는 신중함입니다. 현대 기술은 한번 잘못되면 인류 전체와 자연에 회복할 수 없는 결과를 낳을 수 있기 때문에, 불확실할 때는 낙관보다 신중이 앞서야 한다는 것입니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-05","grade":"h2"},
{"id":"soc-h-ethics-05#f2","kind":"faq","title":"위조와 변조는 어떻게 구별하나요?","text":"처음부터 없던 것을 만들어 냈다면 위조, 실제로 있던 자료를 바꾸거나 빼서 결과를 왜곡했다면 변조입니다. 예를 들어 하지 않은 실험의 결과를 지어내면 위조, 실제 측정값 중 불리한 값을 지우면 변조입니다.","keywords":["위조","변조"],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-05","grade":"h2"},
{"id":"soc-h-ethics-05#m0","kind":"mistake","title":"자주 하는 실수","text":"가치 중립성을 부정하는 입장을 과학 기술 혐오주의와 같은 것으로 보는 실수 — 가치 중립성을 부정한다고 기술을 거부하는 것은 아닙니다. 연구 단계부터 윤리적 검토가 필요하다는 뜻입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-05","grade":"h2"},
{"id":"soc-h-ethics-05#m1","kind":"mistake","title":"자주 하는 실수","text":"연구 결과의 사회적 영향에 대한 책임을 내적 책임으로 분류하는 실수 — 연구 과정의 정직성은 내적 책임, 사회와 자연에 미칠 영향에 대한 책임은 외적(사회적) 책임입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-05","grade":"h2"},
{"id":"soc-h-ethics-05#m2","kind":"mistake","title":"자주 하는 실수","text":"요나스의 책임을 서로 주고받는 상호적 책임으로 이해하는 실수 — 미래 세대와 자연은 보답할 수 없으므로 요나스의 책임은 비상호적 책임입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-05","grade":"h2"},
{"id":"soc-h-ethics-06","kind":"unit","title":"정보 사회와 인공지능 윤리","text":"저작권 침해·사생활 침해·사이버 폭력 같은 정보 사회의 윤리 문제와 지적 재산권을 보는 두 관점(정보 공유론·정보 사유론), 뉴미디어 시대의 미디어 윤리를 살펴봅니다. 이어서 인공지능의 도덕적 지위와 책임 문제, 인공지능 윤리 가이드라인이 강조하는 책임성·투명성·편향성 문제와 해결 방안을 알아봅니다. 정보 사회의 윤리 문제(저작권 침해, 사생활 침해, 사…","keywords":["저작권","사이버 폭력","정보 사유론","정보 공유론","카피레프트","미디어 문해력","알 권리","확증 편향","도덕적 행위자","알고리즘 편향"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-06","grade":"h2"},
{"id":"soc-h-ethics-06#c0","kind":"concept","title":"정보 사회의 윤리 문제","text":"정보 통신 기술 덕분에 누구나 쉽게 정보를 만들고 나눌 수 있게 되었습니다. 그러나 정보 사회의 몇 가지 특성은 새로운 윤리 문제를 낳습니다. 쉬운 복제와 빠른 확산: 디지털 정보는 원본과 똑같이 복제되고 순식간에 퍼집니다. 익명성과 비대면성: 얼굴을 마주하지 않고 이름을 감출 수 있어","keywords":["저작권","사이버 폭력"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-06","grade":"h2"},
{"id":"soc-h-ethics-06#c1","kind":"concept","title":"정보 공유론과 정보 사유론","text":"소설·음악·소프트웨어 같은 창작물에 대한 권리를 지적 재산권이라고 합니다. 이 권리를 얼마나 보호해야 하는지를 두고 두 관점이 있습니다. 구분 · 정보 사유론 · 정보 공유론 핵심 주장 · 정보는 만든 사람의 노력의 결과이므로 그 사람의 소유이다 · 정보는 인류가 함께 쌓아 온 공동의 ","keywords":["저작권","정보 사유론","정보 공유론","카피레프트"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-06","grade":"h2"},
{"id":"soc-h-ethics-06#c2","kind":"concept","title":"뉴미디어와 미디어 윤리","text":"누리 소통망, 영상 공유 서비스, 1인 방송처럼 디지털 기술로 정보를 주고받는 매체를 뉴미디어라고 합니다. 뉴미디어에서는 누구나 정보의 소비자이면서 생산자가 되고, 정보가 쌍방향으로 빠르게 퍼집니다. 1. 미디어 문해력: 미디어가 전하는 정보를 비판적으로 읽고 판단하며, 스스로 책임 있","keywords":["미디어 문해력","알 권리"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-06","grade":"h2"},
{"id":"soc-h-ethics-06#c3","kind":"concept","title":"인간과 인공지능의 관계","text":"인공지능은 사람의 학습·추론·판단 같은 지적 능력을 컴퓨터로 구현한 기술입니다. 특정한 일만 잘하는 약한 인공지능과 사람처럼 폭넓게 사고하고 스스로를 의식하는 강한 인공지능으로 나누기도 합니다. 오늘날 쓰이는 인공지능은 약한 인공지능입니다. 1. 인공지능의 도덕적 지위: 스스로 옳고 그","keywords":["도덕적 행위자"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-06","grade":"h2"},
{"id":"soc-h-ethics-06#c4","kind":"concept","title":"인공지능 윤리: 책임성·투명성·편향성","text":"여러 나라와 국제기구는 인공지능 윤리 가이드라인을 만들어 인공지능을 개발하고 쓸 때 지킬 원칙을 제시하고 있습니다. 그중 자주 강조되는 것은 다음과 같습니다. 원칙·문제 · 뜻 · 해결 방안 책임성 · 인공지능이 낳은 결과에 대해 누가 책임지는지가 분명해야 한다 · 개발·운영 단계별 책","keywords":[],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-06","grade":"h2"},
{"id":"soc-h-ethics-06#t0","kind":"term","title":"저작권","text":"소설·음악·그림·소프트웨어 같은 창작물을 만든 사람이 그 저작물에 대해 가지는 권리입니다.","keywords":["저작권"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-06","grade":"h2"},
{"id":"soc-h-ethics-06#t1","kind":"term","title":"사이버 폭력","text":"정보 통신망에서 글·사진·영상 등으로 다른 사람에게 정신적 피해를 주는 행위입니다. 악성 댓글, 사이버 따돌림, 허위 사실 유포 등이 있습니다.","keywords":["사이버 폭력"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-06","grade":"h2"},
{"id":"soc-h-ethics-06#t2","kind":"term","title":"정보 사유론","text":"정보는 만든 사람의 노력의 결과이므로 개인의 소유로 인정하고 보호해야 한다는 관점입니다.","keywords":["정보 사유론"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-06","grade":"h2"},
{"id":"soc-h-ethics-06#t3","kind":"term","title":"정보 공유론","text":"정보는 인류 공동의 자산이므로 누구나 자유롭게 이용할 수 있어야 한다는 관점입니다.","keywords":["정보 공유론"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-06","grade":"h2"},
{"id":"soc-h-ethics-06#t4","kind":"term","title":"카피레프트","text":"저작물을 누구나 자유롭게 쓰고 고치고 나눌 수 있게 하자는 운동입니다. 저작권(카피라이트)을 비틀어 만든 말입니다.","keywords":["카피레프트"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-06","grade":"h2"},
{"id":"soc-h-ethics-06#t5","kind":"term","title":"미디어 문해력","text":"미디어의 정보를 비판적으로 읽고 판단하며, 책임 있게 정보를 만들고 나누는 능력입니다. 미디어 리터러시라고도 합니다.","keywords":["미디어 문해력"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-06","grade":"h2"},
{"id":"soc-h-ethics-06#t6","kind":"term","title":"알 권리","text":"시민이 공적인 사안에 관한 정보를 자유롭게 얻을 수 있는 권리입니다. 개인의 사생활 보호와 조화를 이루어야 합니다.","keywords":["알 권리"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-06","grade":"h2"},
{"id":"soc-h-ethics-06#t7","kind":"term","title":"확증 편향","text":"자기 생각과 맞는 정보만 받아들이고 맞지 않는 정보는 무시하려는 경향입니다.","keywords":["확증 편향"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-06","grade":"h2"},
{"id":"soc-h-ethics-06#t8","kind":"term","title":"도덕적 행위자","text":"스스로 옳고 그름을 판단하고 그 행위에 대해 책임질 수 있는 존재입니다.","keywords":["도덕적 행위자"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-06","grade":"h2"},
{"id":"soc-h-ethics-06#t9","kind":"term","title":"알고리즘 편향","text":"치우친 데이터나 설계 때문에 인공지능 같은 알고리즘이 특정 집단에게 불공정한 결과를 내는 것입니다.","keywords":["알고리즘 편향"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-06","grade":"h2"},
{"id":"soc-h-ethics-06#f0","kind":"faq","title":"인터넷에 공개된 그림이나 글은 마음대로 써도 되는 것 아닌가요?","text":"아닙니다. 인터넷에 공개되어 있다는 것과 누구나 써도 된다는 것은 다릅니다. 대부분의 창작물에는 저작권이 있으므로, 쓰기 전에 이용 허락 조건(출처 표시, 상업적 이용 금지 등)을 확인하고 지켜야 합니다. 저작권 보호 기간이 끝났거나 창작자가 자유 이용을 허락한 경우에는 그 조건 안에서 자유롭게 쓸 수 있습니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-06","grade":"h2"},
{"id":"soc-h-ethics-06#f1","kind":"faq","title":"인공지능이 잘못된 판단을 하면 누가 책임지나요?","text":"오늘날의 인공지능은 스스로 책임질 수 있는 도덕적 행위자로 보기 어렵다는 견해가 많아서, 인공지능을 개발·제조·운영·사용한 사람들이 각자의 역할에 따라 책임을 나누어 진다고 봅니다. 그래서 인공지능 윤리 가이드라인은 책임 주체를 미리 분명히 하고 피해 구제 절차를 마련하라고 강조합니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-06","grade":"h2"},
{"id":"soc-h-ethics-06#f2","kind":"faq","title":"허위 정보인지 어떻게 알 수 있나요?","text":"완벽한 방법은 없지만 습관이 도움이 됩니다. 출처가 분명한지, 믿을 만한 다른 매체도 같은 내용을 전하는지, 날짜가 오래된 정보를 새것처럼 퍼뜨린 것은 아닌지, 지나치게 감정을 자극하는 표현을 쓰지는 않는지 확인해 보세요. 확인이 안 되면 공유하지 않는 것도 좋은 선택입니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-06","grade":"h2"},
{"id":"soc-h-ethics-06#m0","kind":"mistake","title":"자주 하는 실수","text":"정보 공유론을 \"남의 것을 마음대로 써도 된다\"는 뜻으로 이해하는 실수 — 정보 공유론은 정보를 인류 공동의 자산으로 보고 자유로운 이용 체계를 만들자는 주장이며, 정해진 이용 조건을 무시하라는 뜻이 아닙니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-06","grade":"h2"},
{"id":"soc-h-ethics-06#m1","kind":"mistake","title":"자주 하는 실수","text":"인공지능의 판단은 숫자로 나오므로 늘 객관적이라고 여기는 실수 — 치우친 데이터로 학습하면 사회의 편견을 그대로 되풀이할 수 있습니다(편향성 문제).","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-06","grade":"h2"},
{"id":"soc-h-ethics-06#m2","kind":"mistake","title":"자주 하는 실수","text":"투명성과 책임성을 헷갈리는 실수 — 판단 근거를 설명할 수 있는가는 투명성, 결과에 누가 책임지는가는 책임성입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-06","grade":"h2"},
{"id":"soc-h-ethics-07","kind":"unit","title":"직업 생활과 윤리","text":"직업이 개인과 사회에 갖는 의미와 동서양 사상가들의 직업관을 살펴보고, 기업가·근로자·전문직·공직자가 지켜야 할 직업윤리를 알아봅니다. 청렴한 삶이 왜 중요한지, 부패가 공동체에 어떤 해를 끼치는지, 노동을 존중하는 사회가 왜 필요한지도 함께 생각해 봅니다. 직업의 의의를 생계 유지, 자아실현, 사회적 역할 분담의 측면에서 설명할 수 있다. 공자·맹자·칼…","keywords":["직업","정명","항산과 항심","소명 의식","노동 소외","기업의 사회적 책임","직업윤리","청렴","부패","노동 3권"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-07","grade":"h2"},
{"id":"soc-h-ethics-07#c0","kind":"concept","title":"직업의 의의","text":"직업은 사람이 생계를 유지하기 위해 일정 기간 계속하는 일입니다. 직업은 크게 세 가지 의미를 가집니다. 측면 · 의미 · 예 생계 유지 (경제적 의미) · 소득을 얻어 자신과 가족의 생활을 꾸린다 · 월급으로 생활비와 학비를 마련한다 자아실현 (개인적 의미) · 자신의 소질과 능력을 ","keywords":["직업"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-07","grade":"h2"},
{"id":"soc-h-ethics-07#c1","kind":"concept","title":"동양의 직업관: 공자의 정명, 맹자의 항산과 항심","text":"공자는 정명(正名)을 강조했습니다. 정명이란 \"이름을 바로잡는다\"는 뜻으로, 사람이 자신에게 주어진 지위와 이름에 걸맞게 역할과 책임을 다해야 한다는 것입니다. 『논어』에서 공자는 임금은 임금답고, 신하는 신하답고, 부모는 부모답고, 자식은 자식다워야 한다고 말했습니다. 이를 직업에 적","keywords":["직업","정명","항산과 항심"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-07","grade":"h2"},
{"id":"soc-h-ethics-07#c2","kind":"concept","title":"서양의 직업관: 칼뱅의 소명 의식, 마르크스의 노동 소외","text":"칼뱅은 종교 개혁가로서 직업을 신이 부여한 소명(부르심)으로 보았습니다. 모든 직업은 신의 뜻에 따른 것이므로 신성하며, 직업에 귀천이 없다고 보았습니다. 자기 직업에 근면·성실하게 종사하고 검소하게 생활하여 얻은 부는 정당하다고 보았습니다. 칼뱅의 예정설을 따르는 사람들은 직업에서의 ","keywords":["직업","소명 의식","노동 소외"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-07","grade":"h2"},
{"id":"soc-h-ethics-07#c3","kind":"concept","title":"직업군에 따른 직업윤리","text":"모든 직업인에게는 정직·성실·책임 같은 일반적 직업윤리가 필요합니다. 그와 함께 직업의 특성에 따라 더 강조되는 특수한 직업윤리가 있습니다. 직업군 · 강조되는 직업윤리 기업가 · 정당한 방법으로 이윤 추구, 공정한 경쟁, 소비자의 안전과 권리 존중, 근로자의 정당한 대우, 환경 보호와","keywords":["직업","기업의 사회적 책임","직업윤리","청렴"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-07","grade":"h2"},
{"id":"soc-h-ethics-07#c4","kind":"concept","title":"청렴한 삶과 부패의 해악","text":"청렴(淸廉)은 성품과 행실이 맑고 깨끗하여 탐욕이 없는 것을 말합니다. 직업 생활에서는 자기 지위나 권한을 이용해 부당한 이익을 얻지 않는 태도입니다. 조선 후기의 학자 정약용은 『목민심서』에서 청렴은 목민관(백성을 다스리는 관리)의 기본 임무이며 모든 선과 덕의 근본이라고 보았습니다.","keywords":["직업","청렴","부패"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-07","grade":"h2"},
{"id":"soc-h-ethics-07#c5","kind":"concept","title":"노동의 가치와 노동에 대한 사회적 존중","text":"노동은 생계를 꾸리는 수단이면서, 자신의 능력을 발휘해 자아를 실현하고 사회에 필요한 것을 만들어 내는 활동입니다. 우리가 누리는 음식, 옷, 집, 교통, 의료, 깨끗한 거리는 모두 누군가의 노동 덕분입니다. 그래서 모든 정당한 노동은 존중받아야 합니다. 어떤 일을 하는지, 얼마를 버는","keywords":["노동 3권"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-07","grade":"h2"},
{"id":"soc-h-ethics-07#t0","kind":"term","title":"직업","text":"생계를 유지하기 위해 일정 기간 계속하는 일입니다. 생계 유지, 자아실현, 사회적 역할 분담의 의미를 가집니다.","keywords":["직업"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-07","grade":"h2"},
{"id":"soc-h-ethics-07#t1","kind":"term","title":"정명","text":"공자의 사상으로, 사람이 자신의 지위와 이름에 걸맞게 역할과 책임을 다해야 한다는 뜻입니다.","keywords":["정명"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-07","grade":"h2"},
{"id":"soc-h-ethics-07#t2","kind":"term","title":"항산과 항심","text":"맹자의 말로, 항산은 일정한 생업과 재산, 항심은 변하지 않는 도덕적 마음입니다. 일반 백성은 항산이 없으면 항심을 지니기 어렵다고 보았습니다.","keywords":["항산과 항심"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-07","grade":"h2"},
{"id":"soc-h-ethics-07#t3","kind":"term","title":"소명 의식","text":"자신의 직업을 신이 부여한 거룩한 부름으로 여기는 생각입니다. 칼뱅의 직업관이 대표적입니다.","keywords":["소명 의식"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-07","grade":"h2"},
{"id":"soc-h-ethics-07#t4","kind":"term","title":"노동 소외","text":"마르크스의 개념으로, 자본주의에서 노동자가 자기 생산물·노동 과정·인간 본질·다른 인간으로부터 멀어지는 현상입니다.","keywords":["노동 소외"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-07","grade":"h2"},
{"id":"soc-h-ethics-07#t5","kind":"term","title":"기업의 사회적 책임","text":"기업이 이윤 추구뿐 아니라 법 준수, 소비자·근로자 보호, 환경 보호, 사회 공헌 등 사회에 대한 책임을 다하는 것입니다.","keywords":["기업의 사회적 책임"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-07","grade":"h2"},
{"id":"soc-h-ethics-07#t6","kind":"term","title":"직업윤리","text":"직업인이 직업 생활에서 지켜야 할 행동 규범입니다. 모든 직업에 공통인 일반적 직업윤리와 직업마다 다른 특수한 직업윤리가 있습니다.","keywords":["직업윤리"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-07","grade":"h2"},
{"id":"soc-h-ethics-07#t7","kind":"term","title":"청렴","text":"성품과 행실이 맑고 깨끗하여 탐욕이 없는 것입니다. 지위나 권한을 이용해 부당한 이익을 얻지 않는 태도입니다.","keywords":["청렴"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-07","grade":"h2"},
{"id":"soc-h-ethics-07#t8","kind":"term","title":"부패","text":"공적인 지위나 권한을 사적인 이익을 위해 남용하는 것입니다. 뇌물, 부정 청탁, 공금 횡령 등이 있습니다.","keywords":["부패"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-07","grade":"h2"},
{"id":"soc-h-ethics-07#t9","kind":"term","title":"노동 3권","text":"헌법이 보장하는 근로자의 단결권, 단체 교섭권, 단체 행동권입니다.","keywords":["노동 3권"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-07","grade":"h2"},
{"id":"soc-h-ethics-07#f0","kind":"faq","title":"좋아하는 일과 돈을 잘 버는 일 중 무엇을 직업으로 골라야 하나요?","text":"정답이 하나로 정해진 질문은 아니지만, 직업의 세 가지 의미를 함께 생각해 보면 도움이 됩니다. 생계를 꾸릴 수 있는지(생계 유지), 내 능력을 발휘하며 보람을 느낄 수 있는지(자아실현), 사회에 필요한 역할을 하는지(사회적 역할 분담)를 고루 따져 보세요. 한 가지만 보고 고르면 다른 측면에서 어려움을 겪기 쉽습니다.","keywords":["직업"],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-07","grade":"h2"},
{"id":"soc-h-ethics-07#f1","kind":"faq","title":"맹자는 생업이 없으면 바른 마음도 없다고 했는데, 그럼 가난한 사람은 도덕적이지 않다는 뜻인가요?","text":"그런 뜻이 아닙니다. 맹자의 말은 개인을 평가하려는 것이 아니라 통치자의 책임을 강조하려는 것입니다. 백성이 바르게 살기를 바란다면 먼저 생활의 안정을 보장해야 한다는 것이지요. 또 맹자는 선비처럼 수양한 사람은 항산이 없어도 항심을 지킬 수 있다고 보았습니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-07","grade":"h2"},
{"id":"soc-h-ethics-07#f2","kind":"faq","title":"작은 선물도 받으면 안 되나요? 고마운 마음을 표현한 것일 수도 있잖아요.","text":"직무와 관련된 사람에게서 받는 선물은 대가성이 없어 보여도 공정한 판단을 흐리거나 남들에게 그렇게 보일 수 있습니다. 그래서 공직자 등에게는 직무와 관련된 금품을 받는 것을 법으로 엄격하게 제한하고 있습니다. 구체적인 허용 범위는 법령과 기관의 규정을 확인해야 합니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-07","grade":"h2"},
{"id":"soc-h-ethics-07#m0","kind":"mistake","title":"자주 하는 실수","text":"공자의 정명과 맹자의 항산·항심을 헷갈리는 실수 — 이름(지위)에 걸맞게 역할을 다하라는 것은 공자의 정명, 생업과 도덕적 마음의 관계는 맹자의 항산과 항심입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-07","grade":"h2"},
{"id":"soc-h-ethics-07#m1","kind":"mistake","title":"자주 하는 실수","text":"마르크스가 노동 자체를 나쁘게 보았다고 생각하는 실수 — 마르크스는 노동을 본래 자아실현 활동으로 보았고, 자본주의에서 노동이 소외되는 것을 비판했습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-07","grade":"h2"},
{"id":"soc-h-ethics-07#m2","kind":"mistake","title":"자주 하는 실수","text":"부패를 당사자들만의 문제로 여기는 실수 — 부패의 비용과 피해는 공정한 경쟁, 사회적 신뢰, 세금 낭비를 통해 공동체 전체에 돌아갑니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-07","grade":"h2"},
{"id":"soc-h-ethics-08","kind":"unit","title":"사회 정의와 윤리","text":"롤스의 정의론, 노직의 소유 권리론, 왈처의 복합 평등론을 비교하고 이 이론들로 우대 정책과 복지 정책을 평가해 봅니다. 이어서 교정적 정의의 관점에서 응보주의와 공리주의의 형벌관, 사형 제도를 둘러싼 베카리아·칸트·루소의 입장을 검토합니다. 롤스의 원초적 입장, 무지의 베일, 정의의 두 원칙을 설명할 수 있다. 노직의 소유 권리론과 왈처의 복합 평등론을…","keywords":["원초적 입장","무지의 베일","차등의 원칙","최소 수혜자","소유 권리론","최소 국가","복합 평등","우대 정책","응보주의","교정적 정의"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-08","grade":"h2"},
{"id":"soc-h-ethics-08#c0","kind":"concept","title":"롤스의 정의론: 원초적 입장과 정의의 두 원칙","text":"분배적 정의는 사회의 이익과 부담을 구성원에게 어떻게 나누어야 공정한지를 묻습니다. 미국의 철학자 롤스는 공정한 절차를 거쳐 합의한 원칙이 정의의 원칙이라고 보았습니다(공정으로서의 정의). 원초적 입장: 정의의 원칙을 정하기 위해 가정한 공정한 합의 상황입니다. 이곳의 사람들은 합리적이","keywords":["원초적 입장","무지의 베일"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-08","grade":"h2"},
{"id":"soc-h-ethics-08#c1","kind":"concept","title":"노직의 소유 권리론과 최소 국가","text":"미국의 철학자 노직은 자유주의 가운데에서도 개인의 소유권을 가장 강하게 내세운 사상가입니다. 노직은 어떤 분배가 정의로운지는 결과의 모양(얼마나 평등한가)이 아니라, 그 소유가 어떤 과정을 거쳐 생겼는지로 판단해야 한다고 보았습니다. 이를 소유 권리론(자격 이론)이라고 합니다. 원칙 ·","keywords":["소유 권리론","최소 국가"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-08","grade":"h2"},
{"id":"soc-h-ethics-08#c2","kind":"concept","title":"왈처의 복합 평등론","text":"미국의 철학자 왈처는 하나의 원칙으로 모든 것을 나누려는 생각을 비판했습니다. 사회적 가치는 저마다 의미가 다릅니다. 돈, 정치 권력, 공직, 의료, 교육, 명예 같은 사회적 가치는 그 공동체에서 공유하는 고유한 의미를 지닙니다. 그래서 가치마다 분배 기준이 달라야 합니다. 예를 들어 ","keywords":["복합 평등"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-08","grade":"h2"},
{"id":"soc-h-ethics-08#c3","kind":"concept","title":"분배 정의 이론으로 정책 평가하기","text":"분배 정의 이론은 실제 정책을 평가하는 잣대가 됩니다. 같은 정책도 어떤 이론으로 보느냐에 따라 평가가 달라집니다. 1. 우대 정책(적극적 우대 조치): 사회적 약자에게 입학·채용 등에서 혜택을 주는 정책입니다. 장애인 의무 고용 제도, 농어촌 학생 특별 전형이 그 예입니다. 정당화하는","keywords":["차등의 원칙","우대 정책"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-08","grade":"h2"},
{"id":"soc-h-ethics-08#c4","kind":"concept","title":"교정적 정의와 형벌: 응보주의와 공리주의","text":"아리스토텔레스는 좁은 의미의 정의(특수적 정의)를 몫을 나누는 분배적 정의와, 잘못으로 생긴 불균형을 바로잡는 교정적 정의로 나누었습니다. 범죄에 대한 처벌과 손해 배상은 교정적 정의의 문제입니다. 국가는 왜, 그리고 얼마나 처벌해야 할까요? 구분 · 응보주의 (칸트) · 공리주의 (벤","keywords":["응보주의","교정적 정의"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-08","grade":"h2"},
{"id":"soc-h-ethics-08#c5","kind":"concept","title":"사형 제도 존폐 논쟁","text":"사형은 범죄자의 생명을 빼앗는 가장 무거운 형벌입니다. 사형 제도를 유지할지 없앨지를 두고 사상가들의 입장이 갈립니다. 사상가 · 입장 · 근거 칸트 · 사형 찬성 · 응보주의의 동등성 원리에 따라 살인한 자는 죽음으로 대가를 치러야 하며, 이를 대신할 다른 형벌은 정의를 만족시키지 못","keywords":["응보주의"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-08","grade":"h2"},
{"id":"soc-h-ethics-08#t0","kind":"term","title":"원초적 입장","text":"롤스가 정의의 원칙을 정하기 위해 가정한 공정한 합의 상황입니다. 사람들은 무지의 베일을 쓰고 원칙을 고릅니다.","keywords":["원초적 입장"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-08","grade":"h2"},
{"id":"soc-h-ethics-08#t1","kind":"term","title":"무지의 베일","text":"원초적 입장의 사람들이 자신의 성별·계층·재능·가치관 같은 자기 정보를 모르게 하는 장치입니다. 자기에게만 유리한 원칙을 고르지 못하게 합니다.","keywords":["무지의 베일"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-08","grade":"h2"},
{"id":"soc-h-ethics-08#t2","kind":"term","title":"차등의 원칙","text":"롤스의 정의의 제2원칙 가운데 하나로, 사회적·경제적 불평등은 최소 수혜자에게 최대 이익이 되도록 편성되어야 한다는 원칙입니다.","keywords":["차등의 원칙"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-08","grade":"h2"},
{"id":"soc-h-ethics-08#t3","kind":"term","title":"최소 수혜자","text":"사회에서 가장 불리한 처지에 있는 사람입니다. 롤스의 차등의 원칙은 이들의 처지를 기준으로 불평등을 평가합니다.","keywords":["최소 수혜자"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-08","grade":"h2"},
{"id":"soc-h-ethics-08#t4","kind":"term","title":"소유 권리론","text":"노직의 분배 정의론으로, 정당하게 취득하고 이전받은 소유라면 결과가 불평등해도 정의롭다고 봅니다. 취득·이전·교정의 원칙으로 이루어집니다.","keywords":["소유 권리론"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-08","grade":"h2"},
{"id":"soc-h-ethics-08#t5","kind":"term","title":"최소 국가","text":"폭력·절도·사기로부터 개인을 보호하고 계약을 지키게 하는 역할만 하는 국가입니다. 노직이 정당하다고 본 국가입니다.","keywords":["최소 국가"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-08","grade":"h2"},
{"id":"soc-h-ethics-08#t6","kind":"term","title":"복합 평등","text":"왈처의 주장으로, 사회적 가치마다 다른 분배 기준을 적용하고 한 가치가 다른 영역을 지배하지 못하게 하는 평등입니다.","keywords":["복합 평등"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-08","grade":"h2"},
{"id":"soc-h-ethics-08#t7","kind":"term","title":"우대 정책","text":"사회적 약자에게 입학·채용 등에서 혜택을 주는 정책입니다. 적극적 우대 조치라고도 하며, 역차별 논란이 있습니다.","keywords":["우대 정책"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-08","grade":"h2"},
{"id":"soc-h-ethics-08#t8","kind":"term","title":"응보주의","text":"처벌의 근거를 범죄를 저질렀다는 사실 그 자체에서 찾고, 범죄에 마땅한 만큼 처벌해야 한다는 형벌관입니다. 칸트가 대표적입니다.","keywords":["응보주의"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-08","grade":"h2"},
{"id":"soc-h-ethics-08#t9","kind":"term","title":"교정적 정의","text":"범죄나 잘못으로 생긴 불균형을 처벌이나 배상으로 바로잡는 정의입니다. 몫을 나누는 분배적 정의와 구별됩니다.","keywords":["교정적 정의"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-08","grade":"h2"},
{"id":"soc-h-ethics-08#f0","kind":"faq","title":"무지의 베일은 실제로는 불가능하잖아요. 그런 가정이 무슨 쓸모가 있나요?","text":"맞습니다. 실제로 자기 처지를 모르는 사람은 없습니다. 무지의 베일은 실제 상황이 아니라 생각 실험입니다. \"내가 어떤 처지에 놓일지 모른다면 어떤 규칙에 찬성할까?\"라고 물어보게 하여, 자기 이익에 치우치지 않은 공정한 원칙을 찾는 도구로 쓰입니다.","keywords":["무지의 베일"],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-08","grade":"h2"},
{"id":"soc-h-ethics-08#f1","kind":"faq","title":"노직은 가난한 사람을 돕지 말라고 한 건가요?","text":"그렇지 않습니다. 노직은 어려운 사람을 돕는 일 자체를 반대하지 않았습니다. 다만 국가가 세금으로 강제로 재분배하는 것은 개인의 소유권을 침해한다고 보았고, 돕는 일은 개인의 자발적인 자선으로 이루어져야 한다고 주장했습니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-08","grade":"h2"},
{"id":"soc-h-ethics-08#f2","kind":"faq","title":"우리나라에는 지금 사형 제도가 있나요?","text":"법에는 사형이 형벌로 규정되어 있습니다. 하지만 1997년 12월 이후 사형을 집행하지 않아, 국제 사회에서는 실질적 사형 폐지국으로 분류됩니다. 사형 제도를 유지할지 없앨지는 지금도 사회적으로 논쟁이 이어지는 문제입니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-08","grade":"h2"},
{"id":"soc-h-ethics-08#m0","kind":"mistake","title":"자주 하는 실수","text":"롤스가 모든 불평등을 없애야 한다고 보았다고 생각하는 실수 — 롤스는 최소 수혜자에게 최대 이익이 되는 불평등은 허용했습니다(차등의 원칙).","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-08","grade":"h2"},
{"id":"soc-h-ethics-08#m1","kind":"mistake","title":"자주 하는 실수","text":"루소를 사형 반대론자로 기억하는 실수 — 루소와 베카리아는 모두 사회 계약을 근거로 들었지만, 루소는 사형 찬성, 베카리아는 사형 반대입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-08","grade":"h2"},
{"id":"soc-h-ethics-08#m2","kind":"mistake","title":"자주 하는 실수","text":"왈처의 복합 평등을 \"모든 것을 똑같이 나누자\"는 뜻으로 이해하는 실수 — 그것은 단순 평등입니다. 복합 평등은 가치마다 다른 기준으로 나누고 한 가치가 다른 영역을 지배하지 못하게 하는 것입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-08","grade":"h2"},
{"id":"soc-h-ethics-09","kind":"unit","title":"국가와 시민의 윤리","text":"국가 권위의 근거를 동양의 민본·덕치 사상과 서양의 사회 계약설에서 찾아보고, 개인선과 공동선의 조화, 민주 시민의 정치 참여, 시민 불복종의 조건과 정당성을 따져 봅니다. 동양의 민본·덕치 사상과 서양의 사회 계약설로 국가 권위의 근거와 시민의 의무를 설명할 수 있다. 자유주의와 공동체주의의 관점을 비교하고, 개인선과 공동선이 조화를 이루어야 하는 까닭…","keywords":["민본","덕치","역성혁명","사회 계약설","자연 상태","일반 의지","공동선","공동체주의","시민적 덕성","시민 불복종"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-09","grade":"h2"},
{"id":"soc-h-ethics-09#c0","kind":"concept","title":"국가의 권위 — 동양의 민본과 덕치","text":"국가는 법을 만들고 세금을 거두며 강제력을 씁니다. 시민은 왜 이런 국가의 명령에 따라야 할까요? 국가의 권위가 정당하다는 근거를 찾는 것이 국가 윤리의 첫 질문입니다. 동양의 유교 사상은 그 근거를 백성과 덕에서 찾았습니다. 민본(民本): 백성이 나라의 근본이라는 생각입니다. 『서경』","keywords":["민본","덕치","역성혁명"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-09","grade":"h2"},
{"id":"soc-h-ethics-09#c1","kind":"concept","title":"서양의 사회 계약설","text":"서양 근대의 사회 계약설은 국가가 신이나 혈통이 아니라 자유롭고 평등한 개인들의 합의(계약)로 세워졌다고 봅니다. 그래서 국가 권위의 근거는 시민의 동의이고, 국가는 시민의 생명과 권리를 지키기 위해 존재합니다. 사상가마다 국가가 생기기 전의 자연 상태를 다르게 보았기 때문에 그리는 국","keywords":["사회 계약설","자연 상태"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-09","grade":"h2"},
{"id":"soc-h-ethics-09#c2","kind":"concept","title":"개인선과 공동선의 조화","text":"개인선은 각자가 추구하는 좋은 삶(행복, 자아실현, 이익)이고, 공동선은 공동체 구성원 모두에게 두루 이로운 것(안전, 질서, 깨끗한 환경, 공정한 제도)입니다. 둘의 관계를 보는 대표적인 관점은 다음과 같습니다. 구분 · 자유주의 · 공동체주의 개인 · 공동체보다 앞서는 독립적인 존재","keywords":["공동선","공동체주의"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-09","grade":"h2"},
{"id":"soc-h-ethics-09#c3","kind":"concept","title":"민주 시민의 정치 참여","text":"민주주의에서 주권은 국민에게 있습니다. 그러나 대표를 뽑은 뒤 지켜보기만 하면 정치가 시민의 뜻에서 멀어질 수 있습니다. 그래서 시민의 정치 참여가 필요합니다. 참여가 필요한 까닭 시민의 권리와 이익을 지키고, 대표자의 권력 남용을 감시하고 견제합니다. 다양한 의견이 반영되어 정책의 정","keywords":["시민적 덕성"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-09","grade":"h2"},
{"id":"soc-h-ethics-09#c4","kind":"concept","title":"시민 불복종의 의미와 정당화 조건","text":"시민 불복종은 정의롭지 못한 법이나 정책을 바로잡기 위해 그 법을 의도적으로 어기는 공개적이고 비폭력적인 행위입니다. 법을 어긴다는 점에서는 위법이지만, 법체계 전체를 부정하지 않고 더 정의로운 법을 만들려 한다는 점에서 단순한 범죄나 폭동과 다릅니다. 시민 불복종이 정당화되려면 다음 ","keywords":["공동선","시민 불복종"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-09","grade":"h2"},
{"id":"soc-h-ethics-09#c5","kind":"concept","title":"시민 불복종에 대한 소로와 롤스의 입장","text":"소로는 19세기 미국의 사상가로, 노예 제도와 전쟁을 지원하는 정부에 항의하여 세금 납부를 거부하고 감옥에 갇힌 일이 있습니다. 그는 이 경험을 바탕으로 쓴 글에서 다음과 같이 주장하였습니다. 시민은 법보다 먼저 옳음(정의)을 존중해야 하며, 판단의 기준은 개인의 양심이다. 정의롭지 못","keywords":["시민 불복종"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-09","grade":"h2"},
{"id":"soc-h-ethics-09#t0","kind":"term","title":"민본","text":"백성을 나라의 근본으로 여기는 유교의 정치사상입니다. 통치자는 백성을 위해 존재한다고 봅니다.","keywords":["민본"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-09","grade":"h2"},
{"id":"soc-h-ethics-09#t1","kind":"term","title":"덕치","text":"통치자가 먼저 덕을 닦고 모범을 보여 백성을 이끄는 정치입니다. 공자가 강조하였습니다.","keywords":["덕치"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-09","grade":"h2"},
{"id":"soc-h-ethics-09#t2","kind":"term","title":"역성혁명","text":"백성을 해치는 폭군은 군주의 자격을 잃었으므로 바꿀 수 있다는 맹자의 주장입니다.","keywords":["역성혁명"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-09","grade":"h2"},
{"id":"soc-h-ethics-09#t3","kind":"term","title":"사회 계약설","text":"국가가 자유롭고 평등한 개인들의 합의(계약)로 세워졌다고 보는 이론입니다. 홉스, 로크, 루소가 대표적입니다.","keywords":["사회 계약설"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-09","grade":"h2"},
{"id":"soc-h-ethics-09#t4","kind":"term","title":"자연 상태","text":"사회 계약설에서 국가와 법이 생기기 전의 상태를 말합니다. 사상가마다 다르게 그렸습니다.","keywords":["자연 상태"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-09","grade":"h2"},
{"id":"soc-h-ethics-09#t5","kind":"term","title":"일반 의지","text":"루소가 말한 것으로, 개인의 사적 이익이 아니라 공동선을 지향하는 공동체 전체의 의지입니다.","keywords":["일반 의지"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-09","grade":"h2"},
{"id":"soc-h-ethics-09#t6","kind":"term","title":"공동선","text":"공동체 구성원 모두에게 두루 이로운 것입니다. 예: 안전, 질서, 깨끗한 환경, 공정한 제도","keywords":["공동선"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-09","grade":"h2"},
{"id":"soc-h-ethics-09#t7","kind":"term","title":"공동체주의","text":"개인은 공동체의 역사와 전통 속에서 정체성을 가진다고 보고, 공동선과 시민의 덕성을 강조하는 관점입니다.","keywords":["공동체주의"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-09","grade":"h2"},
{"id":"soc-h-ethics-09#t8","kind":"term","title":"시민적 덕성","text":"공동체의 일에 관심을 갖고 책임 있게 참여하는 시민의 자질입니다. 책임감, 배려, 공공심 등이 있습니다.","keywords":["시민적 덕성"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-09","grade":"h2"},
{"id":"soc-h-ethics-09#t9","kind":"term","title":"시민 불복종","text":"정의롭지 못한 법이나 정책을 바로잡기 위해 그 법을 의도적으로 어기는 공개적이고 비폭력적인 행위입니다.","keywords":["시민 불복종"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-09","grade":"h2"},
{"id":"soc-h-ethics-09#f0","kind":"faq","title":"시민 불복종은 법을 어기는 건데 왜 정당할 수 있어요?","text":"법은 정의를 실현하려고 만든 것이지만, 사람이 만든 법이 늘 정의로운 것은 아닙니다. 합법적인 방법으로 바로잡으려 해도 바뀌지 않을 때, 공개적·비폭력적으로 법을 어기고 처벌까지 받아들이는 행동은 사회의 정의감에 호소하여 법을 고치게 하는 힘이 됩니다. 다만 정당화 조건(공익성·공개성·비폭력성·최후의 수단·처벌 감수)을 갖추어야 하며, 이를 갖추지 못한 …","keywords":["시민 불복종"],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-09","grade":"h2"},
{"id":"soc-h-ethics-09#f1","kind":"faq","title":"자유주의와 공동체주의 중에 어느 쪽이 맞아요?","text":"어느 한쪽만 옳다고 하기는 어렵습니다. 자유주의는 개인의 권리를 지켜 주는 장점이 있지만 지나치면 이기주의로 흐를 수 있고, 공동체주의는 연대와 책임을 일깨우지만 지나치면 개인의 자유를 억누를 수 있습니다. 그래서 두 관점의 장점을 살려 개인선과 공동선이 조화를 이루도록 하는 것이 중요합니다.","keywords":["공동체주의"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-09","grade":"h2"},
{"id":"soc-h-ethics-09#f2","kind":"faq","title":"홉스는 왜 그렇게 강한 국가가 필요하다고 했어요?","text":"홉스는 국가가 없으면 사람들이 자기 보존을 위해 서로 싸우는 \"만인의 만인에 대한 투쟁\" 상태가 된다고 보았습니다. 이런 상태에서는 누구도 안전하지 않으므로, 모두가 자연권을 통치자에게 넘겨 평화를 지켜 줄 강력한 국가를 세워야 한다고 생각하였습니다. 홉스가 살던 시대 영국이 내전으로 큰 혼란을 겪은 것도 이런 생각에 영향을 주었습니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-09","grade":"h2"},
{"id":"soc-h-ethics-09#m0","kind":"mistake","title":"자주 하는 실수","text":"법을 어기는 모든 시위를 시민 불복종이라고 보는 실수 — 공익성·공개성·비폭력성·최후의 수단·처벌 감수를 갖추어야 시민 불복종으로 정당화됩니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-09","grade":"h2"},
{"id":"soc-h-ethics-09#m1","kind":"mistake","title":"자주 하는 실수","text":"소로와 롤스의 판단 기준을 바꾸어 기억하는 실수 — 소로는 개인의 양심, 롤스는 다수가 공유하는 정의관입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-09","grade":"h2"},
{"id":"soc-h-ethics-09#m2","kind":"mistake","title":"자주 하는 실수","text":"홉스와 로크의 저항권을 헷갈리는 실수 — 홉스는 저항권을 원칙적으로 인정하지 않고, 로크는 정부가 신탁을 어기면 저항권을 인정합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-09","grade":"h2"},
{"id":"soc-h-ethics-10","kind":"unit","title":"예술·대중문화와 소비 윤리","text":"예술과 도덕의 관계를 도덕주의와 심미주의로 살피고, 대중문화의 순기능과 역기능, 의식주와 경제생활의 윤리, 현대 소비문화의 문제와 윤리적 소비를 탐구합니다. 예술과 도덕의 관계에 대한 도덕주의와 심미주의의 입장을 비교할 수 있다. 대중문화의 순기능과 역기능을 알고, 대중문화 규제를 둘러싼 논쟁을 평가할 수 있다. 의식주 생활과 경제생활에서 생기는 윤리적 …","keywords":["도덕주의","심미주의","대중문화","문화 산업","미디어 리터러시","로컬 푸드","사회적 자본","과시 소비","기호 소비","윤리적 소비"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-10","grade":"h2"},
{"id":"soc-h-ethics-10#c0","kind":"concept","title":"예술과 도덕의 관계 — 도덕주의와 심미주의","text":"예술은 아름다움을 추구합니다. 그렇다면 예술도 도덕의 평가를 받아야 할까요? 이 물음에 대한 대표적인 입장이 둘 있습니다. 구분 · 도덕주의 · 심미주의(예술 지상주의) 예술의 목적 · 도덕적 가치를 담아 사람들의 품성을 기름 · 아름다움 그 자체 예술과 도덕 · 예술은 도덕의 지도를 ","keywords":["도덕주의","심미주의"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-10","grade":"h2"},
{"id":"soc-h-ethics-10#c1","kind":"concept","title":"대중문화의 순기능과 역기능","text":"대중문화는 대중 매체를 통해 많은 사람이 쉽게 접하고 즐기는 문화입니다. 영화, 드라마, 대중가요, 웹툰, 영상 콘텐츠 등이 있습니다. 순기능 많은 사람이 적은 비용으로 문화를 누릴 수 있게 하여 문화를 누리는 기회를 넓힙니다. 휴식과 즐거움을 주고, 같은 작품을 즐기며 공감과 유대감을","keywords":["대중문화"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-10","grade":"h2"},
{"id":"soc-h-ethics-10#c2","kind":"concept","title":"대중문화 규제 논쟁","text":"대중문화의 역기능을 막으려고 국가가 내용을 규제해야 한다는 주장과, 규제를 최소화해야 한다는 주장이 맞섭니다. 규제 찬성 · 규제 반대 청소년을 유해한 내용으로부터 보호해야 함 · 표현의 자유와 창작의 자율성이 위축됨 선정성·폭력성은 인간의 존엄성을 해침 · 무엇이 유해한지 판단하는 기","keywords":["대중문화","미디어 리터러시"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-10","grade":"h2"},
{"id":"soc-h-ethics-10#c3","kind":"concept","title":"의식주 생활의 윤리","text":"먹고 입고 사는 일상에도 윤리적 물음이 숨어 있습니다. 의복 — 유행과 개성 옷은 몸을 보호할 뿐 아니라 예의를 갖추고 자신을 표현하는 수단입니다. 유행을 따르면 소속감을 느낄 수 있지만, 지나치게 좇으면 개성을 잃고 낭비가 생깁니다. 한 철 입고 버리도록 값싸게 대량 생산하는 옷은 자","keywords":[],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-10","grade":"h2"},
{"id":"soc-h-ethics-10#c4","kind":"concept","title":"경제생활의 윤리와 사회적 자본","text":"이윤 추구는 경제 활동의 정당한 동기입니다. 그러나 이윤만 좇으면 도덕적 선과 부딪칠 수 있습니다. 불량품을 속여 팔거나, 노동자의 권리를 무시하거나, 환경을 오염시키며 비용을 줄이는 경우가 그렇습니다. 기업의 사회적 책임을 두고는 생각이 갈립니다. 프리드먼은 기업이 법과 규칙을 지키는","keywords":["사회적 자본"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-10","grade":"h2"},
{"id":"soc-h-ethics-10#c5","kind":"concept","title":"현대 소비문화의 문제와 윤리적 소비","text":"현대 사회에서 소비는 필요를 채우는 것을 넘어 자신을 드러내는 수단이 되기도 합니다. 과시 소비: 자신의 부나 지위를 남에게 드러내려는 소비입니다. 베블런은 『유한계급론』에서 부유층이 재산을 과시하려고 소비하는 모습을 비판하였습니다. 가격이 오를수록 오히려 수요가 늘어나는 현상을 베블런","keywords":["과시 소비","기호 소비","윤리적 소비"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-10","grade":"h2"},
{"id":"soc-h-ethics-10#t0","kind":"term","title":"도덕주의","text":"예술은 도덕적 가치를 담아 사람들의 품성을 기르는 데 이바지해야 한다는 입장입니다. 플라톤, 톨스토이가 대표적입니다.","keywords":["도덕주의"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-10","grade":"h2"},
{"id":"soc-h-ethics-10#t1","kind":"term","title":"심미주의","text":"예술의 목적은 아름다움 그 자체이며 도덕적 기준으로 평가할 수 없다는 입장입니다. 예술 지상주의라고도 합니다.","keywords":["심미주의"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-10","grade":"h2"},
{"id":"soc-h-ethics-10#t2","kind":"term","title":"대중문화","text":"대중 매체를 통해 많은 사람이 쉽게 접하고 즐기는 문화입니다. 영화, 드라마, 대중가요 등이 있습니다.","keywords":["대중문화"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-10","grade":"h2"},
{"id":"soc-h-ethics-10#t3","kind":"term","title":"문화 산업","text":"대중문화가 공장에서 물건을 찍어 내듯 표준화된 상품이 되었다고 비판한 아도르노와 호르크하이머의 말입니다.","keywords":["문화 산업"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-10","grade":"h2"},
{"id":"soc-h-ethics-10#t4","kind":"term","title":"미디어 리터러시","text":"미디어의 내용을 비판적으로 이해하고 골라 쓰며, 책임 있게 표현하는 능력입니다.","keywords":["미디어 리터러시"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-10","grade":"h2"},
{"id":"soc-h-ethics-10#t5","kind":"term","title":"로컬 푸드","text":"가까운 지역에서 생산된 먹거리입니다. 운송에 드는 에너지를 줄이고 지역 농가를 돕습니다.","keywords":["로컬 푸드"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-10","grade":"h2"},
{"id":"soc-h-ethics-10#t6","kind":"term","title":"사회적 자본","text":"사람들 사이의 신뢰, 규범, 관계망처럼 협력을 쉽게 해 주는 사회적 자원입니다.","keywords":["사회적 자본"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-10","grade":"h2"},
{"id":"soc-h-ethics-10#t7","kind":"term","title":"과시 소비","text":"자신의 부나 지위를 남에게 드러내려는 소비입니다. 베블런이 비판하였습니다.","keywords":["과시 소비"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-10","grade":"h2"},
{"id":"soc-h-ethics-10#t8","kind":"term","title":"기호 소비","text":"상품의 기능보다 상품이 나타내는 신분·개성·이미지 같은 의미(기호)를 소비하는 것입니다.","keywords":["기호 소비"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-10","grade":"h2"},
{"id":"soc-h-ethics-10#t9","kind":"term","title":"윤리적 소비","text":"소비가 생산자의 인권, 환경, 동물, 지역 공동체에 미치는 영향까지 생각하는 소비입니다. 공정 무역 제품 구매가 그 예입니다.","keywords":["윤리적 소비"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-10","grade":"h2"},
{"id":"soc-h-ethics-10#f0","kind":"faq","title":"좋아하는 가수의 상품을 사는 것도 과시 소비인가요?","text":"좋아하는 마음을 표현하고 즐거움을 얻으려고 형편에 맞게 사는 것은 자연스러운 소비입니다. 다만 남에게 보여 주려고 무리하게 사거나, 필요 이상으로 계속 사서 생활에 부담이 된다면 과시 소비나 모방 소비가 아닌지 돌아볼 필요가 있습니다. 기준은 \"내 필요와 형편에 맞는가, 남의 눈 때문인가\"입니다.","keywords":["과시 소비"],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-10","grade":"h2"},
{"id":"soc-h-ethics-10#f1","kind":"faq","title":"윤리적 소비는 비싸서 학생은 하기 어렵지 않나요?","text":"윤리적 소비가 꼭 비싼 제품을 사는 것만은 아닙니다. 필요한 만큼만 사기, 오래 쓰고 고쳐 쓰기, 음식 남기지 않기, 일회용품 줄이기처럼 돈이 들지 않거나 오히려 아껴지는 실천도 모두 윤리적 소비입니다. 할 수 있는 것부터 하나씩 해 보면 됩니다.","keywords":["윤리적 소비"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-10","grade":"h2"},
{"id":"soc-h-ethics-10#f2","kind":"faq","title":"도덕적으로 문제가 있는 예술 작품은 금지해야 하나요?","text":"쉽게 답하기 어려운 문제입니다. 도덕주의의 관점에서는 사회에 해로운 영향을 주는 작품을 제한해야 한다고 볼 수 있고, 심미주의의 관점에서는 예술의 자율성을 지켜야 한다고 볼 것입니다. 그래서 오늘날에는 일률적으로 금지하기보다 연령 등급 분류, 자율 규제, 감상자의 비판적 수용 능력을 함께 고려하는 경우가 많습니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-10","grade":"h2"},
{"id":"soc-h-ethics-10#m0","kind":"mistake","title":"자주 하는 실수","text":"합리적 소비와 윤리적 소비를 같은 것으로 보는 실수 — 합리적 소비는 비용에 비해 큰 만족을, 윤리적 소비는 인권·환경·동물·공동체에 미치는 영향까지 생각합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-10","grade":"h2"},
{"id":"soc-h-ethics-10#m1","kind":"mistake","title":"자주 하는 실수","text":"도덕주의와 심미주의를 바꾸어 기억하는 실수 — 예술이 도덕적 가치를 담아야 한다는 것이 도덕주의, 예술은 아름다움 그 자체가 목적이라는 것이 심미주의입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-10","grade":"h2"},
{"id":"soc-h-ethics-10#m2","kind":"mistake","title":"자주 하는 실수","text":"과시 소비와 기호 소비를 구별하지 못하는 실수 — 과시 소비는 부와 지위를 드러내려는 것이고, 기호 소비는 상품이 나타내는 의미(신분·개성·이미지)를 소비하는 더 넓은 개념입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-10","grade":"h2"},
{"id":"soc-h-ethics-11","kind":"unit","title":"다문화 사회와 사회 통합","text":"다문화 이론으로 문화 다양성 존중의 필요성을 알고, 관용과 그 한계, 종교 갈등과 이주민 차별의 해결 방안을 탐구하며, 사회 갈등을 동서양의 통합 사상과 바람직한 소통·담론으로 풀어 가는 방법을 찾습니다. 용광로 이론, 샐러드 볼 이론, 국수 대접 이론을 비교하여 설명할 수 있다. 문화 다양성을 존중하는 관용의 의미와 한계를 말하고, 종교 갈등과 이주민 …","keywords":["용광로 이론","샐러드 볼 이론","국수 대접 이론","문화 상대주의","관용","관용의 역설","화쟁","화이부동","이상적 담화 상황"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-11","grade":"h2"},
{"id":"soc-h-ethics-11#c0","kind":"concept","title":"다문화 이론 — 용광로, 샐러드 볼, 국수 대접","text":"한 사회 안에 여러 문화가 함께 있는 다문화 사회에서는 서로 다른 문화를 어떻게 대할지에 대한 이론이 필요합니다. 이론 · 비유 · 관점 · 한계 용광로 이론 · 여러 금속을 녹여 하나로 만드는 용광로 · 이주민의 문화를 주류 문화에 녹여 하나로 만듦(동화주의) · 이주민 문화의 정체성","keywords":["용광로 이론","샐러드 볼 이론","국수 대접 이론"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-11","grade":"h2"},
{"id":"soc-h-ethics-11#c1","kind":"concept","title":"문화 다양성 존중과 관용, 관용의 한계","text":"문화를 그 사회의 자연환경과 역사 속에서 이해하려는 태도를 문화 상대주의라고 합니다. 다른 문화를 내 문화의 잣대로 낮추어 보는 자문화 중심주의를 넘어서게 해 줍니다. 문화 다양성을 존중하려면 관용이 필요합니다. 관용은 나와 다른 생각·신념·생활 방식을 가진 사람을 인정하고 존중하는 태","keywords":["문화 상대주의","관용"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-11","grade":"h2"},
{"id":"soc-h-ethics-11#c2","kind":"concept","title":"종교 갈등과 이주민 차별의 해결","text":"종교 갈등은 자기 종교만을 절대적 진리로 여겨 다른 종교를 배척할 때, 그리고 종교가 정치적·경제적 이해관계와 얽힐 때 깊어집니다. 해결 방안 헌법이 보장하는 종교의 자유를 존중하고, 종교를 이유로 차별하지 않습니다. 다른 종교의 가르침을 이해하려 노력하고, 종교 간 대화와 협력을 넓힙","keywords":[],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-11","grade":"h2"},
{"id":"soc-h-ethics-11#c3","kind":"concept","title":"사회적 갈등의 양상","text":"사회적 갈등은 개인이나 집단이 서로 다른 가치나 이해관계 때문에 부딪치는 것입니다. 우리 사회에서 자주 나타나는 갈등은 다음과 같습니다. 갈등 · 모습 이념 갈등 · 사회가 나아갈 방향과 중시할 가치에 대한 정치적 생각의 차이로 생기는 갈등 지역 갈등 · 지역 사이의 불균형한 발전, 지","keywords":[],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-11","grade":"h2"},
{"id":"soc-h-ethics-11#c4","kind":"concept","title":"동양 사상에서 찾는 사회 통합 — 화쟁과 화이부동","text":"원효의 화쟁(和諍) 신라의 승려 원효는 당시 불교의 여러 종파가 서로 자기 주장만 옳다고 다투는 것을 보고 화쟁 사상을 펼쳤습니다. 모든 것은 한마음(일심, 一心)에서 나왔으므로, 서로 다른 주장도 그 근원에서는 하나로 통합니다. 서로 다른 주장은 저마다 일리가 있습니다. 한쪽만 고집하","keywords":["화쟁","화이부동"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-11","grade":"h2"},
{"id":"soc-h-ethics-11#c5","kind":"concept","title":"바람직한 소통과 담론 — 하버마스","text":"갈등을 풀려면 힘이나 숫자로 밀어붙이지 않고 대화와 토론(담론)으로 합의에 이르러야 합니다. 하버마스는 사람들이 서로 이해하고 합의에 이르려는 의사소통적 합리성을 강조하였습니다. 하버마스는 합리적인 합의를 이루려면 이상적 담화 상황이 필요하다고 보았습니다. 대화에 참여할 수 있는 사람은","keywords":["이상적 담화 상황"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-11","grade":"h2"},
{"id":"soc-h-ethics-11#t0","kind":"term","title":"용광로 이론","text":"이주민의 문화를 주류 문화에 녹여 하나의 문화로 만들어야 한다는 동화주의 이론입니다.","keywords":["용광로 이론"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-11","grade":"h2"},
{"id":"soc-h-ethics-11#t1","kind":"term","title":"샐러드 볼 이론","text":"여러 문화가 고유성을 지키면서 동등하게 공존해야 한다는 다문화주의 이론입니다.","keywords":["샐러드 볼 이론"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-11","grade":"h2"},
{"id":"soc-h-ethics-11#t2","kind":"term","title":"국수 대접 이론","text":"주류 문화를 중심으로 이주민 문화가 고명처럼 어우러져야 한다는 문화 다원주의 이론입니다.","keywords":["국수 대접 이론"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-11","grade":"h2"},
{"id":"soc-h-ethics-11#t3","kind":"term","title":"문화 상대주의","text":"문화를 그 사회의 자연환경과 역사적 맥락 속에서 이해하려는 태도입니다.","keywords":["문화 상대주의"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-11","grade":"h2"},
{"id":"soc-h-ethics-11#t4","kind":"term","title":"관용","text":"나와 다른 생각·신념·생활 방식을 가진 사람을 인정하고 존중하는 태도입니다.","keywords":["관용"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-11","grade":"h2"},
{"id":"soc-h-ethics-11#t5","kind":"term","title":"관용의 역설","text":"관용하지 않는 사람들까지 무제한으로 관용하면 관용하는 사회 자체가 무너진다는 포퍼의 지적입니다.","keywords":["관용의 역설"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-11","grade":"h2"},
{"id":"soc-h-ethics-11#t6","kind":"term","title":"화쟁","text":"서로 다른 주장들을 한마음(일심)에 바탕을 두고 더 높은 차원에서 조화시키려는 원효의 사상입니다.","keywords":["화쟁"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-11","grade":"h2"},
{"id":"soc-h-ethics-11#t7","kind":"term","title":"화이부동","text":"다른 사람과 조화를 이루되 무조건 같아지지 않는다는 공자의 말입니다.","keywords":["화이부동"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-11","grade":"h2"},
{"id":"soc-h-ethics-11#t8","kind":"term","title":"이상적 담화 상황","text":"하버마스가 말한 것으로, 누구나 강제 없이 자유롭게 주장하고 의문을 제기할 수 있는 대화의 상황입니다.","keywords":["이상적 담화 상황"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-11","grade":"h2"},
{"id":"soc-h-ethics-11#f0","kind":"faq","title":"다문화 이론 중에 어느 것이 정답이에요?","text":"어느 하나가 늘 정답이라고 하기는 어렵습니다. 용광로 이론은 통합에, 샐러드 볼 이론은 다양성에, 국수 대접 이론은 그 둘의 균형에 무게를 둡니다. 각 이론의 장점과 한계를 알고, 우리 사회의 상황에 맞게 다양성과 통합을 함께 살리는 방안을 찾는 것이 중요합니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-11","grade":"h2"},
{"id":"soc-h-ethics-11#f1","kind":"faq","title":"관용하려면 다른 사람의 생각을 하나도 비판하면 안 되나요?","text":"아닙니다. 관용은 상대에게 무조건 동의하는 것이 아니라, 나와 생각이 달라도 그 사람이 그렇게 생각하고 살아갈 권리를 인정하는 것입니다. 그래서 근거를 들어 정중하게 비판하고 토론하는 것은 관용과 함께할 수 있습니다. 다만 인권을 침해하는 행위는 관용의 대상이 아닙니다.","keywords":["관용"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-11","grade":"h2"},
{"id":"soc-h-ethics-11#f2","kind":"faq","title":"화이부동이랑 화쟁은 뭐가 달라요?","text":"둘 다 차이를 인정하면서 조화를 이루려는 생각이라는 점은 같습니다. 화이부동은 공자가 군자의 태도로 말한 것으로, 다른 사람과 어울리되 무조건 같아지지 않는 것입니다. 화쟁은 원효가 불교 종파들의 다툼을 보고 펼친 사상으로, 서로 다른 주장들이 한마음(일심)이라는 근원에서 하나로 통한다고 보고 더 높은 차원에서 화해시키려 합니다.","keywords":["화쟁","화이부동"],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-11","grade":"h2"},
{"id":"soc-h-ethics-11#m0","kind":"mistake","title":"자주 하는 실수","text":"국수 대접 이론과 샐러드 볼 이론을 헷갈리는 실수 — 주류 문화(국수)를 중심에 두면 국수 대접 이론, 중심 없이 모든 문화가 동등하면 샐러드 볼 이론입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-11","grade":"h2"},
{"id":"soc-h-ethics-11#m1","kind":"mistake","title":"자주 하는 실수","text":"하버마스의 진리성과 진실성을 헷갈리는 실수 — 진리성은 말하는 내용이 사실인가, 진실성은 말하는 사람이 속이지 않고 진심인가입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-11","grade":"h2"},
{"id":"soc-h-ethics-11#m2","kind":"mistake","title":"자주 하는 실수","text":"문화 상대주의를 \"모든 관습이 옳다\"는 뜻으로 오해하는 실수 — 보편적 인권을 침해하는 관습까지 옳다고 보는 것은 윤리 상대주의로, 경계해야 합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-11","grade":"h2"},
{"id":"soc-h-ethics-12","kind":"unit","title":"평화와 공존의 윤리","text":"통일을 둘러싼 쟁점을 분단 비용·통일 비용·평화 비용으로 객관적으로 살피고, 남북한 화해를 위한 노력, 국제 분쟁을 보는 관점과 칸트의 영구 평화론, 국제 정의와 해외 원조의 윤리를 탐구합니다. 분단 비용·통일 비용·평화 비용을 구별하고, 통일을 둘러싼 여러 견해를 근거와 함께 설명할 수 있다. 남북한의 화해를 위한 개인적·국가적 노력을 제시할 수 있다.…","keywords":["분단 비용","통일 비용","평화 비용","통일 편익","현실주의","이상주의","영구 평화론","형사적 정의","분배적 정의","난민"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-12","grade":"h2"},
{"id":"soc-h-ethics-12#c0","kind":"concept","title":"통일을 둘러싼 쟁점 — 분단 비용, 통일 비용, 평화 비용","text":"우리 헌법은 평화적 통일을 지향한다고 밝히고 있습니다. 그러나 통일을 언제, 어떻게 이룰지, 그 부담을 어떻게 나눌지에 대해서는 여러 견해가 있습니다. 통일이 필요하다는 근거: 이산가족의 고통 해소, 전쟁 위협 제거와 평화 정착, 분단으로 생기는 손실 해소와 경제 발전, 북한 주민의 인","keywords":["분단 비용","통일 비용","평화 비용"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-12","grade":"h2"},
{"id":"soc-h-ethics-12#c1","kind":"concept","title":"남북한의 화해를 위한 노력","text":"오랜 분단으로 남북한은 서로를 믿지 못하고, 말과 생활 방식도 많이 달라졌습니다. 화해와 통일은 정부의 노력만으로 이루어지지 않으며, 개인과 국가의 노력이 함께 필요합니다. 개인적 노력 북한을 균형 있게 바라봅니다. 북한은 우리의 안보를 위협하는 경계의 대상이면서, 평화와 통일을 함께 ","keywords":[],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-12","grade":"h2"},
{"id":"soc-h-ethics-12#c2","kind":"concept","title":"국제 분쟁을 보는 관점 — 현실주의와 이상주의","text":"국제 사회에는 영토, 자원, 종교, 민족 문제 등으로 분쟁이 끊이지 않습니다. 분쟁의 원인과 평화의 길을 보는 대표적인 관점이 둘 있습니다. 구분 · 현실주의 · 이상주의 국제 사회 · 국가 위에 강제력을 가진 권위가 없는 무정부 상태 · 국제법과 국제기구로 협력할 수 있는 사회 국가 ","keywords":["현실주의","이상주의"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-12","grade":"h2"},
{"id":"soc-h-ethics-12#c3","kind":"concept","title":"칸트의 영구 평화론","text":"칸트는 1795년 『영구 평화론』에서 전쟁을 잠시 멈춘 휴전이 아니라, 모든 적대 관계가 끝난 영구적인 평화를 이루는 길을 제시하였습니다. 칸트는 평화가 저절로 오는 것이 아니라, 이성에 따라 만들어 가야 하는 것이며 도덕적 의무라고 보았습니다. 예비 조항(전쟁의 원인을 없애는 조건) ","keywords":["영구 평화론"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-12","grade":"h2"},
{"id":"soc-h-ethics-12#c4","kind":"concept","title":"국제 정의 — 분쟁·난민·빈곤 문제","text":"국제 사회에서도 정의를 실현해야 한다는 생각이 국제 정의입니다. 국제 정의는 크게 두 가지로 나누어 봅니다. 구분 · 뜻 · 관련 문제와 노력 형사적 정의 · 국제 사회의 평화를 해치는 범죄를 저지른 사람을 처벌하여 정의를 세움 · 집단 살해, 반인도적 범죄, 전쟁 범죄. 국제 형사 재","keywords":["형사적 정의","분배적 정의","난민"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-12","grade":"h2"},
{"id":"soc-h-ethics-12#c5","kind":"concept","title":"해외 원조의 윤리 — 싱어, 롤스, 노직","text":"가난한 나라를 돕는 해외 원조는 반드시 해야 하는 의무일까요, 하면 좋은 자선일까요? 사상가마다 대답이 다릅니다. 싱어 — 공리주의 비슷한 도덕적 가치를 희생하지 않고 나쁜 일을 막을 수 있다면 막아야 한다고 보았습니다. 얕은 연못에 빠진 아이를 옷이 젖는다는 이유로 구하지 않는 것이 ","keywords":[],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-12","grade":"h2"},
{"id":"soc-h-ethics-12#t0","kind":"term","title":"분단 비용","text":"분단 때문에 남북한이 치르는 유형·무형의 손실입니다. 분단이 계속되는 한 계속 생기는 소모적 비용입니다. 예: 지나친 군사비, 이산가족의 고통","keywords":["분단 비용"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-12","grade":"h2"},
{"id":"soc-h-ethics-12#t1","kind":"term","title":"통일 비용","text":"통일 이후 남북한의 격차를 줄이고 제도를 하나로 합치는 데 드는 비용입니다. 통일 이후 일정 기간 생기며 투자의 성격이 있습니다.","keywords":["통일 비용"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-12","grade":"h2"},
{"id":"soc-h-ethics-12#t2","kind":"term","title":"평화 비용","text":"통일 이전에 전쟁을 막고 평화를 유지하는 데 드는 비용입니다. 예: 인도적 지원, 남북 교류·협력","keywords":["평화 비용"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-12","grade":"h2"},
{"id":"soc-h-ethics-12#t3","kind":"term","title":"통일 편익","text":"통일로 얻는 경제적·비경제적 이익입니다. 분단 비용의 해소, 경제 규모 확대, 이산가족의 고통과 전쟁 공포의 해소 등이 있습니다.","keywords":["통일 편익"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-12","grade":"h2"},
{"id":"soc-h-ethics-12#t4","kind":"term","title":"현실주의","text":"국제 사회를 무정부 상태로 보고, 국가는 자국의 이익과 힘을 추구하며 평화는 세력 균형으로 유지된다고 보는 관점입니다.","keywords":["현실주의"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-12","grade":"h2"},
{"id":"soc-h-ethics-12#t5","kind":"term","title":"이상주의","text":"국제법과 국제기구, 인간의 이성과 도덕을 통해 분쟁을 막고 평화를 이룰 수 있다고 보는 관점입니다.","keywords":["이상주의"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-12","grade":"h2"},
{"id":"soc-h-ethics-12#t6","kind":"term","title":"영구 평화론","text":"칸트가 1795년에 제시한 평화 이론입니다. 공화정, 자유로운 국가들의 연맹, 보편적 우호를 영구 평화의 조건으로 들었습니다.","keywords":["영구 평화론"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-12","grade":"h2"},
{"id":"soc-h-ethics-12#t7","kind":"term","title":"형사적 정의","text":"집단 살해·반인도적 범죄·전쟁 범죄처럼 국제 사회의 평화를 해치는 범죄를 저지른 사람을 처벌하여 세우는 정의입니다.","keywords":["형사적 정의"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-12","grade":"h2"},
{"id":"soc-h-ethics-12#t8","kind":"term","title":"분배적 정의","text":"국가 사이의 부와 자원의 격차, 빈곤과 기아 문제를 바로잡으려는 정의입니다.","keywords":["분배적 정의"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-12","grade":"h2"},
{"id":"soc-h-ethics-12#t9","kind":"term","title":"난민","text":"인종·종교·국적·정치적 의견 등 때문에 박해를 받을 우려가 있어 자기 나라를 떠났고, 자기 나라의 보호를 받을 수 없는 사람입니다.","keywords":["난민"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-12","grade":"h2"},
{"id":"soc-h-ethics-12#f0","kind":"faq","title":"통일 비용이 그렇게 많이 드는데 왜 통일 이야기를 해요?","text":"통일 비용이 큰 것은 사실이고, 그래서 통일에 신중해야 한다는 의견도 있습니다. 다만 통일 비용은 통일 이후 일정 기간 드는 한시적 비용이고, 지금도 분단 때문에 분단 비용이 계속 들고 있습니다. 또 통일이 되면 통일 편익이 생깁니다. 통일을 어떻게 볼지는 사람마다 다를 수 있지만, 이런 비용과 이익을 함께 따져 보고 판단하는 것이 중요합니다.","keywords":["통일 비용"],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-12","grade":"h2"},
{"id":"soc-h-ethics-12#f1","kind":"faq","title":"현실주의랑 이상주의 중에 뭐가 맞아요?","text":"어느 한쪽만 옳다고 하기는 어렵습니다. 현실주의는 국가가 이익과 힘을 앞세우는 현실을 냉정하게 보게 해 주고, 이상주의는 국제법과 국제기구로 협력할 수 있다는 가능성을 보여 줍니다. 실제 국제 사회에서는 힘의 현실을 인정하면서도 협력의 제도를 넓혀 가는 노력이 함께 이루어지고 있습니다.","keywords":["현실주의","이상주의"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-12","grade":"h2"},
{"id":"soc-h-ethics-12#f2","kind":"faq","title":"싱어는 왜 해외 원조가 의무라고 해요?","text":"싱어는 공리주의자로, 모든 사람의 고통을 똑같이 중요하게 여겨야 한다고 보았습니다. 얕은 연못에 빠진 아이를 옷이 젖는다는 이유로 구하지 않는 것이 잘못이듯, 큰 희생 없이 굶주린 사람을 도울 수 있는데 돕지 않는 것도 잘못이라는 것입니다. 그 사람이 멀리 산다는 것은 도덕적으로 중요한 차이가 아니라고 보았습니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-12","grade":"h2"},
{"id":"soc-h-ethics-12#f3","kind":"faq","title":"롤스도 원조가 의무라는데 싱어랑 뭐가 달라요?","text":"둘 다 원조를 의무로 보지만 목적이 다릅니다. 싱어는 세계 전체의 고통을 줄이는 것을 목적으로 보고 고통받는 개인을 돕는 데 초점을 둡니다. 롤스는 고통받는 사회가 정의롭고 안정된 제도를 갖추어 질서 정연한 사회가 되도록 돕는 것을 목적으로 보며, 그 목표에 이르면 원조의 의무가 끝난다고 봅니다.","keywords":[],"ref":{"tab":"faq","idx":3},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-12","grade":"h2"},
{"id":"soc-h-ethics-12#m0","kind":"mistake","title":"자주 하는 실수","text":"분단 비용·통일 비용·평화 비용을 헷갈리는 실수 — 언제 생기는지를 봅니다. 분단이 계속되는 동안 생기는 손실은 분단 비용, 통일 이전에 평화를 위해 쓰는 돈은 평화 비용, 통일 이후 통합에 드는 돈은 통일 비용입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-12","grade":"h2"},
{"id":"soc-h-ethics-12#m1","kind":"mistake","title":"자주 하는 실수","text":"롤스의 원조 목적을 \"나라 사이의 부를 똑같이 나누는 것\"으로 아는 실수 — 롤스는 고통받는 사회가 질서 정연한 사회가 되도록 돕는 것을 목적으로 보고, 그 목표에 이르면 원조의 의무가 끝난다고 보았습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-12","grade":"h2"},
{"id":"soc-h-ethics-12#m2","kind":"mistake","title":"자주 하는 실수","text":"칸트가 세계 국가를 주장했다고 아는 실수 — 칸트는 각 나라가 독립을 유지하면서 맺는 자유로운 국가들의 연맹을 제시하였습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-ethics","unit":"soc-h-ethics-12","grade":"h2"},
{"id":"soc-h-geo-01","kind":"unit","title":"세계화와 세계시민","text":"세계화를 지역·국가·세계라는 여러 공간 규모(스케일)에서 살펴보고, 세계화를 이끄는 주체와 세계화·지역화의 상호 작용을 이해하며, 긴밀하게 연결된 세계에서 세계시민이 할 일을 생각합니다. 지리적 스케일의 의미를 알고, 같은 현상을 지역·국가·세계 규모에서 다르게 해석할 수 있다. 국가·기업·국제기구·시민이 세계화 과정에서 서로 영향을 주고받는 모습을 설명…","keywords":["지리적 스케일","다중 스케일 관점","세계화","지역화","세방화","다국적 기업","국제기구","비정부 기구","공정 무역","세계시민"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-01","grade":"h2"},
{"id":"soc-h-geo-01#c0","kind":"concept","title":"지리적 스케일 — 어느 규모에서 볼 것인가","text":"지리적 스케일(공간 규모) 은 어떤 현상을 바라보고 분석하는 공간의 범위를 말합니다. 흔히 지역(로컬), 국가, 세계(글로벌) 규모로 나누며, 그 사이에 여러 나라를 묶은 권역 규모를 두기도 합니다. 같은 현상이라도 어느 스케일에서 보느냐에 따라 보이는 것이 달라집니다. 기후 변화를 예","keywords":["지리적 스케일"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-01","grade":"h2"},
{"id":"soc-h-geo-01#c1","kind":"concept","title":"세계화를 이끄는 주체들","text":"세계화는 저절로 일어나지 않습니다. 여러 주체가 각자의 목적을 가지고 움직이며 서로 영향을 주고받는 가운데 진행됩니다. 주체 · 하는 일의 예 국가 · 무역 협정을 맺고 관세를 정하며, 외국 기업의 투자를 끌어들이거나 규제함 기업 · 여러 나라에 공장·지사를 두고(다국적 기업), 부품과","keywords":["세계화","다국적 기업","국제기구","비정부 기구","공정 무역"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-01","grade":"h2"},
{"id":"soc-h-geo-01#c2","kind":"concept","title":"세계화와 지역화, 그리고 세방화","text":"세계화는 사람·상품·자본·정보가 국경을 넘어 활발히 오가며 세계가 긴밀하게 연결되는 현상입니다. 지역화는 지역의 고유한 자연환경·문화·특산물이 그 지역만의 경쟁력이 되어 세계적으로 가치를 인정받는 현상입니다. 두 현상은 반대 방향처럼 보이지만 실제로는 함께 진행됩니다. 세계 어디서나 비","keywords":["세계화","지역화","세방화"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-01","grade":"h2"},
{"id":"soc-h-geo-01#c3","kind":"concept","title":"다중 스케일로 세계화 사례 읽기","text":"다중 스케일 관점은 하나의 현상을 지역·국가·세계 규모에서 함께 살펴보고, 각 규모가 서로 어떻게 이어져 있는지 분석하는 방법입니다. 커피 한 잔이 우리 손에 오기까지를 생각해 봅시다. 세계 스케일: 커피는 주로 열대 지역에서 재배되어 세계 곳곳으로 팔려 나갑니다. 국제 원두 가격은 세","keywords":["다중 스케일 관점","세계화"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-01","grade":"h2"},
{"id":"soc-h-geo-01#c4","kind":"concept","title":"연결된 세계의 세계시민","text":"세계시민은 자신을 한 나라의 국민이면서 동시에 지구 공동체의 구성원으로 여기고, 인권·평화·환경 같은 인류 공동의 가치를 위해 책임 있게 행동하는 사람입니다. 세계가 긴밀하게 연결될수록 한 곳의 문제는 다른 곳의 문제가 됩니다. 한 지역에서 생긴 감염병이 빠르게 퍼지고, 오염 물질이 국","keywords":["공정 무역","세계시민"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-01","grade":"h2"},
{"id":"soc-h-geo-01#t0","kind":"term","title":"지리적 스케일","text":"어떤 현상을 바라보고 분석하는 공간의 범위(규모)입니다. 지역(로컬)·국가·세계(글로벌) 규모로 나누어 봅니다. 지도의 축척과는 다른 뜻입니다.","keywords":["지리적 스케일"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-01","grade":"h2"},
{"id":"soc-h-geo-01#t1","kind":"term","title":"다중 스케일 관점","text":"하나의 현상을 지역·국가·세계 규모에서 함께 살펴보고, 규모 사이의 연결을 분석하는 관점입니다.","keywords":["다중 스케일 관점"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-01","grade":"h2"},
{"id":"soc-h-geo-01#t2","kind":"term","title":"세계화","text":"사람·상품·자본·정보가 국경을 넘어 활발히 오가며 세계가 긴밀하게 연결되는 현상입니다.","keywords":["세계화"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-01","grade":"h2"},
{"id":"soc-h-geo-01#t3","kind":"term","title":"지역화","text":"지역의 고유한 자연환경·문화·특산물이 경쟁력이 되어 세계적으로 가치를 인정받는 현상입니다.","keywords":["지역화"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-01","grade":"h2"},
{"id":"soc-h-geo-01#t4","kind":"term","title":"세방화","text":"세계화와 지역화가 결합한 현상입니다. 글로컬라이제이션, 세계지역화라고도 합니다. 예: 다국적 기업이 나라마다 메뉴를 바꾸는 것","keywords":["세방화"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-01","grade":"h2"},
{"id":"soc-h-geo-01#t5","kind":"term","title":"다국적 기업","text":"둘 이상의 나라에 지사·공장·연구소를 두고 세계를 무대로 활동하는 기업입니다.","keywords":["다국적 기업"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-01","grade":"h2"},
{"id":"soc-h-geo-01#t6","kind":"term","title":"국제기구","text":"여러 나라가 공동의 목적을 위해 만든 조직입니다. 예: 세계 무역 기구(WTO), 국제 연합(UN)","keywords":["국제기구"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-01","grade":"h2"},
{"id":"soc-h-geo-01#t7","kind":"term","title":"비정부 기구","text":"NGO라고도 합니다. 정부에 속하지 않은 시민들이 인권·환경·빈곤 같은 공익을 위해 만든 단체입니다.","keywords":["비정부 기구"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-01","grade":"h2"},
{"id":"soc-h-geo-01#t8","kind":"term","title":"공정 무역","text":"생산자에게 정당한 대가를 지불하고 노동 환경과 자연환경을 보호하며 거래하는 무역 방식입니다.","keywords":["공정 무역"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-01","grade":"h2"},
{"id":"soc-h-geo-01#t9","kind":"term","title":"세계시민","text":"자신을 지구 공동체의 구성원으로 여기고 인권·평화·환경 같은 인류 공동의 가치를 위해 책임 있게 행동하는 사람입니다.","keywords":["세계시민"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-01","grade":"h2"},
{"id":"soc-h-geo-01#f0","kind":"faq","title":"세방화랑 세계지역화, 글로컬라이제이션은 다른 말이에요?","text":"모두 같은 현상을 가리키는 말입니다. 영어 글로벌(global)과 로컬(local)을 합친 글로컬라이제이션을 우리말로 옮기면서 세방화, 세계지역화처럼 책마다 표현이 조금씩 다를 뿐입니다. 핵심은 세계화와 지역화가 함께 일어난다는 점입니다.","keywords":["지역화","세방화"],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-01","grade":"h2"},
{"id":"soc-h-geo-01#f1","kind":"faq","title":"스케일이랑 축척은 뭐가 달라요?","text":"축척은 지도 위의 거리를 실제 거리로 나눈 비율로, 지도를 얼마나 줄여 그렸는지를 나타냅니다. 이 단원의 지리적 스케일은 현상을 분석하는 공간의 범위(지역·국가·세계)를 뜻합니다. 영어로는 둘 다 scale이라고 해서 헷갈리기 쉬우니, 문맥을 보고 구별하세요.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-01","grade":"h2"},
{"id":"soc-h-geo-01#f2","kind":"faq","title":"세계시민이 되려면 외국에 나가 봐야 하나요?","text":"그렇지 않습니다. 세계시민은 사는 곳이 아니라 생각과 태도로 정해집니다. 내가 사는 곳에서 세계 문제에 관심을 갖고, 다른 문화를 존중하며, 윤리적 소비나 자원 절약을 실천하는 것도 세계시민의 행동입니다.","keywords":["세계시민"],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-01","grade":"h2"},
{"id":"soc-h-geo-01#m0","kind":"mistake","title":"자주 하는 실수","text":"지리적 스케일을 지도의 축척과 혼동하는 실수 — 스케일은 현상을 분석하는 공간의 범위(지역·국가·세계)입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-01","grade":"h2"},
{"id":"soc-h-geo-01#m1","kind":"mistake","title":"자주 하는 실수","text":"세계화와 지역화를 반대 현상으로만 보는 실수 — 두 현상은 함께 진행되며, 둘이 결합한 현상을 세방화라고 합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-01","grade":"h2"},
{"id":"soc-h-geo-01#m2","kind":"mistake","title":"자주 하는 실수","text":"세계화의 주체를 국가와 기업으로만 보는 실수 — 국제기구와 시민·시민 단체도 세계화의 방향에 영향을 줍니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-01","grade":"h2"},
{"id":"soc-h-geo-02","kind":"unit","title":"지역 통합과 분리","text":"여러 나라가 경제 블록으로 묶이거나 한 나라 안의 지역이 분리를 요구하는 사례와 그 원인을 살펴, 지역이 사회적으로 만들어지고 늘 변하는 실체라는 것을 이해합니다. 지역이 사회적으로 만들어지고 변하는 역동적 실체임을 설명할 수 있다. 지역 경제 통합의 단계를 구분하고, 유럽 연합·동남아시아 국가 연합·미국·멕시코·캐나다 협정의 특징을 비교할 수 있다. 언…","keywords":["지역","지역 경제 통합","자유 무역 협정","관세 동맹","공동 시장","경제 동맹","완전 경제 통합","분리 독립 운동","브렉시트"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-02","grade":"h2"},
{"id":"soc-h-geo-02#c0","kind":"concept","title":"지역은 만들어지고 변한다","text":"지역은 지표 공간 가운데 다른 곳과 구별되는 특성을 지닌 범위입니다. 지역을 나누는 기준은 기후·지형 같은 자연환경일 수도 있고, 언어·종교·경제 활동·정치적 경계 같은 인문 환경일 수도 있습니다. 중요한 점은 지역이 처음부터 정해진 고정된 칸이 아니라는 것입니다. 지역은 사람들이 어떤","keywords":["지역"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-02","grade":"h2"},
{"id":"soc-h-geo-02#c1","kind":"concept","title":"지역 경제 통합의 단계","text":"지역 경제 통합은 가까운 나라들이 무역 장벽을 낮추고 경제적으로 협력하기 위해 하나의 경제 블록을 이루는 것입니다. 통합의 정도에 따라 다음과 같은 단계로 나눕니다. 뒤 단계는 앞 단계의 내용을 모두 포함합니다. 단계 · 더해지는 내용 자유 무역 협정 · 회원국끼리 관세 등 무역 장벽을","keywords":["지역","지역 경제 통합","자유 무역 협정","관세 동맹","공동 시장","경제 동맹","완전 경제 통합"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-02","grade":"h2"},
{"id":"soc-h-geo-02#c2","kind":"concept","title":"지역 통합의 사례 — EU·ASEAN·USMCA","text":"세계 곳곳에서 이웃 나라들이 경제 블록을 이루고 있습니다. 대표적인 세 사례를 비교해 봅시다. 경제 블록 · 특징 유럽 연합(EU) · 1993년 출범. 회원국 사이에 상품·서비스·사람·자본이 자유롭게 오가는 단일 시장을 이루고, 많은 회원국이 공동 화폐 유로를 씀. 공동 시장을 넘어 ","keywords":["지역","자유 무역 협정","공동 시장","경제 동맹"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-02","grade":"h2"},
{"id":"soc-h-geo-02#c3","kind":"concept","title":"지역 분리 — 하나였던 지역이 갈라질 때","text":"통합과 반대로, 한 나라 안의 지역이 분리 독립이나 더 큰 자치를 요구하기도 합니다. 그 원인은 대개 여러 가지가 얽혀 있습니다. 언어·민족: 나라의 다수 집단과 언어나 민족이 다른 지역 주민들이 고유한 정체성을 지키려 합니다. 종교: 종교가 다른 집단 사이의 갈등이 분리 요구로 이어집","keywords":["지역"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-02","grade":"h2"},
{"id":"soc-h-geo-02#c4","kind":"concept","title":"영국의 유럽 연합 탈퇴(브렉시트)","text":"브렉시트(Brexit) 는 영국(Britain)과 탈퇴(exit)를 합친 말로, 영국이 유럽 연합에서 탈퇴한 일을 가리킵니다. 영국은 2016년 국민 투표에서 탈퇴 찬성이 과반을 차지한 뒤 협상을 거쳐 2020년 유럽 연합에서 공식 탈퇴했습니다. 이로써 유럽 연합 회원국은 28개국에서 ","keywords":["지역","브렉시트"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-02","grade":"h2"},
{"id":"soc-h-geo-02#c5","kind":"concept","title":"통합과 분리가 삶과 세계에 미치는 영향","text":"지역 통합과 분리는 국가의 일만이 아니라 주민의 일상까지 바꿉니다. 구분 · 긍정적 영향 · 부정적 영향 지역 통합 · 시장이 넓어져 기업의 판매가 늘고, 관세가 사라져 소비자가 상품을 더 싸게 삼. 국경을 넘어 일하고 공부하기 쉬움 · 경쟁력이 약한 산업이 타격을 받음. 회원국 사이의","keywords":["지역"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-02","grade":"h2"},
{"id":"soc-h-geo-02#t0","kind":"term","title":"지역","text":"지표 공간 가운데 다른 곳과 구별되는 특성을 지닌 범위입니다. 사회적으로 만들어지고 시간에 따라 변합니다.","keywords":["지역"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-02","grade":"h2"},
{"id":"soc-h-geo-02#t1","kind":"term","title":"지역 경제 통합","text":"이웃한 나라들이 무역 장벽을 낮추고 경제적으로 협력하기 위해 하나의 경제 블록을 이루는 것입니다.","keywords":["지역 경제 통합"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-02","grade":"h2"},
{"id":"soc-h-geo-02#t2","kind":"term","title":"자유 무역 협정","text":"FTA라고도 합니다. 회원국끼리 관세 등 무역 장벽을 없애거나 낮추는 단계입니다. 회원국 밖의 나라에 대한 관세는 나라마다 따로 정합니다.","keywords":["자유 무역 협정"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-02","grade":"h2"},
{"id":"soc-h-geo-02#t3","kind":"term","title":"관세 동맹","text":"자유 무역 협정에 더해 회원국 밖의 나라에 공동 관세를 매기는 단계입니다.","keywords":["관세 동맹"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-02","grade":"h2"},
{"id":"soc-h-geo-02#t4","kind":"term","title":"공동 시장","text":"관세 동맹에 더해 노동·자본 같은 생산 요소가 회원국 사이를 자유롭게 이동하는 단계입니다.","keywords":["공동 시장"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-02","grade":"h2"},
{"id":"soc-h-geo-02#t5","kind":"term","title":"경제 동맹","text":"공동 시장에 더해 회원국이 재정·금융·통화 같은 경제 정책을 함께 조정하는 단계입니다. 예: 유럽 연합","keywords":["경제 동맹"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-02","grade":"h2"},
{"id":"soc-h-geo-02#t6","kind":"term","title":"완전 경제 통합","text":"회원국 위에 초국가적 기구를 두고 경제 정책을 하나로 운영하는, 경제 통합의 가장 높은 단계입니다.","keywords":["완전 경제 통합"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-02","grade":"h2"},
{"id":"soc-h-geo-02#t7","kind":"term","title":"분리 독립 운동","text":"한 나라 안의 지역이 언어·종교·민족·경제·역사 등의 차이를 이유로 그 나라에서 떨어져 나와 독립하려는 움직임입니다.","keywords":["분리 독립 운동"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-02","grade":"h2"},
{"id":"soc-h-geo-02#t8","kind":"term","title":"브렉시트","text":"영국(Britain)과 탈퇴(exit)를 합친 말로, 영국이 2020년 유럽 연합에서 탈퇴한 일을 가리킵니다.","keywords":["브렉시트"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-02","grade":"h2"},
{"id":"soc-h-geo-02#f0","kind":"faq","title":"유럽 연합 회원국은 모두 유로를 쓰나요?","text":"아닙니다. 많은 회원국이 유로를 쓰지만, 덴마크·스웨덴·폴란드처럼 자기 나라 화폐를 계속 쓰는 회원국도 있습니다. 유로를 쓰려면 물가·재정 등 정해진 조건을 갖추어야 하고, 나라마다 사정과 선택이 다르기 때문입니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-02","grade":"h2"},
{"id":"soc-h-geo-02#f1","kind":"faq","title":"자유 무역 협정이랑 관세 동맹은 뭐가 달라요?","text":"둘 다 회원국끼리는 관세를 없애거나 낮춥니다. 차이는 회원국 밖의 나라에 대한 관세입니다. 자유 무역 협정은 나라마다 따로 정하고, 관세 동맹은 모든 회원국이 같은 공동 관세를 매깁니다.","keywords":["자유 무역 협정","관세 동맹"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-02","grade":"h2"},
{"id":"soc-h-geo-02#f2","kind":"faq","title":"지역 통합이 되면 회원국은 나라가 아니게 되나요?","text":"그렇지 않습니다. 유럽 연합처럼 깊이 통합된 경우에도 회원국은 각자 정부와 의회를 가진 독립된 나라입니다. 다만 통합이 깊어질수록 무역·화폐 같은 일부 분야의 결정 권한을 공동 기구와 나누게 됩니다.","keywords":["지역"],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-02","grade":"h2"},
{"id":"soc-h-geo-02#m0","kind":"mistake","title":"자주 하는 실수","text":"이름에 \"공동 시장\"이 들어 있으면 공동 시장 단계라고 단정하는 실수 — 역외 공동 관세, 생산 요소의 이동 같은 실제 내용으로 단계를 판단합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-02","grade":"h2"},
{"id":"soc-h-geo-02#m1","kind":"mistake","title":"자주 하는 실수","text":"자유 무역 협정만 맺어도 역외 공동 관세가 생긴다고 생각하는 실수 — 공동 관세는 관세 동맹 단계부터입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-02","grade":"h2"},
{"id":"soc-h-geo-02#m2","kind":"mistake","title":"자주 하는 실수","text":"유럽 연합 회원국이 모두 유로를 쓴다고 생각하는 실수 — 자기 나라 화폐를 쓰는 회원국도 있습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-02","grade":"h2"},
{"id":"soc-h-geo-03","kind":"unit","title":"지리 정보와 지리정보기술","text":"지리 정보의 유형과 지리 정보를 모으는 원격 탐사·위성 항법 시스템, 지리 정보를 분석하는 지리 정보 시스템(GIS)을 알고, 생활과 공간적 의사 결정에 쓰이는 사례와 위치 정보 보호·정보 격차 문제를 살펴봅니다. 지리 정보를 공간 정보·속성 정보·관계 정보로 구분할 수 있다. 원격 탐사와 위성 항법 시스템이 지리 정보를 모으는 방식과 쓰임을 설명할 수 …","keywords":["지리 정보","공간 정보","속성 정보","관계 정보","원격 탐사","위성 항법 시스템","지리 정보 시스템(GIS)","중첩 분석","버퍼 분석","정보 격차"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-03","grade":"h2"},
{"id":"soc-h-geo-03#c0","kind":"concept","title":"지리 정보의 세 가지 유형","text":"지리 정보는 장소와 지역에 관한 정보를 통틀어 이르는 말입니다. 지리 정보는 무엇을 알려 주느냐에 따라 세 가지로 나눕니다. 유형 · 뜻 · 예 공간 정보 · 장소나 지역의 위치와 형태 · 위도·경도, 주소, 해안선·경계선의 모양 속성 정보 · 장소나 지역이 지닌 자연적·인문적 특성 ·","keywords":["지리 정보","공간 정보","속성 정보","관계 정보"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-03","grade":"h2"},
{"id":"soc-h-geo-03#c1","kind":"concept","title":"지리 정보를 모으는 기술 — 원격 탐사와 위성 항법 시스템","text":"예전에는 지리 정보를 주로 현지 조사(직접 가서 관찰·측정·면담)와 문헌·통계로 모았습니다. 오늘날에는 첨단 기술이 더해져 더 넓은 지역의 정보를 더 빠르게 모읍니다. 원격 탐사 인공위성·항공기·드론에 실은 센서로, 대상에 직접 닿지 않고 멀리서 지표의 정보를 얻는 기술입니다. 센서는 ","keywords":["지리 정보","원격 탐사","위성 항법 시스템"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-03","grade":"h2"},
{"id":"soc-h-geo-03#c2","kind":"concept","title":"지리 정보 시스템(GIS)과 중첩 분석","text":"지리 정보 시스템(GIS) 은 지리 정보를 컴퓨터에 입력·저장하고, 이를 분석하여 지도·그래프 등으로 표현하는 체계입니다. GIS는 지리 정보를 주제별 레이어(층) 로 나누어 저장합니다. 도로 레이어, 하천 레이어, 토지 이용 레이어, 인구 레이어처럼, 투명한 필름에 주제별로 그린 지도","keywords":["지리 정보","지리 정보 시스템(GIS)","중첩 분석"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-03","grade":"h2"},
{"id":"soc-h-geo-03#c3","kind":"concept","title":"디지털 전환 시대, 생활 속 지리정보기술","text":"디지털 전환이 빨라지면서 지리정보기술은 일상과 공공 영역 곳곳에 쓰입니다. 분야 · 활용 모습 지도 앱·길 찾기 · 위성 항법 시스템으로 현재 위치를 찾고, 실시간 교통 정보를 반영해 빠른 길과 도착 예정 시각을 알려 줌 위치 기반 서비스 · 내 주변의 병원·약국·대중교통 정보를 찾아 ","keywords":["위성 항법 시스템"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-03","grade":"h2"},
{"id":"soc-h-geo-03#c4","kind":"concept","title":"지리정보기술을 쓸 때의 문제 — 위치 정보 보호와 정보 격차","text":"지리정보기술이 편리한 만큼 조심하고 함께 해결해야 할 문제도 있습니다. 위치 정보 보호 스마트폰과 여러 앱은 사용자의 위치를 계속 기록할 수 있습니다. 위치 기록이 쌓이면 집·학교·자주 가는 곳이 드러나고, 유출되면 범죄나 사생활 침해에 악용될 수 있습니다. 그래서 우리나라는 법으로, ","keywords":["정보 격차"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-03","grade":"h2"},
{"id":"soc-h-geo-03#t0","kind":"term","title":"지리 정보","text":"장소와 지역에 관한 정보를 통틀어 이르는 말입니다. 공간 정보·속성 정보·관계 정보로 나눕니다.","keywords":["지리 정보"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-03","grade":"h2"},
{"id":"soc-h-geo-03#t1","kind":"term","title":"공간 정보","text":"장소나 지역의 위치와 형태에 관한 정보입니다. 예: 위도·경도, 주소, 해안선의 모양","keywords":["공간 정보"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-03","grade":"h2"},
{"id":"soc-h-geo-03#t2","kind":"term","title":"속성 정보","text":"장소나 지역이 지닌 자연적·인문적 특성에 관한 정보입니다. 예: 기온, 강수량, 인구, 토지 이용","keywords":["속성 정보"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-03","grade":"h2"},
{"id":"soc-h-geo-03#t3","kind":"term","title":"관계 정보","text":"한 장소나 지역이 다른 곳과 맺는 관계에 관한 정보입니다. 예: 이웃함(인접성), 교통로로 이어짐(연결성), 사람·물자의 이동","keywords":["관계 정보"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-03","grade":"h2"},
{"id":"soc-h-geo-03#t4","kind":"term","title":"원격 탐사","text":"인공위성·항공기·드론에 실은 센서로 대상에 직접 닿지 않고 멀리서 지표의 정보를 얻는 기술입니다.","keywords":["원격 탐사"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-03","grade":"h2"},
{"id":"soc-h-geo-03#t5","kind":"term","title":"위성 항법 시스템","text":"여러 인공위성이 보내는 신호를 받아 수신기의 위치와 시각을 알아내는 체계입니다. 미국의 GPS가 대표적입니다.","keywords":["위성 항법 시스템"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-03","grade":"h2"},
{"id":"soc-h-geo-03#t6","kind":"term","title":"지리 정보 시스템(GIS)","text":"지리 정보를 컴퓨터에 입력·저장하고 분석하여 지도 등으로 표현하는 체계입니다.","keywords":["지리 정보 시스템(GIS)"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-03","grade":"h2"},
{"id":"soc-h-geo-03#t7","kind":"term","title":"중첩 분석","text":"GIS에서 여러 주제의 레이어를 겹쳐 조건을 모두 만족하는 곳을 찾는 분석 방법입니다.","keywords":["중첩 분석"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-03","grade":"h2"},
{"id":"soc-h-geo-03#t8","kind":"term","title":"버퍼 분석","text":"어떤 시설이나 선(도로·하천)에서 일정한 거리 안에 드는 범위를 표시하는 분석 방법입니다.","keywords":["버퍼 분석"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-03","grade":"h2"},
{"id":"soc-h-geo-03#t9","kind":"term","title":"정보 격차","text":"기기·인터넷을 쓸 수 있는지, 다룰 줄 아는지에 따라 정보와 서비스를 누리는 정도가 달라지는 것입니다. 디지털 격차라고도 합니다.","keywords":["정보 격차"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-03","grade":"h2"},
{"id":"soc-h-geo-03#f0","kind":"faq","title":"GPS랑 GIS는 뭐가 달라요?","text":"GPS는 위성 신호로 내 위치를 알아내는 위성 항법 시스템이고, GIS는 모은 지리 정보를 저장·분석·표현하는 지리 정보 시스템입니다. 글자는 비슷하지만 하는 일이 다릅니다. 지도 앱을 예로 들면, GPS가 내 위치를 찾고 GIS가 도로 자료를 분석해 빠른 길을 찾아 줍니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-03","grade":"h2"},
{"id":"soc-h-geo-03#f1","kind":"faq","title":"원격 탐사는 꼭 인공위성으로만 하나요?","text":"아닙니다. 항공기나 드론에 센서를 실어도 원격 탐사입니다. 인공위성은 넓은 지역을 주기적으로 관측하는 데 유리하고, 드론은 좁은 지역을 아주 자세하게 볼 때 유리합니다. 대상에 직접 닿지 않고 멀리서 정보를 얻는다는 점이 핵심입니다.","keywords":["원격 탐사"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-03","grade":"h2"},
{"id":"soc-h-geo-03#f2","kind":"faq","title":"위치 권한을 꺼 두면 길 찾기를 아예 못 하나요?","text":"대부분의 지도 앱은 위치 권한이 없어도 출발지를 직접 입력하면 길을 찾아 줍니다. 다만 \"현재 위치\"를 자동으로 잡는 기능은 쓸 수 없습니다. 길을 찾을 때만 \"앱을 사용하는 동안 허용\"으로 두는 것도 좋은 방법입니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-03","grade":"h2"},
{"id":"soc-h-geo-03#f3","kind":"faq","title":"공간 정보랑 관계 정보가 헷갈려요.","text":"공간 정보는 그 장소 하나만 보고 알 수 있는 위치와 모양이고, 관계 정보는 두 곳 이상을 함께 보아야 알 수 있는 연결과 이동입니다. \"A역은 북위 37° 부근에 있다\"는 공간 정보, \"A역과 B역은 지하철로 이어져 있다\"는 관계 정보입니다.","keywords":["공간 정보","관계 정보"],"ref":{"tab":"faq","idx":3},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-03","grade":"h2"},
{"id":"soc-h-geo-03#m0","kind":"mistake","title":"자주 하는 실수","text":"GPS와 GIS를 같은 것으로 아는 실수 — GPS는 위치를 알아내는 위성 항법 시스템, GIS는 지리 정보를 저장·분석·표현하는 지리 정보 시스템입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-03","grade":"h2"},
{"id":"soc-h-geo-03#m1","kind":"mistake","title":"자주 하는 실수","text":"중첩 분석에서 조건을 하나라도 만족하는 곳을 모두 고르는 실수 — 중첩 분석은 모든 레이어가 겹치는 곳, 곧 조건을 동시에 만족하는 곳을 찾습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-03","grade":"h2"},
{"id":"soc-h-geo-03#m2","kind":"mistake","title":"자주 하는 실수","text":"가중치가 있는 평가에서 점수만 더하는 실수 — 조건마다 점수에 가중치를 곱한 뒤 더해야 합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-03","grade":"h2"},
{"id":"soc-h-geo-04","kind":"unit","title":"세계의 기후와 인간 생활","text":"기후 요소와 기후 요인, 쾨펜의 기후 구분을 알고, 열대·건조·온대·냉대·한대·고산 기후 지역 사람들이 기후에 적응하거나 기후를 활용하고 극복하며 사는 모습을 살펴봅니다. 기후 요소와 기후 요인을 구별하고, 쾨펜의 기준으로 큰 기후대를 구분할 수 있다. 열대·건조 기후 지역의 가옥과 농업·목축을 기후 특성과 관련지어 설명할 수 있다. 온대·냉대·한대·고산…","keywords":["기후","기후 요소","기후 요인","기온의 연교차","쾨펜의 기후 구분","고상 가옥","이동식 화전 농업","플랜테이션","오아시스 농업","수목 농업"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-04","grade":"h2"},
{"id":"soc-h-geo-04#c0","kind":"concept","title":"기후 요소·기후 요인과 쾨펜의 기후 구분","text":"날씨는 그날그날의 대기 상태이고, 기후는 한 지역에서 오랫동안(보통 30년) 되풀이되어 나타나는 평균적인 대기 상태입니다. 기후 요소: 기후를 이루는 대기의 성질 — 기온, 강수, 바람, 습도 등 기후 요인: 기후 요소를 지역마다 다르게 만드는 원인 — 위도, 수륙 분포(바다와 육지의 ","keywords":["기후","기후 요소","기후 요인","기온의 연교차","쾨펜의 기후 구분"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-04","grade":"h2"},
{"id":"soc-h-geo-04#c1","kind":"concept","title":"열대 기후 지역의 생활","text":"열대 기후는 1년 내내 덥습니다. 적도 부근의 열대 우림 기후는 연중 비가 많고, 오후에 강한 소나기(스콜)가 자주 내립니다. 그 바깥쪽의 사바나 기후는 비가 많이 오는 우기와 비가 거의 없는 건기가 뚜렷합니다. 가옥 — 고상 가옥 덥고 습하며 비가 많으므로, 기둥을 세워 바닥을 땅에서","keywords":["기후","고상 가옥","이동식 화전 농업"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-04","grade":"h2"},
{"id":"soc-h-geo-04#c2","kind":"concept","title":"건조 기후 지역의 생활","text":"건조 기후는 비가 적어 연 강수량이 증발량보다 적은 기후입니다. 연 강수량이 대체로 250 mm 미만인 사막 기후와 250~500 mm 정도로 짧은 풀이 자라는 스텝 기후로 나눕니다. 구름이 적어 낮에는 햇볕이 강하고 밤에는 열이 쉽게 빠져나가므로 일교차가 매우 큽니다. 농업 — 오아시","keywords":["기후","오아시스 농업"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-04","grade":"h2"},
{"id":"soc-h-geo-04#c3","kind":"concept","title":"온대 기후 지역의 생활","text":"온대 기후는 사계절이 나타나며 사람이 살기에 알맞아 세계 인구가 많이 모여 있습니다. 같은 온대라도 강수의 계절 분포에 따라 생활 모습이 다릅니다. 계절풍(몬순) 지역과 벼농사 동아시아와 남아시아에는 계절에 따라 방향이 바뀌는 계절풍이 붑니다. 여름에는 바다에서 덥고 습한 바람이 불어와","keywords":["기후","수목 농업"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-04","grade":"h2"},
{"id":"soc-h-geo-04#c4","kind":"concept","title":"냉대·한대·고산 기후 지역의 생활","text":"냉대 기후 겨울이 길고 매우 춥지만 여름은 비교적 따뜻합니다. 유라시아와 북아메리카 대륙의 북부에 넓게 나타납니다. 추위에 강한 침엽수림(타이가) 이 넓게 펼쳐져 목재와 종이의 원료(펄프)를 얻는 임업이 발달했습니다. 한대 기후 가장 더운 달도 평균 기온이 10 °C에 못 미칩니다. 짧","keywords":["기후"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-04","grade":"h2"},
{"id":"soc-h-geo-04#c5","kind":"concept","title":"기후를 활용하고 극복하는 사람들","text":"사람들은 기후에 적응할 뿐 아니라, 기후를 자원으로 활용하거나 기술로 극복하기도 합니다. 분야 · 기후를 활용한 예 · 기후를 극복한 예 관광 · 맑고 건조한 여름을 찾는 지중해 연안의 휴양 관광, 눈이 많은 산지의 스키 관광, 열대 해안의 해변 관광 · 더운 지역에 실내 스키장 등 인","keywords":["기후"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-04","grade":"h2"},
{"id":"soc-h-geo-04#t0","kind":"term","title":"기후","text":"한 지역에서 오랫동안 되풀이되어 나타나는 평균적인 대기 상태입니다. 그날그날의 대기 상태인 날씨와 구별합니다.","keywords":["기후"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-04","grade":"h2"},
{"id":"soc-h-geo-04#t1","kind":"term","title":"기후 요소","text":"기후를 이루는 대기의 성질입니다. 기온, 강수, 바람, 습도 등이 있습니다.","keywords":["기후 요소"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-04","grade":"h2"},
{"id":"soc-h-geo-04#t2","kind":"term","title":"기후 요인","text":"기후 요소를 지역마다 다르게 만드는 원인입니다. 위도, 수륙 분포, 해발 고도, 지형, 해류 등이 있습니다.","keywords":["기후 요인"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-04","grade":"h2"},
{"id":"soc-h-geo-04#t3","kind":"term","title":"기온의 연교차","text":"1년 중 가장 더운 달과 가장 추운 달의 평균 기온 차이입니다. 바다에 가까운 곳일수록 작습니다.","keywords":["기온의 연교차"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-04","grade":"h2"},
{"id":"soc-h-geo-04#t4","kind":"term","title":"쾨펜의 기후 구분","text":"식생 분포에 주목하여 기온과 강수량으로 세계의 기후를 열대·건조·온대·냉대·한대 기후로 나눈 방법입니다.","keywords":["쾨펜의 기후 구분"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-04","grade":"h2"},
{"id":"soc-h-geo-04#t5","kind":"term","title":"고상 가옥","text":"기둥을 세워 바닥을 땅에서 높이 띄운 집입니다. 열대 지역에서 습기·해충·홍수를 피하려고 짓습니다.","keywords":["고상 가옥"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-04","grade":"h2"},
{"id":"soc-h-geo-04#t6","kind":"term","title":"이동식 화전 농업","text":"숲을 불태운 재를 거름 삼아 작물을 기르다가 땅이 메마르면 다른 곳으로 옮기는 열대 지역의 농업입니다.","keywords":["이동식 화전 농업"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-04","grade":"h2"},
{"id":"soc-h-geo-04#t7","kind":"term","title":"플랜테이션","text":"선진국의 자본·기술과 현지의 노동력이 결합하여 천연고무·커피 같은 상품 작물을 대규모로 한 가지씩 재배하는 농업입니다.","keywords":["플랜테이션"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-04","grade":"h2"},
{"id":"soc-h-geo-04#t8","kind":"term","title":"오아시스 농업","text":"건조 지역에서 샘물이나 외래 하천의 물을 이용해 대추야자·밀 등을 기르는 농업입니다.","keywords":["오아시스 농업"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-04","grade":"h2"},
{"id":"soc-h-geo-04#t9","kind":"term","title":"수목 농업","text":"지중해성 기후 지역에서 여름 건조에 강한 올리브·포도·코르크참나무 등을 기르는 농업입니다.","keywords":["수목 농업"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-04","grade":"h2"},
{"id":"soc-h-geo-04#f0","kind":"faq","title":"고상 가옥이랑 툰드라 지역의 띄운 건물은 같은 거예요?","text":"둘 다 바닥을 땅에서 띄웠다는 모양은 비슷하지만 까닭이 다릅니다. 열대의 고상 가옥은 습기·해충·홍수를 피하려는 것이고, 툰드라의 띄운 건물은 건물의 열이 영구 동토층을 녹이지 않게 하려는 것입니다. 모양보다 까닭을 기억해 두면 헷갈리지 않습니다.","keywords":["고상 가옥"],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-04","grade":"h2"},
{"id":"soc-h-geo-04#f1","kind":"faq","title":"적도에 가까우면 다 더운 거 아니에요?","text":"위도만 보면 적도 부근은 덥지만, 기온은 해발 고도에 따라서도 달라집니다. 대체로 100 m 높아질 때마다 약 0.5~0.6 °C씩 낮아지므로, 해발 2,000~3,000 m의 고원은 저지대보다 10 °C 이상 서늘합니다. 그래서 적도 부근 안데스산맥에 1년 내내 봄 같은 고산 도시가 있습니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-04","grade":"h2"},
{"id":"soc-h-geo-04#f2","kind":"faq","title":"건조 기후는 왜 기온이 아니라 강수량으로 나눠요?","text":"건조 기후는 덥든 춥든 물이 모자라 나무가 자라기 어려운 곳이기 때문입니다. 쾨펜은 식생 분포에 주목했으므로, 먼저 강수량이 증발량보다 적은지를 보아 건조 기후를 가려내고, 나머지를 기온으로 나눕니다. 사막은 더운 곳에도, 추운 곳에도 있습니다.","keywords":["기후"],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-04","grade":"h2"},
{"id":"soc-h-geo-04#f3","kind":"faq","title":"같은 온대인데 왜 우리나라는 벼농사, 지중해는 올리브예요?","text":"비가 오는 계절이 다르기 때문입니다. 우리나라 같은 계절풍 지역은 여름에 비가 많아 물이 많이 드는 벼농사에 알맞고, 지중해성 기후는 여름이 건조하여 가뭄에 강한 올리브·포도를 기릅니다.","keywords":[],"ref":{"tab":"faq","idx":3},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-04","grade":"h2"},
{"id":"soc-h-geo-04#m0","kind":"mistake","title":"자주 하는 실수","text":"기후 요소와 기후 요인을 바꾸어 아는 실수 — 기온·강수·바람은 기후 요소(결과), 위도·수륙 분포·해발 고도·해류는 기후 요인(원인)입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-04","grade":"h2"},
{"id":"soc-h-geo-04#m1","kind":"mistake","title":"자주 하는 실수","text":"기후 그래프에서 7월이 가장 춥다고 한대나 냉대로 단정하는 실수 — 남반구는 1월 무렵이 여름입니다. 가장 추운 달과 가장 더운 달의 값으로 판단합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-04","grade":"h2"},
{"id":"soc-h-geo-04#m2","kind":"mistake","title":"자주 하는 실수","text":"고상 가옥(열대)과 흙벽돌집(건조)의 특징을 섞는 실수 — 비가 많은 곳은 지붕 경사가 급하고 바닥을 띄우며, 비가 적은 곳은 지붕이 평평하고 벽이 두껍습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-04","grade":"h2"},
{"id":"soc-h-geo-05","kind":"unit","title":"세계의 지형과 인간 생활","text":"지형을 만드는 내적·외적 작용과 세계의 대지형, 하천·해안·건조·카르스트·화산 지형과 그곳의 생활을 알고, 지형을 관광 자원으로 개발할지 보존할지를 둘러싼 갈등과 지속가능한 이용 방안을 탐구합니다. 지형을 만드는 내적 작용과 외적 작용을 구별하고, 판의 경계에서 나타나는 지형을 설명할 수 있다. 안정육괴, 고기 습곡 산지, 신기 습곡 산지의 특징과 그곳의…","keywords":["내적 작용","외적 작용","안정육괴","고기 습곡 산지","신기 습곡 산지","범람원","삼각주","해안 사구","피오르","카르스트 지형"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-05","grade":"h2"},
{"id":"soc-h-geo-05#c0","kind":"concept","title":"지형을 만드는 두 힘 — 내적 작용과 외적 작용","text":"지구의 표면은 두 가지 힘이 서로 겨루며 모양을 바꾸어 왔습니다. 구분 · 내적 작용 · 외적 작용 에너지 · 지구 내부의 에너지 · 태양 에너지와 중력 하는 일 · 땅을 솟아오르게 하거나 꺼지게 하고, 휘게 하거나 끊음 · 암석을 부수고(풍화) 깎아(침식) 옮겨(운반) 쌓음(퇴적) 결","keywords":["내적 작용","외적 작용"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-05","grade":"h2"},
{"id":"soc-h-geo-05#c1","kind":"concept","title":"세계의 대지형과 생활","text":"대륙의 큰 지형(대지형)은 땅이 만들어진 시기에 따라 셋으로 나눌 수 있습니다. 구분 · 형성 시기 · 특징 · 예 · 자원 안정육괴 · 아주 오래전(시원대) 조산 운동 뒤 · 오랫동안 깎여 평탄한 순상지·구조 평야가 넓음. 지각이 안정 · 캐나다 순상지, 발트 순상지, 오스트레일리아 ","keywords":["안정육괴","고기 습곡 산지","신기 습곡 산지"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-05","grade":"h2"},
{"id":"soc-h-geo-05#c2","kind":"concept","title":"하천 지형과 생활","text":"하천은 상류에서 하류로 흐르며 깎고, 옮기고, 쌓아 여러 지형을 만듭니다. 상류: 경사가 급해 아래로 깊이 깎는 침식이 활발합니다. 폭이 좁고 깊은 V자곡이 나타납니다. 선상지: 하천이 산지를 벗어나 평지로 나오는 곳에서 갑자기 경사가 완만해져 모래·자갈이 부채 모양으로 쌓인 지형입니다","keywords":["범람원","삼각주"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-05","grade":"h2"},
{"id":"soc-h-geo-05#c3","kind":"concept","title":"해안 지형과 생활 — 해안 사구와 피오르","text":"해안은 파랑(파도)과 연안류(해안을 따라 흐르는 바닷물), 바람이 지형을 만듭니다. 침식 지형 — 바다 쪽으로 튀어나온 곶에 파랑의 힘이 모여 깎입니다. 해식애: 파랑에 깎여 생긴 가파른 절벽 시스택: 해식애가 깎이고 남은 바위섬 퇴적 지형 — 육지 쪽으로 들어간 만에 모래가 쌓입니다.","keywords":["해안 사구","피오르"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-05","grade":"h2"},
{"id":"soc-h-geo-05#c4","kind":"concept","title":"건조·카르스트·화산 지형과 관광 자원","text":"독특한 지형은 그 자체로 세계적인 관광 자원이 됩니다. 건조 지형 — 비가 적어 식생이 드문 곳은 바람과 가끔 내리는 비가 지형을 만듭니다. 사구(모래 언덕), 버섯바위(바람에 날린 모래가 바위 아랫부분을 깎음) 와디: 비가 올 때만 물이 흐르는 마른 골짜기. 평소에는 교통로로 쓰입니다","keywords":["카르스트 지형"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-05","grade":"h2"},
{"id":"soc-h-geo-05#c5","kind":"concept","title":"지형의 개발과 보존 — 지속가능한 이용","text":"아름다운 지형을 관광지로 개발하면 지역에 일자리와 소득이 생기고, 도로·숙박 시설 같은 기반 시설도 늘어납니다. 그러나 관광객이 지나치게 몰리면 문제가 생깁니다. 개발을 바라는 쪽의 주장 · 보존을 바라는 쪽의 주장 관광 수입과 일자리로 지역 경제가 살아난다 · 오랜 세월 만들어진 지형","keywords":[],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-05","grade":"h2"},
{"id":"soc-h-geo-05#t0","kind":"term","title":"내적 작용","text":"지구 내부의 에너지로 일어나 땅을 솟게 하거나 꺼지게 하는 작용입니다. 조산 운동, 화산 활동, 지진 등이 있으며 지표의 기복을 크게 만듭니다.","keywords":["내적 작용"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-05","grade":"h2"},
{"id":"soc-h-geo-05#t1","kind":"term","title":"외적 작용","text":"태양 에너지와 중력에 의해 일어나는 풍화·침식·운반·퇴적 작용입니다. 지표의 기복을 작게 만듭니다.","keywords":["외적 작용"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-05","grade":"h2"},
{"id":"soc-h-geo-05#t2","kind":"term","title":"안정육괴","text":"아주 오래전 조산 운동을 받은 뒤 오랫동안 깎여 평탄해진 땅입니다. 지각이 안정되어 있고 철광석이 많습니다. 예: 캐나다 순상지","keywords":["안정육괴"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-05","grade":"h2"},
{"id":"soc-h-geo-05#t3","kind":"term","title":"고기 습곡 산지","text":"고생대 조산 운동으로 만들어져 오래 깎인 산지입니다. 해발 고도가 낮고 경사가 완만하며 석탄이 많습니다. 예: 애팔래치아산맥","keywords":["고기 습곡 산지"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-05","grade":"h2"},
{"id":"soc-h-geo-05#t4","kind":"term","title":"신기 습곡 산지","text":"중생대 말~신생대 조산 운동으로 만들어진 높고 험한 산지입니다. 지각이 불안정해 지진이 잦고 화산 활동이 활발한 곳이 많습니다. 예: 알프스산맥, 안데스산맥","keywords":["신기 습곡 산지"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-05","grade":"h2"},
{"id":"soc-h-geo-05#t5","kind":"term","title":"범람원","text":"하천 중·하류에서 홍수 때 넘친 물이 운반 물질을 쌓아 만든 평야입니다. 자연 제방과 배후 습지로 이루어집니다.","keywords":["범람원"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-05","grade":"h2"},
{"id":"soc-h-geo-05#t6","kind":"term","title":"삼각주","text":"하천이 바다나 호수로 들어가는 하구에 운반 물질이 쌓여 생긴 평탄한 지형입니다. 땅이 기름지지만 홍수와 해수면 상승에 취약합니다.","keywords":["삼각주"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-05","grade":"h2"},
{"id":"soc-h-geo-05#t7","kind":"term","title":"해안 사구","text":"사빈의 모래가 바람에 날려 해안 뒤쪽에 쌓인 모래 언덕입니다. 바람·해일을 막고 지하수를 저장합니다.","keywords":["해안 사구"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-05","grade":"h2"},
{"id":"soc-h-geo-05#t8","kind":"term","title":"피오르","text":"빙하가 깎은 U자곡에 바닷물이 들어와 생긴 좁고 길며 깊은 만입니다. 예: 노르웨이 서해안","keywords":["피오르"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-05","grade":"h2"},
{"id":"soc-h-geo-05#t9","kind":"term","title":"카르스트 지형","text":"석회암이 빗물·지하수에 녹는 용식 작용으로 생긴 지형입니다. 돌리네, 석회동굴, 탑 카르스트 등이 있습니다.","keywords":["카르스트 지형"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-05","grade":"h2"},
{"id":"soc-h-geo-05#f0","kind":"faq","title":"내적 작용이랑 외적 작용은 어떻게 구별해요?","text":"에너지가 어디서 오는지, 땅을 어떻게 바꾸는지 보면 됩니다. 지구 내부의 힘으로 땅을 솟게 하거나 끊는 것(조산 운동, 화산, 지진)은 내적 작용이고, 하천·바람·빙하·파랑처럼 바깥에서 깎고 쌓는 것은 외적 작용입니다. 내적 작용은 기복을 키우고 외적 작용은 기복을 줄입니다.","keywords":["내적 작용","외적 작용"],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-05","grade":"h2"},
{"id":"soc-h-geo-05#f1","kind":"faq","title":"오래된 산이 더 높을 것 같은데 왜 더 낮아요?","text":"산은 만들어진 순간부터 비바람에 깎이기 시작합니다. 오래된 산일수록 깎인 시간이 길어서 낮고 완만해집니다. 그래서 고생대에 만들어진 애팔래치아산맥은 낮고 완만하고, 비교적 최근(신생대)에 만들어진 히말라야산맥은 높고 험합니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-05","grade":"h2"},
{"id":"soc-h-geo-05#f2","kind":"faq","title":"화산 근처는 위험한데 왜 사람들이 많이 살아요?","text":"화산재가 풍화된 흙은 영양분이 많아 농사가 잘되고, 땅속의 열로 지열 발전과 온천을 할 수 있으며, 독특한 경관은 관광 자원이 되기 때문입니다. 그래서 위험을 줄이기 위해 화산 감시, 대피 훈련, 내진 설계 같은 대비를 하며 살아갑니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-05","grade":"h2"},
{"id":"soc-h-geo-05#m0","kind":"mistake","title":"자주 하는 실수","text":"피오르를 하천이 만든 지형으로 아는 실수 — 피오르는 빙하가 깎은 U자곡에 바닷물이 들어와 생깁니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-05","grade":"h2"},
{"id":"soc-h-geo-05#m1","kind":"mistake","title":"자주 하는 실수","text":"자연 제방과 배후 습지의 토지 이용을 거꾸로 짝짓는 실수 — 높고 배수가 좋은 자연 제방은 취락·밭, 낮고 배수가 나쁜 배후 습지는 논입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-05","grade":"h2"},
{"id":"soc-h-geo-05#m2","kind":"mistake","title":"자주 하는 실수","text":"오래된 산지가 더 높다고 생각하는 실수 — 오래될수록 오래 깎여 낮고 완만합니다. 고기 습곡 산지는 낮고, 신기 습곡 산지는 높습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-05","grade":"h2"},
{"id":"soc-h-geo-06","kind":"unit","title":"세계의 종교와 생활 문화","text":"세계 주요 종교의 발상지와 전파·분포, 종교 경관과 생활 속 규율을 알고, 지역마다 다른 음식과 축제를 자연환경과 인문환경으로 설명하며, 세계화 속에서 문화 다양성을 지키는 방법을 탐구합니다. 불교·크리스트교·이슬람교·힌두교의 발상지와 전파 경로, 오늘날의 분포를 설명할 수 있다. 종교 경관에 담긴 의미와 종교가 음식·옷차림·순례 같은 생활에 미치는 영향…","keywords":["보편 종교","민족 종교","종교 경관","모스크","할랄","라마단","성지 순례","유목","현지화","문화 다양성"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-06","grade":"h2"},
{"id":"soc-h-geo-06#c0","kind":"concept","title":"세계 주요 종교의 발상지와 전파","text":"종교는 사람들의 가치관과 생활 양식에 큰 영향을 주며, 사람의 이동을 따라 퍼져 나갔습니다. 종교 · 발상지와 시기 · 전파와 오늘날의 분포 불교 · 기원전 6세기경 인도 북동부 · 동남아시아(타이·미얀마·캄보디아 등)와 동아시아로 전파. 정작 발상지 인도에서는 신자가 적음 크리스트교 ","keywords":[],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-06","grade":"h2"},
{"id":"soc-h-geo-06#c1","kind":"concept","title":"종교 경관 — 건축물에 담긴 의미","text":"종교 건축물처럼 종교가 땅 위에 남긴 모습을 종교 경관이라고 합니다. 경관을 보면 그 지역의 종교와 그 종교가 소중히 여기는 것을 알 수 있습니다. 종교 · 대표 경관 · 담긴 의미 불교 · 사원, 탑, 불상 · 탑은 부처의 사리를 모시던 데서 비롯되었습니다. 동남아시아에는 금빛으로 빛","keywords":["종교 경관","모스크"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-06","grade":"h2"},
{"id":"soc-h-geo-06#c2","kind":"concept","title":"종교가 생활에 미치는 영향 — 음식·옷차림·순례","text":"종교는 무엇을 먹고, 어떻게 입고, 어디를 찾아가는지에까지 영향을 줍니다. 이슬람교 돼지고기와 술을 먹지 않습니다. 이슬람 율법에 따라 허용된 것을 할랄, 금지된 것을 하람이라고 합니다. 고기는 율법에 맞게 처리한 할랄 고기를 먹습니다. 라마단(이슬람력 9월) 한 달 동안 해가 떠 있는","keywords":["할랄","라마단","성지 순례"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-06","grade":"h2"},
{"id":"soc-h-geo-06#c3","kind":"concept","title":"음식 문화의 지리적 배경 — 주식과 가축","text":"무엇을 주식으로 먹고 어떤 가축을 기르는지는 먼저 기후에 따라 달라집니다. 주식 곡물 곡물 · 잘 자라는 환경 · 주로 먹는 지역 · 음식의 예 쌀 · 여름이 덥고 비가 많은 곳 · 동아시아·동남아시아·남아시아의 계절풍(몬순) 지역 · 밥, 쌀국수 밀 · 서늘하고 비교적 건조한 곳 · ","keywords":["유목"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-06","grade":"h2"},
{"id":"soc-h-geo-06#c4","kind":"concept","title":"세계의 축제와 그 배경","text":"축제에는 그 지역의 자연과 역사, 종교가 담겨 있습니다. 자연적 배경 — 계절·기후·농업 겨울 얼음 축제: 겨울이 길고 몹시 추운 중국 하얼빈에서는 얼음과 눈으로 거대한 조각을 만드는 빙설제가 열립니다. 타이의 송크란: 일 년 중 가장 더운 4월, 전통 새해를 맞아 서로 물을 뿌리며 복","keywords":[],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-06","grade":"h2"},
{"id":"soc-h-geo-06#c5","kind":"concept","title":"세계화와 음식·축제 문화의 융합, 문화 다양성","text":"교통·통신이 발달하고 사람들의 이동이 늘면서 음식과 축제도 국경을 넘나듭니다. 융합과 현지화 서로 다른 지역의 음식이 섞여 새로운 퓨전 음식이 생겨납니다. 세계적으로 퍼진 음식도 그 지역의 입맛과 종교에 맞게 바뀝니다(현지화). 예를 들어 세계 곳곳에 체인점이 있는 햄버거 가게가 인도에","keywords":["할랄","현지화","문화 다양성"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-06","grade":"h2"},
{"id":"soc-h-geo-06#t0","kind":"term","title":"보편 종교","text":"특정 민족이나 지역을 넘어 세계 여러 곳으로 퍼진 종교입니다. 예: 불교, 크리스트교, 이슬람교","keywords":["보편 종교"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-06","grade":"h2"},
{"id":"soc-h-geo-06#t1","kind":"term","title":"민족 종교","text":"특정 민족을 중심으로 믿는 종교입니다. 예: 힌두교, 유대교","keywords":["민족 종교"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-06","grade":"h2"},
{"id":"soc-h-geo-06#t2","kind":"term","title":"종교 경관","text":"종교 건축물처럼 종교가 땅 위에 남긴 모습입니다. 예: 불탑, 성당, 모스크, 힌두교 사원","keywords":["종교 경관"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-06","grade":"h2"},
{"id":"soc-h-geo-06#t3","kind":"term","title":"모스크","text":"이슬람교의 예배당입니다. 둥근 돔과 첨탑이 있고, 내부를 기하학적 무늬와 쿠란 글귀로 꾸밉니다.","keywords":["모스크"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-06","grade":"h2"},
{"id":"soc-h-geo-06#t4","kind":"term","title":"할랄","text":"이슬람 율법에 따라 허용된 것입니다. 율법에 맞게 처리한 고기 등 이슬람교 신자가 먹을 수 있는 음식을 할랄 음식이라고 합니다.","keywords":["할랄"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-06","grade":"h2"},
{"id":"soc-h-geo-06#t5","kind":"term","title":"라마단","text":"이슬람력 9월로, 이 한 달 동안 이슬람교 신자는 해가 떠 있는 동안 금식합니다.","keywords":["라마단"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-06","grade":"h2"},
{"id":"soc-h-geo-06#t6","kind":"term","title":"성지 순례","text":"종교적으로 신성한 곳을 찾아가는 일입니다. 예: 이슬람교의 메카 순례, 힌두교의 바라나시 순례","keywords":["성지 순례"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-06","grade":"h2"},
{"id":"soc-h-geo-06#t7","kind":"term","title":"유목","text":"물과 풀을 찾아 가축을 몰고 옮겨 다니며 생활하는 방식입니다. 건조 지역과 초원에서 나타납니다.","keywords":["유목"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-06","grade":"h2"},
{"id":"soc-h-geo-06#t8","kind":"term","title":"현지화","text":"세계로 퍼진 상품이나 문화가 그 지역의 문화와 입맛에 맞게 바뀌는 것입니다.","keywords":["현지화"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-06","grade":"h2"},
{"id":"soc-h-geo-06#t9","kind":"term","title":"문화 다양성","text":"세계 여러 지역의 서로 다른 문화가 저마다의 가치를 지니고 함께 존재하는 상태입니다.","keywords":["문화 다양성"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-06","grade":"h2"},
{"id":"soc-h-geo-06#f0","kind":"faq","title":"할랄이 정확히 뭐예요? 돼지고기만 안 먹으면 할랄인가요?","text":"할랄은 이슬람 율법에서 \"허용된 것\"을 뜻합니다. 돼지고기와 술을 피하는 것뿐 아니라, 다른 고기도 율법에 맞는 방식으로 처리해야 할랄 고기가 됩니다. 그래서 이슬람교 신자가 많은 나라나 관광지에서는 할랄 인증 표시를 붙여 신자들이 안심하고 고를 수 있게 합니다.","keywords":["할랄"],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-06","grade":"h2"},
{"id":"soc-h-geo-06#f1","kind":"faq","title":"불교는 인도에서 시작됐는데 왜 인도에는 불교 신자가 적어요?","text":"불교는 인도에서 시작되어 아시아 여러 지역으로 널리 퍼졌지만, 인도 안에서는 오랜 세월에 걸쳐 힌두교가 다시 크게 자리 잡으면서 불교의 세력이 약해졌습니다. 그래서 오늘날 불교 신자는 발상지보다 동남아시아와 동아시아에 훨씬 많습니다. 종교의 발상지와 오늘날의 분포가 다를 수 있다는 좋은 예입니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-06","grade":"h2"},
{"id":"soc-h-geo-06#f2","kind":"faq","title":"음식이 기후 때문인지 종교 때문인지 어떻게 구별해요?","text":"무엇을 먹을 수 있는가(어떤 곡물이 자라고 어떤 가축을 기를 수 있는가)는 주로 기후와 지형 같은 자연환경이 정합니다. 그중 무엇을 먹지 않는가, 언제 먹는가(돼지고기·소고기 금기, 금식)는 주로 종교 같은 인문환경이 정합니다. 실제로는 두 가지가 함께 작용하는 경우가 많습니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-06","grade":"h2"},
{"id":"soc-h-geo-06#m0","kind":"mistake","title":"자주 하는 실수","text":"돼지고기 금기와 소고기 금기를 바꾸어 기억하는 실수 — 돼지고기를 먹지 않는 것은 이슬람교, 소고기를 먹지 않는 것은 힌두교입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-06","grade":"h2"},
{"id":"soc-h-geo-06#m1","kind":"mistake","title":"자주 하는 실수","text":"종교의 발상지와 오늘날 신자가 많은 곳을 같다고 생각하는 실수 — 불교는 인도에서 시작했지만 오늘날 신자는 동남아시아·동아시아에 많습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-06","grade":"h2"},
{"id":"soc-h-geo-06#m2","kind":"mistake","title":"자주 하는 실수","text":"모든 축제를 종교 때문이라고만 보는 실수 — 얼음 축제, 물 축제처럼 기후·계절 같은 자연적 배경에서 생긴 축제도 많습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-06","grade":"h2"},
{"id":"soc-h-geo-07","kind":"unit","title":"세계의 인구와 국제 이주","text":"세계 인구 분포와 인구 변천 단계에 따른 인구 구조의 차이, 빠른 인구 증가와 저출생·고령화가 함께 나타나는 인구 문제를 알고, 국제 이주의 원인과 이주가 떠나는 지역·받아들이는 지역에 주는 영향을 탐구합니다. 세계 인구 분포의 지역 차이를 자연적·인문적 요인으로 설명할 수 있다. 인구 변천 단계와 인구 피라미드로 지역별 인구 구조의 차이를 해석할 수 있…","keywords":["인구 변천 모형","자연 증가율","인구 피라미드","합계 출산율","고령화","노년 부양비","배출 요인","흡인 요인","난민","해외 송금"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-07","grade":"h2"},
{"id":"soc-h-geo-07#c0","kind":"concept","title":"세계 인구 분포의 지역 차이","text":"세계 인구는 고르게 퍼져 있지 않습니다. 세계 인구의 약 60%가 아시아에 살고, 대부분이 북반구에 삽니다. 구분 · 대표 지역 · 까닭 인구 밀집 지역 · 동아시아, 남아시아(갠지스강 유역), 동남아시아(자와섬 등), 서부 유럽, 북아메리카 북동부 · 기후가 온화하고 평야·하천이 있어","keywords":[],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-07","grade":"h2"},
{"id":"soc-h-geo-07#c1","kind":"concept","title":"인구 변천 단계와 인구 구조","text":"한 나라의 인구는 경제가 발전하면서 대체로 다음과 같은 단계를 거쳐 변합니다. 이를 인구 변천 모형이라고 합니다. 인구가 늘어나는 정도는 자연 증가율(출생률 − 사망률)로 봅니다. 단계 · 출생률 · 사망률 · 인구 증가 · 모습 1단계 · 높음 · 높음 · 느림 · 산업화 이전. 많이","keywords":["인구 변천 모형","자연 증가율","인구 피라미드"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-07","grade":"h2"},
{"id":"soc-h-geo-07#c2","kind":"concept","title":"지역별 인구 문제 — 빠른 증가와 저출생·고령화의 공존","text":"세계 전체 인구는 계속 늘고 있지만, 지역에 따라 전혀 다른 인구 문제를 겪습니다. 구분 · 빠른 인구 증가 · 저출생·고령화 주로 나타나는 곳 · 사하라 이남 아프리카, 남아시아·서남아시아 일부 등 개발 도상국 · 유럽, 동아시아(우리나라 포함), 북아메리카 등 선진국 원인 · 사망률","keywords":["고령화"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-07","grade":"h2"},
{"id":"soc-h-geo-07#c3","kind":"concept","title":"국제 이주의 유형과 원인","text":"사람이 나라의 경계를 넘어 옮겨 가 사는 것을 국제 이주라고 합니다. 이주의 유형 자발적 이주: 스스로 선택한 이주. 오늘날 가장 많은 것은 일자리와 높은 임금을 찾는 경제적 이주입니다. 유학, 결혼에 따른 이주도 있습니다. 강제적 이주: 원하지 않는데도 떠나야 하는 이주. 과거 아프리","keywords":["배출 요인","흡인 요인","난민"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-07","grade":"h2"},
{"id":"soc-h-geo-07#c4","kind":"concept","title":"인구 유출 지역이 받는 영향","text":"사람이 빠져나가는 지역(대개 개발 도상국)에는 좋은 영향과 어려움이 함께 나타납니다. 긍정적 영향 해외 송금: 이주 노동자가 고향의 가족에게 보내는 돈은 가계 소득을 늘리고, 나라 전체로는 외화를 벌어들이는 중요한 수입원이 됩니다. 송금이 국내 총생산(GDP)에서 큰 비중을 차지하는 나","keywords":["고령화","해외 송금"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-07","grade":"h2"},
{"id":"soc-h-geo-07#c5","kind":"concept","title":"인구 유입 지역이 받는 영향","text":"이주자를 받아들이는 지역(대개 선진국이나 산유국)에도 좋은 영향과 해결해야 할 과제가 함께 나타납니다. 긍정적 영향 노동력 확보: 저출생·고령화로 일할 사람이 부족한 산업(농업, 제조업, 건설업, 돌봄 서비스 등)의 일손을 채웁니다. 이주자의 소비와 세금 납부가 경제에 활력을 줍니다. ","keywords":["고령화"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-07","grade":"h2"},
{"id":"soc-h-geo-07#t0","kind":"term","title":"인구 변천 모형","text":"출생률과 사망률의 변화에 따라 인구가 1단계(다산다사)에서 4단계(소산소사)로 변해 가는 과정을 나타낸 모형입니다.","keywords":["인구 변천 모형"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-07","grade":"h2"},
{"id":"soc-h-geo-07#t1","kind":"term","title":"자연 증가율","text":"출생률에서 사망률을 뺀 값으로, 이동을 빼고 태어나고 죽는 것만으로 인구가 늘어나는 정도입니다.","keywords":["자연 증가율"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-07","grade":"h2"},
{"id":"soc-h-geo-07#t2","kind":"term","title":"인구 피라미드","text":"성별·연령별 인구 비율을 나타낸 그래프입니다. 피라미드형·종형·방추형 등으로 나눕니다.","keywords":["인구 피라미드"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-07","grade":"h2"},
{"id":"soc-h-geo-07#t3","kind":"term","title":"합계 출산율","text":"한 여성이 평생 낳을 것으로 예상되는 평균 자녀 수입니다. 인구가 유지되려면 약 2.1명(대체 출산율)이 필요합니다.","keywords":["합계 출산율"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-07","grade":"h2"},
{"id":"soc-h-geo-07#t4","kind":"term","title":"고령화","text":"전체 인구에서 65세 이상 인구의 비율이 높아지는 현상입니다. 7% 이상 고령화 사회, 14% 이상 고령 사회, 20% 이상 초고령 사회입니다.","keywords":["고령화"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-07","grade":"h2"},
{"id":"soc-h-geo-07#t5","kind":"term","title":"노년 부양비","text":"15~64세 인구에 대한 65세 이상 인구의 비율을 100을 곱해 나타낸 값입니다. 일하는 사람 100명이 노인 몇 명을 부양하는지 보여 줍니다.","keywords":["노년 부양비"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-07","grade":"h2"},
{"id":"soc-h-geo-07#t6","kind":"term","title":"배출 요인","text":"사람을 떠나게 만드는 원래 지역의 조건입니다. 예: 일자리 부족, 낮은 임금, 분쟁, 박해, 자연재해","keywords":["배출 요인"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-07","grade":"h2"},
{"id":"soc-h-geo-07#t7","kind":"term","title":"흡인 요인","text":"사람을 끌어들이는 도착 지역의 조건입니다. 예: 풍부한 일자리, 높은 임금, 안정된 정치, 좋은 교육·복지","keywords":["흡인 요인"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-07","grade":"h2"},
{"id":"soc-h-geo-07#t8","kind":"term","title":"난민","text":"전쟁·분쟁이나 인종·종교·정치적 의견 등을 이유로 한 박해를 피해 자기 나라를 떠난 사람입니다.","keywords":["난민"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-07","grade":"h2"},
{"id":"soc-h-geo-07#t9","kind":"term","title":"해외 송금","text":"외국에서 일하는 이주자가 고향의 가족에게 보내는 돈입니다. 유출 지역의 가계 소득과 외화 수입원이 됩니다.","keywords":["해외 송금"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-07","grade":"h2"},
{"id":"soc-h-geo-07#f0","kind":"faq","title":"인구가 많이 늘어나는 나라가 있는데 왜 다른 나라는 인구가 줄어서 걱정해요?","text":"나라마다 인구 변천 단계가 다르기 때문입니다. 아직 출생률이 높은 개발 도상국은 인구가 빠르게 늘어 식량·일자리가 모자라고, 출생률이 크게 낮아진 선진국은 일할 사람이 줄고 노인 부양 부담이 커집니다. 그래서 세계 전체로는 인구가 늘면서도 지역마다 정반대의 인구 문제가 함께 나타납니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-07","grade":"h2"},
{"id":"soc-h-geo-07#f1","kind":"faq","title":"배출 요인이랑 흡인 요인이 헷갈려요.","text":"\"배출\"은 밖으로 내보낸다, \"흡인\"은 빨아들인다는 뜻입니다. 떠나는 곳의 나쁜 조건(일자리 부족, 분쟁, 가뭄)이 사람을 밀어내면 배출 요인, 도착하는 곳의 좋은 조건(높은 임금, 안전, 좋은 교육)이 사람을 끌어당기면 흡인 요인입니다. 같은 \"일자리\"라도 부족하면 배출 요인, 풍부하면 흡인 요인입니다.","keywords":["배출 요인","흡인 요인"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-07","grade":"h2"},
{"id":"soc-h-geo-07#f2","kind":"faq","title":"해외 송금은 좋은 건데 왜 문제가 될 수 있어요?","text":"송금은 가족의 생활을 돕고 나라에 외화를 가져다주는 중요한 수입입니다. 하지만 경제가 송금에 지나치게 기대면, 이주자가 일하는 나라의 경기가 나빠지거나 일자리가 줄 때 송금이 갑자기 줄어 경제가 크게 흔들립니다. 또 일할 사람이 떠난 자리가 비어 나라 안의 산업이 성장하기 어려워질 수도 있습니다.","keywords":["해외 송금"],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-07","grade":"h2"},
{"id":"soc-h-geo-07#m0","kind":"mistake","title":"자주 하는 실수","text":"인구 변천 2단계에서 출생률이 먼저 떨어진다고 생각하는 실수 — 사망률이 먼저 떨어지고 출생률은 3단계에서 떨어집니다. 그래서 2단계의 인구 증가가 가장 빠릅니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-07","grade":"h2"},
{"id":"soc-h-geo-07#m1","kind":"mistake","title":"자주 하는 실수","text":"노년 부양비를 전체 인구에서 노인이 차지하는 비율로 계산하는 실수 — 부양비는 15~64세 인구로 나눕니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-07","grade":"h2"},
{"id":"soc-h-geo-07#m2","kind":"mistake","title":"자주 하는 실수","text":"해외 송금을 받는 나라를 이주자가 들어오는 나라로 착각하는 실수 — 송금을 받는 쪽은 사람이 빠져나간 유출 지역입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-07","grade":"h2"},
{"id":"soc-h-geo-08","kind":"unit","title":"식량 자원과 식량 문제","text":"쌀·밀·옥수수가 생산되는 곳과 소비되는 곳이 다른 까닭, 육류·사료·바이오 연료로 달라지는 곡물 수요, 식량 문제의 구조적 원인과 식량 과잉·부족 지역의 공존을 알고, 안정적인 식량 공급을 위한 나라별 정책을 비교합니다. 쌀·밀·옥수수의 재배 조건과 생산·소비 지역, 국제 이동의 특징을 비교할 수 있다. 육류 소비 증가와 사료·바이오 연료용 곡물 수요가 …","keywords":["3대 곡물","기업적 농업","곡물 메이저","사료 작물","바이오 연료","식량 안보","식량 자급률","곡물 자급률","해외 농업 개발","수입선 다변화"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-08","grade":"h2"},
{"id":"soc-h-geo-08#c0","kind":"concept","title":"세계 3대 곡물 — 쌀·밀·옥수수","text":"쌀·밀·옥수수는 세계 사람들이 먹는 열량의 큰 부분을 차지하는 3대 곡물입니다. 곡물마다 잘 자라는 환경이 달라 생산 지역도 다릅니다. 곡물 · 원산지 · 재배 조건 · 주요 생산 지역 쌀 · 아시아의 계절풍 지역 · 여름이 덥고 비가 많아야 함. 물을 대는 논에서 기르고 일손이 많이 ","keywords":["3대 곡물"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-08","grade":"h2"},
{"id":"soc-h-geo-08#c1","kind":"concept","title":"곡물의 생산지와 소비지, 그리고 국제 이동","text":"곡물이 많이 생산되는 곳과 많이 소비되는 곳이 늘 같지는 않습니다. 남는 곳에서 모자란 곳으로 곡물이 국제 이동을 합니다. 쌀 — 자급적 성격이 강함 쌀을 많이 생산하는 아시아는 인구가 많아 쌀을 많이 소비하는 곳이기도 합니다. 그래서 생산된 곳에서 대부분 소비되고, 생산량에 비해 국제","keywords":["기업적 농업"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-08","grade":"h2"},
{"id":"soc-h-geo-08#c2","kind":"concept","title":"식량 소비의 변화 — 육류, 사료, 바이오 연료","text":"곡물은 사람이 직접 먹는 데만 쓰이지 않습니다. 오늘날 곡물 수요를 크게 늘리는 두 가지 변화가 있습니다. 1. 육류 소비 증가 → 사료용 곡물 수요 증가 소득이 늘고 식생활이 바뀌면서 개발 도상국을 중심으로 고기와 유제품 소비가 빠르게 늘고 있습니다. 가축을 길러 고기 1 kg을 얻으","keywords":["바이오 연료"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-08","grade":"h2"},
{"id":"soc-h-geo-08#c3","kind":"concept","title":"식량 문제의 구조적 원인","text":"식량 문제는 한 해 농사가 잘되고 못되는 것만으로 생기지 않습니다. 세계 식량 체계 자체에 문제를 만드는 구조적 원인이 있습니다. 1. 곡물 기업의 생산·유통 장악 소수의 거대한 국제 곡물 기업(곡물 메이저)이 종자·비료 공급, 곡물 구매·저장·운송·가공·판매까지 세계 곡물 유통의 많은","keywords":["곡물 메이저"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-08","grade":"h2"},
{"id":"soc-h-geo-08#c4","kind":"concept","title":"식량 과잉 지역과 식량 부족 지역의 공존","text":"세계 전체의 식량 생산량은 세계 인구가 먹기에 모자라지 않을 만큼 늘었습니다. 그런데도 한쪽에서는 식량이 남고, 다른 쪽에서는 굶주리는 사람이 많습니다. 구분 · 식량 과잉 지역 · 식량 부족 지역 주로 나타나는 곳 · 미국·캐나다·유럽·오스트레일리아 등 선진국 · 사하라 이남 아프리카","keywords":[],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-08","grade":"h2"},
{"id":"soc-h-geo-08#c5","kind":"concept","title":"안정적인 식량 공급을 위한 각국의 정책","text":"모든 사람이 언제나 충분하고 안전한 식량을 얻을 수 있는 상태를 식량 안보라고 합니다. 각 나라는 처지에 맞게 여러 정책을 폅니다. 식량 자급률: 한 나라가 소비하는 식량 가운데 국내에서 생산한 양이 차지하는 비율입니다. 식량 자급률(%) = 국내 생산량 ÷ 국내 소비량 × 100 나라","keywords":["식량 안보","식량 자급률","해외 농업 개발"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-08","grade":"h2"},
{"id":"soc-h-geo-08#t0","kind":"term","title":"3대 곡물","text":"세계적으로 가장 많이 생산·소비되는 쌀·밀·옥수수를 함께 이르는 말입니다.","keywords":["3대 곡물"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-08","grade":"h2"},
{"id":"soc-h-geo-08#t1","kind":"term","title":"기업적 농업","text":"넓은 땅에서 큰 기계와 많은 자본을 써서 한 가지 작물을 대량으로 길러 판매하는 농업입니다. 미국·캐나다·오스트레일리아 등의 밀·옥수수 농업이 대표적입니다.","keywords":["기업적 농업"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-08","grade":"h2"},
{"id":"soc-h-geo-08#t2","kind":"term","title":"곡물 메이저","text":"종자 공급부터 곡물의 구매·저장·운송·판매까지 세계 곡물 유통의 많은 부분을 장악한 소수의 거대 국제 곡물 기업입니다. 국제 곡물 가격에 큰 영향을 줍니다.","keywords":["곡물 메이저"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-08","grade":"h2"},
{"id":"soc-h-geo-08#t3","kind":"term","title":"사료 작물","text":"가축의 먹이로 쓰려고 기르는 작물입니다. 옥수수와 콩이 대표적이며, 육류 소비가 늘면 수요가 늘어납니다.","keywords":["사료 작물"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-08","grade":"h2"},
{"id":"soc-h-geo-08#t4","kind":"term","title":"바이오 연료","text":"옥수수·사탕수수·콩·유채 같은 생물 자원으로 만든 연료입니다. 옥수수·사탕수수로 만든 바이오 에탄올, 콩·유채 기름으로 만든 바이오 디젤이 있습니다.","keywords":["바이오 연료"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-08","grade":"h2"},
{"id":"soc-h-geo-08#t5","kind":"term","title":"식량 안보","text":"모든 사람이 언제나 충분하고 안전한 식량을 얻을 수 있는 상태, 또는 그런 상태를 지키려는 노력입니다.","keywords":["식량 안보"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-08","grade":"h2"},
{"id":"soc-h-geo-08#t6","kind":"term","title":"식량 자급률","text":"한 나라가 소비하는 식량 가운데 국내에서 생산한 양이 차지하는 비율입니다. 국내 생산량 ÷ 국내 소비량 × 100으로 구합니다.","keywords":["식량 자급률"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-08","grade":"h2"},
{"id":"soc-h-geo-08#t7","kind":"term","title":"곡물 자급률","text":"사료용 곡물까지 포함한 곡물 소비량 가운데 국내 생산량이 차지하는 비율입니다. 사료용 옥수수 등을 많이 수입하는 나라는 식량 자급률보다 낮게 나옵니다.","keywords":["곡물 자급률"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-08","grade":"h2"},
{"id":"soc-h-geo-08#t8","kind":"term","title":"해외 농업 개발","text":"농지가 넓은 다른 나라에 투자해 곡물을 재배하거나 해외의 곡물 유통 시설을 확보해 식량을 들여오는 정책입니다.","keywords":["해외 농업 개발"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-08","grade":"h2"},
{"id":"soc-h-geo-08#t9","kind":"term","title":"수입선 다변화","text":"물건을 사 오는 나라를 여러 곳으로 나누는 것입니다. 한 수출국에 문제가 생겨도 공급이 끊기지 않게 합니다.","keywords":["수입선 다변화"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-08","grade":"h2"},
{"id":"soc-h-geo-08#f0","kind":"faq","title":"세계에 식량이 충분하다는데 왜 굶는 사람이 있어요?","text":"식량이 필요한 곳에 고르게 나누어지지 못하고, 가난한 사람은 식량을 살 돈(구매력)이 없기 때문입니다. 여기에 분쟁으로 농사와 운송이 막히거나 가뭄으로 수확이 줄면 굶주림이 더 심해집니다. 그래서 식량 문제는 생산량만이 아니라 분배·소득·평화의 문제이기도 합니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-08","grade":"h2"},
{"id":"soc-h-geo-08#f1","kind":"faq","title":"고기를 많이 먹으면 왜 곡물이 모자라요?","text":"가축은 먹은 곡물의 일부만 몸의 살로 바꾸기 때문에, 고기 1 kg을 얻으려면 그보다 몇 배 많은 곡물을 사료로 먹여야 합니다. 그래서 육류 소비가 늘면 사람이 곡물을 직접 먹을 때보다 훨씬 많은 곡물이 필요해지고, 사료용 곡물 수요가 늘어 곡물 가격이 오를 수 있습니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-08","grade":"h2"},
{"id":"soc-h-geo-08#f2","kind":"faq","title":"식량 자급률이랑 곡물 자급률은 뭐가 달라요?","text":"둘 다 국내 소비량 가운데 국내 생산량의 비율이지만, 무엇을 넣어 계산하느냐가 다릅니다. 곡물 자급률은 가축 사료로 쓰는 곡물까지 포함하고, 식량 자급률은 주로 사람이 먹는 식량을 기준으로 합니다. 사료용 옥수수·콩을 많이 수입하는 우리나라는 곡물 자급률이 식량 자급률보다 낮게 나옵니다.","keywords":["식량 자급률","곡물 자급률"],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-08","grade":"h2"},
{"id":"soc-h-geo-08#f3","kind":"faq","title":"바이오 연료는 친환경이라는데 왜 식량 문제와 연결돼요?","text":"바이오 연료는 석유를 대신하고 온실가스를 줄이려고 만들지만, 원료가 옥수수·사탕수수·콩 같은 작물입니다. 연료용으로 쓰는 곡물과 농경지가 늘면 사람이 먹을 곡물과 경쟁하게 되어 곡물 가격이 오를 수 있습니다. 그래서 먹을 수 없는 식물 줄기나 폐기물로 연료를 만드는 기술도 연구되고 있습니다.","keywords":["바이오 연료"],"ref":{"tab":"faq","idx":3},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-08","grade":"h2"},
{"id":"soc-h-geo-08#m0","kind":"mistake","title":"자주 하는 실수","text":"자급률을 거꾸로 계산하는 실수 — 자급률은 국내 생산량 ÷ 국내 소비량 × 100입니다. 소비량을 생산량으로 나누면 안 됩니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-08","grade":"h2"},
{"id":"soc-h-geo-08#m1","kind":"mistake","title":"자주 하는 실수","text":"쌀이 밀보다 국제 이동량이 많다고 생각하는 실수 — 쌀은 생산지에서 대부분 소비되는 자급적 곡물이라 국제 이동량이 적고, 밀·옥수수는 상업적 성격이 강합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-08","grade":"h2"},
{"id":"soc-h-geo-08#m2","kind":"mistake","title":"자주 하는 실수","text":"기아의 원인을 세계 식량 생산량 부족 하나로만 보는 실수 — 세계 전체 생산량은 모자라지 않을 만큼 늘었고, 분배·구매력·분쟁 같은 구조적 원인이 큽니다.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-h-geo","unit":"soc-h-geo-08","grade":"h2"}
]);
